-- ---------------------------------------------------------------------
-- [표준 구분: KS X 9101 표준] 표 12, 조항 7.4.1.1 | 업무영역: 기준정보
-- 테이블명(물리): "Site" | 테이블명(논리): 사업장
-- 설명: 회사 내 하위 관리단위로서의 사업장을 의미한다.
-- ---------------------------------------------------------------------
CREATE TABLE "Site" ( -- [KS X 9101 표준] 사업장 (표 12)
    "SiteSequenceNo" BIGINT GENERATED BY DEFAULT AS IDENTITY, -- [KS X 9101 표준] 사업장 일련번호(PK)
    "EnterpriseID" VARCHAR(50) NOT NULL, -- [KS X 9101 표준] 회사식별자
    "CreatorID" VARCHAR(50), -- [KS X 9101 표준] 등록자식별자
    "CreationDateTime" TIMESTAMP, -- [KS X 9101 표준] 등록일시
    "ModifierID" VARCHAR(50), -- [KS X 9101 표준] 수정자식별자
    "ModificationDateTime" TIMESTAMP, -- [KS X 9101 표준] 수정일시
    "Note" VARCHAR(1000), -- [KS X 9101 표준] 비고
    "SiteID" VARCHAR(50) NOT NULL, -- [KS X 9101 표준] 사업장식별자
    "SiteName" VARCHAR(200), -- [KS X 9101 표준] 사업장명
    "BusinessRegistrationNumber" VARCHAR(50), -- [KS X 9101 표준] 사업자등록번호
    "DialNumber" VARCHAR(30), -- [KS X 9101 표준] 전화번호
    "PostalCode" VARCHAR(10), -- [KS X 9101 표준] 우편번호
    "BaseAddress" VARCHAR(1000), -- [KS X 9101 표준] 기본주소
    "DetailAddress" VARCHAR(1000), -- [KS X 9101 표준] 상세주소
    "UseIndicator" BOOLEAN, -- [KS X 9101 표준] 사용여부
    CONSTRAINT "PK_Site" PRIMARY KEY ("SiteSequenceNo"),
    CONSTRAINT "UK_Site" UNIQUE ("EnterpriseID", "SiteID")
);

COMMENT ON TABLE "Site" IS '[KS X 9101 표준] 사업장 (회사 내 하위 관리단위로서의 사업장을 의미한다.)';
COMMENT ON COLUMN "Site"."SiteSequenceNo" IS '[KS X 9101 표준] 사업장 일련번호: — 테이블 행을 식별하는 일련번호(PK, 대리키) — 표준 외 물리 컬럼
— 자동 증가 값(IDENTITY)으로 부여하며 다른 테이블이 참조하지 않음(FK는 UK 참조)';
COMMENT ON COLUMN "Site"."EnterpriseID" IS '[KS X 9101 표준] 회사식별자: — 회사를 유일하게 구분할 수 있는 고유식별값
— 기업업무시스템 간의 연동을 수행하는 회사들 간에 자체적으로 정의한 고유식별값
— 참조 대상: 회사(Enterprise)';
COMMENT ON COLUMN "Site"."CreatorID" IS '[KS X 9101 표준] 등록자식별자: — 정보를 처음으로 등록한 사람을 구분할 수 있는 고유식별값으로, 일반적으로 사원번호가사용됨
— 참조 대상: 사원(Personnel)';
COMMENT ON COLUMN "Site"."CreationDateTime" IS '[KS X 9101 표준] 등록일시: — 정보를 처음으로 등록한 날짜 (KS X ISO 8601을 따른다)';
COMMENT ON COLUMN "Site"."ModifierID" IS '[KS X 9101 표준] 수정자식별자: — 정보를 마지막으로 수정한 사람을 구분할 수 있는 고유식별값으로, 일반적으로 사원번호가 사용됨
— 참조 대상: 사원(Personnel)';
COMMENT ON COLUMN "Site"."ModificationDateTime" IS '[KS X 9101 표준] 수정일시: — 정보를 마지막으로 수정한 날짜 (KS X ISO 8601을 따른다.)';
COMMENT ON COLUMN "Site"."Note" IS '[KS X 9101 표준] 비고: — 비고사항';
COMMENT ON COLUMN "Site"."SiteID" IS '[KS X 9101 표준] 사업장식별자: — 사업장의 고유식별값';
COMMENT ON COLUMN "Site"."SiteName" IS '[KS X 9101 표준] 사업장명: — 사업장의 명칭';
COMMENT ON COLUMN "Site"."BusinessRegistrationNumber" IS '[KS X 9101 표준] 사업자등록번호: — 사업장의 사업자등록번호';
COMMENT ON COLUMN "Site"."DialNumber" IS '[KS X 9101 표준] 전화번호: — 사업장의 전화번호';
COMMENT ON COLUMN "Site"."PostalCode" IS '[KS X 9101 표준] 우편번호: — 사업장의 우편번호';
COMMENT ON COLUMN "Site"."BaseAddress" IS '[KS X 9101 표준] 기본주소: — 우편번호로 검색되는 사업장 주소';
COMMENT ON COLUMN "Site"."DetailAddress" IS '[KS X 9101 표준] 상세주소: — 기본주소에 추가되는 사업장의 상세주소';
COMMENT ON COLUMN "Site"."UseIndicator" IS '[KS X 9101 표준] 사용여부: — 사업장의 사용 여부';

-- ---------------------------------------------------------------------
-- [표준 구분: KS X 9101 표준] 표 13, 조항 7.4.1.2 | 업무영역: 기준정보
-- 테이블명(물리): "Plant" | 테이블명(논리): 공장
-- 설명: 회사 내 하위 관리단위로서의 공장을 의미한다.
-- ---------------------------------------------------------------------
CREATE TABLE "Plant" ( -- [KS X 9101 표준] 공장 (표 13)
    "PlantSequenceNo" BIGINT GENERATED BY DEFAULT AS IDENTITY, -- [KS X 9101 표준] 공장 일련번호(PK)
    "EnterpriseID" VARCHAR(50) NOT NULL, -- [KS X 9101 표준] 회사식별자
    "SiteID" VARCHAR(50) NOT NULL, -- [KS X 9101 표준] 사업장식별자
    "CreatorID" VARCHAR(50), -- [KS X 9101 표준] 등록자식별자
    "CreationDateTime" TIMESTAMP, -- [KS X 9101 표준] 등록일시
    "ModifierID" VARCHAR(50), -- [KS X 9101 표준] 수정자식별자
    "ModificationDateTime" TIMESTAMP, -- [KS X 9101 표준] 수정일시
    "Note" VARCHAR(1000), -- [KS X 9101 표준] 비고
    "PlantID" VARCHAR(50) NOT NULL, -- [KS X 9101 표준] 공장식별자
    "PlantName" VARCHAR(200), -- [KS X 9101 표준] 공장명
    "DialNumber" VARCHAR(30), -- [KS X 9101 표준] 전화번호
    "CountryID" VARCHAR(30), -- [KS X 9101 표준] 국가식별자
    "PostalCode" VARCHAR(10), -- [KS X 9101 표준] 우편번호
    "BaseAddress" VARCHAR(1000), -- [KS X 9101 표준] 기본주소
    "DetailAddress" VARCHAR(1000), -- [KS X 9101 표준] 상세주소
    CONSTRAINT "PK_Plant" PRIMARY KEY ("PlantSequenceNo"),
    CONSTRAINT "UK_Plant" UNIQUE ("EnterpriseID", "PlantID")
);

COMMENT ON TABLE "Plant" IS '[KS X 9101 표준] 공장 (회사 내 하위 관리단위로서의 공장을 의미한다.)';
COMMENT ON COLUMN "Plant"."PlantSequenceNo" IS '[KS X 9101 표준] 공장 일련번호: — 테이블 행을 식별하는 일련번호(PK, 대리키) — 표준 외 물리 컬럼
— 자동 증가 값(IDENTITY)으로 부여하며 다른 테이블이 참조하지 않음(FK는 UK 참조)';
COMMENT ON COLUMN "Plant"."EnterpriseID" IS '[KS X 9101 표준] 회사식별자: — 회사를 유일하게 구분할 수 있는 고유식별값
— 기업업무시스템 간의 연동을 수행하는 회사들 간에 자체적으로 정의한 고유식별값
— 참조 대상: 회사(Enterprise)';
COMMENT ON COLUMN "Plant"."SiteID" IS '[KS X 9101 표준] 사업장식별자: — 회사 내에서 사업장을 구분할수 있는 고유식별값
— 참조 대상: 사업장(Site)';
COMMENT ON COLUMN "Plant"."CreatorID" IS '[KS X 9101 표준] 등록자식별자: — 정보를 처음으로 등록한 사람을 구분할 수 있는 고유식별값으로, 일반적으로 사원번호가사용됨
— 참조 대상: 사원(Personnel)';
COMMENT ON COLUMN "Plant"."CreationDateTime" IS '[KS X 9101 표준] 등록일시: — 정보를 처음으로 등록한 날짜 (KS X ISO 8601을 따른다)';
COMMENT ON COLUMN "Plant"."ModifierID" IS '[KS X 9101 표준] 수정자식별자: — 정보를 마지막으로 수정한 사람을 구분할 수 있는 고유식별값으로, 일반적으로 사원번호가 사용됨
— 참조 대상: 사원(Personnel)';
COMMENT ON COLUMN "Plant"."ModificationDateTime" IS '[KS X 9101 표준] 수정일시: — 정보를 마지막으로 수정한 날짜 (KS X ISO 8601을 따른다.)';
COMMENT ON COLUMN "Plant"."Note" IS '[KS X 9101 표준] 비고: — 비고사항';
COMMENT ON COLUMN "Plant"."PlantID" IS '[KS X 9101 표준] 공장식별자: — 공장의 고유식별값';
COMMENT ON COLUMN "Plant"."PlantName" IS '[KS X 9101 표준] 공장명: — 공장의 명칭';
COMMENT ON COLUMN "Plant"."DialNumber" IS '[KS X 9101 표준] 전화번호: — 공장의 대표전화번호';
COMMENT ON COLUMN "Plant"."CountryID" IS '[KS X 9101 표준] 국가식별자: — 공장의 국가를 식별하기 위한 고유값
— 참조 대상: 공통코드정보(CommonCodeMaster)의 코드(ISO 3166-1 국가코드 사용 권고)';
COMMENT ON COLUMN "Plant"."PostalCode" IS '[KS X 9101 표준] 우편번호: — 공장의 우편번호';
COMMENT ON COLUMN "Plant"."BaseAddress" IS '[KS X 9101 표준] 기본주소: — 우편번호 검색을 통해 찾는 공장 주소';
