-- ---------------------------------------------------------------------
-- [표준 구분: KS X 9101 표준] 표 14, 조항 7.4.1.3 | 업무영역: 기준정보
-- 테이블명(물리): "Department" | 테이블명(논리): 부서
-- 설명: 회사 내 하위 관리 단위로서의 부서를 의미한다.
-- ---------------------------------------------------------------------
CREATE TABLE "Department" ( -- [KS X 9101 표준] 부서 (표 14)
    "DepartmentSequenceNo" BIGINT GENERATED BY DEFAULT AS IDENTITY, -- [KS X 9101 표준] 부서 일련번호(PK)
    "EnterpriseID" VARCHAR(50) NOT NULL, -- [KS X 9101 표준] 회사식별자
    "SiteID" VARCHAR(50) NOT NULL, -- [KS X 9101 표준] 사업장식별자
    "PlantID" VARCHAR(50) NOT NULL, -- [KS X 9101 표준] 공장식별자
    "CreatorID" VARCHAR(50), -- [KS X 9101 표준] 등록자식별자
    "CreationDateTime" TIMESTAMP, -- [KS X 9101 표준] 등록일시
    "ModifierID" VARCHAR(50), -- [KS X 9101 표준] 수정자식별자
    "ModificationDateTime" TIMESTAMP, -- [KS X 9101 표준] 수정일시
    "Note" VARCHAR(1000), -- [KS X 9101 표준] 비고
    "DepartmentID" VARCHAR(50) NOT NULL, -- [KS X 9101 표준] 부서식별자
    "DepartmentName" VARCHAR(200), -- [KS X 9101 표준] 부서명
    "ParentDepartmentID" VARCHAR(50), -- [KS X 9101 표준] 상위부서식별자
    CONSTRAINT "PK_Department" PRIMARY KEY ("DepartmentSequenceNo"),
    CONSTRAINT "UK_Department" UNIQUE ("EnterpriseID", "DepartmentID")
);

COMMENT ON TABLE "Department" IS '[KS X 9101 표준] 부서 (회사 내 하위 관리 단위로서의 부서를 의미한다.)';
COMMENT ON COLUMN "Department"."DepartmentSequenceNo" IS '[KS X 9101 표준] 부서 일련번호: — 테이블 행을 식별하는 일련번호(PK, 대리키) — 표준 외 물리 컬럼
— 자동 증가 값(IDENTITY)으로 부여하며 다른 테이블이 참조하지 않음(FK는 UK 참조)';
COMMENT ON COLUMN "Department"."EnterpriseID" IS '[KS X 9101 표준] 회사식별자: — 회사를 유일하게 구분할 수 있는 고유식별값
— 기업업무시스템 간의 연동을 수행하는 회사들 간에 자체적으로 정의한 고유식별값
— 참조 대상: 회사(Enterprise)';
COMMENT ON COLUMN "Department"."SiteID" IS '[KS X 9101 표준] 사업장식별자: — 회사 내에서 사업장을 구분할수 있는 고유식별값
— 참조 대상: 사업장(Site)';
COMMENT ON COLUMN "Department"."PlantID" IS '[KS X 9101 표준] 공장식별자: — 회사 내에서 공장을 구분할 수있는 고유식별값(만약, 공장 개념을 사용하지 않는다면 고정식별자로 설정하여 입력해야 함)
— 참조 대상: 공장(Plant)';
COMMENT ON COLUMN "Department"."CreatorID" IS '[KS X 9101 표준] 등록자식별자: — 정보를 처음으로 등록한 사람을 구분할 수 있는 고유식별값으로, 일반적으로 사원번호가사용됨
— 참조 대상: 사원(Personnel)';
COMMENT ON COLUMN "Department"."CreationDateTime" IS '[KS X 9101 표준] 등록일시: — 정보를 처음으로 등록한 날짜 (KS X ISO 8601을 따른다)';
COMMENT ON COLUMN "Department"."ModifierID" IS '[KS X 9101 표준] 수정자식별자: — 정보를 마지막으로 수정한 사람을 구분할 수 있는 고유식별값으로, 일반적으로 사원번호가 사용됨
— 참조 대상: 사원(Personnel)';
COMMENT ON COLUMN "Department"."ModificationDateTime" IS '[KS X 9101 표준] 수정일시: — 정보를 마지막으로 수정한 날짜 (KS X ISO 8601을 따른다.)';
COMMENT ON COLUMN "Department"."Note" IS '[KS X 9101 표준] 비고: — 비고사항';
COMMENT ON COLUMN "Department"."DepartmentID" IS '[KS X 9101 표준] 부서식별자: — 인사조직 중 부서를 식별하기 위한 고유값';
COMMENT ON COLUMN "Department"."DepartmentName" IS '[KS X 9101 표준] 부서명: — 부서 명칭';
COMMENT ON COLUMN "Department"."ParentDepartmentID" IS '[KS X 9101 표준] 상위부서식별자: — 해당 부서의 상위부서
— 참조 대상: 부서(Department)';

-- ---------------------------------------------------------------------
-- [표준 구분: KS X 9101 표준] 표 15, 조항 7.4.1.4 | 업무영역: 기준정보
-- 테이블명(물리): "Personnel" | 테이블명(논리): 사원
-- 설명: 사원코드, 사원명, 인적정보 등을 관리하는 사원 마스터를 의미한다. 일반적으로 HRMS(Human Resource Management System)에서 사용되지만 작업 스케줄링 또는 자원 할당에서 사용될 수도 있다.
-- ---------------------------------------------------------------------
CREATE TABLE "Personnel" ( -- [KS X 9101 표준] 사원 (표 15)
