COMMENT ON COLUMN "VendorPartyMaster"."DetailAddress" IS '[KS X 9101 표준] 상세주소: — 기본주소에 추가되는 공급사의 상세주소';
COMMENT ON COLUMN "VendorPartyMaster"."DialNumber" IS '[KS X 9101 표준] 전화번호: — 공급사의 대표전화번호';
COMMENT ON COLUMN "VendorPartyMaster"."FaxNumber" IS '[KS X 9101 표준] 팩스번호: — 공급사의 팩스번호';
