-- ---------------------------------------------------------------------
-- [표준 구분: KS X 9101 표준] 표 18, 조항 7.4.1.7 | 업무영역: 기준정보
-- 테이블명(물리): "CommonCodeMaster" | 테이블명(논리): 공통코드정보
-- 설명: 애플리케이션 내에서 사용되는 각종 코드를 모아 놓은 통합 코드를 의미한다.
-- ---------------------------------------------------------------------
CREATE TABLE "CommonCodeMaster" ( -- [KS X 9101 표준] 공통코드정보 (표 18)
    "CommonCodeMasterSequenceNo" BIGINT GENERATED BY DEFAULT AS IDENTITY, -- [KS X 9101 표준] 공통코드정보 일련번호(PK)
    "EnterpriseID" VARCHAR(50) NOT NULL, -- [KS X 9101 표준] 회사식별자
    "SiteID" VARCHAR(50) NOT NULL, -- [KS X 9101 표준] 사업장식별자
    "PlantID" VARCHAR(50) NOT NULL, -- [KS X 9101 표준] 공장식별자
    "CreatorID" VARCHAR(50), -- [KS X 9101 표준] 등록자식별자
    "CreationDateTime" TIMESTAMP, -- [KS X 9101 표준] 등록일시
    "ModifierID" VARCHAR(50), -- [KS X 9101 표준] 수정자식별자
    "ModificationDateTime" TIMESTAMP, -- [KS X 9101 표준] 수정일시
    "Note" VARCHAR(1000), -- [KS X 9101 표준] 비고
    "CommonCodeID" VARCHAR(50) NOT NULL, -- [KS X 9101 표준] 공통코드식별자
    "CommonCodeName" VARCHAR(200), -- [KS X 9101 표준] 공통코드명
    "CommonCodeGroup" VARCHAR(30) NOT NULL, -- [KS X 9101 표준] 공통코드그룹
    "ParentCommonCodeGroup" VARCHAR(50), -- [KS X 9101 표준] 상위공통코드그룹
    "ParentCommonCodeID" VARCHAR(50), -- [KS X 9101 표준] 상위공통코드식별자
    "CommonCodeSequence" INTEGER, -- [KS X 9101 표준] 표시순번
    "UseIndicator" BOOLEAN, -- [KS X 9101 표준] 사용여부
    CONSTRAINT "PK_CommonCodeMaster" PRIMARY KEY ("CommonCodeMasterSequenceNo"),
    CONSTRAINT "UK_CommonCodeMaster" UNIQUE ("EnterpriseID", "CommonCodeGroup", "CommonCodeID")
);

COMMENT ON TABLE "CommonCodeMaster" IS '[KS X 9101 표준] 공통코드정보 (애플리케이션 내에서 사용되는 각종 코드를 모아 놓은 통합 코드를 의미한다.)';
COMMENT ON COLUMN "CommonCodeMaster"."CommonCodeMasterSequenceNo" IS '[KS X 9101 표준] 공통코드정보 일련번호: — 테이블 행을 식별하는 일련번호(PK, 대리키) — 표준 외 물리 컬럼
— 자동 증가 값(IDENTITY)으로 부여하며 다른 테이블이 참조하지 않음(FK는 UK 참조)';
COMMENT ON COLUMN "CommonCodeMaster"."EnterpriseID" IS '[KS X 9101 표준] 회사식별자: — 회사를 유일하게 구분할 수 있는 고유식별값
— 기업업무시스템 간의 연동을 수행하는 회사들 간에 자체적으로 정의한 고유식별값
— 참조 대상: 회사(Enterprise)';
COMMENT ON COLUMN "CommonCodeMaster"."SiteID" IS '[KS X 9101 표준] 사업장식별자: — 회사 내에서 사업장을 구분할수 있는 고유식별값
— 참조 대상: 사업장(Site)';
COMMENT ON COLUMN "CommonCodeMaster"."PlantID" IS '[KS X 9101 표준] 공장식별자: — 회사 내에서 공장을 구분할 수있는 고유식별값(만약, 공장 개념을 사용하지 않는다면 고정식별자로 설정하여 입력해야 함)
— 참조 대상: 공장(Plant)';
COMMENT ON COLUMN "CommonCodeMaster"."CreatorID" IS '[KS X 9101 표준] 등록자식별자: — 정보를 처음으로 등록한 사람을 구분할 수 있는 고유식별값으로, 일반적으로 사원번호가사용됨
— 참조 대상: 사원(Personnel)';
COMMENT ON COLUMN "CommonCodeMaster"."CreationDateTime" IS '[KS X 9101 표준] 등록일시: — 정보를 처음으로 등록한 날짜 (KS X ISO 8601을 따른다)';
COMMENT ON COLUMN "CommonCodeMaster"."ModifierID" IS '[KS X 9101 표준] 수정자식별자: — 정보를 마지막으로 수정한 사람을 구분할 수 있는 고유식별값으로, 일반적으로 사원번호가 사용됨
— 참조 대상: 사원(Personnel)';
COMMENT ON COLUMN "CommonCodeMaster"."ModificationDateTime" IS '[KS X 9101 표준] 수정일시: — 정보를 마지막으로 수정한 날짜 (KS X ISO 8601을 따른다.)';
COMMENT ON COLUMN "CommonCodeMaster"."Note" IS '[KS X 9101 표준] 비고: — 비고사항';
COMMENT ON COLUMN "CommonCodeMaster"."CommonCodeID" IS '[KS X 9101 표준] 공통코드식별자: — 기준정보 외 시스템에서 공통적으로 사용되는 코드';
COMMENT ON COLUMN "CommonCodeMaster"."CommonCodeName" IS '[KS X 9101 표준] 공통코드명: — 공통코드 명칭';
COMMENT ON COLUMN "CommonCodeMaster"."CommonCodeGroup" IS '[KS X 9101 표준] 공통코드그룹: — 공통코드의 집합
— 공통코드그룹과 공통코드식별자의 조합은 회사 내에서 유일하다';
COMMENT ON COLUMN "CommonCodeMaster"."ParentCommonCodeGroup" IS '[KS X 9101 표준] 상위공통코드그룹: — 상위 코드가 속한 공통코드그룹
— 상위공통코드식별자(ParentCommonCodeID)와 함께 상위 코드를 가리키며, 계층이 없는 코드는 비워 둔다
— 참조 대상: 공통코드정보(CommonCodeMaster)';
COMMENT ON COLUMN "CommonCodeMaster"."ParentCommonCodeID" IS '[KS X 9101 표준] 상위공통코드식별자: — 상위 코드의 공통코드식별자
— 상위공통코드그룹(ParentCommonCodeGroup)과 함께 상위 코드를 가리킨다(예: 품목중분류 코드의 상위는 품목대분류 그룹의 코드)
— 참조 대상: 공통코드정보(CommonCodeMaster)';
COMMENT ON COLUMN "CommonCodeMaster"."CommonCodeSequence" IS '[KS X 9101 표준] 표시순번: — 공통코드가 화면에 표시되는 순서';
COMMENT ON COLUMN "CommonCodeMaster"."UseIndicator" IS '[KS X 9101 표준] 사용여부: — 공통코드의 사용 여부';

