-- 테이블명(물리): "UOMGroupLine" | 테이블명(논리): 단위그룹라인
-- 설명: 단위그룹(UOMGroup) 명사의 라인 구조체(struct[1..N]) 단위그룹에 속하는 단위코드 행 정보 단위그룹헤더 아래에 1회 이상 반복하여 나타남(1..N)
-- ---------------------------------------------------------------------
CREATE TABLE "UOMGroupLine" ( -- [KS X 9101 표준] 단위그룹라인 (표 20)
    "UOMGroupLineSequenceNo" BIGINT GENERATED BY DEFAULT AS IDENTITY, -- [KS X 9101 표준] 단위그룹라인 일련번호(PK)
    "EnterpriseID" VARCHAR(50) NOT NULL, -- [KS X 9101 표준] 회사식별자
    "SiteID" VARCHAR(50) NOT NULL, -- [KS X 9101 표준] 사업장식별자
    "PlantID" VARCHAR(50) NOT NULL, -- [KS X 9101 표준] 공장식별자
    "CreatorID" VARCHAR(50), -- [KS X 9101 표준] 등록자식별자
    "CreationDateTime" TIMESTAMP, -- [KS X 9101 표준] 등록일시
    "ModifierID" VARCHAR(50), -- [KS X 9101 표준] 수정자식별자
    "ModificationDateTime" TIMESTAMP, -- [KS X 9101 표준] 수정일시
    "Note" VARCHAR(1000), -- [KS X 9101 표준] 비고
    "UOMGroupID" VARCHAR(50) NOT NULL, -- [KS X 9101 표준] 단위그룹식별자
    "UOMCode" VARCHAR(20) NOT NULL, -- [KS X 9101 표준] 단위코드
    "UOMCodeName" VARCHAR(200), -- [KS X 9101 표준] 단위코드명
    "UseIndicator" BOOLEAN, -- [KS X 9101 표준] 사용여부
    CONSTRAINT "PK_UOMGroupLine" PRIMARY KEY ("UOMGroupLineSequenceNo"),
    CONSTRAINT "UK_UOMGroupLine" UNIQUE ("EnterpriseID", "UOMGroupID", "UOMCode")
);

