COMMENT ON COLUMN "UOMGroupLine"."ModifierID" IS '[KS X 9101 표준] 수정자식별자: — 정보를 마지막으로 수정한 사람을 구분할 수 있는 고유식별값으로, 일반적으로 사원번호가 사용됨
