— 참조 대상: 단위그룹헤더(UOMGroupHeader)';
COMMENT ON COLUMN "UOMGroupLine"."UOMCode" IS '[KS X 9101 표준] 단위코드: — 측정 단위를 식별하기 위한 고유값
— 단위코드는 대소문자를 구분한다
— 개수·포장 단위는 영문 대문자 약어로 표기(예: EA, DZ, HD, SET, BOX)
— 물리량 단위는 SI 단위 기호로 표기하고, 위첨자·특수기호는 UCUM 표기에 따라 ASCII 문자로 표기(예: mg, kg, mL, L, mm, cm3, m3, h, min, kPa, mV, Cel)
— 비율 단위는 영문 대문자 약어로 표기(예: PCT, RH, PPM)
— 외부 시스템과 교환할 때에는 UN/CEFACT 권고 20(Recommendation No. 20)의 단위 코드와 대응시켜 사용할 수 있음
— 단위그룹라인은 단위그룹식별자와 단위코드의 조합으로 구분함(라인 코드)';
COMMENT ON COLUMN "UOMGroupLine"."UOMCodeName" IS '[KS X 9101 표준] 단위코드명: — 단위의 명칭';
COMMENT ON COLUMN "UOMGroupLine"."UseIndicator" IS '[KS X 9101 표준] 사용여부: — 단위의 사용 여부';

