    "NetWeight" NUMERIC(18,6), -- [KS X 9101 표준] 순중량
    "WeightUOMCode" VARCHAR(20), -- [KS X 9101 표준] 중량단위코드
    "Volume" NUMERIC(18,6), -- [KS X 9101 표준] 부피
    "VolumeUOMCode" VARCHAR(20), -- [KS X 9101 표준] 부피단위코드
    "Length" NUMERIC(18,6), -- [KS X 9101 표준] 길이
    "Width" NUMERIC(18,6), -- [KS X 9101 표준] 너비
    "Height" NUMERIC(18,6), -- [KS X 9101 표준] 높이
    "DimensionUOMCode" VARCHAR(20), -- [KS X 9101 표준] 치수단위코드
    "ValidEndDate" DATE, -- [KS X 9101 표준] 유효종료일
    "DrawingNumber" VARCHAR(50), -- [KS X 9101 표준] 도면번호
    "LotControlIndicator" BOOLEAN, -- [KS X 9101 표준] 로트사용여부
    "PurchaseLeadTime" INTERVAL, -- [KS X 9101 표준] 구매리드타임
    "ProductionLeadTime" INTERVAL, -- [KS X 9101 표준] 생산리드타임
    "LotSize" NUMERIC(18,6), -- [KS X 9101 표준] 로트사이즈
    "MainCustomerID" VARCHAR(50), -- [KS X 9101 표준] 주요 고객사식별자
    "MainVendorID" VARCHAR(50), -- [KS X 9101 표준] 주요 공급사식별자
