    "FinalInspectionIndicator" BOOLEAN, -- [KS X 9101 표준] 생산입고(최종)검사여부
    "OutgoingInspectionIndicator" BOOLEAN, -- [KS X 9101 표준] 출하검사여부
    CONSTRAINT "PK_ItemMaster" PRIMARY KEY ("ItemMasterSequenceNo"),
    CONSTRAINT "UK_ItemMaster" UNIQUE ("EnterpriseID", "ItemID")
);

