COMMENT ON COLUMN "ItemMaster"."ModificationDateTime" IS '[KS X 9101 표준] 수정일시: — 정보를 마지막으로 수정한 날짜 (KS X ISO 8601을 따른다.)';
COMMENT ON COLUMN "ItemMaster"."Note" IS '[KS X 9101 표준] 비고: — 비고사항';
COMMENT ON COLUMN "ItemMaster"."ItemID" IS '[KS X 9101 표준] 품목식별자: — 품목을 식별하기 위한 고유값
— 제품, 반제품, 상품, 원자재, 부자재, 저장품, 소모품 등 회사 내 시스템으로 관리되는 모든 품목을 포함';
COMMENT ON COLUMN "ItemMaster"."ItemName" IS '[KS X 9101 표준] 품목명: — 품목의 명칭';
COMMENT ON COLUMN "ItemMaster"."ItemType" IS '[KS X 9101 표준] 품목유형: — 품목의 유형(상품, 제품, 원자재, 반제품 등)
— 참조 대상: 공통코드정보(CommonCodeMaster)의 코드';
COMMENT ON COLUMN "ItemMaster"."PhantomIndicator" IS '[KS X 9101 표준] 가상품목여부: — 가상 품목으로 지정여부';
COMMENT ON COLUMN "ItemMaster"."ItemLargeClass" IS '[KS X 9101 표준] 품목대분류: — 품목이 속한 품목대분류
— 품목대분류는 공통코드에 등록하여 관리하며 회사 기준 분류체계에 의해 정해짐
— 예: 금속소재, 수지소재, 전자부품, 기계부품, 포장자재 등
— 참조 대상: 공통코드정보(CommonCodeMaster)의 코드';
COMMENT ON COLUMN "ItemMaster"."ItemMediumClass" IS '[KS X 9101 표준] 품목중분류: — 품목이 속한 품목중분류(품목대분류 하위에 속함)
— 품목중분류는 공통코드에 등록하여 관리하며 회사 기준 분류체계에 의해 정해짐
— 예: 품목대분류 금속소재 하위의 철강, 알루미늄, 동 등
— 참조 대상: 공통코드정보(CommonCodeMaster)의 코드';
COMMENT ON COLUMN "ItemMaster"."ItemSmallClass" IS '[KS X 9101 표준] 품목소분류: — 품목이 속한 품목소분류(품목중분류 하위에 속함)
— 품목소분류는 공통코드에 등록하여 관리하며 회사 기준 분류체계에 의해 정해짐
— 예: 품목중분류 철강 하위의 강판, 봉강, 강관 등
— 참조 대상: 공통코드정보(CommonCodeMaster)의 코드';
COMMENT ON COLUMN "ItemMaster"."ModelName" IS '[KS X 9101 표준] 모델명: — 제품의 모델명';
COMMENT ON COLUMN "ItemMaster"."ItemSpecification" IS '[KS X 9101 표준] 품목사양: — 품목의 사양 또는 규격';
COMMENT ON COLUMN "ItemMaster"."ItemDetailSpecification" IS '[KS X 9101 표준] 품목상세사양: — 품목의 상세사양 또는 상세규격';
COMMENT ON COLUMN "ItemMaster"."UseIndicator" IS '[KS X 9101 표준] 사용여부: — 품목의 사용 여부';
COMMENT ON COLUMN "ItemMaster"."CountryOfOrigin" IS '[KS X 9101 표준] 원산국가: — 품목의 원산 국가';
COMMENT ON COLUMN "ItemMaster"."PlaceOfOrigin" IS '[KS X 9101 표준] 원산지역: — 품목의 원산 지역';
COMMENT ON COLUMN "ItemMaster"."ItemUOMCode" IS '[KS X 9101 표준] 기준단위코드: — 기준단위코드(예: EA, DZ, HD 등)
— 참조 대상: 단위그룹(UOMGroup)의 단위코드';
COMMENT ON COLUMN "ItemMaster"."Weight" IS '[KS X 9101 표준] 중량: — 포장까지 완료된 품목의 중량(중량의 단위는 중량단위코드로 함)';
COMMENT ON COLUMN "ItemMaster"."NetWeight" IS '[KS X 9101 표준] 순중량: — 품목의 순중량(중량의 단위는 중량단위코드로 함)';
COMMENT ON COLUMN "ItemMaster"."WeightUOMCode" IS '[KS X 9101 표준] 중량단위코드: — 품목의 중량을 측정하는 단위의 코드(예: mg, g, kg, t 등)
— 참조 대상: 단위그룹(UOMGroup)의 단위코드';
COMMENT ON COLUMN "ItemMaster"."Volume" IS '[KS X 9101 표준] 부피: — 품목의 부피(부피의 단위는 부피단위코드로 함)';
COMMENT ON COLUMN "ItemMaster"."VolumeUOMCode" IS '[KS X 9101 표준] 부피단위코드: — 품목의 부피를 측정하는 단위의 코드(예: cm³, m³ 등)
— 참조 대상: 단위그룹(UOMGroup)의 단위코드';
COMMENT ON COLUMN "ItemMaster"."Length" IS '[KS X 9101 표준] 길이: — 품목의 길이(길이의 단위는 치수단위코드로 함)';
COMMENT ON COLUMN "ItemMaster"."Width" IS '[KS X 9101 표준] 너비: — 품목의 너비(너비의 단위는 치수단위코드로 함)';
COMMENT ON COLUMN "ItemMaster"."Height" IS '[KS X 9101 표준] 높이: — 품목의 높이(높이의 단위는 치수단위코드로 함)';
COMMENT ON COLUMN "ItemMaster"."DimensionUOMCode" IS '[KS X 9101 표준] 치수단위코드: — 품목의 길이/너비/높이를 측정하는 단위의 코드(예: mm, cm, m, km 등)
— 참조 대상: 단위그룹(UOMGroup)의 단위코드';
COMMENT ON COLUMN "ItemMaster"."ValidEndDate" IS '[KS X 9101 표준] 유효종료일: — 품목사용이 유효한 기한(KS X ISO 8601을 따른다)';
COMMENT ON COLUMN "ItemMaster"."DrawingNumber" IS '[KS X 9101 표준] 도면번호: — 품목의 도면 식별번호';
COMMENT ON COLUMN "ItemMaster"."LotControlIndicator" IS '[KS X 9101 표준] 로트사용여부: — 품목의 로트 단위로 관리 여부';
COMMENT ON COLUMN "ItemMaster"."PurchaseLeadTime" IS '[KS X 9101 표준] 구매리드타임: — 구매에 소요되는 총 소요일수(KS X ISO 8601을 따른다)';
COMMENT ON COLUMN "ItemMaster"."ProductionLeadTime" IS '[KS X 9101 표준] 생산리드타임: — 생산에 소요되는 총 소요일수(KS X ISO 8601을 따른다)';
COMMENT ON COLUMN "ItemMaster"."LotSize" IS '[KS X 9101 표준] 로트사이즈: — 품목의 물류 이동 단위';
COMMENT ON COLUMN "ItemMaster"."MainCustomerID" IS '[KS X 9101 표준] 주요 고객사식별자: — 품목과 연관된 주요 매출처
— 참조 대상: 고객사(CustomerPartyMaster)';
COMMENT ON COLUMN "ItemMaster"."MainVendorID" IS '[KS X 9101 표준] 주요 공급사식별자: — 품목과 연관된 주요 매입처
— 참조 대상: 공급사(VendorPartyMaster)';
COMMENT ON COLUMN "ItemMaster"."SafetyStock" IS '[KS X 9101 표준] 안전재고: — 예측 잘못이나 잦은 계획 변경에서 비롯된 문제점을 방지하기 위한안전재고
— 통상적으로 생산계획에서 재고수량 하한치를 의미';
COMMENT ON COLUMN "ItemMaster"."MaximumStockLevel" IS '[KS X 9101 표준] 최대재고수준: — 품목의 재고수량 상한치';
COMMENT ON COLUMN "ItemMaster"."ReceiptWarehouseID" IS '[KS X 9101 표준] 입고창고식별자: — 품목의 기본 입고 창고(저장위치)
— 참조 대상: 창고(WarehouseLocation)';
COMMENT ON COLUMN "ItemMaster"."IssueWarehouseID" IS '[KS X 9101 표준] 출고창고식별자: — 품목의 기본 출고 창고(저장위치)
— 참조 대상: 창고(WarehouseLocation)';
COMMENT ON COLUMN "ItemMaster"."ABCClass" IS '[KS X 9101 표준] 에이비씨분류: — 품목의 재고관리를 위해 A, B, C의 세 종류로 분류
— ABC 분류는 각 회사에서 A, B, C 기준을 이용하여 관리하는 방식
— 참조 대상: 공통코드정보(CommonCodeMaster)의 코드';
COMMENT ON COLUMN "ItemMaster"."ReplacementItemID" IS '[KS X 9101 표준] 대체품목식별자: — 품목 대신 사용할 수 있는 대체품목의 고유식별값
— 참조 대상: 품목마스터(ItemMaster)';
COMMENT ON COLUMN "ItemMaster"."IncomingInspectionIndicator" IS '[KS X 9101 표준] 수입검사여부: — 구매품목을 입고하기 전 검사 여부';
COMMENT ON COLUMN "ItemMaster"."FinalInspectionIndicator" IS '[KS X 9101 표준] 생산입고(최종)검사여부: — 생산품목의 제조과정 중 마지막 공정까지 완료한 상태에서 창고에 입고 전 검사 여부';
COMMENT ON COLUMN "ItemMaster"."OutgoingInspectionIndicator" IS '[KS X 9101 표준] 출하검사여부: — 고객에게 제품 또는 상품이 출하(출고)되기 전 검사 여부';

-- ---------------------------------------------------------------------
-- [표준 구분: KS X 9101 표준] 표 22, 조항 7.4.1.11 | 업무영역: 기준정보
-- 테이블명(물리): "BOMHeader" | 테이블명(논리): 자재명세서헤더
-- 설명: 자재명세서(BOM) 명사의 헤더 구조체(struct) 자재명세서 1건의 공통 정보(모품목, 버전, 유형, 공정경로) 자재명세서마다 1회 나타남
-- ---------------------------------------------------------------------
CREATE TABLE "BOMHeader" ( -- [KS X 9101 표준] 자재명세서헤더 (표 22)
    "BOMHeaderSequenceNo" BIGINT GENERATED BY DEFAULT AS IDENTITY, -- [KS X 9101 표준] 자재명세서헤더 일련번호(PK)
    "EnterpriseID" VARCHAR(50) NOT NULL, -- [KS X 9101 표준] 회사식별자
    "SiteID" VARCHAR(50) NOT NULL, -- [KS X 9101 표준] 사업장식별자
    "PlantID" VARCHAR(50) NOT NULL, -- [KS X 9101 표준] 공장식별자
    "CreatorID" VARCHAR(50), -- [KS X 9101 표준] 등록자식별자
    "CreationDateTime" TIMESTAMP, -- [KS X 9101 표준] 등록일시
    "ModifierID" VARCHAR(50), -- [KS X 9101 표준] 수정자식별자
    "ModificationDateTime" TIMESTAMP, -- [KS X 9101 표준] 수정일시
    "Note" VARCHAR(1000), -- [KS X 9101 표준] 비고
    "BOMID" VARCHAR(50) NOT NULL, -- [KS X 9101 표준] 자재명세서식별자
    "BOMRevisionNumber" INTEGER NOT NULL, -- [KS X 9101 표준] 자재명세서버전
    "BOMType" VARCHAR(30), -- [KS X 9101 표준] 자재명세서유형
    "ItemID" VARCHAR(50), -- [KS X 9101 표준] 품목식별자
    "BOMQuantity" NUMERIC(18,6), -- [KS X 9101 표준] 품목기준수량
    "ItemUOMCode" VARCHAR(20), -- [KS X 9101 표준] 기준단위코드
    "RoutingID" VARCHAR(50), -- [KS X 9101 표준] 공정경로식별자
    CONSTRAINT "PK_BOMHeader" PRIMARY KEY ("BOMHeaderSequenceNo"),
    CONSTRAINT "UK_BOMHeader" UNIQUE ("EnterpriseID", "BOMID", "BOMRevisionNumber")
);

COMMENT ON TABLE "BOMHeader" IS '[KS X 9101 표준] 자재명세서헤더 (자재명세서(BOM) 명사의 헤더 구조체(struct) 자재명세서 1건의 공통 정보(모품목, 버전, 유형, 공정경로) 자재명세서마다 1회 나타남)';
COMMENT ON COLUMN "BOMHeader"."BOMHeaderSequenceNo" IS '[KS X 9101 표준] 자재명세서헤더 일련번호: — 테이블 행을 식별하는 일련번호(PK, 대리키) — 표준 외 물리 컬럼
— 자동 증가 값(IDENTITY)으로 부여하며 다른 테이블이 참조하지 않음(FK는 UK 참조)';
COMMENT ON COLUMN "BOMHeader"."EnterpriseID" IS '[KS X 9101 표준] 회사식별자: — 회사를 유일하게 구분할 수 있는 고유식별값
— 기업업무시스템 간의 연동을 수행하는 회사들 간에 자체적으로 정의한 고유식별값
— 참조 대상: 회사(Enterprise)';
COMMENT ON COLUMN "BOMHeader"."SiteID" IS '[KS X 9101 표준] 사업장식별자: — 회사 내에서 사업장을 구분할수 있는 고유식별값
— 참조 대상: 사업장(Site)';
COMMENT ON COLUMN "BOMHeader"."PlantID" IS '[KS X 9101 표준] 공장식별자: — 회사 내에서 공장을 구분할 수있는 고유식별값(만약, 공장 개념을 사용하지 않는다면 고정식별자로 설정하여 입력해야 함)
— 참조 대상: 공장(Plant)';
COMMENT ON COLUMN "BOMHeader"."CreatorID" IS '[KS X 9101 표준] 등록자식별자: — 정보를 처음으로 등록한 사람을 구분할 수 있는 고유식별값으로, 일반적으로 사원번호가사용됨
— 참조 대상: 사원(Personnel)';
COMMENT ON COLUMN "BOMHeader"."CreationDateTime" IS '[KS X 9101 표준] 등록일시: — 정보를 처음으로 등록한 날짜 (KS X ISO 8601을 따른다)';
COMMENT ON COLUMN "BOMHeader"."ModifierID" IS '[KS X 9101 표준] 수정자식별자: — 정보를 마지막으로 수정한 사람을 구분할 수 있는 고유식별값으로, 일반적으로 사원번호가 사용됨
— 참조 대상: 사원(Personnel)';
COMMENT ON COLUMN "BOMHeader"."ModificationDateTime" IS '[KS X 9101 표준] 수정일시: — 정보를 마지막으로 수정한 날짜 (KS X ISO 8601을 따른다.)';
COMMENT ON COLUMN "BOMHeader"."Note" IS '[KS X 9101 표준] 비고: — 비고사항';
COMMENT ON COLUMN "BOMHeader"."BOMID" IS '[KS X 9101 표준] 자재명세서식별자: — 자재명세서를 식별하기 위한 고유값
— 모품목의 자재명세서 단위로 부여하며, 자재명세서헤더에 1회 기재함';
COMMENT ON COLUMN "BOMHeader"."BOMRevisionNumber" IS '[KS X 9101 표준] 자재명세서버전: — 자재명세서의 버전
— 자재명세서는 자재명세서식별자와 자재명세서버전의 조합으로 식별함';
COMMENT ON COLUMN "BOMHeader"."BOMType" IS '[KS X 9101 표준] 자재명세서유형: — 자재명세서의 유형
— 예: 제조BOM, 원가BOM 등
— 참조 대상: 공통코드정보(CommonCodeMaster)의 코드';
COMMENT ON COLUMN "BOMHeader"."ItemID" IS '[KS X 9101 표준] 품목식별자: — 품목을 식별하기 위한 고유값
— 제품, 반제품, 상품, 원자재, 부자재, 저장품, 소모품 등 회사 내시스템으로 관리되는 모든 품목을 포함
— 참조 대상: 품목마스터(ItemMaster)';
COMMENT ON COLUMN "BOMHeader"."BOMQuantity" IS '[KS X 9101 표준] 품목기준수량: — 자재명세서를 구성하는 품목의 기준수량(수량의 단위는 기준단위코드로 함)
— 예: 모품목기준수량이 1 EA이면 1 EA를 생산하기 위해 필요한 BOM이고 100 EA이면 100 EA를 생산하기 위해 필요한 BOM을의미';
COMMENT ON COLUMN "BOMHeader"."ItemUOMCode" IS '[KS X 9101 표준] 기준단위코드: — 기준단위코드(예: EA, DZ, HD 등)
— 참조 대상: 단위그룹(UOMGroup)의 단위코드';
COMMENT ON COLUMN "BOMHeader"."RoutingID" IS '[KS X 9101 표준] 공정경로식별자: — 공정경로의 고유식별값
— BOM유형이 제조BOM 또는 생산BOM일 때 사용
— 참조 대상: 공정경로(Routing)';

-- ---------------------------------------------------------------------
-- [표준 구분: KS X 9101 표준] 표 22, 조항 7.4.1.11 | 업무영역: 기준정보
-- 테이블명(물리): "BOMLine" | 테이블명(논리): 자재명세서라인
-- 설명: 자재명세서(BOM) 명사의 라인 구조체(struct[1..N]) 자재명세서를 구성하는 자품목 행 정보 자재명세서헤더 아래에 1회 이상 반복하여 나타남(1..N)
-- ---------------------------------------------------------------------
CREATE TABLE "BOMLine" ( -- [KS X 9101 표준] 자재명세서라인 (표 22)
    "BOMLineSequenceNo" BIGINT GENERATED BY DEFAULT AS IDENTITY, -- [KS X 9101 표준] 자재명세서라인 일련번호(PK)
    "EnterpriseID" VARCHAR(50) NOT NULL, -- [KS X 9101 표준] 회사식별자
    "SiteID" VARCHAR(50) NOT NULL, -- [KS X 9101 표준] 사업장식별자
    "PlantID" VARCHAR(50) NOT NULL, -- [KS X 9101 표준] 공장식별자
    "CreatorID" VARCHAR(50), -- [KS X 9101 표준] 등록자식별자
    "CreationDateTime" TIMESTAMP, -- [KS X 9101 표준] 등록일시
    "ModifierID" VARCHAR(50), -- [KS X 9101 표준] 수정자식별자
    "ModificationDateTime" TIMESTAMP, -- [KS X 9101 표준] 수정일시
    "Note" VARCHAR(1000), -- [KS X 9101 표준] 비고
    "BOMID" VARCHAR(50) NOT NULL, -- [KS X 9101 표준] 자재명세서식별자
    "BOMRevisionNumber" INTEGER NOT NULL, -- [KS X 9101 표준] 자재명세서버전
    "BOMLineSequence" INTEGER NOT NULL, -- [KS X 9101 표준] 자재명세서라인순번
    "ChildItemID" VARCHAR(50), -- [KS X 9101 표준] 자품목식별자
    "ChildItemUOMCode" VARCHAR(20), -- [KS X 9101 표준] 자품목기준단위코드
    "ActualRequirementQuantity" NUMERIC(18,6), -- [KS X 9101 표준] 실소요수량
    "OperationSequence" INTEGER, -- [KS X 9101 표준] 공정순번
    "BackFlushedIndicator" BOOLEAN, -- [KS X 9101 표준] 백플러시여부
    "ValidStartDateTime" TIMESTAMP, -- [KS X 9101 표준] 유효시작일시
    "ValidEndDateTime" TIMESTAMP, -- [KS X 9101 표준] 유효종료일시
    CONSTRAINT "PK_BOMLine" PRIMARY KEY ("BOMLineSequenceNo"),
    CONSTRAINT "UK_BOMLine" UNIQUE ("EnterpriseID", "BOMID", "BOMRevisionNumber", "BOMLineSequence")
);

COMMENT ON TABLE "BOMLine" IS '[KS X 9101 표준] 자재명세서라인 (자재명세서(BOM) 명사의 라인 구조체(struct[1..N]) 자재명세서를 구성하는 자품목 행 정보 자재명세서헤더 아래에 1회 이상 반복하여 나타남(1..N))';
COMMENT ON COLUMN "BOMLine"."BOMLineSequenceNo" IS '[KS X 9101 표준] 자재명세서라인 일련번호: — 테이블 행을 식별하는 일련번호(PK, 대리키) — 표준 외 물리 컬럼
— 자동 증가 값(IDENTITY)으로 부여하며 다른 테이블이 참조하지 않음(FK는 UK 참조)';
COMMENT ON COLUMN "BOMLine"."EnterpriseID" IS '[KS X 9101 표준] 회사식별자: — 회사를 유일하게 구분할 수 있는 고유식별값
— 기업업무시스템 간의 연동을 수행하는 회사들 간에 자체적으로 정의한 고유식별값
— 참조 대상: 회사(Enterprise)';
COMMENT ON COLUMN "BOMLine"."SiteID" IS '[KS X 9101 표준] 사업장식별자: — 회사 내에서 사업장을 구분할수 있는 고유식별값
— 참조 대상: 사업장(Site)';
COMMENT ON COLUMN "BOMLine"."PlantID" IS '[KS X 9101 표준] 공장식별자: — 회사 내에서 공장을 구분할 수있는 고유식별값(만약, 공장 개념을 사용하지 않는다면 고정식별자로 설정하여 입력해야 함)
— 참조 대상: 공장(Plant)';
COMMENT ON COLUMN "BOMLine"."CreatorID" IS '[KS X 9101 표준] 등록자식별자: — 정보를 처음으로 등록한 사람을 구분할 수 있는 고유식별값으로, 일반적으로 사원번호가사용됨
— 참조 대상: 사원(Personnel)';
COMMENT ON COLUMN "BOMLine"."CreationDateTime" IS '[KS X 9101 표준] 등록일시: — 정보를 처음으로 등록한 날짜 (KS X ISO 8601을 따른다)';
COMMENT ON COLUMN "BOMLine"."ModifierID" IS '[KS X 9101 표준] 수정자식별자: — 정보를 마지막으로 수정한 사람을 구분할 수 있는 고유식별값으로, 일반적으로 사원번호가 사용됨
— 참조 대상: 사원(Personnel)';
COMMENT ON COLUMN "BOMLine"."ModificationDateTime" IS '[KS X 9101 표준] 수정일시: — 정보를 마지막으로 수정한 날짜 (KS X ISO 8601을 따른다.)';
COMMENT ON COLUMN "BOMLine"."Note" IS '[KS X 9101 표준] 비고: — 비고사항';
COMMENT ON COLUMN "BOMLine"."BOMID" IS '[KS X 9101 표준] 자재명세서식별자: — 자재명세서를 식별하기 위한 고유값
— 참조 대상: 자재명세서헤더(BOMHeader)';
COMMENT ON COLUMN "BOMLine"."BOMRevisionNumber" IS '[KS X 9101 표준] 자재명세서버전: — 자재명세서의 버전
— 자재명세서식별자(BOMID)와 함께 자재명세서헤더(BOMHeader)를 참조한다';
COMMENT ON COLUMN "BOMLine"."BOMLineSequence" IS '[KS X 9101 표준] 자재명세서라인순번: — 자재명세서 내 자품목 행의 순서
— 자재명세서라인은 자재명세서식별자, 자재명세서버전, 자재명세서라인순번의 조합으로 구분하며, 같은 자품목을 여러 공정에 나누어 투입하는 경우에도 행을 구분함';
COMMENT ON COLUMN "BOMLine"."ChildItemID" IS '[KS X 9101 표준] 자품목식별자: — 대상 품목을 생산하기 위해 투입되는 품목
— 참조 대상: 품목마스터(ItemMaster)';
COMMENT ON COLUMN "BOMLine"."ChildItemUOMCode" IS '[KS X 9101 표준] 자품목기준단위코드: — 대상 품목을 생산하기 위해 투입되는 품목의 기준단위(예: EA, DZ, HD 등)
— 참조 대상: 단위그룹(UOMGroup)의 단위코드';
COMMENT ON COLUMN "BOMLine"."ActualRequirementQuantity" IS '[KS X 9101 표준] 실소요수량: — 대상 품목을 생산하기 위해 투입되는 품목의 소요량(예: EA, DZ, HD 등)';
COMMENT ON COLUMN "BOMLine"."OperationSequence" IS '[KS X 9101 표준] 공정순번: — 공정경로를 구성하는 공정의 순서
— 공정경로식별자(RoutingID)와 함께 공정경로(Routing)를 참조한다';
COMMENT ON COLUMN "BOMLine"."BackFlushedIndicator" IS '[KS X 9101 표준] 백플러시여부: — 생산 완료 시점에 모품목을 만들기 위해 소요되는 자품목의 생산투입 수량 일괄 처리 여부';
COMMENT ON COLUMN "BOMLine"."ValidStartDateTime" IS '[KS X 9101 표준] 유효시작일시: — 자품목 행의 적용이 시작되는 일시(KS X ISO 8601을 따른다)';
COMMENT ON COLUMN "BOMLine"."ValidEndDateTime" IS '[KS X 9101 표준] 유효종료일시: — 자품목 행의 적용이 종료되는 일시(KS X ISO 8601을 따른다)';

-- ---------------------------------------------------------------------
-- [표준 구분: KS X 9101 표준] 표 23, 조항 7.4.1.12 | 업무영역: 기준정보
-- 테이블명(물리): "Lot" | 테이블명(논리): 로트
-- 설명: 묶음 생산 단위의 정보를 의미한다.
-- ---------------------------------------------------------------------
CREATE TABLE "Lot" ( -- [KS X 9101 표준] 로트 (표 23)
    "LotSequenceNo" BIGINT GENERATED BY DEFAULT AS IDENTITY, -- [KS X 9101 표준] 로트 일련번호(PK)
    "EnterpriseID" VARCHAR(50) NOT NULL, -- [KS X 9101 표준] 회사식별자
    "SiteID" VARCHAR(50) NOT NULL, -- [KS X 9101 표준] 사업장식별자
    "PlantID" VARCHAR(50) NOT NULL, -- [KS X 9101 표준] 공장식별자
    "CreatorID" VARCHAR(50), -- [KS X 9101 표준] 등록자식별자
    "CreationDateTime" TIMESTAMP, -- [KS X 9101 표준] 등록일시
    "ModifierID" VARCHAR(50), -- [KS X 9101 표준] 수정자식별자
    "ModificationDateTime" TIMESTAMP, -- [KS X 9101 표준] 수정일시
    "Note" VARCHAR(1000), -- [KS X 9101 표준] 비고
    "LotID" VARCHAR(50) NOT NULL, -- [KS X 9101 표준] 로트식별자
    "LotName" VARCHAR(200), -- [KS X 9101 표준] 로트명
    "LotDescription" VARCHAR(1000), -- [KS X 9101 표준] 로트설명
    "ParentLotID" VARCHAR(50), -- [KS X 9101 표준] 모로트식별자
    "ChildLotID" VARCHAR(50), -- [KS X 9101 표준] 자로트식별자
    "LotType" VARCHAR(30), -- [KS X 9101 표준] 로트유형
    "ItemID" VARCHAR(50), -- [KS X 9101 표준] 품목식별자
    "CarrierID" VARCHAR(50), -- [KS X 9101 표준] 캐리어식별자
    "ProductionOrderID" VARCHAR(50), -- [KS X 9101 표준] 생산지시식별자
    "ProductionOrderSequence" INTEGER, -- [KS X 9101 표준] 생산지시순번
    "ScheduledDueDate" DATE, -- [KS X 9101 표준] 생산마감기한
    "LotPriority" INTEGER, -- [KS X 9101 표준] 로트우선순위
    "CurrentOperationID" VARCHAR(50), -- [KS X 9101 표준] 현재공정식별자
    "NextOperationID" VARCHAR(50), -- [KS X 9101 표준] 다음공정식별자
    "LotState" VARCHAR(30), -- [KS X 9101 표준] 로트상태
    "HoldIndicator" BOOLEAN, -- [KS X 9101 표준] 보류여부
    "HotIndicator" BOOLEAN, -- [KS X 9101 표준] 긴급여부
    "ReworkIndicator" BOOLEAN, -- [KS X 9101 표준] 재작업여부
    "LotCreatedQuantity" NUMERIC(18,6), -- [KS X 9101 표준] 로트수량
    "ProducedQuantity" NUMERIC(18,6), -- [KS X 9101 표준] 생산수량
    "DefectQuantity" NUMERIC(18,6), -- [KS X 9101 표준] 불량수량
    "ReworkQuantity" INTEGER, -- [KS X 9101 표준] 재작업수량
    "ReworkCount" INTEGER, -- [KS X 9101 표준] 재작업횟수
    "TotalReworkCount" INTEGER, -- [KS X 9101 표준] 총재작업횟수
    "LotStartedDateTime" TIMESTAMP, -- [KS X 9101 표준] 공정투입일시
    "PersonnelID" VARCHAR(50), -- [KS X 9101 표준] 사원식별자
    CONSTRAINT "PK_Lot" PRIMARY KEY ("LotSequenceNo"),
    CONSTRAINT "UK_Lot" UNIQUE ("EnterpriseID", "LotID")
);

COMMENT ON TABLE "Lot" IS '[KS X 9101 표준] 로트 (묶음 생산 단위의 정보를 의미한다.)';
COMMENT ON COLUMN "Lot"."LotSequenceNo" IS '[KS X 9101 표준] 로트 일련번호: — 테이블 행을 식별하는 일련번호(PK, 대리키) — 표준 외 물리 컬럼
— 자동 증가 값(IDENTITY)으로 부여하며 다른 테이블이 참조하지 않음(FK는 UK 참조)';
COMMENT ON COLUMN "Lot"."EnterpriseID" IS '[KS X 9101 표준] 회사식별자: — 회사를 유일하게 구분할 수 있는 고유식별값
— 기업업무시스템 간의 연동을 수행하는 회사들 간에 자체적으로 정의한 고유식별값
— 참조 대상: 회사(Enterprise)';
COMMENT ON COLUMN "Lot"."SiteID" IS '[KS X 9101 표준] 사업장식별자: — 회사 내에서 사업장을 구분할수 있는 고유식별값
— 참조 대상: 사업장(Site)';
COMMENT ON COLUMN "Lot"."PlantID" IS '[KS X 9101 표준] 공장식별자: — 회사 내에서 공장을 구분할 수있는 고유식별값(만약, 공장 개념을 사용하지 않는다면 고정식별자로 설정하여 입력해야 함)
— 참조 대상: 공장(Plant)';
COMMENT ON COLUMN "Lot"."CreatorID" IS '[KS X 9101 표준] 등록자식별자: — 정보를 처음으로 등록한 사람을 구분할 수 있는 고유식별값으로, 일반적으로 사원번호가사용됨
— 참조 대상: 사원(Personnel)';
COMMENT ON COLUMN "Lot"."CreationDateTime" IS '[KS X 9101 표준] 등록일시: — 정보를 처음으로 등록한 날짜 (KS X ISO 8601을 따른다)';
COMMENT ON COLUMN "Lot"."ModifierID" IS '[KS X 9101 표준] 수정자식별자: — 정보를 마지막으로 수정한 사람을 구분할 수 있는 고유식별값으로, 일반적으로 사원번호가 사용됨
— 참조 대상: 사원(Personnel)';
COMMENT ON COLUMN "Lot"."ModificationDateTime" IS '[KS X 9101 표준] 수정일시: — 정보를 마지막으로 수정한 날짜 (KS X ISO 8601을 따른다.)';
COMMENT ON COLUMN "Lot"."Note" IS '[KS X 9101 표준] 비고: — 비고사항';
COMMENT ON COLUMN "Lot"."LotID" IS '[KS X 9101 표준] 로트식별자: — 로트를 식별하기 위한 고유값';
COMMENT ON COLUMN "Lot"."LotName" IS '[KS X 9101 표준] 로트명: — 로트의 명칭';
COMMENT ON COLUMN "Lot"."LotDescription" IS '[KS X 9101 표준] 로트설명: — 로트 설명 정보';
COMMENT ON COLUMN "Lot"."ParentLotID" IS '[KS X 9101 표준] 모로트식별자: — Split, Merge, Transfer 등을 통하여 파생된 자 ID일 경우 이전 부모 로트 식별자
— 참조 대상: 로트(Lot)';
COMMENT ON COLUMN "Lot"."ChildLotID" IS '[KS X 9101 표준] 자로트식별자: — Split, Merge, Transfer 등을 통하여 파생한 자 로트 식별자
— 참조 대상: 로트(Lot)';
COMMENT ON COLUMN "Lot"."LotType" IS '[KS X 9101 표준] 로트유형: — 로트 유형(예: Production, Development, Engineering 등)
— 참조 대상: 공통코드정보(CommonCodeMaster)의 코드';
COMMENT ON COLUMN "Lot"."ItemID" IS '[KS X 9101 표준] 품목식별자: — 품목을 식별하기 위한 고유값
— 제품, 반제품, 상품, 원자재, 부자재, 저장품, 소모품 등 회사 내시스템으로 관리되는 모든 품목을 포함
— 참조 대상: 품목마스터(ItemMaster)';
COMMENT ON COLUMN "Lot"."CarrierID" IS '[KS X 9101 표준] 캐리어식별자: — 캐리어를 식별하기 위한 고유값
— 참조 대상: 캐리어(Carrier)';
COMMENT ON COLUMN "Lot"."ProductionOrderID" IS '[KS X 9101 표준] 생산지시식별자: — 생산지시를 식별하기 위한 고유값
— 참조 대상: 생산지시(ProductionOrder)';
COMMENT ON COLUMN "Lot"."ProductionOrderSequence" IS '[KS X 9101 표준] 생산지시순번: — 생산지시식별자 내 순서
— 생산지시식별자(ProductionOrderID)와 함께 생산지시(ProductionOrder)를 참조한다';
COMMENT ON COLUMN "Lot"."ScheduledDueDate" IS '[KS X 9101 표준] 생산마감기한: — 로트의 생산을 완료하는 마감일';
COMMENT ON COLUMN "Lot"."LotPriority" IS '[KS X 9101 표준] 로트우선순위: — 로트의 생산 투입 및 공정을 진행하는 순위';
COMMENT ON COLUMN "Lot"."CurrentOperationID" IS '[KS X 9101 표준] 현재공정식별자: — 현재 진행중인 공정을 식별하기 위한 고유값
— 참조 대상: 공정(Operation)';
COMMENT ON COLUMN "Lot"."NextOperationID" IS '[KS X 9101 표준] 다음공정식별자: — 다음 번째 진행할 공정을 식별하기 위한 고유값
— 참조 대상: 공정(Operation)';
COMMENT ON COLUMN "Lot"."LotState" IS '[KS X 9101 표준] 로트상태: — 로트의 상태(예: Open(등록), Release(발행), Start(시작), Closing(마감 또는 종료))
— 참조 대상: 공통코드정보(CommonCodeMaster)의 코드';
COMMENT ON COLUMN "Lot"."HoldIndicator" IS '[KS X 9101 표준] 보류여부: — 공정 작업 보류 여부';
COMMENT ON COLUMN "Lot"."HotIndicator" IS '[KS X 9101 표준] 긴급여부: — 긴급 작업 여부';
COMMENT ON COLUMN "Lot"."ReworkIndicator" IS '[KS X 9101 표준] 재작업여부: — 재작업 진행 여부';
COMMENT ON COLUMN "Lot"."LotCreatedQuantity" IS '[KS X 9101 표준] 로트수량: — 처음 생성시 로트 수량';
COMMENT ON COLUMN "Lot"."ProducedQuantity" IS '[KS X 9101 표준] 생산수량: — 해당 공정에서 생산된 로트의 전체 수량';
COMMENT ON COLUMN "Lot"."DefectQuantity" IS '[KS X 9101 표준] 불량수량: — 해당 공정에서 생산된 로트의 전체 수량 중 불량수량';
COMMENT ON COLUMN "Lot"."ReworkQuantity" IS '[KS X 9101 표준] 재작업수량: — 해당 공정의 불량수량 중 재작업을 수행한 수량';
COMMENT ON COLUMN "Lot"."ReworkCount" IS '[KS X 9101 표준] 재작업횟수: — 해당 공정의 재작업 횟수';
COMMENT ON COLUMN "Lot"."TotalReworkCount" IS '[KS X 9101 표준] 총재작업횟수: — 총 재작업 횟수';
COMMENT ON COLUMN "Lot"."LotStartedDateTime" IS '[KS X 9101 표준] 공정투입일시: — 로트를 공정에 투입한 일시';
COMMENT ON COLUMN "Lot"."PersonnelID" IS '[KS X 9101 표준] 사원식별자: — 인사조직 내 사원을 식별하기 위한 고유값
— 로트를 공정에 투입한 작업자의 식별정보
— 참조 대상: 사원(Personnel)';

-- ---------------------------------------------------------------------
-- [표준 구분: KS X 9101 표준] 표 24, 조항 7.4.1.13 | 업무영역: 기준정보
-- 테이블명(물리): "RoutingHeader" | 테이블명(논리): 공정경로헤더
-- 설명: 공정경로(Routing) 명사의 헤더 구조체(struct) 공정경로 1건의 공통 정보(공정경로명, 대상 품목, 사용 여부) 공정경로마다 1회 나타남
-- ---------------------------------------------------------------------
CREATE TABLE "RoutingHeader" ( -- [KS X 9101 표준] 공정경로헤더 (표 24)
    "RoutingHeaderSequenceNo" BIGINT GENERATED BY DEFAULT AS IDENTITY, -- [KS X 9101 표준] 공정경로헤더 일련번호(PK)
    "EnterpriseID" VARCHAR(50) NOT NULL, -- [KS X 9101 표준] 회사식별자
    "SiteID" VARCHAR(50) NOT NULL, -- [KS X 9101 표준] 사업장식별자
    "PlantID" VARCHAR(50) NOT NULL, -- [KS X 9101 표준] 공장식별자
    "CreatorID" VARCHAR(50), -- [KS X 9101 표준] 등록자식별자
    "CreationDateTime" TIMESTAMP, -- [KS X 9101 표준] 등록일시
    "ModifierID" VARCHAR(50), -- [KS X 9101 표준] 수정자식별자
    "ModificationDateTime" TIMESTAMP, -- [KS X 9101 표준] 수정일시
    "Note" VARCHAR(1000), -- [KS X 9101 표준] 비고
    "RoutingID" VARCHAR(50) NOT NULL, -- [KS X 9101 표준] 공정경로식별자
    "RoutingName" VARCHAR(200), -- [KS X 9101 표준] 공정경로명
    "ItemID" VARCHAR(50), -- [KS X 9101 표준] 품목식별자
    "UseIndicator" BOOLEAN, -- [KS X 9101 표준] 사용여부
    CONSTRAINT "PK_RoutingHeader" PRIMARY KEY ("RoutingHeaderSequenceNo"),
    CONSTRAINT "UK_RoutingHeader" UNIQUE ("EnterpriseID", "RoutingID")
);

COMMENT ON TABLE "RoutingHeader" IS '[KS X 9101 표준] 공정경로헤더 (공정경로(Routing) 명사의 헤더 구조체(struct) 공정경로 1건의 공통 정보(공정경로명, 대상 품목, 사용 여부) 공정경로마다 1회 나타남)';
COMMENT ON COLUMN "RoutingHeader"."RoutingHeaderSequenceNo" IS '[KS X 9101 표준] 공정경로헤더 일련번호: — 테이블 행을 식별하는 일련번호(PK, 대리키) — 표준 외 물리 컬럼
— 자동 증가 값(IDENTITY)으로 부여하며 다른 테이블이 참조하지 않음(FK는 UK 참조)';
COMMENT ON COLUMN "RoutingHeader"."EnterpriseID" IS '[KS X 9101 표준] 회사식별자: — 회사를 유일하게 구분할 수 있는 고유식별값
— 기업업무시스템 간의 연동을 수행하는 회사들 간에 자체적으로 정의한 고유식별값
— 참조 대상: 회사(Enterprise)';
COMMENT ON COLUMN "RoutingHeader"."SiteID" IS '[KS X 9101 표준] 사업장식별자: — 회사 내에서 사업장을 구분할수 있는 고유식별값
— 참조 대상: 사업장(Site)';
COMMENT ON COLUMN "RoutingHeader"."PlantID" IS '[KS X 9101 표준] 공장식별자: — 회사 내에서 공장을 구분할 수있는 고유식별값(만약, 공장 개념을 사용하지 않는다면 고정식별자로 설정하여 입력해야 함)
— 참조 대상: 공장(Plant)';
COMMENT ON COLUMN "RoutingHeader"."CreatorID" IS '[KS X 9101 표준] 등록자식별자: — 정보를 처음으로 등록한 사람을 구분할 수 있는 고유식별값으로, 일반적으로 사원번호가사용됨
— 참조 대상: 사원(Personnel)';
COMMENT ON COLUMN "RoutingHeader"."CreationDateTime" IS '[KS X 9101 표준] 등록일시: — 정보를 처음으로 등록한 날짜 (KS X ISO 8601을 따른다)';
COMMENT ON COLUMN "RoutingHeader"."ModifierID" IS '[KS X 9101 표준] 수정자식별자: — 정보를 마지막으로 수정한 사람을 구분할 수 있는 고유식별값으로, 일반적으로 사원번호가 사용됨
— 참조 대상: 사원(Personnel)';
COMMENT ON COLUMN "RoutingHeader"."ModificationDateTime" IS '[KS X 9101 표준] 수정일시: — 정보를 마지막으로 수정한 날짜 (KS X ISO 8601을 따른다.)';
COMMENT ON COLUMN "RoutingHeader"."Note" IS '[KS X 9101 표준] 비고: — 비고사항';
COMMENT ON COLUMN "RoutingHeader"."RoutingID" IS '[KS X 9101 표준] 공정경로식별자: — 공정경로를 식별하기 위한 고유값
— 품목의 공정경로 단위로 부여하며, 공정경로헤더에 1회 기재함';
COMMENT ON COLUMN "RoutingHeader"."RoutingName" IS '[KS X 9101 표준] 공정경로명: — 공정경로의 명칭';
COMMENT ON COLUMN "RoutingHeader"."ItemID" IS '[KS X 9101 표준] 품목식별자: — 품목을 식별하기 위한 고유값
— 제품, 반제품, 상품, 원자재, 부자재, 저장품, 소모품 등 회사 내시스템으로 관리되는 모든 품목을 포함
— 참조 대상: 품목마스터(ItemMaster)';
COMMENT ON COLUMN "RoutingHeader"."UseIndicator" IS '[KS X 9101 표준] 사용여부: — 공정경로의 사용 여부';

-- ---------------------------------------------------------------------
-- [표준 구분: KS X 9101 표준] 표 24, 조항 7.4.1.13 | 업무영역: 기준정보
-- 테이블명(물리): "RoutingLine" | 테이블명(논리): 공정경로라인
-- 설명: 공정경로(Routing) 명사의 라인 구조체(struct[1..N]) 공정경로를 구성하는 공정 행 정보 공정경로헤더 아래에 1회 이상 반복하여 나타남(1..N)
-- ---------------------------------------------------------------------
CREATE TABLE "RoutingLine" ( -- [KS X 9101 표준] 공정경로라인 (표 24)
    "RoutingLineSequenceNo" BIGINT GENERATED BY DEFAULT AS IDENTITY, -- [KS X 9101 표준] 공정경로라인 일련번호(PK)
    "EnterpriseID" VARCHAR(50) NOT NULL, -- [KS X 9101 표준] 회사식별자
    "SiteID" VARCHAR(50) NOT NULL, -- [KS X 9101 표준] 사업장식별자
    "PlantID" VARCHAR(50) NOT NULL, -- [KS X 9101 표준] 공장식별자
    "CreatorID" VARCHAR(50), -- [KS X 9101 표준] 등록자식별자
    "CreationDateTime" TIMESTAMP, -- [KS X 9101 표준] 등록일시
    "ModifierID" VARCHAR(50), -- [KS X 9101 표준] 수정자식별자
    "ModificationDateTime" TIMESTAMP, -- [KS X 9101 표준] 수정일시
    "Note" VARCHAR(1000), -- [KS X 9101 표준] 비고
    "RoutingID" VARCHAR(50) NOT NULL, -- [KS X 9101 표준] 공정경로식별자
    "OperationSequence" INTEGER NOT NULL, -- [KS X 9101 표준] 공정순번
    "OperationID" VARCHAR(50), -- [KS X 9101 표준] 공정식별자
    "LastOperationIndicator" BOOLEAN, -- [KS X 9101 표준] 최종공정여부
    "SetupTime" INTERVAL, -- [KS X 9101 표준] 준비시간
    "RunTime" INTERVAL, -- [KS X 9101 표준] 작업시간
    "MoveTime" INTERVAL, -- [KS X 9101 표준] 이동시간
    CONSTRAINT "PK_RoutingLine" PRIMARY KEY ("RoutingLineSequenceNo"),
    CONSTRAINT "UK_RoutingLine" UNIQUE ("EnterpriseID", "RoutingID", "OperationSequence")
);

COMMENT ON TABLE "RoutingLine" IS '[KS X 9101 표준] 공정경로라인 (공정경로(Routing) 명사의 라인 구조체(struct[1..N]) 공정경로를 구성하는 공정 행 정보 공정경로헤더 아래에 1회 이상 반복하여 나타남(1..N))';
COMMENT ON COLUMN "RoutingLine"."RoutingLineSequenceNo" IS '[KS X 9101 표준] 공정경로라인 일련번호: — 테이블 행을 식별하는 일련번호(PK, 대리키) — 표준 외 물리 컬럼
— 자동 증가 값(IDENTITY)으로 부여하며 다른 테이블이 참조하지 않음(FK는 UK 참조)';
COMMENT ON COLUMN "RoutingLine"."EnterpriseID" IS '[KS X 9101 표준] 회사식별자: — 회사를 유일하게 구분할 수 있는 고유식별값
— 기업업무시스템 간의 연동을 수행하는 회사들 간에 자체적으로 정의한 고유식별값
— 참조 대상: 회사(Enterprise)';
COMMENT ON COLUMN "RoutingLine"."SiteID" IS '[KS X 9101 표준] 사업장식별자: — 회사 내에서 사업장을 구분할수 있는 고유식별값
— 참조 대상: 사업장(Site)';
COMMENT ON COLUMN "RoutingLine"."PlantID" IS '[KS X 9101 표준] 공장식별자: — 회사 내에서 공장을 구분할 수있는 고유식별값(만약, 공장 개념을 사용하지 않는다면 고정식별자로 설정하여 입력해야 함)
— 참조 대상: 공장(Plant)';
COMMENT ON COLUMN "RoutingLine"."CreatorID" IS '[KS X 9101 표준] 등록자식별자: — 정보를 처음으로 등록한 사람을 구분할 수 있는 고유식별값으로, 일반적으로 사원번호가사용됨
— 참조 대상: 사원(Personnel)';
COMMENT ON COLUMN "RoutingLine"."CreationDateTime" IS '[KS X 9101 표준] 등록일시: — 정보를 처음으로 등록한 날짜 (KS X ISO 8601을 따른다)';
COMMENT ON COLUMN "RoutingLine"."ModifierID" IS '[KS X 9101 표준] 수정자식별자: — 정보를 마지막으로 수정한 사람을 구분할 수 있는 고유식별값으로, 일반적으로 사원번호가 사용됨
— 참조 대상: 사원(Personnel)';
COMMENT ON COLUMN "RoutingLine"."ModificationDateTime" IS '[KS X 9101 표준] 수정일시: — 정보를 마지막으로 수정한 날짜 (KS X ISO 8601을 따른다.)';
COMMENT ON COLUMN "RoutingLine"."Note" IS '[KS X 9101 표준] 비고: — 비고사항';
COMMENT ON COLUMN "RoutingLine"."RoutingID" IS '[KS X 9101 표준] 공정경로식별자: — 공정경로를 식별하기 위한 고유값
— 참조 대상: 공정경로헤더(RoutingHeader)';
COMMENT ON COLUMN "RoutingLine"."OperationSequence" IS '[KS X 9101 표준] 공정순번: — 공정경로를 구성하는 공정의 순서
— 공정경로라인의 행 순번으로, 공정경로라인은 공정경로식별자와 공정순번의 조합으로 구분하며, 같은 공정이 한 공정경로에 두 번 이상 나오는 경우에도 공정순번으로 구분함';
COMMENT ON COLUMN "RoutingLine"."OperationID" IS '[KS X 9101 표준] 공정식별자: — 공정을 식별하기 위한 고유값
— 참조 대상: 공정(Operation)';
COMMENT ON COLUMN "RoutingLine"."LastOperationIndicator" IS '[KS X 9101 표준] 최종공정여부: — 공정경로상 마지막 공정';
COMMENT ON COLUMN "RoutingLine"."SetupTime" IS '[KS X 9101 표준] 준비시간: — 공정의 작업 준비시간(KS X ISO 8601을 따른다)';
COMMENT ON COLUMN "RoutingLine"."RunTime" IS '[KS X 9101 표준] 작업시간: — 공정의 작업 실행시간(KS X ISO 8601을 따른다)';
COMMENT ON COLUMN "RoutingLine"."MoveTime" IS '[KS X 9101 표준] 이동시간: — 공정 작업 후 재공품이 다음 공정으로 이동하는 데 걸리는 시간(KS X ISO 8601을 따른다)';

-- ---------------------------------------------------------------------
-- [표준 구분: KS X 9101 표준] 표 25, 조항 7.4.1.14 | 업무영역: 기준정보
-- 테이블명(물리): "Operation" | 테이블명(논리): 공정
-- 설명: 생산작업을 수행하는 작업장 또는 작업장 내 세부 작업단위를 의미한다.
