CREATE TABLE "Operation" ( -- [KS X 9101 표준] 공정 (표 25)
    "OperationSequenceNo" BIGINT GENERATED BY DEFAULT AS IDENTITY, -- [KS X 9101 표준] 공정 일련번호(PK)
    "EnterpriseID" VARCHAR(50) NOT NULL, -- [KS X 9101 표준] 회사식별자
    "SiteID" VARCHAR(50) NOT NULL, -- [KS X 9101 표준] 사업장식별자
    "PlantID" VARCHAR(50) NOT NULL, -- [KS X 9101 표준] 공장식별자
    "CreatorID" VARCHAR(50), -- [KS X 9101 표준] 등록자식별자
    "CreationDateTime" TIMESTAMP, -- [KS X 9101 표준] 등록일시
    "ModifierID" VARCHAR(50), -- [KS X 9101 표준] 수정자식별자
    "ModificationDateTime" TIMESTAMP, -- [KS X 9101 표준] 수정일시
    "Note" VARCHAR(1000), -- [KS X 9101 표준] 비고
    "OperationID" VARCHAR(50) NOT NULL, -- [KS X 9101 표준] 공정식별자
    "OperationName" VARCHAR(200), -- [KS X 9101 표준] 공정명
    "OperationType" VARCHAR(30), -- [KS X 9101 표준] 공정유형
    "UseIndicator" BOOLEAN, -- [KS X 9101 표준] 사용여부
    "OperationLargeClass" VARCHAR(30), -- [KS X 9101 표준] 공정대분류
    "OperationMediumClass" VARCHAR(30), -- [KS X 9101 표준] 공정중분류
    "OperationSmallClass" VARCHAR(30), -- [KS X 9101 표준] 공정소분류
    "BackFlushedIndicator" BOOLEAN, -- [KS X 9101 표준] 백플러시여부
    CONSTRAINT "PK_Operation" PRIMARY KEY ("OperationSequenceNo"),
    CONSTRAINT "UK_Operation" UNIQUE ("EnterpriseID", "OperationID")
);

COMMENT ON TABLE "Operation" IS '[KS X 9101 표준] 공정 (생산작업을 수행하는 작업장 또는 작업장 내 세부 작업단위를 의미한다.)';
