— 자동 증가 값(IDENTITY)으로 부여하며 다른 테이블이 참조하지 않음(FK는 UK 참조)';
COMMENT ON COLUMN "Operation"."EnterpriseID" IS '[KS X 9101 표준] 회사식별자: — 회사를 유일하게 구분할 수 있는 고유식별값
— 기업업무시스템 간의 연동을 수행하는 회사들 간에 자체적으로 정의한 고유식별값
— 참조 대상: 회사(Enterprise)';
COMMENT ON COLUMN "Operation"."SiteID" IS '[KS X 9101 표준] 사업장식별자: — 회사 내에서 사업장을 구분할수 있는 고유식별값
— 참조 대상: 사업장(Site)';
COMMENT ON COLUMN "Operation"."PlantID" IS '[KS X 9101 표준] 공장식별자: — 회사 내에서 공장을 구분할 수있는 고유식별값(만약, 공장 개념을 사용하지 않는다면 고정식별자로 설정하여 입력해야 함)
— 참조 대상: 공장(Plant)';
COMMENT ON COLUMN "Operation"."CreatorID" IS '[KS X 9101 표준] 등록자식별자: — 정보를 처음으로 등록한 사람을 구분할 수 있는 고유식별값으로, 일반적으로 사원번호가사용됨
— 참조 대상: 사원(Personnel)';
COMMENT ON COLUMN "Operation"."CreationDateTime" IS '[KS X 9101 표준] 등록일시: — 정보를 처음으로 등록한 날짜 (KS X ISO 8601을 따른다)';
COMMENT ON COLUMN "Operation"."ModifierID" IS '[KS X 9101 표준] 수정자식별자: — 정보를 마지막으로 수정한 사람을 구분할 수 있는 고유식별값으로, 일반적으로 사원번호가 사용됨
— 참조 대상: 사원(Personnel)';
COMMENT ON COLUMN "Operation"."ModificationDateTime" IS '[KS X 9101 표준] 수정일시: — 정보를 마지막으로 수정한 날짜 (KS X ISO 8601을 따른다.)';
COMMENT ON COLUMN "Operation"."Note" IS '[KS X 9101 표준] 비고: — 비고사항';
COMMENT ON COLUMN "Operation"."OperationID" IS '[KS X 9101 표준] 공정식별자: — 공정을 식별하기 위한 고유값';
COMMENT ON COLUMN "Operation"."OperationName" IS '[KS X 9101 표준] 공정명: — 공정의 명칭';
COMMENT ON COLUMN "Operation"."OperationType" IS '[KS X 9101 표준] 공정유형: — 생산공정, 외주공정, 계측공정, 검사공정 등 공정의 유형
— 공정유형은 회사가 공통코드에 등록하여 관리
— 참조 대상: 공통코드정보(CommonCodeMaster)의 코드';
COMMENT ON COLUMN "Operation"."UseIndicator" IS '[KS X 9101 표준] 사용여부: — 공정의 사용 여부';
COMMENT ON COLUMN "Operation"."OperationLargeClass" IS '[KS X 9101 표준] 공정대분류: — 공정이 속한 공정대분류
— 공정대분류는 공통코드에 등록하여 관리하며 회사 기준 분류체계에 의해 정해짐
— 예: 가공, 조립, 표면처리, 열처리, 검사, 포장 등
— 참조 대상: 공통코드정보(CommonCodeMaster)의 코드';
COMMENT ON COLUMN "Operation"."OperationMediumClass" IS '[KS X 9101 표준] 공정중분류: — 공정이 속한 공정중분류(공정대분류 하위에 속함)
— 공정중분류는 공통코드에 등록하여 관리하며 회사 기준 분류체계에 의해 정해짐
— 예: 공정대분류 가공 하위의 절삭, 프레스, 용접, 사출 등
— 참조 대상: 공통코드정보(CommonCodeMaster)의 코드';
COMMENT ON COLUMN "Operation"."OperationSmallClass" IS '[KS X 9101 표준] 공정소분류: — 공정이 속한 공정소분류(공정중분류 하위에 속함)
— 공정소분류는 공통코드에 등록하여 관리하며 회사 기준 분류체계에 의해 정해짐
— 예: 공정중분류 절삭 하위의 선삭, 밀링, 드릴링 등
— 참조 대상: 공통코드정보(CommonCodeMaster)의 코드';
COMMENT ON COLUMN "Operation"."BackFlushedIndicator" IS '[KS X 9101 표준] 백플러시여부: — 생산 완료 시점에 모품목을 만들기 위해 소요되는 자품목의 생산투입 수량 일괄 처리 여부';

-- ---------------------------------------------------------------------
-- [표준 구분: KS X 9101 표준] 표 26, 조항 7.4.1.15 | 업무영역: 기준정보
-- 테이블명(물리): "Equipment" | 테이블명(논리): 설비
-- 설명: 설비명, 설비유형 등 설비 관리 및 회사의 자산으로서 관리를 위한 설비정보를 의미한다.
-- ---------------------------------------------------------------------
CREATE TABLE "Equipment" ( -- [KS X 9101 표준] 설비 (표 26)
    "EquipmentSequenceNo" BIGINT GENERATED BY DEFAULT AS IDENTITY, -- [KS X 9101 표준] 설비 일련번호(PK)
    "EnterpriseID" VARCHAR(50) NOT NULL, -- [KS X 9101 표준] 회사식별자
    "SiteID" VARCHAR(50) NOT NULL, -- [KS X 9101 표준] 사업장식별자
    "PlantID" VARCHAR(50) NOT NULL, -- [KS X 9101 표준] 공장식별자
    "CreatorID" VARCHAR(50), -- [KS X 9101 표준] 등록자식별자
    "CreationDateTime" TIMESTAMP, -- [KS X 9101 표준] 등록일시
    "ModifierID" VARCHAR(50), -- [KS X 9101 표준] 수정자식별자
    "ModificationDateTime" TIMESTAMP, -- [KS X 9101 표준] 수정일시
    "Note" VARCHAR(1000), -- [KS X 9101 표준] 비고
    "EquipmentID" VARCHAR(50) NOT NULL, -- [KS X 9101 표준] 설비식별자
    "EquipmentName" VARCHAR(200), -- [KS X 9101 표준] 설비명
    "ParentEquipmentID" VARCHAR(50), -- [KS X 9101 표준] 상위설비식별자
    "EquipmentType" VARCHAR(30), -- [KS X 9101 표준] 설비유형
    "EquipmentLargeClass" VARCHAR(30), -- [KS X 9101 표준] 설비대분류
    "EquipmentMediumClass" VARCHAR(30), -- [KS X 9101 표준] 설비중분류
    "EquipmentSmallClass" VARCHAR(30), -- [KS X 9101 표준] 설비소분류
    "DepartmentInChargeID" VARCHAR(50), -- [KS X 9101 표준] 관리부서식별자
    "PersonInChargeID" VARCHAR(50), -- [KS X 9101 표준] 관리자식별자
    "OperationID" VARCHAR(50), -- [KS X 9101 표준] 공정식별자
    "UseIndicator" BOOLEAN, -- [KS X 9101 표준] 사용여부
    "DAQDevice" VARCHAR(255), -- [KS X 9101 표준] 데이터수집장치
    "FixedAssetID" VARCHAR(50), -- [KS X 9101 표준] 고정자산식별자
    "ModelNumber" VARCHAR(50), -- [KS X 9101 표준] 모델번호
    "SerialNumber" VARCHAR(50), -- [KS X 9101 표준] 일련번호
    "CountryOfOrigin" VARCHAR(255), -- [KS X 9101 표준] 제조국가
    "Manufacturer" VARCHAR(255), -- [KS X 9101 표준] 제조업체
    "AcquisitionDate" DATE, -- [KS X 9101 표준] 취득일
    "Location" VARCHAR(1000), -- [KS X 9101 표준] 위치
    CONSTRAINT "PK_Equipment" PRIMARY KEY ("EquipmentSequenceNo"),
    CONSTRAINT "UK_Equipment" UNIQUE ("EnterpriseID", "EquipmentID")
);

COMMENT ON TABLE "Equipment" IS '[KS X 9101 표준] 설비 (설비명, 설비유형 등 설비 관리 및 회사의 자산으로서 관리를 위한 설비정보를 의미한다.)';
COMMENT ON COLUMN "Equipment"."EquipmentSequenceNo" IS '[KS X 9101 표준] 설비 일련번호: — 테이블 행을 식별하는 일련번호(PK, 대리키) — 표준 외 물리 컬럼
— 자동 증가 값(IDENTITY)으로 부여하며 다른 테이블이 참조하지 않음(FK는 UK 참조)';
COMMENT ON COLUMN "Equipment"."EnterpriseID" IS '[KS X 9101 표준] 회사식별자: — 회사를 유일하게 구분할 수 있는 고유식별값
— 기업업무시스템 간의 연동을 수행하는 회사들 간에 자체적으로 정의한 고유식별값
