COMMENT ON COLUMN "Equipment"."PlantID" IS '[KS X 9101 표준] 공장식별자: — 회사 내에서 공장을 구분할 수있는 고유식별값(만약, 공장 개념을 사용하지 않는다면 고정식별자로 설정하여 입력해야 함)
— 참조 대상: 공장(Plant)';
COMMENT ON COLUMN "Equipment"."CreatorID" IS '[KS X 9101 표준] 등록자식별자: — 정보를 처음으로 등록한 사람을 구분할 수 있는 고유식별값으로, 일반적으로 사원번호가사용됨
— 참조 대상: 사원(Personnel)';
COMMENT ON COLUMN "Equipment"."CreationDateTime" IS '[KS X 9101 표준] 등록일시: — 정보를 처음으로 등록한 날짜 (KS X ISO 8601을 따른다)';
COMMENT ON COLUMN "Equipment"."ModifierID" IS '[KS X 9101 표준] 수정자식별자: — 정보를 마지막으로 수정한 사람을 구분할 수 있는 고유식별값으로, 일반적으로 사원번호가 사용됨
— 참조 대상: 사원(Personnel)';
COMMENT ON COLUMN "Equipment"."ModificationDateTime" IS '[KS X 9101 표준] 수정일시: — 정보를 마지막으로 수정한 날짜 (KS X ISO 8601을 따른다.)';
COMMENT ON COLUMN "Equipment"."Note" IS '[KS X 9101 표준] 비고: — 비고사항';
COMMENT ON COLUMN "Equipment"."EquipmentID" IS '[KS X 9101 표준] 설비식별자: — 설비를 식별하기 위한 고유값';
COMMENT ON COLUMN "Equipment"."EquipmentName" IS '[KS X 9101 표준] 설비명: — 설비의 명칭';
COMMENT ON COLUMN "Equipment"."ParentEquipmentID" IS '[KS X 9101 표준] 상위설비식별자: — 해당 설비의 상위설비
— 참조 대상: 설비(Equipment)';
COMMENT ON COLUMN "Equipment"."EquipmentType" IS '[KS X 9101 표준] 설비유형: — 설비의 유형
— 예: 생산설비, 검사설비, 계측기, 물류·반송설비, 유틸리티설비, 금형·치공구 등
— 참조 대상: 공통코드정보(CommonCodeMaster)의 코드';
COMMENT ON COLUMN "Equipment"."EquipmentLargeClass" IS '[KS X 9101 표준] 설비대분류: — 설비가 속한 설비대분류
— 공통코드에 등록하여 관리하며 회사 기준 분류체계에 의해 정해짐
