COMMENT ON COLUMN "Equipment"."OperationID" IS '[KS X 9101 표준] 공정식별자: — 공정을 식별하기 위한 고유값
— 참조 대상: 공정(Operation)';
COMMENT ON COLUMN "Equipment"."UseIndicator" IS '[KS X 9101 표준] 사용여부: — 설비의 사용 여부';
