COMMENT ON COLUMN "Equipment"."FixedAssetID" IS '[KS X 9101 표준] 고정자산식별자: — 설비의 회계적 자산으로서의 고유번호';
COMMENT ON COLUMN "Equipment"."ModelNumber" IS '[KS X 9101 표준] 모델번호: — 설비의 모델번호';
COMMENT ON COLUMN "Equipment"."SerialNumber" IS '[KS X 9101 표준] 일련번호: — 설비의 일련번호';
COMMENT ON COLUMN "Equipment"."CountryOfOrigin" IS '[KS X 9101 표준] 제조국가: — 설비의 제조국가';
COMMENT ON COLUMN "Equipment"."Manufacturer" IS '[KS X 9101 표준] 제조업체: — 설비의 제조업체';
COMMENT ON COLUMN "Equipment"."AcquisitionDate" IS '[KS X 9101 표준] 취득일: — 설비 실물을 취득한 일자(KS X ISO 8601을 따른다)';
COMMENT ON COLUMN "Equipment"."Location" IS '[KS X 9101 표준] 위치: — 설비가 배치되어 있는 장소';

-- ---------------------------------------------------------------------
-- [표준 구분: KS X 9101 표준] 표 27, 조항 7.4.1.16 | 업무영역: 기준정보
-- 테이블명(물리): "OperationEquipment" | 테이블명(논리): 공정설비
