    "EquipmentQuantity" INTEGER, -- [KS X 9101 표준] 기준사용대수
    CONSTRAINT "PK_OperationEquipment" PRIMARY KEY ("OperationEquipmentSequenceNo"),
    CONSTRAINT "UK_OperationEquipment" UNIQUE ("EnterpriseID", "OperationID", "EquipmentID")
);

