COMMENT ON COLUMN "OperationEquipment"."PlantID" IS '[KS X 9101 표준] 공장식별자: — 회사 내에서 공장을 구분할 수있는 고유식별값(만약, 공장 개념을 사용하지 않는다면 고정식별자로 설정하여 입력해야 함)
— 참조 대상: 공장(Plant)';
COMMENT ON COLUMN "OperationEquipment"."CreatorID" IS '[KS X 9101 표준] 등록자식별자: — 정보를 처음으로 등록한 사람을 구분할 수 있는 고유식별값으로, 일반적으로 사원번호가사용됨
— 참조 대상: 사원(Personnel)';
COMMENT ON COLUMN "OperationEquipment"."CreationDateTime" IS '[KS X 9101 표준] 등록일시: — 정보를 처음으로 등록한 날짜 (KS X ISO 8601을 따른다)';
COMMENT ON COLUMN "OperationEquipment"."ModifierID" IS '[KS X 9101 표준] 수정자식별자: — 정보를 마지막으로 수정한 사람을 구분할 수 있는 고유식별값으로, 일반적으로 사원번호가 사용됨
— 참조 대상: 사원(Personnel)';
COMMENT ON COLUMN "OperationEquipment"."ModificationDateTime" IS '[KS X 9101 표준] 수정일시: — 정보를 마지막으로 수정한 날짜 (KS X ISO 8601을 따른다.)';
COMMENT ON COLUMN "OperationEquipment"."Note" IS '[KS X 9101 표준] 비고: — 비고사항';
COMMENT ON COLUMN "OperationEquipment"."OperationID" IS '[KS X 9101 표준] 공정식별자: — 공정을 식별하기 위한 고유값
— 참조 대상: 공정(Operation)';
COMMENT ON COLUMN "OperationEquipment"."OperationName" IS '[KS X 9101 표준] 공정명: — 공정의 명칭
— 참조 대상: 공정(Operation.OperationName)';
COMMENT ON COLUMN "OperationEquipment"."EquipmentID" IS '[KS X 9101 표준] 설비식별자: — 설비를 식별하기 위한 고유값
— 참조 대상: 설비(Equipment)
— 공정설비 행은 공정식별자와 설비식별자의 조합으로 구분하며, 조합에 포함되는 속성은 값을 생략할 수 없음(7.1)';
COMMENT ON COLUMN "OperationEquipment"."EquipmentName" IS '[KS X 9101 표준] 설비명: — 설비의 명칭
— 참조 대상: 설비(Equipment.EquipmentName)';
COMMENT ON COLUMN "OperationEquipment"."EquipmentSmallClass" IS '[KS X 9101 표준] 설비소분류: — 설비가 속한 설비소분류(설비중분류 하위에 속함)
— 설비소분류는 공통코드에 등록하여 관리하며, 회사 기준 분류체계에 의해 정해짐
— 예: 설비중분류 머시닝센터 하위의 수직형 머시닝센터, 수평형 머시닝센터 등
— 참조 대상: 공통코드정보(CommonCodeMaster)의 코드';
COMMENT ON COLUMN "OperationEquipment"."EquipmentQuantity" IS '[KS X 9101 표준] 기준사용대수: — 공정별 사용되는 설비대수';

-- ---------------------------------------------------------------------
-- [표준 구분: KS X 9101 표준] 표 28, 조항 7.4.1.17 | 업무영역: 기준정보
-- 테이블명(물리): "Carrier" | 테이블명(논리): 캐리어
-- 설명: 제조 공정 내 이동에 필요한 물리적 용기를 의미한다.
-- ---------------------------------------------------------------------
CREATE TABLE "Carrier" ( -- [KS X 9101 표준] 캐리어 (표 28)
    "CarrierSequenceNo" BIGINT GENERATED BY DEFAULT AS IDENTITY, -- [KS X 9101 표준] 캐리어 일련번호(PK)
    "EnterpriseID" VARCHAR(50) NOT NULL, -- [KS X 9101 표준] 회사식별자
    "SiteID" VARCHAR(50) NOT NULL, -- [KS X 9101 표준] 사업장식별자
    "PlantID" VARCHAR(50) NOT NULL, -- [KS X 9101 표준] 공장식별자
    "CreatorID" VARCHAR(50), -- [KS X 9101 표준] 등록자식별자
    "CreationDateTime" TIMESTAMP, -- [KS X 9101 표준] 등록일시
    "ModifierID" VARCHAR(50), -- [KS X 9101 표준] 수정자식별자
    "ModificationDateTime" TIMESTAMP, -- [KS X 9101 표준] 수정일시
    "Note" VARCHAR(1000), -- [KS X 9101 표준] 비고
    "CarrierID" VARCHAR(50) NOT NULL, -- [KS X 9101 표준] 캐리어식별자
    "CarrierType" VARCHAR(30), -- [KS X 9101 표준] 캐리어유형
    "ItemType" VARCHAR(30), -- [KS X 9101 표준] 품목유형
    "LoadState" VARCHAR(30), -- [KS X 9101 표준] 적재상태
    "CarrierState" VARCHAR(30), -- [KS X 9101 표준] 캐리어상태
    "CurrentQuantity" NUMERIC(18,6), -- [KS X 9101 표준] 적재수량
    CONSTRAINT "PK_Carrier" PRIMARY KEY ("CarrierSequenceNo"),
    CONSTRAINT "UK_Carrier" UNIQUE ("EnterpriseID", "CarrierID")
);

COMMENT ON TABLE "Carrier" IS '[KS X 9101 표준] 캐리어 (제조 공정 내 이동에 필요한 물리적 용기를 의미한다.)';
COMMENT ON COLUMN "Carrier"."CarrierSequenceNo" IS '[KS X 9101 표준] 캐리어 일련번호: — 테이블 행을 식별하는 일련번호(PK, 대리키) — 표준 외 물리 컬럼
— 자동 증가 값(IDENTITY)으로 부여하며 다른 테이블이 참조하지 않음(FK는 UK 참조)';
COMMENT ON COLUMN "Carrier"."EnterpriseID" IS '[KS X 9101 표준] 회사식별자: — 회사를 유일하게 구분할 수 있는 고유식별값
— 기업업무시스템 간의 연동을 수행하는 회사들 간에 자체적으로 정의한 고유식별값
— 참조 대상: 회사(Enterprise)';
COMMENT ON COLUMN "Carrier"."SiteID" IS '[KS X 9101 표준] 사업장식별자: — 회사 내에서 사업장을 구분할수 있는 고유식별값
— 참조 대상: 사업장(Site)';
COMMENT ON COLUMN "Carrier"."PlantID" IS '[KS X 9101 표준] 공장식별자: — 회사 내에서 공장을 구분할 수있는 고유식별값(만약, 공장 개념을 사용하지 않는다면 고정식별자로 설정하여 입력해야 함)
— 참조 대상: 공장(Plant)';
COMMENT ON COLUMN "Carrier"."CreatorID" IS '[KS X 9101 표준] 등록자식별자: — 정보를 처음으로 등록한 사람을 구분할 수 있는 고유식별값으로, 일반적으로 사원번호가사용됨
— 참조 대상: 사원(Personnel)';
COMMENT ON COLUMN "Carrier"."CreationDateTime" IS '[KS X 9101 표준] 등록일시: — 정보를 처음으로 등록한 날짜 (KS X ISO 8601을 따른다)';
COMMENT ON COLUMN "Carrier"."ModifierID" IS '[KS X 9101 표준] 수정자식별자: — 정보를 마지막으로 수정한 사람을 구분할 수 있는 고유식별값으로, 일반적으로 사원번호가 사용됨
— 참조 대상: 사원(Personnel)';
COMMENT ON COLUMN "Carrier"."ModificationDateTime" IS '[KS X 9101 표준] 수정일시: — 정보를 마지막으로 수정한 날짜 (KS X ISO 8601을 따른다.)';
COMMENT ON COLUMN "Carrier"."Note" IS '[KS X 9101 표준] 비고: — 비고사항';
COMMENT ON COLUMN "Carrier"."CarrierID" IS '[KS X 9101 표준] 캐리어식별자: — 캐리어를 식별하기 위한 고유값';
COMMENT ON COLUMN "Carrier"."CarrierType" IS '[KS X 9101 표준] 캐리어유형: — 캐리어의 유형(종류)(예: FOUP, Cassette, Magazine, Tray 등)
— 참조 대상: 공통코드정보(CommonCodeMaster)의 코드';
COMMENT ON COLUMN "Carrier"."ItemType" IS '[KS X 9101 표준] 품목유형: — 캐리어에 적재할 품목의 유형
— 예: 원자재, 반제품, 제품 등
— 참조 대상: 공통코드정보(CommonCodeMaster)의 코드';
COMMENT ON COLUMN "Carrier"."LoadState" IS '[KS X 9101 표준] 적재상태: — 적재 상태(예: Empty, Full, Partial)
— 참조 대상: 공통코드정보(CommonCodeMaster)의 코드';
COMMENT ON COLUMN "Carrier"."CarrierState" IS '[KS X 9101 표준] 캐리어상태: — 캐리어의 상태(예: Available, NotAvailable, InUse)
— 참조 대상: 공통코드정보(CommonCodeMaster)의 코드';
COMMENT ON COLUMN "Carrier"."CurrentQuantity" IS '[KS X 9101 표준] 적재수량: — 적재된 자재의 수량';

-- ---------------------------------------------------------------------
-- [표준 구분: KS X 9101 표준] 표 29, 조항 7.4.1.18 | 업무영역: 기준정보
-- 테이블명(물리): "StockerInventory" | 테이블명(논리): 저장소재공정보
-- 설명: 공장 내 공정 물류 저장소 정보를 의미한다. 이는 공정 내 물류 최적화를 위해 Lot Dispatcher를 사용하는데 SCS(StockerControlSystem), Dispatcher, MES 상호연동을 위해 존재한다.
-- ---------------------------------------------------------------------
CREATE TABLE "StockerInventory" ( -- [KS X 9101 표준] 저장소재공정보 (표 29)
    "StockerInventorySequenceNo" BIGINT GENERATED BY DEFAULT AS IDENTITY, -- [KS X 9101 표준] 저장소재공정보 일련번호(PK)
    "EnterpriseID" VARCHAR(50) NOT NULL, -- [KS X 9101 표준] 회사식별자
    "SiteID" VARCHAR(50) NOT NULL, -- [KS X 9101 표준] 사업장식별자
    "PlantID" VARCHAR(50) NOT NULL, -- [KS X 9101 표준] 공장식별자
    "CreatorID" VARCHAR(50), -- [KS X 9101 표준] 등록자식별자
    "CreationDateTime" TIMESTAMP, -- [KS X 9101 표준] 등록일시
    "ModifierID" VARCHAR(50), -- [KS X 9101 표준] 수정자식별자
    "ModificationDateTime" TIMESTAMP, -- [KS X 9101 표준] 수정일시
    "Note" VARCHAR(1000), -- [KS X 9101 표준] 비고
    "StockerID" VARCHAR(50) NOT NULL, -- [KS X 9101 표준] 저장소식별자
    "ZoneID" VARCHAR(50), -- [KS X 9101 표준] 구역식별자
    "FullCapacity" INTEGER, -- [KS X 9101 표준] 최대용량
    "CurrentCapacity" INTEGER, -- [KS X 9101 표준] 현재용량
    "LotID" VARCHAR(50), -- [KS X 9101 표준] 로트식별자
    "CarrierID" VARCHAR(50), -- [KS X 9101 표준] 캐리어식별자
    "AlternateStockerID" VARCHAR(50), -- [KS X 9101 표준] 대체저장소식별자
    CONSTRAINT "PK_StockerInventory" PRIMARY KEY ("StockerInventorySequenceNo"),
    CONSTRAINT "UK_StockerInventory" UNIQUE ("EnterpriseID", "StockerID")
);

COMMENT ON TABLE "StockerInventory" IS '[KS X 9101 표준] 저장소재공정보 (공장 내 공정 물류 저장소 정보를 의미한다. 이는 공정 내 물류 최적화를 위해 Lot Dispatcher를 사용하는데 SCS(StockerControlSystem), Dispatcher, MES 상호연동을 위해 존재한다.)';
COMMENT ON COLUMN "StockerInventory"."StockerInventorySequenceNo" IS '[KS X 9101 표준] 저장소재공정보 일련번호: — 테이블 행을 식별하는 일련번호(PK, 대리키) — 표준 외 물리 컬럼
— 자동 증가 값(IDENTITY)으로 부여하며 다른 테이블이 참조하지 않음(FK는 UK 참조)';
COMMENT ON COLUMN "StockerInventory"."EnterpriseID" IS '[KS X 9101 표준] 회사식별자: — 회사를 유일하게 구분할 수 있는 고유식별값
— 기업업무시스템 간의 연동을 수행하는 회사들 간에 자체적으로 정의한 고유식별값
— 참조 대상: 회사(Enterprise)';
COMMENT ON COLUMN "StockerInventory"."SiteID" IS '[KS X 9101 표준] 사업장식별자: — 회사 내에서 사업장을 구분할수 있는 고유식별값
— 참조 대상: 사업장(Site)';
COMMENT ON COLUMN "StockerInventory"."PlantID" IS '[KS X 9101 표준] 공장식별자: — 회사 내에서 공장을 구분할 수있는 고유식별값(만약, 공장 개념을 사용하지 않는다면 고정식별자로 설정하여 입력해야 함)
— 참조 대상: 공장(Plant)';
COMMENT ON COLUMN "StockerInventory"."CreatorID" IS '[KS X 9101 표준] 등록자식별자: — 정보를 처음으로 등록한 사람을 구분할 수 있는 고유식별값으로, 일반적으로 사원번호가사용됨
— 참조 대상: 사원(Personnel)';
COMMENT ON COLUMN "StockerInventory"."CreationDateTime" IS '[KS X 9101 표준] 등록일시: — 정보를 처음으로 등록한 날짜 (KS X ISO 8601을 따른다)';
COMMENT ON COLUMN "StockerInventory"."ModifierID" IS '[KS X 9101 표준] 수정자식별자: — 정보를 마지막으로 수정한 사람을 구분할 수 있는 고유식별값으로, 일반적으로 사원번호가 사용됨
— 참조 대상: 사원(Personnel)';
COMMENT ON COLUMN "StockerInventory"."ModificationDateTime" IS '[KS X 9101 표준] 수정일시: — 정보를 마지막으로 수정한 날짜 (KS X ISO 8601을 따른다.)';
COMMENT ON COLUMN "StockerInventory"."Note" IS '[KS X 9101 표준] 비고: — 비고사항';
COMMENT ON COLUMN "StockerInventory"."StockerID" IS '[KS X 9101 표준] 저장소식별자: — 해당 장비와 공정의 물류를 적재하는 저장소를 식별하기 위한고유값';
COMMENT ON COLUMN "StockerInventory"."ZoneID" IS '[KS X 9101 표준] 구역식별자: — 저장소가 위치한 영역을 식별하기 위한 고유값';
COMMENT ON COLUMN "StockerInventory"."FullCapacity" IS '[KS X 9101 표준] 최대용량: — 저장소에 로트를 최대 적재할 수 있는 수량';
COMMENT ON COLUMN "StockerInventory"."CurrentCapacity" IS '[KS X 9101 표준] 현재용량: — 현재 저장소에 적재되어 있는 로트 수량';
COMMENT ON COLUMN "StockerInventory"."LotID" IS '[KS X 9101 표준] 로트식별자: — 로트를 식별하기 위한 고유값
