COMMENT ON COLUMN "StockerInventory"."CarrierID" IS '[KS X 9101 표준] 캐리어식별자: — 캐리어를 식별하기 위한 고유값
— 참조 대상: 캐리어(Carrier)';
COMMENT ON COLUMN "StockerInventory"."AlternateStockerID" IS '[KS X 9101 표준] 대체저장소식별자: — 지정된 저장소가 만재되었을 때 대체할 수 있는 저장소를 식별하기 위한 고유값
— 참조 대상: 저장소재공정보(StockerInventory)';

-- ---------------------------------------------------------------------
-- [표준 구분: KS X 9101 표준] 표 30, 조항 7.4.1.19 | 업무영역: 기준정보
-- 테이블명(물리): "WarehouseLocationHeader" | 테이블명(논리): 창고헤더
-- 설명: 창고(WarehouseLocation) 명사의 헤더 구조체(struct) 창고 1건의 공통 정보(창고명, 창고유형, 재고 관리 기준) 창고마다 1회 나타남
-- ---------------------------------------------------------------------
CREATE TABLE "WarehouseLocationHeader" ( -- [KS X 9101 표준] 창고헤더 (표 30)
    "WarehouseLocationHeaderSequenceNo" BIGINT GENERATED BY DEFAULT AS IDENTITY, -- [KS X 9101 표준] 창고헤더 일련번호(PK)
    "EnterpriseID" VARCHAR(50) NOT NULL, -- [KS X 9101 표준] 회사식별자
    "SiteID" VARCHAR(50) NOT NULL, -- [KS X 9101 표준] 사업장식별자
    "PlantID" VARCHAR(50) NOT NULL, -- [KS X 9101 표준] 공장식별자
    "CreatorID" VARCHAR(50), -- [KS X 9101 표준] 등록자식별자
    "CreationDateTime" TIMESTAMP, -- [KS X 9101 표준] 등록일시
    "ModifierID" VARCHAR(50), -- [KS X 9101 표준] 수정자식별자
    "ModificationDateTime" TIMESTAMP, -- [KS X 9101 표준] 수정일시
    "Note" VARCHAR(1000), -- [KS X 9101 표준] 비고
    "WarehouseID" VARCHAR(50) NOT NULL, -- [KS X 9101 표준] 창고식별자
    "WarehouseName" VARCHAR(200), -- [KS X 9101 표준] 창고명
    "WarehouseType" VARCHAR(30), -- [KS X 9101 표준] 창고유형
    "UseIndicator" BOOLEAN, -- [KS X 9101 표준] 사용여부
    "NegativeInventoryIndicator" BOOLEAN, -- [KS X 9101 표준] 음수재고허용여부
    CONSTRAINT "PK_WarehouseLocationHeader" PRIMARY KEY ("WarehouseLocationHeaderSequenceNo"),
    CONSTRAINT "UK_WarehouseLocationHeader" UNIQUE ("EnterpriseID", "WarehouseID")
);

COMMENT ON TABLE "WarehouseLocationHeader" IS '[KS X 9101 표준] 창고헤더 (창고(WarehouseLocation) 명사의 헤더 구조체(struct) 창고 1건의 공통 정보(창고명, 창고유형, 재고 관리 기준) 창고마다 1회 나타남)';
