-- [표준 구분: KS X 9101 표준] 표 30, 조항 7.4.1.19 | 업무영역: 기준정보
-- 테이블명(물리): "WarehouseLocationLine" | 테이블명(논리): 창고라인
-- 설명: 창고(WarehouseLocation) 명사의 라인 구조체(struct[1..N]) 창고 내 저장 섹션 행 정보 창고헤더 아래에 1회 이상 반복하여 나타남(1..N)
-- ---------------------------------------------------------------------
CREATE TABLE "WarehouseLocationLine" ( -- [KS X 9101 표준] 창고라인 (표 30)
    "WarehouseLocationLineSequenceNo" BIGINT GENERATED BY DEFAULT AS IDENTITY, -- [KS X 9101 표준] 창고라인 일련번호(PK)
    "EnterpriseID" VARCHAR(50) NOT NULL, -- [KS X 9101 표준] 회사식별자
    "SiteID" VARCHAR(50) NOT NULL, -- [KS X 9101 표준] 사업장식별자
    "PlantID" VARCHAR(50) NOT NULL, -- [KS X 9101 표준] 공장식별자
    "CreatorID" VARCHAR(50), -- [KS X 9101 표준] 등록자식별자
    "CreationDateTime" TIMESTAMP, -- [KS X 9101 표준] 등록일시
    "ModifierID" VARCHAR(50), -- [KS X 9101 표준] 수정자식별자
    "ModificationDateTime" TIMESTAMP, -- [KS X 9101 표준] 수정일시
    "Note" VARCHAR(1000), -- [KS X 9101 표준] 비고
    "WarehouseID" VARCHAR(50) NOT NULL, -- [KS X 9101 표준] 창고식별자
    "WarehouseSection" VARCHAR(255) NOT NULL, -- [KS X 9101 표준] 창고섹션
    "WarehouseSectionName" VARCHAR(200), -- [KS X 9101 표준] 창고섹션명
    CONSTRAINT "PK_WarehouseLocationLine" PRIMARY KEY ("WarehouseLocationLineSequenceNo"),
    CONSTRAINT "UK_WarehouseLocationLine" UNIQUE ("EnterpriseID", "WarehouseID", "WarehouseSection")
);

