-- ---------------------------------------------------------------------
-- [표준 구분: KS X 9101 표준] 표 31, 조항 7.4.1.20 | 업무영역: 기준정보
-- 테이블명(물리): "Batch" | 테이블명(논리): 배치
-- 설명: 배치 공정의 1회 실행으로 생산되고 있거나 생산된 물질의 단위를 의미한다. 원료를 정해진 양만큼 투입하여 일괄 처리하는 공정(배합, 반응, 발효, 열처리 등)의 생산 단위이며, 공급사에서 생산하여 납품한 구매품의 배치를 포함한다.
-- ---------------------------------------------------------------------
CREATE TABLE "Batch" ( -- [KS X 9101 표준] 배치 (표 31)
    "BatchSequenceNo" BIGINT GENERATED BY DEFAULT AS IDENTITY, -- [KS X 9101 표준] 배치 일련번호(PK)
    "EnterpriseID" VARCHAR(50) NOT NULL, -- [KS X 9101 표준] 회사식별자
    "SiteID" VARCHAR(50) NOT NULL, -- [KS X 9101 표준] 사업장식별자
    "PlantID" VARCHAR(50) NOT NULL, -- [KS X 9101 표준] 공장식별자
    "CreatorID" VARCHAR(50), -- [KS X 9101 표준] 등록자식별자
    "CreationDateTime" TIMESTAMP, -- [KS X 9101 표준] 등록일시
    "ModifierID" VARCHAR(50), -- [KS X 9101 표준] 수정자식별자
    "ModificationDateTime" TIMESTAMP, -- [KS X 9101 표준] 수정일시
    "Note" VARCHAR(1000), -- [KS X 9101 표준] 비고
    "BatchID" VARCHAR(50) NOT NULL, -- [KS X 9101 표준] 배치식별자
    "BatchName" VARCHAR(200), -- [KS X 9101 표준] 배치명
    "BatchDescription" VARCHAR(1000), -- [KS X 9101 표준] 배치설명
    "BatchType" VARCHAR(30), -- [KS X 9101 표준] 배치유형
    "ParentBatchID" VARCHAR(50), -- [KS X 9101 표준] 모배치식별자
    "ItemID" VARCHAR(50), -- [KS X 9101 표준] 품목식별자
    "LotID" VARCHAR(50), -- [KS X 9101 표준] 로트식별자
    "ProductionOrderID" VARCHAR(50), -- [KS X 9101 표준] 생산지시식별자
    "ProductionOrderSequence" INTEGER, -- [KS X 9101 표준] 생산지시순번
    "BOMID" VARCHAR(50), -- [KS X 9101 표준] 자재명세서식별자
    "BOMRevisionNumber" INTEGER, -- [KS X 9101 표준] 자재명세서버전
    "RecipeID" VARCHAR(50), -- [KS X 9101 표준] 레시피식별자
    "RecipeVersion" VARCHAR(255), -- [KS X 9101 표준] 레시피버전
    "OperationID" VARCHAR(50), -- [KS X 9101 표준] 공정식별자
    "EquipmentID" VARCHAR(50), -- [KS X 9101 표준] 설비식별자
    "BatchState" VARCHAR(30), -- [KS X 9101 표준] 배치상태
    "HoldIndicator" BOOLEAN, -- [KS X 9101 표준] 보류여부
    "ReworkIndicator" BOOLEAN, -- [KS X 9101 표준] 재작업여부
    "QualityDispositionCode" VARCHAR(30), -- [KS X 9101 표준] 품질판정코드
    "BatchPlannedQuantity" NUMERIC(18,6), -- [KS X 9101 표준] 배치계획수량
    "ProducedQuantity" NUMERIC(18,6), -- [KS X 9101 표준] 생산수량
    "DefectQuantity" NUMERIC(18,6), -- [KS X 9101 표준] 불량수량
    "ItemUOMCode" VARCHAR(20), -- [KS X 9101 표준] 기준단위코드
    "ScheduleStartDateTime" TIMESTAMP, -- [KS X 9101 표준] 계획시작일시
    "ScheduleEndDateTime" TIMESTAMP, -- [KS X 9101 표준] 계획종료일시
    "BatchStartDateTime" TIMESTAMP, -- [KS X 9101 표준] 배치시작일시
    "BatchEndDateTime" TIMESTAMP, -- [KS X 9101 표준] 배치종료일시
    "ManufactureDate" DATE, -- [KS X 9101 표준] 제조일
    "ValidEndDate" DATE, -- [KS X 9101 표준] 유효종료일
    "PersonnelID" VARCHAR(50), -- [KS X 9101 표준] 사원식별자
    CONSTRAINT "PK_Batch" PRIMARY KEY ("BatchSequenceNo"),
    CONSTRAINT "UK_Batch" UNIQUE ("EnterpriseID", "BatchID")
);

