— 배치로 생산 또는 구매되는 품목(원자재, 반제품, 제품 등)
— 참조 대상: 품목마스터(ItemMaster)';
COMMENT ON COLUMN "Batch"."LotID" IS '[KS X 9101 표준] 로트식별자: — 배치로 생산된 품목이 편성된 로트의 고유식별값
— 참조 대상: 로트(Lot)';
COMMENT ON COLUMN "Batch"."ProductionOrderID" IS '[KS X 9101 표준] 생산지시식별자: — 배치 생산을 지시한 생산지시의 고유식별값(사내 생산 배치인 경우)
— 참조 대상: 생산지시(ProductionOrder)';
COMMENT ON COLUMN "Batch"."ProductionOrderSequence" IS '[KS X 9101 표준] 생산지시순번: — 생산지시식별자 내 순서
— 생산지시식별자(ProductionOrderID)와 함께 생산지시(ProductionOrder)를 참조한다';
COMMENT ON COLUMN "Batch"."BOMID" IS '[KS X 9101 표준] 자재명세서식별자: — 배치에 투입되는 원료 배합의 기준이 되는 자재명세서의 고유식별값
— 참조 대상: 자재명세서(BOM)';
COMMENT ON COLUMN "Batch"."BOMRevisionNumber" IS '[KS X 9101 표준] 자재명세서버전: — 자재명세서의 버전
— 자재명세서식별자(BOMID)와 함께 자재명세서(BOM)를 참조한다';
COMMENT ON COLUMN "Batch"."RecipeID" IS '[KS X 9101 표준] 레시피식별자: — 배치 수행에 사용한 제어 레시피의 식별번호(배치제어시스템 또는 설비에서 관리)
— 레시피를 관리하는 경우에 기재(선택 입력)';
COMMENT ON COLUMN "Batch"."RecipeVersion" IS '[KS X 9101 표준] 레시피버전: — 배치 수행에 사용한 제어 레시피의 버전
— 레시피를 관리하는 경우에 기재(선택 입력)';
COMMENT ON COLUMN "Batch"."OperationID" IS '[KS X 9101 표준] 공정식별자: — 배치를 수행하는 공정의 고유식별값
— 참조 대상: 공정(Operation)';
COMMENT ON COLUMN "Batch"."EquipmentID" IS '[KS X 9101 표준] 설비식별자: — 배치를 수행하는 주 설비의 고유식별값(예: 반응기, 배합기, 건조기)
— 참조 대상: 설비(Equipment)';
COMMENT ON COLUMN "Batch"."BatchState" IS '[KS X 9101 표준] 배치상태: — 배치의 상태(예: Idle(대기), Running(진행), Hold(보류), Complete(완료), Abort(중단))
— 참조 대상: 공통코드정보(CommonCodeMaster)의 코드';
COMMENT ON COLUMN "Batch"."HoldIndicator" IS '[KS X 9101 표준] 보류여부: — 배치의 진행 또는 사용 보류 여부';
COMMENT ON COLUMN "Batch"."ReworkIndicator" IS '[KS X 9101 표준] 재작업여부: — 재작업 배치 여부';
COMMENT ON COLUMN "Batch"."QualityDispositionCode" IS '[KS X 9101 표준] 품질판정코드: — 배치의 품질 판정 결과(예: Pending(판정대기), Accepted(합격), Rejected(불합격), Conditional(조건부 합격))
— 참조 대상: 공통코드정보(CommonCodeMaster)의 코드';
COMMENT ON COLUMN "Batch"."BatchPlannedQuantity" IS '[KS X 9101 표준] 배치계획수량: — 배치 1회 실행으로 생산하도록 계획한 수량(배치 크기)(수량의 단위는 기준단위코드로 함)';
COMMENT ON COLUMN "Batch"."ProducedQuantity" IS '[KS X 9101 표준] 생산수량: — 배치로 생산된 전체 수량(수량의 단위는 기준단위코드로 함)';
COMMENT ON COLUMN "Batch"."DefectQuantity" IS '[KS X 9101 표준] 불량수량: — 배치로 생산된 전체 수량 중 불량수량(수량의 단위는 기준단위코드로 함)';
COMMENT ON COLUMN "Batch"."ItemUOMCode" IS '[KS X 9101 표준] 기준단위코드: — 기준단위코드(예: kg, L, EA 등)
— 참조 대상: 단위그룹(UOMGroup)의 단위코드';
COMMENT ON COLUMN "Batch"."ScheduleStartDateTime" IS '[KS X 9101 표준] 계획시작일시: — 배치의 계획 시작일시(KS X ISO 8601을 따른다)';
COMMENT ON COLUMN "Batch"."ScheduleEndDateTime" IS '[KS X 9101 표준] 계획종료일시: — 배치의 계획 종료일시(KS X ISO 8601을 따른다)';
COMMENT ON COLUMN "Batch"."BatchStartDateTime" IS '[KS X 9101 표준] 배치시작일시: — 배치를 실제로 시작한 일시(KS X ISO 8601을 따른다)';
COMMENT ON COLUMN "Batch"."BatchEndDateTime" IS '[KS X 9101 표준] 배치종료일시: — 배치를 실제로 종료한 일시(KS X ISO 8601을 따른다)';
COMMENT ON COLUMN "Batch"."ManufactureDate" IS '[KS X 9101 표준] 제조일: — 배치의 제조일자(공급사 생산 배치는 공급사의 제조일자)(KS X ISO 8601을 따른다)';
COMMENT ON COLUMN "Batch"."ValidEndDate" IS '[KS X 9101 표준] 유효종료일: — 배치의 사용 가능 기한(KS X ISO 8601을 따른다)';
COMMENT ON COLUMN "Batch"."PersonnelID" IS '[KS X 9101 표준] 사원식별자: — 인사조직 내 사원을 식별하기 위한 고유값
— 배치를 수행한 작업자의 식별정보
— 참조 대상: 사원(Personnel)';

-- ---------------------------------------------------------------------
-- [표준 구분: KS X 9101 표준] 표 32, 조항 7.4.1.21 | 업무영역: 기준정보
-- 테이블명(물리): "Line" | 테이블명(논리): 라인
-- 설명: 같은 공장 안에서 공정과 설비를 일정한 흐름으로 배치하여 특정 품목 또는 품목군을 생산하는 생산 단위를 의미한다. 라인은 공장에 속하며, 하나 이상의 공정과 설비로 구성된다.
-- ---------------------------------------------------------------------
CREATE TABLE "Line" ( -- [KS X 9101 표준] 라인 (표 32)
    "LineSequenceNo" BIGINT GENERATED BY DEFAULT AS IDENTITY, -- [KS X 9101 표준] 라인 일련번호(PK)
    "EnterpriseID" VARCHAR(50) NOT NULL, -- [KS X 9101 표준] 회사식별자
    "SiteID" VARCHAR(50) NOT NULL, -- [KS X 9101 표준] 사업장식별자
    "PlantID" VARCHAR(50) NOT NULL, -- [KS X 9101 표준] 공장식별자
    "CreatorID" VARCHAR(50), -- [KS X 9101 표준] 등록자식별자
    "CreationDateTime" TIMESTAMP, -- [KS X 9101 표준] 등록일시
    "ModifierID" VARCHAR(50), -- [KS X 9101 표준] 수정자식별자
    "ModificationDateTime" TIMESTAMP, -- [KS X 9101 표준] 수정일시
    "Note" VARCHAR(1000), -- [KS X 9101 표준] 비고
    "LineID" VARCHAR(50) NOT NULL, -- [KS X 9101 표준] 라인식별자
    "LineName" VARCHAR(200), -- [KS X 9101 표준] 라인명
    "LineDescription" VARCHAR(1000), -- [KS X 9101 표준] 라인설명
    "LineType" VARCHAR(30), -- [KS X 9101 표준] 라인유형
    "ProductionMethodType" VARCHAR(30), -- [KS X 9101 표준] 생산방식유형
    "ParentLineID" VARCHAR(50), -- [KS X 9101 표준] 상위라인식별자
    "DepartmentInChargeID" VARCHAR(50), -- [KS X 9101 표준] 관리부서식별자
    "PersonInChargeID" VARCHAR(50), -- [KS X 9101 표준] 관리자식별자
    "CalendarID" VARCHAR(50), -- [KS X 9101 표준] 달력식별자
    "IssueWarehouseID" VARCHAR(50), -- [KS X 9101 표준] 출고창고식별자
    "ReceiptWarehouseID" VARCHAR(50), -- [KS X 9101 표준] 입고창고식별자
    "StandardCapacity" NUMERIC(18,6), -- [KS X 9101 표준] 표준생산능력
    "CapacityUOMCode" VARCHAR(20), -- [KS X 9101 표준] 생산능력단위코드
    "StandardCycleTime" INTERVAL, -- [KS X 9101 표준] 표준사이클타임
    "ShiftCount" INTEGER, -- [KS X 9101 표준] 작업조수
    "StandardHeadcount" INTEGER, -- [KS X 9101 표준] 표준작업인원
    "Location" VARCHAR(1000), -- [KS X 9101 표준] 위치
    "UseIndicator" BOOLEAN, -- [KS X 9101 표준] 사용여부
    "ValidStartDate" DATE, -- [KS X 9101 표준] 유효시작일
    "ValidEndDate" DATE, -- [KS X 9101 표준] 유효종료일
    CONSTRAINT "PK_Line" PRIMARY KEY ("LineSequenceNo"),
    CONSTRAINT "UK_Line" UNIQUE ("EnterpriseID", "LineID")
);

COMMENT ON TABLE "Line" IS '[KS X 9101 표준] 라인 (같은 공장 안에서 공정과 설비를 일정한 흐름으로 배치하여 특정 품목 또는 품목군을 생산하는 생산 단위를 의미한다. 라인은 공장에 속하며, 하나 이상의 공정과 설비로 구성된다.)';
COMMENT ON COLUMN "Line"."LineSequenceNo" IS '[KS X 9101 표준] 라인 일련번호: — 테이블 행을 식별하는 일련번호(PK, 대리키) — 표준 외 물리 컬럼
— 자동 증가 값(IDENTITY)으로 부여하며 다른 테이블이 참조하지 않음(FK는 UK 참조)';
COMMENT ON COLUMN "Line"."EnterpriseID" IS '[KS X 9101 표준] 회사식별자: — 회사를 유일하게 구분할 수 있는 고유식별값
— 기업업무시스템 간의 연동을 수행하는 회사들 간에 자체적으로 정의한 고유식별값
— 참조 대상: 회사(Enterprise)';
COMMENT ON COLUMN "Line"."SiteID" IS '[KS X 9101 표준] 사업장식별자: — 회사 내에서 사업장을 구분할수 있는 고유식별값
— 참조 대상: 사업장(Site)';
COMMENT ON COLUMN "Line"."PlantID" IS '[KS X 9101 표준] 공장식별자: — 회사 내에서 공장을 구분할 수있는 고유식별값(만약, 공장 개념을 사용하지 않는다면 고정식별자로 설정하여 입력해야 함)
— 참조 대상: 공장(Plant)';
COMMENT ON COLUMN "Line"."CreatorID" IS '[KS X 9101 표준] 등록자식별자: — 정보를 처음으로 등록한 사람을 구분할 수 있는 고유식별값으로, 일반적으로 사원번호가사용됨
— 참조 대상: 사원(Personnel)';
COMMENT ON COLUMN "Line"."CreationDateTime" IS '[KS X 9101 표준] 등록일시: — 정보를 처음으로 등록한 날짜 (KS X ISO 8601을 따른다)';
COMMENT ON COLUMN "Line"."ModifierID" IS '[KS X 9101 표준] 수정자식별자: — 정보를 마지막으로 수정한 사람을 구분할 수 있는 고유식별값으로, 일반적으로 사원번호가 사용됨
— 참조 대상: 사원(Personnel)';
COMMENT ON COLUMN "Line"."ModificationDateTime" IS '[KS X 9101 표준] 수정일시: — 정보를 마지막으로 수정한 날짜 (KS X ISO 8601을 따른다.)';
COMMENT ON COLUMN "Line"."Note" IS '[KS X 9101 표준] 비고: — 비고사항';
COMMENT ON COLUMN "Line"."LineID" IS '[KS X 9101 표준] 라인식별자: — 라인을 식별하기 위한 고유값';
COMMENT ON COLUMN "Line"."LineName" IS '[KS X 9101 표준] 라인명: — 라인의 명칭';
COMMENT ON COLUMN "Line"."LineDescription" IS '[KS X 9101 표준] 라인설명: — 라인 설명 정보';
COMMENT ON COLUMN "Line"."LineType" IS '[KS X 9101 표준] 라인유형: — 라인의 유형(예: Assembly(조립), Machining(가공), Process(장치), Packing(포장), Inspection(검사) 등)
— 라인유형은 회사가 공통코드에 등록하여 관리
— 참조 대상: 공통코드정보(CommonCodeMaster)의 코드';
COMMENT ON COLUMN "Line"."ProductionMethodType" IS '[KS X 9101 표준] 생산방식유형: — 라인의 생산 방식(예: Discrete(개별 생산), Batch(배치 생산), Continuous(연속 생산))
— 참조 대상: 공통코드정보(CommonCodeMaster)의 코드';
COMMENT ON COLUMN "Line"."ParentLineID" IS '[KS X 9101 표준] 상위라인식별자: — 라인을 하위 라인(셀, 구간 등)으로 나누어 관리하는 경우 해당 라인의 상위 라인
— 참조 대상: 라인(Line)';
COMMENT ON COLUMN "Line"."DepartmentInChargeID" IS '[KS X 9101 표준] 관리부서식별자: — 라인을 관리하는 부서
— 참조 대상: 부서(Department)';
COMMENT ON COLUMN "Line"."PersonInChargeID" IS '[KS X 9101 표준] 관리자식별자: — 라인을 관리하는 책임자
— 참조 대상: 사원(Personnel)';
COMMENT ON COLUMN "Line"."CalendarID" IS '[KS X 9101 표준] 달력식별자: — 라인 가동일과 휴무일의 기준이 되는 달력
— 참조 대상: 달력(WorkCalendar)';
COMMENT ON COLUMN "Line"."IssueWarehouseID" IS '[KS X 9101 표준] 출고창고식별자: — 라인에 투입되는 자재를 출고하는 창고(라인 공급 창고)
— 참조 대상: 창고(WarehouseLocation)';
COMMENT ON COLUMN "Line"."ReceiptWarehouseID" IS '[KS X 9101 표준] 입고창고식별자: — 라인에서 생산된 품목이 입고되는 창고
— 참조 대상: 창고(WarehouseLocation)';
COMMENT ON COLUMN "Line"."StandardCapacity" IS '[KS X 9101 표준] 표준생산능력: — 라인이 단위 시간 동안 생산할 수 있는 표준 수량(수량과 시간의 단위는 생산능력단위코드로 함)';
COMMENT ON COLUMN "Line"."CapacityUOMCode" IS '[KS X 9101 표준] 생산능력단위코드: — 표준생산능력의 단위코드(예: EA/h, kg/h 등)
— 참조 대상: 단위그룹(UOMGroup)의 단위코드';
COMMENT ON COLUMN "Line"."StandardCycleTime" IS '[KS X 9101 표준] 표준사이클타임: — 라인에서 품목 1 기준단위를 생산하는 데 걸리는 표준 시간(KS X ISO 8601을 따른다)';
COMMENT ON COLUMN "Line"."ShiftCount" IS '[KS X 9101 표준] 작업조수: — 라인을 하루에 운영하는 작업조(근무조)의 수';
COMMENT ON COLUMN "Line"."StandardHeadcount" IS '[KS X 9101 표준] 표준작업인원: — 라인 운영에 필요한 표준 작업자 수';
COMMENT ON COLUMN "Line"."Location" IS '[KS X 9101 표준] 위치: — 라인이 배치되어 있는 장소(예: 동, 층, 구역)';
COMMENT ON COLUMN "Line"."UseIndicator" IS '[KS X 9101 표준] 사용여부: — 라인의 사용 여부';
COMMENT ON COLUMN "Line"."ValidStartDate" IS '[KS X 9101 표준] 유효시작일: — 라인을 사용하기 시작한 일자(KS X ISO 8601을 따른다)';
COMMENT ON COLUMN "Line"."ValidEndDate" IS '[KS X 9101 표준] 유효종료일: — 라인의 사용을 종료한 일자(KS X ISO 8601을 따른다)';

-- ---------------------------------------------------------------------
-- [표준 구분: KS X 9101 표준] 표 33, 조항 7.4.1.22 | 업무영역: 기준정보
-- 테이블명(물리): "Enterprise" | 테이블명(논리): 회사
-- 설명: 기업업무시스템 간 제조업무데이터를 교환하는 법인 단위의 회사를 의미한다. 회사는 하나 이상의 사업장으로 구성되며, 모든 명사 정보의 최상위 소유 범위가 된다.
-- ---------------------------------------------------------------------
CREATE TABLE "Enterprise" ( -- [KS X 9101 표준] 회사 (표 33)
    "EnterpriseSequenceNo" BIGINT GENERATED BY DEFAULT AS IDENTITY, -- [KS X 9101 표준] 회사 일련번호(PK)
    "CreatorID" VARCHAR(50), -- [KS X 9101 표준] 등록자식별자
    "CreationDateTime" TIMESTAMP, -- [KS X 9101 표준] 등록일시
    "ModifierID" VARCHAR(50), -- [KS X 9101 표준] 수정자식별자
    "ModificationDateTime" TIMESTAMP, -- [KS X 9101 표준] 수정일시
    "Note" VARCHAR(1000), -- [KS X 9101 표준] 비고
    "EnterpriseID" VARCHAR(50) NOT NULL, -- [KS X 9101 표준] 회사식별자
    "EnterpriseName" VARCHAR(200), -- [KS X 9101 표준] 회사명
    "BusinessRegistrationNumber" VARCHAR(50), -- [KS X 9101 표준] 사업자등록번호
    "CorporateRegistrationNumber" VARCHAR(50), -- [KS X 9101 표준] 법인등록번호
    "RepresentativeName" VARCHAR(200), -- [KS X 9101 표준] 대표자명
    "ParentEnterpriseID" VARCHAR(50), -- [KS X 9101 표준] 상위회사식별자
    "CountryID" VARCHAR(30), -- [KS X 9101 표준] 국가식별자
    "BaseCurrencyCode" VARCHAR(30), -- [KS X 9101 표준] 기준통화코드
    "DialNumber" VARCHAR(30), -- [KS X 9101 표준] 전화번호
    "FaxNumber" VARCHAR(30), -- [KS X 9101 표준] 팩스번호
    "PostalCode" VARCHAR(10), -- [KS X 9101 표준] 우편번호
    "BaseAddress" VARCHAR(1000), -- [KS X 9101 표준] 기본주소
    "DetailAddress" VARCHAR(1000), -- [KS X 9101 표준] 상세주소
    "UseIndicator" BOOLEAN, -- [KS X 9101 표준] 사용여부
    CONSTRAINT "PK_Enterprise" PRIMARY KEY ("EnterpriseSequenceNo"),
    CONSTRAINT "UK_Enterprise" UNIQUE ("EnterpriseID")
);

COMMENT ON TABLE "Enterprise" IS '[KS X 9101 표준] 회사 (기업업무시스템 간 제조업무데이터를 교환하는 법인 단위의 회사를 의미한다. 회사는 하나 이상의 사업장으로 구성되며, 모든 명사 정보의 최상위 소유 범위가 된다.)';
COMMENT ON COLUMN "Enterprise"."EnterpriseSequenceNo" IS '[KS X 9101 표준] 회사 일련번호: — 테이블 행을 식별하는 일련번호(PK, 대리키) — 표준 외 물리 컬럼
— 자동 증가 값(IDENTITY)으로 부여하며 다른 테이블이 참조하지 않음(FK는 UK 참조)';
COMMENT ON COLUMN "Enterprise"."CreatorID" IS '[KS X 9101 표준] 등록자식별자: — 정보를 처음으로 등록한 사람을 구분할 수 있는 고유식별값으로, 일반적으로 사원번호가사용됨
— 참조 대상: 사원(Personnel)';
COMMENT ON COLUMN "Enterprise"."CreationDateTime" IS '[KS X 9101 표준] 등록일시: — 정보를 처음으로 등록한 날짜 (KS X ISO 8601을 따른다)';
COMMENT ON COLUMN "Enterprise"."ModifierID" IS '[KS X 9101 표준] 수정자식별자: — 정보를 마지막으로 수정한 사람을 구분할 수 있는 고유식별값으로, 일반적으로 사원번호가 사용됨
— 참조 대상: 사원(Personnel)';
COMMENT ON COLUMN "Enterprise"."ModificationDateTime" IS '[KS X 9101 표준] 수정일시: — 정보를 마지막으로 수정한 날짜 (KS X ISO 8601을 따른다.)';
COMMENT ON COLUMN "Enterprise"."Note" IS '[KS X 9101 표준] 비고: — 비고사항';
COMMENT ON COLUMN "Enterprise"."EnterpriseID" IS '[KS X 9101 표준] 회사식별자: — 회사를 유일하게 구분할 수 있는 고유식별값
— 기업업무시스템 간의 연동을 수행하는 회사들 간에 자체적으로 정의한 고유식별값';
COMMENT ON COLUMN "Enterprise"."EnterpriseName" IS '[KS X 9101 표준] 회사명: — 회사의 명칭';
COMMENT ON COLUMN "Enterprise"."BusinessRegistrationNumber" IS '[KS X 9101 표준] 사업자등록번호: — 회사(본사)의 사업자등록증에 기재된 고유번호';
COMMENT ON COLUMN "Enterprise"."CorporateRegistrationNumber" IS '[KS X 9101 표준] 법인등록번호: — 회사의 법인등록번호';
COMMENT ON COLUMN "Enterprise"."RepresentativeName" IS '[KS X 9101 표준] 대표자명: — 회사의 대표자 성명';
COMMENT ON COLUMN "Enterprise"."ParentEnterpriseID" IS '[KS X 9101 표준] 상위회사식별자: — 지주회사, 모회사 등 해당 회사의 상위 회사
— 참조 대상: 회사(Enterprise)';
COMMENT ON COLUMN "Enterprise"."CountryID" IS '[KS X 9101 표준] 국가식별자: — 회사의 국가를 식별하기 위한 고유값
— 참조 대상: 공통코드정보(CommonCodeMaster)의 코드(ISO 3166-1 국가코드 사용 권고)';
COMMENT ON COLUMN "Enterprise"."BaseCurrencyCode" IS '[KS X 9101 표준] 기준통화코드: — 회사의 회계 기준 통화(예: KRW, USD 등)
— 참조 대상: 공통코드정보(CommonCodeMaster)의 코드(ISO 4217 통화코드 사용 권고)';
COMMENT ON COLUMN "Enterprise"."DialNumber" IS '[KS X 9101 표준] 전화번호: — 회사의 대표전화번호';
COMMENT ON COLUMN "Enterprise"."FaxNumber" IS '[KS X 9101 표준] 팩스번호: — 회사의 팩스번호';
COMMENT ON COLUMN "Enterprise"."PostalCode" IS '[KS X 9101 표준] 우편번호: — 회사(본사)의 우편번호';
COMMENT ON COLUMN "Enterprise"."BaseAddress" IS '[KS X 9101 표준] 기본주소: — 우편번호 검색을 통해 찾는 회사(본사) 주소';
COMMENT ON COLUMN "Enterprise"."DetailAddress" IS '[KS X 9101 표준] 상세주소: — 기본주소에 추가되는 회사의 상세주소';
COMMENT ON COLUMN "Enterprise"."UseIndicator" IS '[KS X 9101 표준] 사용여부: — 회사 정보의 사용 여부';

-- ---------------------------------------------------------------------
-- [표준 구분: KS X 9101 표준] 표 34, 조항 7.4.2.1 | 업무영역: 프로젝트관리
-- 테이블명(물리): "ProjectMaster" | 테이블명(논리): 프로젝트마스터
-- 설명: 프로젝트 코드, 프로젝트명 등을 관리하는 프로젝트마스터를 의미한다. 주요 프로젝트 필드의 ProjectAccounting 관련 애플리케이션 활성화를 위한정보로 활용되기도 한다.
-- ---------------------------------------------------------------------
CREATE TABLE "ProjectMaster" ( -- [KS X 9101 표준] 프로젝트마스터 (표 34)
    "ProjectMasterSequenceNo" BIGINT GENERATED BY DEFAULT AS IDENTITY, -- [KS X 9101 표준] 프로젝트마스터 일련번호(PK)
    "EnterpriseID" VARCHAR(50) NOT NULL, -- [KS X 9101 표준] 회사식별자
    "SiteID" VARCHAR(50) NOT NULL, -- [KS X 9101 표준] 사업장식별자
    "PlantID" VARCHAR(50) NOT NULL, -- [KS X 9101 표준] 공장식별자
    "CreatorID" VARCHAR(50), -- [KS X 9101 표준] 등록자식별자
    "CreationDateTime" TIMESTAMP, -- [KS X 9101 표준] 등록일시
    "ModifierID" VARCHAR(50), -- [KS X 9101 표준] 수정자식별자
    "ModificationDateTime" TIMESTAMP, -- [KS X 9101 표준] 수정일시
    "Note" VARCHAR(1000), -- [KS X 9101 표준] 비고
    "ProjectID" VARCHAR(50) NOT NULL, -- [KS X 9101 표준] 프로젝트식별자
    "ProjectName" VARCHAR(200), -- [KS X 9101 표준] 프로젝트명
    "ProjectStatusCode" VARCHAR(30), -- [KS X 9101 표준] 프로젝트상태코드
    "ResponsibleDepartmentID" VARCHAR(50), -- [KS X 9101 표준] 프로젝트담당부서식별자
    "PersonInChargeID" VARCHAR(50), -- [KS X 9101 표준] 프로젝트담당자식별자
    "ProjectContractDate" DATE, -- [KS X 9101 표준] 프로젝트계약일
    "ExpectedStartDate" DATE, -- [KS X 9101 표준] 시작예정일
    "ExpectedEndDate" DATE, -- [KS X 9101 표준] 종료예정일
    "ActualStartDate" DATE, -- [KS X 9101 표준] 실제시작일
    "ActualEndDate" DATE, -- [KS X 9101 표준] 실제종료일
    "SalesDocumentNumber" VARCHAR(50), -- [KS X 9101 표준] 수주문서번호
    "SalesDocumentSequence" INTEGER, -- [KS X 9101 표준] 수주문서순번
    "ItemID" VARCHAR(50), -- [KS X 9101 표준] 품목식별자
    "UseIndicator" BOOLEAN, -- [KS X 9101 표준] 사용여부
    "DivisionID" VARCHAR(50), -- [KS X 9101 표준] 사업부식별자
    CONSTRAINT "PK_ProjectMaster" PRIMARY KEY ("ProjectMasterSequenceNo"),
    CONSTRAINT "UK_ProjectMaster" UNIQUE ("EnterpriseID", "ProjectID")
);

COMMENT ON TABLE "ProjectMaster" IS '[KS X 9101 표준] 프로젝트마스터 (프로젝트 코드, 프로젝트명 등을 관리하는 프로젝트마스터를 의미한다. 주요 프로젝트 필드의 ProjectAccounting 관련 애플리케이션 활성화를 위한정보로 활용되기도 한다.)';
COMMENT ON COLUMN "ProjectMaster"."ProjectMasterSequenceNo" IS '[KS X 9101 표준] 프로젝트마스터 일련번호: — 테이블 행을 식별하는 일련번호(PK, 대리키) — 표준 외 물리 컬럼
— 자동 증가 값(IDENTITY)으로 부여하며 다른 테이블이 참조하지 않음(FK는 UK 참조)';
COMMENT ON COLUMN "ProjectMaster"."EnterpriseID" IS '[KS X 9101 표준] 회사식별자: — 회사를 유일하게 구분할 수 있는 고유식별값
— 기업업무시스템 간의 연동을 수행하는 회사들 간에 자체적으로 정의한 고유식별값
— 참조 대상: 회사(Enterprise)';
COMMENT ON COLUMN "ProjectMaster"."SiteID" IS '[KS X 9101 표준] 사업장식별자: — 회사 내에서 사업장을 구분할수 있는 고유식별값
— 참조 대상: 사업장(Site)';
COMMENT ON COLUMN "ProjectMaster"."PlantID" IS '[KS X 9101 표준] 공장식별자: — 회사 내에서 공장을 구분할 수있는 고유식별값(만약, 공장 개념을 사용하지 않는다면 고정식별자로 설정하여 입력해야 함)
— 참조 대상: 공장(Plant)';
COMMENT ON COLUMN "ProjectMaster"."CreatorID" IS '[KS X 9101 표준] 등록자식별자: — 정보를 처음으로 등록한 사람을 구분할 수 있는 고유식별값으로, 일반적으로 사원번호가사용됨
— 참조 대상: 사원(Personnel)';
COMMENT ON COLUMN "ProjectMaster"."CreationDateTime" IS '[KS X 9101 표준] 등록일시: — 정보를 처음으로 등록한 날짜 (KS X ISO 8601을 따른다)';
COMMENT ON COLUMN "ProjectMaster"."ModifierID" IS '[KS X 9101 표준] 수정자식별자: — 정보를 마지막으로 수정한 사람을 구분할 수 있는 고유식별값으로, 일반적으로 사원번호가 사용됨
— 참조 대상: 사원(Personnel)';
COMMENT ON COLUMN "ProjectMaster"."ModificationDateTime" IS '[KS X 9101 표준] 수정일시: — 정보를 마지막으로 수정한 날짜 (KS X ISO 8601을 따른다.)';
COMMENT ON COLUMN "ProjectMaster"."Note" IS '[KS X 9101 표준] 비고: — 비고사항';
COMMENT ON COLUMN "ProjectMaster"."ProjectID" IS '[KS X 9101 표준] 프로젝트식별자: — 프로젝트를 식별하기 위한 고유값';
COMMENT ON COLUMN "ProjectMaster"."ProjectName" IS '[KS X 9101 표준] 프로젝트명: — 프로젝트의 명칭';
COMMENT ON COLUMN "ProjectMaster"."ProjectStatusCode" IS '[KS X 9101 표준] 프로젝트상태코드: — 프로젝트의 상태
— 프로젝트 상태는 등록, 진행, 종료 등 공통코드에 등록하여 관리하며 회사 기준에 의해 정해짐
— 참조 대상: 공통코드정보(CommonCodeMaster)의 코드';
COMMENT ON COLUMN "ProjectMaster"."ResponsibleDepartmentID" IS '[KS X 9101 표준] 프로젝트담당부서식별자: — 프로젝트 담당 부서를 식별하기 위한 고유값
— 참조 대상: 부서(Department)';
COMMENT ON COLUMN "ProjectMaster"."PersonInChargeID" IS '[KS X 9101 표준] 프로젝트담당자식별자: — 프로젝트 담당자를 식별하기 위한 고유값
— 참조 대상: 사원(Personnel)';
COMMENT ON COLUMN "ProjectMaster"."ProjectContractDate" IS '[KS X 9101 표준] 프로젝트계약일: — 프로젝트 계약일자(KS X ISO 8601을 따른다)';
COMMENT ON COLUMN "ProjectMaster"."ExpectedStartDate" IS '[KS X 9101 표준] 시작예정일: — 예상되는 프로젝트 시작일자(KS X ISO 8601을 따른다)';
COMMENT ON COLUMN "ProjectMaster"."ExpectedEndDate" IS '[KS X 9101 표준] 종료예정일: — 예상되는 프로젝트 종료일자(KS X ISO 8601을 따른다)';
COMMENT ON COLUMN "ProjectMaster"."ActualStartDate" IS '[KS X 9101 표준] 실제시작일: — 실제 프로젝트 시작일자(KS X ISO 8601을 따른다)';
COMMENT ON COLUMN "ProjectMaster"."ActualEndDate" IS '[KS X 9101 표준] 실제종료일: — 실제 프로젝트 종료일자(KS X ISO 8601을 따른다)';
COMMENT ON COLUMN "ProjectMaster"."SalesDocumentNumber" IS '[KS X 9101 표준] 수주문서번호: — 수주문서번호
— 수주문서순번(SalesDocumentSequence)과 함께 사용한다
— 참조 대상: 수주오더(SalesOrder)
— 수주문서순번(SalesDocumentSequence)과 함께 사용한다';
COMMENT ON COLUMN "ProjectMaster"."SalesDocumentSequence" IS '[KS X 9101 표준] 수주문서순번: — 수주문서순번
— 수주문서번호(SalesDocumentNumber)와 함께 수주오더(SalesOrder)를 참조한다';
COMMENT ON COLUMN "ProjectMaster"."ItemID" IS '[KS X 9101 표준] 품목식별자: — 품목을 식별하기 위한 고유값
— 제품, 반제품, 상품, 원자재, 부자재, 저장품, 소모품 등 회사 내시스템으로 관리되는 모든 품목을 포함
— 참조 대상: 품목마스터(ItemMaster)';
COMMENT ON COLUMN "ProjectMaster"."UseIndicator" IS '[KS X 9101 표준] 사용여부: — 프로젝트의 사용 여부';
COMMENT ON COLUMN "ProjectMaster"."DivisionID" IS '[KS X 9101 표준] 사업부식별자: — 프로젝트 담당사업부
— 참조 대상: 부서(Department)';

-- ---------------------------------------------------------------------
-- [표준 구분: KS X 9101 표준] 표 35, 조항 7.4.2.2 | 업무영역: 프로젝트관리
-- 테이블명(물리): "EngineeringChangeOrder" | 테이블명(논리): 설계변경지시
-- 설명: 제품의 설계를 변경하는 지시를 의미한다. 설계변경지시 수행 결과는 BOM 및 공정경로BOM에 반영된다.
-- ---------------------------------------------------------------------
CREATE TABLE "EngineeringChangeOrder" ( -- [KS X 9101 표준] 설계변경지시 (표 35)
    "EngineeringChangeOrderSequenceNo" BIGINT GENERATED BY DEFAULT AS IDENTITY, -- [KS X 9101 표준] 설계변경지시 일련번호(PK)
    "EnterpriseID" VARCHAR(50) NOT NULL, -- [KS X 9101 표준] 회사식별자
    "SiteID" VARCHAR(50) NOT NULL, -- [KS X 9101 표준] 사업장식별자
    "PlantID" VARCHAR(50) NOT NULL, -- [KS X 9101 표준] 공장식별자
    "CreatorID" VARCHAR(50), -- [KS X 9101 표준] 등록자식별자
    "CreationDateTime" TIMESTAMP, -- [KS X 9101 표준] 등록일시
    "ModifierID" VARCHAR(50), -- [KS X 9101 표준] 수정자식별자
    "ModificationDateTime" TIMESTAMP, -- [KS X 9101 표준] 수정일시
    "Note" VARCHAR(1000), -- [KS X 9101 표준] 비고
    "EngineeringChangeOrderID" VARCHAR(50) NOT NULL, -- [KS X 9101 표준] 설계변경지시식별자
    "ItemID" VARCHAR(50), -- [KS X 9101 표준] 품목식별자
    "ValidStartDate" DATE, -- [KS X 9101 표준] 유효시작일
    "ValidEndDate" DATE, -- [KS X 9101 표준] 유효종료일
    "ExpectedExecutionDate" DATE, -- [KS X 9101 표준] 적용예정일
    "ExecutionDate" DATE, -- [KS X 9101 표준] 적용이행일
    "BOMType" VARCHAR(30), -- [KS X 9101 표준] 자재명세서유형
    "BOMID" VARCHAR(50), -- [KS X 9101 표준] 자재명세서식별자
    "BOMRevisionNumber" INTEGER, -- [KS X 9101 표준] 자재명세서버전
    "ChildItemID" VARCHAR(50), -- [KS X 9101 표준] 자품목식별자
    "ItemUOMCode" VARCHAR(20), -- [KS X 9101 표준] 기준단위코드
    "ActualRequirementQuantity" NUMERIC(18,6), -- [KS X 9101 표준] 실소요수량
    CONSTRAINT "PK_EngineeringChangeOrder" PRIMARY KEY ("EngineeringChangeOrderSequenceNo"),
    CONSTRAINT "UK_EngineeringChangeOrder" UNIQUE ("EnterpriseID", "EngineeringChangeOrderID")
);

COMMENT ON TABLE "EngineeringChangeOrder" IS '[KS X 9101 표준] 설계변경지시 (제품의 설계를 변경하는 지시를 의미한다. 설계변경지시 수행 결과는 BOM 및 공정경로BOM에 반영된다.)';
