COMMENT ON COLUMN "EngineeringChangeOrder"."SiteID" IS '[KS X 9101 표준] 사업장식별자: — 회사 내에서 사업장을 구분할수 있는 고유식별값
— 참조 대상: 사업장(Site)';
COMMENT ON COLUMN "EngineeringChangeOrder"."PlantID" IS '[KS X 9101 표준] 공장식별자: — 회사 내에서 공장을 구분할 수있는 고유식별값(만약, 공장 개념을 사용하지 않는다면 고정식별자로 설정하여 입력해야 함)
— 참조 대상: 공장(Plant)';
COMMENT ON COLUMN "EngineeringChangeOrder"."CreatorID" IS '[KS X 9101 표준] 등록자식별자: — 정보를 처음으로 등록한 사람을 구분할 수 있는 고유식별값으로, 일반적으로 사원번호가사용됨
— 참조 대상: 사원(Personnel)';
COMMENT ON COLUMN "EngineeringChangeOrder"."CreationDateTime" IS '[KS X 9101 표준] 등록일시: — 정보를 처음으로 등록한 날짜 (KS X ISO 8601을 따른다)';
COMMENT ON COLUMN "EngineeringChangeOrder"."ModifierID" IS '[KS X 9101 표준] 수정자식별자: — 정보를 마지막으로 수정한 사람을 구분할 수 있는 고유식별값으로, 일반적으로 사원번호가 사용됨
— 참조 대상: 사원(Personnel)';
COMMENT ON COLUMN "EngineeringChangeOrder"."ModificationDateTime" IS '[KS X 9101 표준] 수정일시: — 정보를 마지막으로 수정한 날짜 (KS X ISO 8601을 따른다.)';
COMMENT ON COLUMN "EngineeringChangeOrder"."Note" IS '[KS X 9101 표준] 비고: — 비고사항';
COMMENT ON COLUMN "EngineeringChangeOrder"."EngineeringChangeOrderID" IS '[KS X 9101 표준] 설계변경지시식별자: — 설계변경지시를 식별하기 위한 고유값';
COMMENT ON COLUMN "EngineeringChangeOrder"."ItemID" IS '[KS X 9101 표준] 품목식별자: — 품목을 식별하기 위한 고유값
— 제품, 반제품, 상품, 원자재, 부자재, 저장품, 소모품 등 회사 내시스템으로 관리되는 모든 품목을 포함
— 참조 대상: 품목마스터(ItemMaster)';
COMMENT ON COLUMN "EngineeringChangeOrder"."ValidStartDate" IS '[KS X 9101 표준] 유효시작일: — 설계변경지시의 유효시작일(KS X ISO 8601을 따른다)';
COMMENT ON COLUMN "EngineeringChangeOrder"."ValidEndDate" IS '[KS X 9101 표준] 유효종료일: — 설계변경지시의 유효종료일(KS X ISO 8601을 따른다)';
COMMENT ON COLUMN "EngineeringChangeOrder"."ExpectedExecutionDate" IS '[KS X 9101 표준] 적용예정일: — 설계변경의 적용이 예정된 일자(KS X ISO 8601을 따른다)';
COMMENT ON COLUMN "EngineeringChangeOrder"."ExecutionDate" IS '[KS X 9101 표준] 적용이행일: — 설계변경의 적용을 이행한 일자(KS X ISO 8601을 따른다)';
COMMENT ON COLUMN "EngineeringChangeOrder"."BOMType" IS '[KS X 9101 표준] 자재명세서유형: — 자재명세서의 유형
— 예: 제조BOM, 원가BOM 등
— 참조 대상: 공통코드정보(CommonCodeMaster)의 코드';
COMMENT ON COLUMN "EngineeringChangeOrder"."BOMID" IS '[KS X 9101 표준] 자재명세서식별자: — 설계변경 대상 자재명세서를 식별하기 위한 고유값
— 참조 대상: 자재명세서(BOM)';
COMMENT ON COLUMN "EngineeringChangeOrder"."BOMRevisionNumber" IS '[KS X 9101 표준] 자재명세서버전: — 자재명세서의 버전
— 참조 대상: 자재명세서(BOM)
— 자재명세서식별자(BOMID)와 함께 자재명세서(BOM)를 참조한다';
COMMENT ON COLUMN "EngineeringChangeOrder"."ChildItemID" IS '[KS X 9101 표준] 자품목식별자: — 설계변경지시 자품목을 의미
— 참조 대상: 품목마스터(ItemMaster)';
COMMENT ON COLUMN "EngineeringChangeOrder"."ItemUOMCode" IS '[KS X 9101 표준] 기준단위코드: — 기준단위코드(예: EA, DZ, HD 등)
— 참조 대상: 단위그룹(UOMGroup)의 단위코드';
COMMENT ON COLUMN "EngineeringChangeOrder"."ActualRequirementQuantity" IS '[KS X 9101 표준] 실소요수량: — 대상 품목을 생산하기 위해 투입되는 품목의 소요량(예: EA, DZ, HD 등)';

-- ---------------------------------------------------------------------
-- [표준 구분: KS X 9101 표준] 표 36, 조항 7.4.3.1 | 업무영역: 판매관리
-- 테이블명(물리): "SalesOrderHeader" | 테이블명(논리): 수주오더헤더
-- 설명: 수주오더(SalesOrder) 명사의 헤더 구조체(struct) 수주문서 1건의 공통 정보(고객사, 수주일, 수주유형, 거래 조건) 수주문서마다 1회 나타남
-- ---------------------------------------------------------------------
CREATE TABLE "SalesOrderHeader" ( -- [KS X 9101 표준] 수주오더헤더 (표 36)
    "SalesOrderHeaderSequenceNo" BIGINT GENERATED BY DEFAULT AS IDENTITY, -- [KS X 9101 표준] 수주오더헤더 일련번호(PK)
    "EnterpriseID" VARCHAR(50) NOT NULL, -- [KS X 9101 표준] 회사식별자
    "SiteID" VARCHAR(50) NOT NULL, -- [KS X 9101 표준] 사업장식별자
    "PlantID" VARCHAR(50) NOT NULL, -- [KS X 9101 표준] 공장식별자
    "CreatorID" VARCHAR(50), -- [KS X 9101 표준] 등록자식별자
    "CreationDateTime" TIMESTAMP, -- [KS X 9101 표준] 등록일시
    "ModifierID" VARCHAR(50), -- [KS X 9101 표준] 수정자식별자
    "ModificationDateTime" TIMESTAMP, -- [KS X 9101 표준] 수정일시
    "Note" VARCHAR(1000), -- [KS X 9101 표준] 비고
    "SalesDocumentNumber" VARCHAR(50) NOT NULL, -- [KS X 9101 표준] 수주문서번호
    "SalesOrderType" VARCHAR(30), -- [KS X 9101 표준] 수주유형
    "CustomerID" VARCHAR(50), -- [KS X 9101 표준] 고객사식별자
    "SalesDate" DATE, -- [KS X 9101 표준] 수주일
    "SalesStatus" VARCHAR(30), -- [KS X 9101 표준] 수주상태
    "ShipmentTermsCode" VARCHAR(30), -- [KS X 9101 표준] 출하조건코드
    "SalesTransactionType" VARCHAR(30), -- [KS X 9101 표준] 거래유형
    "ReturnIndicator" BOOLEAN, -- [KS X 9101 표준] 반품여부
    "ExportIndicator" BOOLEAN, -- [KS X 9101 표준] 수출여부
    "SalesAutomaticApprovalIndicator" BOOLEAN, -- [KS X 9101 표준] 수주자동승인여부
    CONSTRAINT "PK_SalesOrderHeader" PRIMARY KEY ("SalesOrderHeaderSequenceNo"),
    CONSTRAINT "UK_SalesOrderHeader" UNIQUE ("EnterpriseID", "SalesDocumentNumber")
);

COMMENT ON TABLE "SalesOrderHeader" IS '[KS X 9101 표준] 수주오더헤더 (수주오더(SalesOrder) 명사의 헤더 구조체(struct) 수주문서 1건의 공통 정보(고객사, 수주일, 수주유형, 거래 조건) 수주문서마다 1회 나타남)';
COMMENT ON COLUMN "SalesOrderHeader"."SalesOrderHeaderSequenceNo" IS '[KS X 9101 표준] 수주오더헤더 일련번호: — 테이블 행을 식별하는 일련번호(PK, 대리키) — 표준 외 물리 컬럼
— 자동 증가 값(IDENTITY)으로 부여하며 다른 테이블이 참조하지 않음(FK는 UK 참조)';
COMMENT ON COLUMN "SalesOrderHeader"."EnterpriseID" IS '[KS X 9101 표준] 회사식별자: — 회사를 유일하게 구분할 수 있는 고유식별값
— 기업업무시스템 간의 연동을 수행하는 회사들 간에 자체적으로 정의한 고유식별값
— 참조 대상: 회사(Enterprise)';
COMMENT ON COLUMN "SalesOrderHeader"."SiteID" IS '[KS X 9101 표준] 사업장식별자: — 회사 내에서 사업장을 구분할수 있는 고유식별값
— 참조 대상: 사업장(Site)';
COMMENT ON COLUMN "SalesOrderHeader"."PlantID" IS '[KS X 9101 표준] 공장식별자: — 회사 내에서 공장을 구분할 수있는 고유식별값(만약, 공장 개념을 사용하지 않는다면 고정식별자로 설정하여 입력해야 함)
— 참조 대상: 공장(Plant)';
COMMENT ON COLUMN "SalesOrderHeader"."CreatorID" IS '[KS X 9101 표준] 등록자식별자: — 정보를 처음으로 등록한 사람을 구분할 수 있는 고유식별값으로, 일반적으로 사원번호가사용됨
— 참조 대상: 사원(Personnel)';
COMMENT ON COLUMN "SalesOrderHeader"."CreationDateTime" IS '[KS X 9101 표준] 등록일시: — 정보를 처음으로 등록한 날짜 (KS X ISO 8601을 따른다)';
COMMENT ON COLUMN "SalesOrderHeader"."ModifierID" IS '[KS X 9101 표준] 수정자식별자: — 정보를 마지막으로 수정한 사람을 구분할 수 있는 고유식별값으로, 일반적으로 사원번호가 사용됨
— 참조 대상: 사원(Personnel)';
COMMENT ON COLUMN "SalesOrderHeader"."ModificationDateTime" IS '[KS X 9101 표준] 수정일시: — 정보를 마지막으로 수정한 날짜 (KS X ISO 8601을 따른다.)';
COMMENT ON COLUMN "SalesOrderHeader"."Note" IS '[KS X 9101 표준] 비고: — 비고사항';
COMMENT ON COLUMN "SalesOrderHeader"."SalesDocumentNumber" IS '[KS X 9101 표준] 수주문서번호: — 수주문서를 식별하기 위한 고유값
— 수주문서 단위로 부여하며, 수주오더헤더에 1회 기재함';
COMMENT ON COLUMN "SalesOrderHeader"."SalesOrderType" IS '[KS X 9101 표준] 수주유형: — 수주유형을 의미
— 수주 형태, 성격 등을 관리
— 수주유형(예: 내수, 수출, 견본, 무상 등)
— 참조 대상: 공통코드정보(CommonCodeMaster)의 코드';
COMMENT ON COLUMN "SalesOrderHeader"."CustomerID" IS '[KS X 9101 표준] 고객사식별자: — 품목을 구매해가는 거래처를 식별하기 위한 고유값
— 참조 대상: 고객사(CustomerPartyMaster)';
COMMENT ON COLUMN "SalesOrderHeader"."SalesDate" IS '[KS X 9101 표준] 수주일: — 수주일(KS X ISO 8601을 따른다)';
COMMENT ON COLUMN "SalesOrderHeader"."SalesStatus" IS '[KS X 9101 표준] 수주상태: — 수주상태
— 예: 수주등록, 수주확정, 부분출하, 출하완료, 매출확정, 종결, 보류, 취소
— 참조 대상: 공통코드정보(CommonCodeMaster)의 코드';
COMMENT ON COLUMN "SalesOrderHeader"."ShipmentTermsCode" IS '[KS X 9101 표준] 출하조건코드: — 출하조건코드
— 출하·인도 조건(예: 공장인도, 도착지인도 등)으로, 국제 거래는 Incoterms 2020 코드(EXW, FCA, FOB, CIF, DAP 등) 사용 권고
— 참조 대상: 공통코드정보(CommonCodeMaster)의 코드';
COMMENT ON COLUMN "SalesOrderHeader"."SalesTransactionType" IS '[KS X 9101 표준] 거래유형: — 거래유형
— 매출 거래유형(예: 과세, 영세율, 면세, 수출 등)
— 참조 대상: 공통코드정보(CommonCodeMaster)의 코드';
COMMENT ON COLUMN "SalesOrderHeader"."ReturnIndicator" IS '[KS X 9101 표준] 반품여부: — 반품여부';
COMMENT ON COLUMN "SalesOrderHeader"."ExportIndicator" IS '[KS X 9101 표준] 수출여부: — 수출여부';
COMMENT ON COLUMN "SalesOrderHeader"."SalesAutomaticApprovalIndicator" IS '[KS X 9101 표준] 수주자동승인여부: — 수주자동승인여부';

-- ---------------------------------------------------------------------
-- [표준 구분: KS X 9101 표준] 표 36, 조항 7.4.3.1 | 업무영역: 판매관리
-- 테이블명(물리): "SalesOrderLine" | 테이블명(논리): 수주오더라인
-- 설명: 수주오더(SalesOrder) 명사의 라인 구조체(struct[1..N]) 수주문서를 구성하는 품목 행 정보 수주오더헤더 아래에 1회 이상 반복하여 나타남(1..N)
-- ---------------------------------------------------------------------
CREATE TABLE "SalesOrderLine" ( -- [KS X 9101 표준] 수주오더라인 (표 36)
    "SalesOrderLineSequenceNo" BIGINT GENERATED BY DEFAULT AS IDENTITY, -- [KS X 9101 표준] 수주오더라인 일련번호(PK)
    "EnterpriseID" VARCHAR(50) NOT NULL, -- [KS X 9101 표준] 회사식별자
    "SiteID" VARCHAR(50) NOT NULL, -- [KS X 9101 표준] 사업장식별자
    "PlantID" VARCHAR(50) NOT NULL, -- [KS X 9101 표준] 공장식별자
    "CreatorID" VARCHAR(50), -- [KS X 9101 표준] 등록자식별자
    "CreationDateTime" TIMESTAMP, -- [KS X 9101 표준] 등록일시
    "ModifierID" VARCHAR(50), -- [KS X 9101 표준] 수정자식별자
    "ModificationDateTime" TIMESTAMP, -- [KS X 9101 표준] 수정일시
    "Note" VARCHAR(1000), -- [KS X 9101 표준] 비고
    "SalesDocumentNumber" VARCHAR(50) NOT NULL, -- [KS X 9101 표준] 수주문서번호
    "SalesDocumentSequence" INTEGER NOT NULL, -- [KS X 9101 표준] 수주문서순번
    "ItemID" VARCHAR(50), -- [KS X 9101 표준] 품목식별자
    "ItemName" VARCHAR(200), -- [KS X 9101 표준] 품목명
    "ItemQuantity" NUMERIC(18,6), -- [KS X 9101 표준] 품목수량
    "ItemUOMCode" VARCHAR(20), -- [KS X 9101 표준] 기준단위코드
    "SellingUOMCode" VARCHAR(20), -- [KS X 9101 표준] 판매단위코드
    "ConversionUnitQuantity" NUMERIC(18,6), -- [KS X 9101 표준] 단위환산수량
    "ItemUnitQuantity" NUMERIC(18,6), -- [KS X 9101 표준] 기준단위수량
    "RequestedDeliveryDate" DATE, -- [KS X 9101 표준] 요청납기일
    CONSTRAINT "PK_SalesOrderLine" PRIMARY KEY ("SalesOrderLineSequenceNo"),
    CONSTRAINT "UK_SalesOrderLine" UNIQUE ("EnterpriseID", "SalesDocumentNumber", "SalesDocumentSequence")
);

COMMENT ON TABLE "SalesOrderLine" IS '[KS X 9101 표준] 수주오더라인 (수주오더(SalesOrder) 명사의 라인 구조체(struct[1..N]) 수주문서를 구성하는 품목 행 정보 수주오더헤더 아래에 1회 이상 반복하여 나타남(1..N))';
COMMENT ON COLUMN "SalesOrderLine"."SalesOrderLineSequenceNo" IS '[KS X 9101 표준] 수주오더라인 일련번호: — 테이블 행을 식별하는 일련번호(PK, 대리키) — 표준 외 물리 컬럼
— 자동 증가 값(IDENTITY)으로 부여하며 다른 테이블이 참조하지 않음(FK는 UK 참조)';
COMMENT ON COLUMN "SalesOrderLine"."EnterpriseID" IS '[KS X 9101 표준] 회사식별자: — 회사를 유일하게 구분할 수 있는 고유식별값
— 기업업무시스템 간의 연동을 수행하는 회사들 간에 자체적으로 정의한 고유식별값
— 참조 대상: 회사(Enterprise)';
COMMENT ON COLUMN "SalesOrderLine"."SiteID" IS '[KS X 9101 표준] 사업장식별자: — 회사 내에서 사업장을 구분할수 있는 고유식별값
— 참조 대상: 사업장(Site)';
COMMENT ON COLUMN "SalesOrderLine"."PlantID" IS '[KS X 9101 표준] 공장식별자: — 회사 내에서 공장을 구분할 수있는 고유식별값(만약, 공장 개념을 사용하지 않는다면 고정식별자로 설정하여 입력해야 함)
— 참조 대상: 공장(Plant)';
COMMENT ON COLUMN "SalesOrderLine"."CreatorID" IS '[KS X 9101 표준] 등록자식별자: — 정보를 처음으로 등록한 사람을 구분할 수 있는 고유식별값으로, 일반적으로 사원번호가사용됨
— 참조 대상: 사원(Personnel)';
COMMENT ON COLUMN "SalesOrderLine"."CreationDateTime" IS '[KS X 9101 표준] 등록일시: — 정보를 처음으로 등록한 날짜 (KS X ISO 8601을 따른다)';
COMMENT ON COLUMN "SalesOrderLine"."ModifierID" IS '[KS X 9101 표준] 수정자식별자: — 정보를 마지막으로 수정한 사람을 구분할 수 있는 고유식별값으로, 일반적으로 사원번호가 사용됨
— 참조 대상: 사원(Personnel)';
COMMENT ON COLUMN "SalesOrderLine"."ModificationDateTime" IS '[KS X 9101 표준] 수정일시: — 정보를 마지막으로 수정한 날짜 (KS X ISO 8601을 따른다.)';
COMMENT ON COLUMN "SalesOrderLine"."Note" IS '[KS X 9101 표준] 비고: — 비고사항';
COMMENT ON COLUMN "SalesOrderLine"."SalesDocumentNumber" IS '[KS X 9101 표준] 수주문서번호: — 수주문서를 식별하기 위한 고유값
— 참조 대상: 수주오더헤더(SalesOrderHeader)';
COMMENT ON COLUMN "SalesOrderLine"."SalesDocumentSequence" IS '[KS X 9101 표준] 수주문서순번: — 수주문서 내 품목 행의 순서
— 수주오더라인은 수주문서번호와 수주문서순번의 조합으로 구분하며, 다른 명사는 이 조합으로 수주오더라인을 참조한다';
COMMENT ON COLUMN "SalesOrderLine"."ItemID" IS '[KS X 9101 표준] 품목식별자: — 품목을 식별하기 위한 고유값
— 제품, 반제품, 상품, 원자재, 부자재, 저장품, 소모품 등 회사내 시스템으로 관리되는 모든 품목을 포함
— 참조 대상: 품목마스터(ItemMaster)';
COMMENT ON COLUMN "SalesOrderLine"."ItemName" IS '[KS X 9101 표준] 품목명: — 품목의 명칭
— 참조 대상: 품목마스터(ItemMaster.ItemName)';
COMMENT ON COLUMN "SalesOrderLine"."ItemQuantity" IS '[KS X 9101 표준] 품목수량: — 품목수량(수량의 단위는 기준단위코드로 함)';
COMMENT ON COLUMN "SalesOrderLine"."ItemUOMCode" IS '[KS X 9101 표준] 기준단위코드: — 기준단위코드(예: EA, DZ, HD 등)
— 참조 대상: 단위그룹(UOMGroup)의 단위코드';
COMMENT ON COLUMN "SalesOrderLine"."SellingUOMCode" IS '[KS X 9101 표준] 판매단위코드: — 판매단위코드
— 예: EA, BOX, SET 등
— 참조 대상: 단위그룹(UOMGroup)의 단위코드';
COMMENT ON COLUMN "SalesOrderLine"."ConversionUnitQuantity" IS '[KS X 9101 표준] 단위환산수량: — 단위환산수량(환산수량의 단위는 판매단위코드로 함)';
COMMENT ON COLUMN "SalesOrderLine"."ItemUnitQuantity" IS '[KS X 9101 표준] 기준단위수량: — 기준수량(수량의 단위는 기준단위코드로 함)';
COMMENT ON COLUMN "SalesOrderLine"."RequestedDeliveryDate" IS '[KS X 9101 표준] 요청납기일: — 요청납기일(KS X ISO 8601을 따른다)';

-- ---------------------------------------------------------------------
-- [표준 구분: KS X 9101 표준] 표 37, 조항 7.4.3.2 | 업무영역: 판매관리
-- 테이블명(물리): "SalesPlan" | 테이블명(논리): 판매계획
-- 설명: 고객사 Forecast정보 및 수요예측정보를 토대로 작성된 판매계획을 의미한다.
-- ---------------------------------------------------------------------
CREATE TABLE "SalesPlan" ( -- [KS X 9101 표준] 판매계획 (표 37)
    "SalesPlanSequenceNo" BIGINT GENERATED BY DEFAULT AS IDENTITY, -- [KS X 9101 표준] 판매계획 일련번호(PK)
    "EnterpriseID" VARCHAR(50) NOT NULL, -- [KS X 9101 표준] 회사식별자
    "SiteID" VARCHAR(50) NOT NULL, -- [KS X 9101 표준] 사업장식별자
    "PlantID" VARCHAR(50) NOT NULL, -- [KS X 9101 표준] 공장식별자
    "CreatorID" VARCHAR(50), -- [KS X 9101 표준] 등록자식별자
    "CreationDateTime" TIMESTAMP, -- [KS X 9101 표준] 등록일시
    "ModifierID" VARCHAR(50), -- [KS X 9101 표준] 수정자식별자
    "ModificationDateTime" TIMESTAMP, -- [KS X 9101 표준] 수정일시
    "Note" VARCHAR(1000), -- [KS X 9101 표준] 비고
    "SalesPlanID" VARCHAR(50) NOT NULL, -- [KS X 9101 표준] 판매계획식별자
    "ItemID" VARCHAR(50), -- [KS X 9101 표준] 품목식별자
    "ItemName" VARCHAR(200), -- [KS X 9101 표준] 품목명
    "SalesProjection" NUMERIC(18,6), -- [KS X 9101 표준] 판매추정치
    "ProjectionStartDate" DATE, -- [KS X 9101 표준] 예측시작일
    "ProjectionEndDate" DATE, -- [KS X 9101 표준] 예측종료일
    CONSTRAINT "PK_SalesPlan" PRIMARY KEY ("SalesPlanSequenceNo"),
    CONSTRAINT "UK_SalesPlan" UNIQUE ("EnterpriseID", "SalesPlanID")
);

COMMENT ON TABLE "SalesPlan" IS '[KS X 9101 표준] 판매계획 (고객사 Forecast정보 및 수요예측정보를 토대로 작성된 판매계획을 의미한다.)';
COMMENT ON COLUMN "SalesPlan"."SalesPlanSequenceNo" IS '[KS X 9101 표준] 판매계획 일련번호: — 테이블 행을 식별하는 일련번호(PK, 대리키) — 표준 외 물리 컬럼
— 자동 증가 값(IDENTITY)으로 부여하며 다른 테이블이 참조하지 않음(FK는 UK 참조)';
COMMENT ON COLUMN "SalesPlan"."EnterpriseID" IS '[KS X 9101 표준] 회사식별자: — 회사를 유일하게 구분할 수 있는 고유식별값
— 기업업무시스템 간의 연동을 수행하는 회사들 간에 자체적으로 정의한 고유식별값
— 참조 대상: 회사(Enterprise)';
COMMENT ON COLUMN "SalesPlan"."SiteID" IS '[KS X 9101 표준] 사업장식별자: — 회사 내에서 사업장을 구분할수 있는 고유식별값
— 참조 대상: 사업장(Site)';
COMMENT ON COLUMN "SalesPlan"."PlantID" IS '[KS X 9101 표준] 공장식별자: — 회사 내에서 공장을 구분할 수있는 고유식별값(만약, 공장 개념을 사용하지 않는다면 고정식별자로 설정하여 입력해야 함)
— 참조 대상: 공장(Plant)';
COMMENT ON COLUMN "SalesPlan"."CreatorID" IS '[KS X 9101 표준] 등록자식별자: — 정보를 처음으로 등록한 사람을 구분할 수 있는 고유식별값으로, 일반적으로 사원번호가사용됨
— 참조 대상: 사원(Personnel)';
COMMENT ON COLUMN "SalesPlan"."CreationDateTime" IS '[KS X 9101 표준] 등록일시: — 정보를 처음으로 등록한 날짜 (KS X ISO 8601을 따른다)';
COMMENT ON COLUMN "SalesPlan"."ModifierID" IS '[KS X 9101 표준] 수정자식별자: — 정보를 마지막으로 수정한 사람을 구분할 수 있는 고유식별값으로, 일반적으로 사원번호가 사용됨
— 참조 대상: 사원(Personnel)';
COMMENT ON COLUMN "SalesPlan"."ModificationDateTime" IS '[KS X 9101 표준] 수정일시: — 정보를 마지막으로 수정한 날짜 (KS X ISO 8601을 따른다.)';
COMMENT ON COLUMN "SalesPlan"."Note" IS '[KS X 9101 표준] 비고: — 비고사항';
COMMENT ON COLUMN "SalesPlan"."SalesPlanID" IS '[KS X 9101 표준] 판매계획식별자: — 판매계획을 식별하기 위한 고유값';
COMMENT ON COLUMN "SalesPlan"."ItemID" IS '[KS X 9101 표준] 품목식별자: — 품목을 식별하기 위한 고유값
— 제품, 반제품, 상품, 원자재, 부자재, 저장품, 소모품 등 회사내 시스템으로 관리되는 모든 품목을 포함
— 참조 대상: 품목마스터(ItemMaster)';
COMMENT ON COLUMN "SalesPlan"."ItemName" IS '[KS X 9101 표준] 품목명: — 품목의 명칭
— 참조 대상: 품목마스터(ItemMaster.ItemName)';
COMMENT ON COLUMN "SalesPlan"."SalesProjection" IS '[KS X 9101 표준] 판매추정치: — 판매추정치';
COMMENT ON COLUMN "SalesPlan"."ProjectionStartDate" IS '[KS X 9101 표준] 예측시작일: — 판매추정치를 산정하기 위한 시작일(KS X ISO 8601을 따른다)';
COMMENT ON COLUMN "SalesPlan"."ProjectionEndDate" IS '[KS X 9101 표준] 예측종료일: — 판매추정치를 산정하기 위한 종료일(KS X ISO 8601을 따른다)';

-- ---------------------------------------------------------------------
-- [표준 구분: KS X 9101 표준] 표 38, 조항 7.4.4.1 | 업무영역: 구매관리
-- 테이블명(물리): "BasePrice" | 테이블명(논리): 기준가격
-- 설명: 구매요청 시 참조하기 위한 구매품의 기준가격 정보를 의미한다.
-- ---------------------------------------------------------------------
CREATE TABLE "BasePrice" ( -- [KS X 9101 표준] 기준가격 (표 38)
    "BasePriceSequenceNo" BIGINT GENERATED BY DEFAULT AS IDENTITY, -- [KS X 9101 표준] 기준가격 일련번호(PK)
    "EnterpriseID" VARCHAR(50) NOT NULL, -- [KS X 9101 표준] 회사식별자
    "SiteID" VARCHAR(50) NOT NULL, -- [KS X 9101 표준] 사업장식별자
    "PlantID" VARCHAR(50) NOT NULL, -- [KS X 9101 표준] 공장식별자
    "CreatorID" VARCHAR(50), -- [KS X 9101 표준] 등록자식별자
    "CreationDateTime" TIMESTAMP, -- [KS X 9101 표준] 등록일시
    "ModifierID" VARCHAR(50), -- [KS X 9101 표준] 수정자식별자
    "ModificationDateTime" TIMESTAMP, -- [KS X 9101 표준] 수정일시
    "Note" VARCHAR(1000), -- [KS X 9101 표준] 비고
    "ItemID" VARCHAR(50) NOT NULL, -- [KS X 9101 표준] 품목식별자
    "CurrencyCode" VARCHAR(30) NOT NULL, -- [KS X 9101 표준] 환종코드
    "UnitPrice" NUMERIC(18,6), -- [KS X 9101 표준] 단가
    "PaymentTermsCode" VARCHAR(30), -- [KS X 9101 표준] 결제조건코드
    "UseIndicator" BOOLEAN, -- [KS X 9101 표준] 사용여부
    CONSTRAINT "PK_BasePrice" PRIMARY KEY ("BasePriceSequenceNo"),
    CONSTRAINT "UK_BasePrice" UNIQUE ("EnterpriseID", "ItemID", "CurrencyCode")
);

COMMENT ON TABLE "BasePrice" IS '[KS X 9101 표준] 기준가격 (구매요청 시 참조하기 위한 구매품의 기준가격 정보를 의미한다.)';
COMMENT ON COLUMN "BasePrice"."BasePriceSequenceNo" IS '[KS X 9101 표준] 기준가격 일련번호: — 테이블 행을 식별하는 일련번호(PK, 대리키) — 표준 외 물리 컬럼
— 자동 증가 값(IDENTITY)으로 부여하며 다른 테이블이 참조하지 않음(FK는 UK 참조)';
COMMENT ON COLUMN "BasePrice"."EnterpriseID" IS '[KS X 9101 표준] 회사식별자: — 회사를 유일하게 구분할 수 있는 고유식별값
— 기업업무시스템 간의 연동을 수행하는 회사들 간에 자체적으로 정의한 고유식별값
— 참조 대상: 회사(Enterprise)';
COMMENT ON COLUMN "BasePrice"."SiteID" IS '[KS X 9101 표준] 사업장식별자: — 회사 내에서 사업장을 구분할수 있는 고유식별값
— 참조 대상: 사업장(Site)';
COMMENT ON COLUMN "BasePrice"."PlantID" IS '[KS X 9101 표준] 공장식별자: — 회사 내에서 공장을 구분할 수있는 고유식별값(만약, 공장 개념을 사용하지 않는다면 고정식별자로 설정하여 입력해야 함)
— 참조 대상: 공장(Plant)';
COMMENT ON COLUMN "BasePrice"."CreatorID" IS '[KS X 9101 표준] 등록자식별자: — 정보를 처음으로 등록한 사람을 구분할 수 있는 고유식별값으로, 일반적으로 사원번호가사용됨
— 참조 대상: 사원(Personnel)';
COMMENT ON COLUMN "BasePrice"."CreationDateTime" IS '[KS X 9101 표준] 등록일시: — 정보를 처음으로 등록한 날짜 (KS X ISO 8601을 따른다)';
COMMENT ON COLUMN "BasePrice"."ModifierID" IS '[KS X 9101 표준] 수정자식별자: — 정보를 마지막으로 수정한 사람을 구분할 수 있는 고유식별값으로, 일반적으로 사원번호가 사용됨
— 참조 대상: 사원(Personnel)';
COMMENT ON COLUMN "BasePrice"."ModificationDateTime" IS '[KS X 9101 표준] 수정일시: — 정보를 마지막으로 수정한 날짜 (KS X ISO 8601을 따른다.)';
COMMENT ON COLUMN "BasePrice"."Note" IS '[KS X 9101 표준] 비고: — 비고사항';
COMMENT ON COLUMN "BasePrice"."ItemID" IS '[KS X 9101 표준] 품목식별자: — 품목을 식별하기 위한 고유값
— 제품, 반제품, 상품, 원자재, 부자재, 저장품, 소모품 등 회사내 시스템으로 관리되는 모든 품목을 포함
— 참조 대상: 품목마스터(ItemMaster)';
COMMENT ON COLUMN "BasePrice"."CurrencyCode" IS '[KS X 9101 표준] 환종코드: — 환종코드(예: KRW, USD, JPY 등)
— 참조 대상: 공통코드정보(CommonCodeMaster)의 코드(ISO 4217 통화코드 사용 권고)
— 기준가격 행은 품목식별자와 환종코드의 조합으로 구분하며, 조합에 포함되는 속성은 값을 생략할 수 없음(7.1)';
COMMENT ON COLUMN "BasePrice"."UnitPrice" IS '[KS X 9101 표준] 단가: — 단가(금액의 단위는 환종코드로 함)';
COMMENT ON COLUMN "BasePrice"."PaymentTermsCode" IS '[KS X 9101 표준] 결제조건코드: — 구매거래처에 대한 대금결제조건
— 대금결제조건(예: 현금, 어음, 월말 마감 후 30일 지급 등)
— 참조 대상: 공통코드정보(CommonCodeMaster)의 코드';
COMMENT ON COLUMN "BasePrice"."UseIndicator" IS '[KS X 9101 표준] 사용여부: — 기준가격의 사용 여부';

-- ---------------------------------------------------------------------
-- [표준 구분: KS X 9101 표준] 표 39, 조항 7.4.4.2 | 업무영역: 구매관리
-- 테이블명(물리): "PurchaseRequisition" | 테이블명(논리): 구매요청
-- 설명: 생산 또는 판매를 위해 수급되어야 할 품목을 요청하는 것을 의미한다(원부자재, 소모품, 상품 등).
-- ---------------------------------------------------------------------
CREATE TABLE "PurchaseRequisition" ( -- [KS X 9101 표준] 구매요청 (표 39)
    "PurchaseRequisitionSequenceNo" BIGINT GENERATED BY DEFAULT AS IDENTITY, -- [KS X 9101 표준] 구매요청 일련번호(PK)
    "EnterpriseID" VARCHAR(50) NOT NULL, -- [KS X 9101 표준] 회사식별자
    "SiteID" VARCHAR(50) NOT NULL, -- [KS X 9101 표준] 사업장식별자
    "PlantID" VARCHAR(50) NOT NULL, -- [KS X 9101 표준] 공장식별자
    "CreatorID" VARCHAR(50), -- [KS X 9101 표준] 등록자식별자
    "CreationDateTime" TIMESTAMP, -- [KS X 9101 표준] 등록일시
    "ModifierID" VARCHAR(50), -- [KS X 9101 표준] 수정자식별자
    "ModificationDateTime" TIMESTAMP, -- [KS X 9101 표준] 수정일시
    "Note" VARCHAR(1000), -- [KS X 9101 표준] 비고
    "PurchaseRequisitionID" VARCHAR(50) NOT NULL, -- [KS X 9101 표준] 구매요청식별자
    "PurchaseRequisitionRevisionNumber" INTEGER, -- [KS X 9101 표준] 구매요청버전
    "ItemID" VARCHAR(50), -- [KS X 9101 표준] 품목식별자
    "ItemName" VARCHAR(200), -- [KS X 9101 표준] 품목명
    "DemandQuantity" NUMERIC(18,6), -- [KS X 9101 표준] 구매요청수량
    "ItemUOMCode" VARCHAR(20), -- [KS X 9101 표준] 기준단위코드
    "PurchaseRequisitionUnitPrice" NUMERIC(18,6), -- [KS X 9101 표준] 구매요청단가
    "CurrencyCode" VARCHAR(30), -- [KS X 9101 표준] 환종코드
    "VendorID" VARCHAR(50), -- [KS X 9101 표준] 공급사식별자
    "VendorName" VARCHAR(200), -- [KS X 9101 표준] 공급사명
    "RequestedDeliveryDate" DATE, -- [KS X 9101 표준] 요청납기일
    "RequesterDepartmentID" VARCHAR(50), -- [KS X 9101 표준] 구매요청부서
    "RequesterPersonnelID" VARCHAR(50), -- [KS X 9101 표준] 구매요청자
    CONSTRAINT "PK_PurchaseRequisition" PRIMARY KEY ("PurchaseRequisitionSequenceNo"),
    CONSTRAINT "UK_PurchaseRequisition" UNIQUE ("EnterpriseID", "PurchaseRequisitionID")
);

COMMENT ON TABLE "PurchaseRequisition" IS '[KS X 9101 표준] 구매요청 (생산 또는 판매를 위해 수급되어야 할 품목을 요청하는 것을 의미한다(원부자재, 소모품, 상품 등).)';
COMMENT ON COLUMN "PurchaseRequisition"."PurchaseRequisitionSequenceNo" IS '[KS X 9101 표준] 구매요청 일련번호: — 테이블 행을 식별하는 일련번호(PK, 대리키) — 표준 외 물리 컬럼
— 자동 증가 값(IDENTITY)으로 부여하며 다른 테이블이 참조하지 않음(FK는 UK 참조)';
COMMENT ON COLUMN "PurchaseRequisition"."EnterpriseID" IS '[KS X 9101 표준] 회사식별자: — 회사를 유일하게 구분할 수 있는 고유식별값
— 기업업무시스템 간의 연동을 수행하는 회사들 간에 자체적으로 정의한 고유식별값
— 참조 대상: 회사(Enterprise)';
COMMENT ON COLUMN "PurchaseRequisition"."SiteID" IS '[KS X 9101 표준] 사업장식별자: — 회사 내에서 사업장을 구분할수 있는 고유식별값
— 참조 대상: 사업장(Site)';
COMMENT ON COLUMN "PurchaseRequisition"."PlantID" IS '[KS X 9101 표준] 공장식별자: — 회사 내에서 공장을 구분할 수있는 고유식별값(만약, 공장 개념을 사용하지 않는다면 고정식별자로 설정하여 입력해야 함)
— 참조 대상: 공장(Plant)';
COMMENT ON COLUMN "PurchaseRequisition"."CreatorID" IS '[KS X 9101 표준] 등록자식별자: — 정보를 처음으로 등록한 사람을 구분할 수 있는 고유식별값으로, 일반적으로 사원번호가사용됨
— 참조 대상: 사원(Personnel)';
COMMENT ON COLUMN "PurchaseRequisition"."CreationDateTime" IS '[KS X 9101 표준] 등록일시: — 정보를 처음으로 등록한 날짜 (KS X ISO 8601을 따른다)';
COMMENT ON COLUMN "PurchaseRequisition"."ModifierID" IS '[KS X 9101 표준] 수정자식별자: — 정보를 마지막으로 수정한 사람을 구분할 수 있는 고유식별값으로, 일반적으로 사원번호가 사용됨
— 참조 대상: 사원(Personnel)';
COMMENT ON COLUMN "PurchaseRequisition"."ModificationDateTime" IS '[KS X 9101 표준] 수정일시: — 정보를 마지막으로 수정한 날짜 (KS X ISO 8601을 따른다.)';
COMMENT ON COLUMN "PurchaseRequisition"."Note" IS '[KS X 9101 표준] 비고: — 비고사항';
COMMENT ON COLUMN "PurchaseRequisition"."PurchaseRequisitionID" IS '[KS X 9101 표준] 구매요청식별자: — 구매요청을 식별하기 위한 고유값';
COMMENT ON COLUMN "PurchaseRequisition"."PurchaseRequisitionRevisionNumber" IS '[KS X 9101 표준] 구매요청버전: — 구매요청버전';
COMMENT ON COLUMN "PurchaseRequisition"."ItemID" IS '[KS X 9101 표준] 품목식별자: — 품목을 식별하기 위한 고유값
— 제품, 반제품, 상품, 원자재, 부자재, 저장품, 소모품 등 회사내 시스템으로 관리되는 모든 품목을 포함
— 참조 대상: 품목마스터(ItemMaster)';
COMMENT ON COLUMN "PurchaseRequisition"."ItemName" IS '[KS X 9101 표준] 품목명: — 품목의 명칭
— 참조 대상: 품목마스터(ItemMaster.ItemName)';
COMMENT ON COLUMN "PurchaseRequisition"."DemandQuantity" IS '[KS X 9101 표준] 구매요청수량: — 구매요청수량(수량의 단위는 기준단위코드로 함)';
COMMENT ON COLUMN "PurchaseRequisition"."ItemUOMCode" IS '[KS X 9101 표준] 기준단위코드: — 기준단위코드(예: EA, DZ, HD 등)
— 참조 대상: 단위그룹(UOMGroup)의 단위코드';
COMMENT ON COLUMN "PurchaseRequisition"."PurchaseRequisitionUnitPrice" IS '[KS X 9101 표준] 구매요청단가: — 구매요청단가(단가의 단위는 환종코드로 함)';
COMMENT ON COLUMN "PurchaseRequisition"."CurrencyCode" IS '[KS X 9101 표준] 환종코드: — 환종코드(예: KRW, USD, JPY 등)
— 참조 대상: 공통코드정보(CommonCodeMaster)의 코드(ISO 4217 통화코드 사용 권고)';
COMMENT ON COLUMN "PurchaseRequisition"."VendorID" IS '[KS X 9101 표준] 공급사식별자: — 품목을 구입해오는 거래처를 식별하기 위한 고유값
— 참조 대상: 공급사(VendorPartyMaster)';
COMMENT ON COLUMN "PurchaseRequisition"."VendorName" IS '[KS X 9101 표준] 공급사명: — 공급사의 명칭
— 참조 대상: 공급사(VendorPartyMaster.VendorName)';
COMMENT ON COLUMN "PurchaseRequisition"."RequestedDeliveryDate" IS '[KS X 9101 표준] 요청납기일: — 요청납기일(KS X ISO 8601을 따른다)';
COMMENT ON COLUMN "PurchaseRequisition"."RequesterDepartmentID" IS '[KS X 9101 표준] 구매요청부서: — 구매요청부서
— 참조 대상: 부서(Department)';
COMMENT ON COLUMN "PurchaseRequisition"."RequesterPersonnelID" IS '[KS X 9101 표준] 구매요청자: — 구매요청자
— 참조 대상: 사원(Personnel)';

-- ---------------------------------------------------------------------
-- [표준 구분: KS X 9101 표준] 표 40, 조항 7.4.4.3 | 업무영역: 구매관리
-- 테이블명(물리): "PurchaseOrderHeader" | 테이블명(논리): 구매발주헤더
-- 설명: 구매발주(PurchaseOrder) 명사의 헤더 구조체(struct) 구매문서 1건의 공통 정보(공급사, 발주일, 결제·거래 조건, 담당자) 구매문서마다 1회 나타남
-- ---------------------------------------------------------------------
CREATE TABLE "PurchaseOrderHeader" ( -- [KS X 9101 표준] 구매발주헤더 (표 40)
    "PurchaseOrderHeaderSequenceNo" BIGINT GENERATED BY DEFAULT AS IDENTITY, -- [KS X 9101 표준] 구매발주헤더 일련번호(PK)
    "EnterpriseID" VARCHAR(50) NOT NULL, -- [KS X 9101 표준] 회사식별자
    "SiteID" VARCHAR(50) NOT NULL, -- [KS X 9101 표준] 사업장식별자
    "PlantID" VARCHAR(50) NOT NULL, -- [KS X 9101 표준] 공장식별자
    "CreatorID" VARCHAR(50), -- [KS X 9101 표준] 등록자식별자
    "CreationDateTime" TIMESTAMP, -- [KS X 9101 표준] 등록일시
    "ModifierID" VARCHAR(50), -- [KS X 9101 표준] 수정자식별자
    "ModificationDateTime" TIMESTAMP, -- [KS X 9101 표준] 수정일시
    "Note" VARCHAR(1000), -- [KS X 9101 표준] 비고
    "PurchaseDocumentNumber" VARCHAR(50) NOT NULL, -- [KS X 9101 표준] 구매문서번호
    "VendorID" VARCHAR(50), -- [KS X 9101 표준] 공급사식별자
    "PaymentTermsCode" VARCHAR(30), -- [KS X 9101 표준] 결제조건코드
    "PurchaseGroupCode" VARCHAR(30), -- [KS X 9101 표준] 구매그룹코드
    "CurrencyCode" VARCHAR(30), -- [KS X 9101 표준] 환종코드
    "ExchangeRate" NUMERIC(18,6), -- [KS X 9101 표준] 환율
    "PurchaseApprovalDate" DATE, -- [KS X 9101 표준] 승인일
    "PurchaseOrderDate" DATE, -- [KS X 9101 표준] 구매발주일
    "PurchaseOrderTypeCode" VARCHAR(30), -- [KS X 9101 표준] 발주유형코드
    "PurchaseTransactionType" VARCHAR(30), -- [KS X 9101 표준] 거래유형
    "PurchaseOrderStartDate" DATE, -- [KS X 9101 표준] 시작일
    "PurchaseOrderValidDate" DATE, -- [KS X 9101 표준] 유효일
    "PersonnelID" VARCHAR(50), -- [KS X 9101 표준] 사원식별자
    "PurchaseOrderClosingIndicator" BOOLEAN, -- [KS X 9101 표준] 발주마감여부
    "PurchaseOrderClosingDate" DATE, -- [KS X 9101 표준] 발주마감일
    CONSTRAINT "PK_PurchaseOrderHeader" PRIMARY KEY ("PurchaseOrderHeaderSequenceNo"),
    CONSTRAINT "UK_PurchaseOrderHeader" UNIQUE ("EnterpriseID", "PurchaseDocumentNumber")
);

COMMENT ON TABLE "PurchaseOrderHeader" IS '[KS X 9101 표준] 구매발주헤더 (구매발주(PurchaseOrder) 명사의 헤더 구조체(struct) 구매문서 1건의 공통 정보(공급사, 발주일, 결제·거래 조건, 담당자) 구매문서마다 1회 나타남)';
COMMENT ON COLUMN "PurchaseOrderHeader"."PurchaseOrderHeaderSequenceNo" IS '[KS X 9101 표준] 구매발주헤더 일련번호: — 테이블 행을 식별하는 일련번호(PK, 대리키) — 표준 외 물리 컬럼
— 자동 증가 값(IDENTITY)으로 부여하며 다른 테이블이 참조하지 않음(FK는 UK 참조)';
COMMENT ON COLUMN "PurchaseOrderHeader"."EnterpriseID" IS '[KS X 9101 표준] 회사식별자: — 회사를 유일하게 구분할 수 있는 고유식별값
— 기업업무시스템 간의 연동을 수행하는 회사들 간에 자체적으로 정의한 고유식별값
— 참조 대상: 회사(Enterprise)';
COMMENT ON COLUMN "PurchaseOrderHeader"."SiteID" IS '[KS X 9101 표준] 사업장식별자: — 회사 내에서 사업장을 구분할수 있는 고유식별값
— 참조 대상: 사업장(Site)';
COMMENT ON COLUMN "PurchaseOrderHeader"."PlantID" IS '[KS X 9101 표준] 공장식별자: — 회사 내에서 공장을 구분할 수있는 고유식별값(만약, 공장 개념을 사용하지 않는다면 고정식별자로 설정하여 입력해야 함)
— 참조 대상: 공장(Plant)';
COMMENT ON COLUMN "PurchaseOrderHeader"."CreatorID" IS '[KS X 9101 표준] 등록자식별자: — 정보를 처음으로 등록한 사람을 구분할 수 있는 고유식별값으로, 일반적으로 사원번호가사용됨
— 참조 대상: 사원(Personnel)';
COMMENT ON COLUMN "PurchaseOrderHeader"."CreationDateTime" IS '[KS X 9101 표준] 등록일시: — 정보를 처음으로 등록한 날짜 (KS X ISO 8601을 따른다)';
COMMENT ON COLUMN "PurchaseOrderHeader"."ModifierID" IS '[KS X 9101 표준] 수정자식별자: — 정보를 마지막으로 수정한 사람을 구분할 수 있는 고유식별값으로, 일반적으로 사원번호가 사용됨
— 참조 대상: 사원(Personnel)';
COMMENT ON COLUMN "PurchaseOrderHeader"."ModificationDateTime" IS '[KS X 9101 표준] 수정일시: — 정보를 마지막으로 수정한 날짜 (KS X ISO 8601을 따른다.)';
COMMENT ON COLUMN "PurchaseOrderHeader"."Note" IS '[KS X 9101 표준] 비고: — 비고사항';
COMMENT ON COLUMN "PurchaseOrderHeader"."PurchaseDocumentNumber" IS '[KS X 9101 표준] 구매문서번호: — 구매문서를 식별하기 위한 고유값
— 구매문서 단위로 부여하며, 구매발주헤더에 1회 기재함';
COMMENT ON COLUMN "PurchaseOrderHeader"."VendorID" IS '[KS X 9101 표준] 공급사식별자: — 품목을 구입해오는 거래처를 식별하기 위한 고유값
— 참조 대상: 공급사(VendorPartyMaster)';
COMMENT ON COLUMN "PurchaseOrderHeader"."PaymentTermsCode" IS '[KS X 9101 표준] 결제조건코드: — 구매거래처에 대한 대금결제 조건
— 대금결제조건(예: 현금, 어음, 월말 마감 후 30일 지급 등)
— 참조 대상: 공통코드정보(CommonCodeMaster)의 코드';
COMMENT ON COLUMN "PurchaseOrderHeader"."PurchaseGroupCode" IS '[KS X 9101 표준] 구매그룹코드: — 구매그룹코드
— 구매 업무를 담당하는 구매그룹(구매조직 내 담당 단위)의 코드
— 구매조직이 세분화되지 않은 기업은 단일 코드로 운영할 수 있음
— 예: 원자재 구매, 부자재 구매, 외주 구매, 설비·자산 구매, MRO 구매, 수입 구매 등
— 참조 대상: 공통코드정보(CommonCodeMaster)의 코드';
COMMENT ON COLUMN "PurchaseOrderHeader"."CurrencyCode" IS '[KS X 9101 표준] 환종코드: — 환종코드(예: KRW, USD, JPY 등)
— 참조 대상: 공통코드정보(CommonCodeMaster)의 코드(ISO 4217 통화코드 사용 권고)';
COMMENT ON COLUMN "PurchaseOrderHeader"."ExchangeRate" IS '[KS X 9101 표준] 환율: — 환율';
COMMENT ON COLUMN "PurchaseOrderHeader"."PurchaseApprovalDate" IS '[KS X 9101 표준] 승인일: — 구매요청에 대한 구매승인일(KS X ISO 8601을 따른다)';
COMMENT ON COLUMN "PurchaseOrderHeader"."PurchaseOrderDate" IS '[KS X 9101 표준] 구매발주일: — 구매발주일(KS X ISO 8601을 따른다)';
COMMENT ON COLUMN "PurchaseOrderHeader"."PurchaseOrderTypeCode" IS '[KS X 9101 표준] 발주유형코드: — 구매유형, 구매형태, 성격 등을 관리
— 발주유형은 일반 발주, 외주 가공 발주, 위탁 발주, 사내 이관 발주, 서비스/공사 발주 등을 포함
— 참조 대상: 공통코드정보(CommonCodeMaster)의 코드';
COMMENT ON COLUMN "PurchaseOrderHeader"."PurchaseTransactionType" IS '[KS X 9101 표준] 거래유형: — 거래유형
— 거래유형은 과세, 면세, 불공제, 수입, 카드과세, 현금영수증 등을 포함
— 참조 대상: 공통코드정보(CommonCodeMaster)의 코드';
COMMENT ON COLUMN "PurchaseOrderHeader"."PurchaseOrderStartDate" IS '[KS X 9101 표준] 시작일: — 구매발주에 대한 실 구매시작일(KS X ISO 8601을 따른다)';
COMMENT ON COLUMN "PurchaseOrderHeader"."PurchaseOrderValidDate" IS '[KS X 9101 표준] 유효일: — 구매발주 유효일(KS X ISO 8601을 따른다)';
COMMENT ON COLUMN "PurchaseOrderHeader"."PersonnelID" IS '[KS X 9101 표준] 사원식별자: — 인사조직 내 사원을 식별하기 위한 고유값
— 구매 및 발주 담당자의 식별정보
— 참조 대상: 사원(Personnel)';
COMMENT ON COLUMN "PurchaseOrderHeader"."PurchaseOrderClosingIndicator" IS '[KS X 9101 표준] 발주마감여부: — 발주마감여부';
COMMENT ON COLUMN "PurchaseOrderHeader"."PurchaseOrderClosingDate" IS '[KS X 9101 표준] 발주마감일: — 발주마감일(KS X ISO 8601을 따른다)';

-- ---------------------------------------------------------------------
-- [표준 구분: KS X 9101 표준] 표 40, 조항 7.4.4.3 | 업무영역: 구매관리
-- 테이블명(물리): "PurchaseOrderLine" | 테이블명(논리): 구매발주라인
-- 설명: 구매발주(PurchaseOrder) 명사의 라인 구조체(struct[1..N]) 구매문서를 구성하는 품목 행 정보 구매발주헤더 아래에 1회 이상 반복하여 나타남(1..N)
-- ---------------------------------------------------------------------
CREATE TABLE "PurchaseOrderLine" ( -- [KS X 9101 표준] 구매발주라인 (표 40)
    "PurchaseOrderLineSequenceNo" BIGINT GENERATED BY DEFAULT AS IDENTITY, -- [KS X 9101 표준] 구매발주라인 일련번호(PK)
    "EnterpriseID" VARCHAR(50) NOT NULL, -- [KS X 9101 표준] 회사식별자
    "SiteID" VARCHAR(50) NOT NULL, -- [KS X 9101 표준] 사업장식별자
    "PlantID" VARCHAR(50) NOT NULL, -- [KS X 9101 표준] 공장식별자
    "CreatorID" VARCHAR(50), -- [KS X 9101 표준] 등록자식별자
    "CreationDateTime" TIMESTAMP, -- [KS X 9101 표준] 등록일시
    "ModifierID" VARCHAR(50), -- [KS X 9101 표준] 수정자식별자
    "ModificationDateTime" TIMESTAMP, -- [KS X 9101 표준] 수정일시
    "Note" VARCHAR(1000), -- [KS X 9101 표준] 비고
    "PurchaseDocumentNumber" VARCHAR(50) NOT NULL, -- [KS X 9101 표준] 구매문서번호
    "PurchaseDocumentSequence" INTEGER NOT NULL, -- [KS X 9101 표준] 구매문서순번
    "ItemPurchaseType" VARCHAR(30), -- [KS X 9101 표준] 구매라인유형
    "ItemID" VARCHAR(50), -- [KS X 9101 표준] 품목식별자
    "ItemName" VARCHAR(200), -- [KS X 9101 표준] 품목명
    "PurchaseOrderLineStatusCode" VARCHAR(30), -- [KS X 9101 표준] 발주라인상태코드
    "TaxCode" VARCHAR(30), -- [KS X 9101 표준] 세무코드
    "ItemUOMCode" VARCHAR(20), -- [KS X 9101 표준] 기준단위코드
    "PurchaseOrderUOMCode" VARCHAR(20), -- [KS X 9101 표준] 발주단위코드
    "ConversionUnitQuantity" NUMERIC(18,6), -- [KS X 9101 표준] 단위환산수량
    "ItemUnitQuantity" NUMERIC(18,6), -- [KS X 9101 표준] 기준단위수량
    "PurchaseOrderQuantity" NUMERIC(18,6), -- [KS X 9101 표준] 구매발주수량
    "PurchaseGoodsReceiptQuantity" NUMERIC(18,6), -- [KS X 9101 표준] 구매입고수량
    "PurchaseTransactionUnitPrice" NUMERIC(18,6), -- [KS X 9101 표준] 구매거래단가
    "PurchaseTransactionPrice" NUMERIC(18,6), -- [KS X 9101 표준] 구매거래금액
    "PurchaseOrderUnitPrice" NUMERIC(18,6), -- [KS X 9101 표준] 발주단가
    "PurchaseOrderPrice" NUMERIC(18,6), -- [KS X 9101 표준] 발주금액
    "VATPrice" NUMERIC(18,6), -- [KS X 9101 표준] 부가세금액
    "ExpectedDeliveryDate" DATE, -- [KS X 9101 표준] 납기예정일
    "IncomingInspectionIndicator" BOOLEAN, -- [KS X 9101 표준] 수입검사여부
    "AccountCode" VARCHAR(30), -- [KS X 9101 표준] 계정코드
    "VATTransactionUnitPrice" NUMERIC(18,6), -- [KS X 9101 표준] 부가세포함거래단가
    "VATTransactionPrice" NUMERIC(18,6), -- [KS X 9101 표준] 부가세포함거래금액
    "VATCarryingAmount" NUMERIC(18,6), -- [KS X 9101 표준] 부가세포함장부금액
    CONSTRAINT "PK_PurchaseOrderLine" PRIMARY KEY ("PurchaseOrderLineSequenceNo"),
    CONSTRAINT "UK_PurchaseOrderLine" UNIQUE ("EnterpriseID", "PurchaseDocumentNumber", "PurchaseDocumentSequence")
);

COMMENT ON TABLE "PurchaseOrderLine" IS '[KS X 9101 표준] 구매발주라인 (구매발주(PurchaseOrder) 명사의 라인 구조체(struct[1..N]) 구매문서를 구성하는 품목 행 정보 구매발주헤더 아래에 1회 이상 반복하여 나타남(1..N))';
COMMENT ON COLUMN "PurchaseOrderLine"."PurchaseOrderLineSequenceNo" IS '[KS X 9101 표준] 구매발주라인 일련번호: — 테이블 행을 식별하는 일련번호(PK, 대리키) — 표준 외 물리 컬럼
— 자동 증가 값(IDENTITY)으로 부여하며 다른 테이블이 참조하지 않음(FK는 UK 참조)';
COMMENT ON COLUMN "PurchaseOrderLine"."EnterpriseID" IS '[KS X 9101 표준] 회사식별자: — 회사를 유일하게 구분할 수 있는 고유식별값
— 기업업무시스템 간의 연동을 수행하는 회사들 간에 자체적으로 정의한 고유식별값
— 참조 대상: 회사(Enterprise)';
COMMENT ON COLUMN "PurchaseOrderLine"."SiteID" IS '[KS X 9101 표준] 사업장식별자: — 회사 내에서 사업장을 구분할수 있는 고유식별값
— 참조 대상: 사업장(Site)';
COMMENT ON COLUMN "PurchaseOrderLine"."PlantID" IS '[KS X 9101 표준] 공장식별자: — 회사 내에서 공장을 구분할 수있는 고유식별값(만약, 공장 개념을 사용하지 않는다면 고정식별자로 설정하여 입력해야 함)
— 참조 대상: 공장(Plant)';
COMMENT ON COLUMN "PurchaseOrderLine"."CreatorID" IS '[KS X 9101 표준] 등록자식별자: — 정보를 처음으로 등록한 사람을 구분할 수 있는 고유식별값으로, 일반적으로 사원번호가사용됨
— 참조 대상: 사원(Personnel)';
COMMENT ON COLUMN "PurchaseOrderLine"."CreationDateTime" IS '[KS X 9101 표준] 등록일시: — 정보를 처음으로 등록한 날짜 (KS X ISO 8601을 따른다)';
COMMENT ON COLUMN "PurchaseOrderLine"."ModifierID" IS '[KS X 9101 표준] 수정자식별자: — 정보를 마지막으로 수정한 사람을 구분할 수 있는 고유식별값으로, 일반적으로 사원번호가 사용됨
— 참조 대상: 사원(Personnel)';
COMMENT ON COLUMN "PurchaseOrderLine"."ModificationDateTime" IS '[KS X 9101 표준] 수정일시: — 정보를 마지막으로 수정한 날짜 (KS X ISO 8601을 따른다.)';
COMMENT ON COLUMN "PurchaseOrderLine"."Note" IS '[KS X 9101 표준] 비고: — 비고사항';
COMMENT ON COLUMN "PurchaseOrderLine"."PurchaseDocumentNumber" IS '[KS X 9101 표준] 구매문서번호: — 구매문서를 식별하기 위한 고유값
— 참조 대상: 구매발주헤더(PurchaseOrderHeader)';
COMMENT ON COLUMN "PurchaseOrderLine"."PurchaseDocumentSequence" IS '[KS X 9101 표준] 구매문서순번: — 구매문서 내 품목 행의 순서
— 구매발주라인은 구매문서번호와 구매문서순번의 조합으로 구분하며, 다른 명사는 이 조합으로 구매발주라인을 참조한다';
COMMENT ON COLUMN "PurchaseOrderLine"."ItemPurchaseType" IS '[KS X 9101 표준] 구매라인유형: — 구매라인유형, 품목별 구매유형을 관리
— 구매라인유형은 품목, 서비스, 고정자산, 비품 등을 포함
— 참조 대상: 공통코드정보(CommonCodeMaster)의 코드';
COMMENT ON COLUMN "PurchaseOrderLine"."ItemID" IS '[KS X 9101 표준] 품목식별자: — 품목을 식별하기 위한 고유값
— 제품, 반제품, 상품, 원자재, 부자재, 저장품, 소모품 등 회사내 시스템으로 관리되는 모든 품목을 포함
— 참조 대상: 품목마스터(ItemMaster)';
COMMENT ON COLUMN "PurchaseOrderLine"."ItemName" IS '[KS X 9101 표준] 품목명: — 품목의 명칭
— 참조 대상: 품목마스터(ItemMaster.ItemName)';
COMMENT ON COLUMN "PurchaseOrderLine"."PurchaseOrderLineStatusCode" IS '[KS X 9101 표준] 발주라인상태코드: — 발주라인상태코드
— 발주라인상태는 발주 진행 중, 입고완료, 송장 처리 완료, 최종 종결, 취소, 보류 등을 포함
— 참조 대상: 공통코드정보(CommonCodeMaster)의 코드';
COMMENT ON COLUMN "PurchaseOrderLine"."TaxCode" IS '[KS X 9101 표준] 세무코드: — 세무코드
— 세무코드는 과세, 영세율 매입, 면세, 불공제, 수입 매입, 카드과세, 현금영수증 과세 등을 포함
— 참조 대상: 공통코드정보(CommonCodeMaster)의 코드';
COMMENT ON COLUMN "PurchaseOrderLine"."ItemUOMCode" IS '[KS X 9101 표준] 기준단위코드: — 기준단위코드(예: EA, DZ, HD 등)
— 참조 대상: 단위그룹(UOMGroup)의 단위코드';
COMMENT ON COLUMN "PurchaseOrderLine"."PurchaseOrderUOMCode" IS '[KS X 9101 표준] 발주단위코드: — 발주단위코드
— 예: EA, BOX, kg, ROL 등
— 참조 대상: 단위그룹(UOMGroup)의 단위코드';
COMMENT ON COLUMN "PurchaseOrderLine"."ConversionUnitQuantity" IS '[KS X 9101 표준] 단위환산수량: — 단위환산수량, 구매발주에서 사용된 단위를 기준단위로 환산한수량을 관리';
COMMENT ON COLUMN "PurchaseOrderLine"."ItemUnitQuantity" IS '[KS X 9101 표준] 기준단위수량: — 기준수량(수량의 단위는 기준단위코드로 함)';
COMMENT ON COLUMN "PurchaseOrderLine"."PurchaseOrderQuantity" IS '[KS X 9101 표준] 구매발주수량: — 구매발주수량(수량의 단위는 기준단위코드로 함)';
COMMENT ON COLUMN "PurchaseOrderLine"."PurchaseGoodsReceiptQuantity" IS '[KS X 9101 표준] 구매입고수량: — 구매입고수량(수량의 단위는 기준단위코드로 함)';
COMMENT ON COLUMN "PurchaseOrderLine"."PurchaseTransactionUnitPrice" IS '[KS X 9101 표준] 구매거래단가: — 구매거래단가(금액의 단위는 환종코드로 함)';
COMMENT ON COLUMN "PurchaseOrderLine"."PurchaseTransactionPrice" IS '[KS X 9101 표준] 구매거래금액: — 구매거래금액(금액의 단위는 환종코드로 함)';
COMMENT ON COLUMN "PurchaseOrderLine"."PurchaseOrderUnitPrice" IS '[KS X 9101 표준] 발주단가: — 발주단가(금액의 단위는 환종코드로 함)';
COMMENT ON COLUMN "PurchaseOrderLine"."PurchaseOrderPrice" IS '[KS X 9101 표준] 발주금액: — 발주금액(금액의 단위는 환종코드로 함)';
COMMENT ON COLUMN "PurchaseOrderLine"."VATPrice" IS '[KS X 9101 표준] 부가세금액: — 부가세금액(금액의 단위는 환종코드로 함)';
COMMENT ON COLUMN "PurchaseOrderLine"."ExpectedDeliveryDate" IS '[KS X 9101 표준] 납기예정일: — 납기예정일(KS X ISO 8601을 따른다)';
COMMENT ON COLUMN "PurchaseOrderLine"."IncomingInspectionIndicator" IS '[KS X 9101 표준] 수입검사여부: — 수입검사여부
— 참조 대상: 품목마스터(ItemMaster.IncomingInspectionIndicator)';
COMMENT ON COLUMN "PurchaseOrderLine"."AccountCode" IS '[KS X 9101 표준] 계정코드: — 계정코드
— 구매 거래가 기표되는 회계 계정과목 코드(예: 원재료, 부재료, 상품, 소모품비 등)
— ERP 회계모듈 또는 자체 회계모듈의 계정과목을 공통코드로 등록하여 사용
— 참조 대상: 공통코드정보(CommonCodeMaster)의 코드';
COMMENT ON COLUMN "PurchaseOrderLine"."VATTransactionUnitPrice" IS '[KS X 9101 표준] 부가세포함거래단가: — 부가세포함거래단가(금액의 단위는 환종코드로 함)';
COMMENT ON COLUMN "PurchaseOrderLine"."VATTransactionPrice" IS '[KS X 9101 표준] 부가세포함거래금액: — 부가세포함거래금액(금액의 단위는 환종코드로 함)';
COMMENT ON COLUMN "PurchaseOrderLine"."VATCarryingAmount" IS '[KS X 9101 표준] 부가세포함장부금액: — 부가세포함장부금액(금액의 단위는 환종코드로 함)';

-- ---------------------------------------------------------------------
-- [표준 구분: KS X 9101 표준] 표 41, 조항 7.4.5.1 | 업무영역: 자재관리
-- 테이블명(물리): "MaterialArrival" | 테이블명(논리): 자재도착
-- 설명: 자재가 입고 전 수입검사를 위해 도착한 정보를 의미한다.
-- ---------------------------------------------------------------------
CREATE TABLE "MaterialArrival" ( -- [KS X 9101 표준] 자재도착 (표 41)
    "MaterialArrivalSequenceNo" BIGINT GENERATED BY DEFAULT AS IDENTITY, -- [KS X 9101 표준] 자재도착 일련번호(PK)
    "EnterpriseID" VARCHAR(50) NOT NULL, -- [KS X 9101 표준] 회사식별자
    "SiteID" VARCHAR(50) NOT NULL, -- [KS X 9101 표준] 사업장식별자
    "PlantID" VARCHAR(50) NOT NULL, -- [KS X 9101 표준] 공장식별자
    "CreatorID" VARCHAR(50), -- [KS X 9101 표준] 등록자식별자
    "CreationDateTime" TIMESTAMP, -- [KS X 9101 표준] 등록일시
    "ModifierID" VARCHAR(50), -- [KS X 9101 표준] 수정자식별자
    "ModificationDateTime" TIMESTAMP, -- [KS X 9101 표준] 수정일시
    "Note" VARCHAR(1000), -- [KS X 9101 표준] 비고
    "PurchaseDocumentNumber" VARCHAR(50) NOT NULL, -- [KS X 9101 표준] 구매문서번호
    "PurchaseDocumentSequence" INTEGER NOT NULL, -- [KS X 9101 표준] 구매문서순번
    "ItemID" VARCHAR(50), -- [KS X 9101 표준] 품목식별자
    "PurchaseGoodsReceiptQuantity" NUMERIC(18,6), -- [KS X 9101 표준] 구매입고수량
    "ReceiptWarehouseID" VARCHAR(50), -- [KS X 9101 표준] 입고창고식별자
    "GoodsReceiptDate" DATE, -- [KS X 9101 표준] 입고처리일
    "LotID" VARCHAR(50) NOT NULL, -- [KS X 9101 표준] 로트식별자
    "ItemQuantity" NUMERIC(18,6), -- [KS X 9101 표준] 품목수량
    "VendorID" VARCHAR(50), -- [KS X 9101 표준] 공급사식별자
    CONSTRAINT "PK_MaterialArrival" PRIMARY KEY ("MaterialArrivalSequenceNo"),
    CONSTRAINT "UK_MaterialArrival" UNIQUE ("EnterpriseID", "PurchaseDocumentNumber", "PurchaseDocumentSequence", "LotID")
);

COMMENT ON TABLE "MaterialArrival" IS '[KS X 9101 표준] 자재도착 (자재가 입고 전 수입검사를 위해 도착한 정보를 의미한다.)';
COMMENT ON COLUMN "MaterialArrival"."MaterialArrivalSequenceNo" IS '[KS X 9101 표준] 자재도착 일련번호: — 테이블 행을 식별하는 일련번호(PK, 대리키) — 표준 외 물리 컬럼
— 자동 증가 값(IDENTITY)으로 부여하며 다른 테이블이 참조하지 않음(FK는 UK 참조)';
COMMENT ON COLUMN "MaterialArrival"."EnterpriseID" IS '[KS X 9101 표준] 회사식별자: — 회사를 유일하게 구분할 수 있는 고유식별값
— 기업업무시스템 간의 연동을 수행하는 회사들 간에 자체적으로 정의한 고유식별값
— 참조 대상: 회사(Enterprise)';
COMMENT ON COLUMN "MaterialArrival"."SiteID" IS '[KS X 9101 표준] 사업장식별자: — 회사 내에서 사업장을 구분할수 있는 고유식별값
— 참조 대상: 사업장(Site)';
COMMENT ON COLUMN "MaterialArrival"."PlantID" IS '[KS X 9101 표준] 공장식별자: — 회사 내에서 공장을 구분할 수있는 고유식별값(만약, 공장 개념을 사용하지 않는다면 고정식별자로 설정하여 입력해야 함)
— 참조 대상: 공장(Plant)';
COMMENT ON COLUMN "MaterialArrival"."CreatorID" IS '[KS X 9101 표준] 등록자식별자: — 정보를 처음으로 등록한 사람을 구분할 수 있는 고유식별값으로, 일반적으로 사원번호가사용됨
— 참조 대상: 사원(Personnel)';
COMMENT ON COLUMN "MaterialArrival"."CreationDateTime" IS '[KS X 9101 표준] 등록일시: — 정보를 처음으로 등록한 날짜 (KS X ISO 8601을 따른다)';
COMMENT ON COLUMN "MaterialArrival"."ModifierID" IS '[KS X 9101 표준] 수정자식별자: — 정보를 마지막으로 수정한 사람을 구분할 수 있는 고유식별값으로, 일반적으로 사원번호가 사용됨
— 참조 대상: 사원(Personnel)';
COMMENT ON COLUMN "MaterialArrival"."ModificationDateTime" IS '[KS X 9101 표준] 수정일시: — 정보를 마지막으로 수정한 날짜 (KS X ISO 8601을 따른다.)';
COMMENT ON COLUMN "MaterialArrival"."Note" IS '[KS X 9101 표준] 비고: — 비고사항';
COMMENT ON COLUMN "MaterialArrival"."PurchaseDocumentNumber" IS '[KS X 9101 표준] 구매문서번호: — 구매문서번호
— 참조 대상: 구매발주(PurchaseOrder)
— 구매문서순번(PurchaseDocumentSequence)과 함께 구매발주(PurchaseOrder)를 참조한다';
COMMENT ON COLUMN "MaterialArrival"."PurchaseDocumentSequence" IS '[KS X 9101 표준] 구매문서순번: — 구매문서순번
— 참조 대상: 구매발주(PurchaseOrder)
— 구매문서번호(PurchaseDocumentNumber)와 함께 구매발주(PurchaseOrder)를 참조한다';
COMMENT ON COLUMN "MaterialArrival"."ItemID" IS '[KS X 9101 표준] 품목식별자: — 품목을 식별하기 위한 고유값
— 제품, 반제품, 상품, 원자재, 부자재, 저장품, 소모품 등 회사내 시스템으로 관리되는 모든 품목을 포함
— 참조 대상: 품목마스터(ItemMaster)';
COMMENT ON COLUMN "MaterialArrival"."PurchaseGoodsReceiptQuantity" IS '[KS X 9101 표준] 구매입고수량: — 구매입고수량(수량의 단위는 기준단위코드로 함)';
COMMENT ON COLUMN "MaterialArrival"."ReceiptWarehouseID" IS '[KS X 9101 표준] 입고창고식별자: — 품목의 기본 입고 창고(저장위치)
— 참조 대상: 창고(WarehouseLocation)';
COMMENT ON COLUMN "MaterialArrival"."GoodsReceiptDate" IS '[KS X 9101 표준] 입고처리일: — 입고처리일';
COMMENT ON COLUMN "MaterialArrival"."LotID" IS '[KS X 9101 표준] 로트식별자: — 자재도착에 포함된 로트의 고유식별값
— 참조 대상: 로트(Lot)
— 자재도착 행은 구매문서번호, 구매문서순번, 로트식별자의 조합으로 구분하며, 조합에 포함되는 속성은 값을 생략할 수 없음(7.1)';
COMMENT ON COLUMN "MaterialArrival"."ItemQuantity" IS '[KS X 9101 표준] 품목수량: — 품목수량(수량의 단위는 기준단위코드로 함)';
COMMENT ON COLUMN "MaterialArrival"."VendorID" IS '[KS X 9101 표준] 공급사식별자: — 품목을 구입해오는 거래처를 식별하기 위한 고유값
— 참조 대상: 공급사(VendorPartyMaster)';

-- ---------------------------------------------------------------------
-- [표준 구분: KS X 9101 표준] 표 42, 조항 7.4.5.2 | 업무영역: 자재관리
-- 테이블명(물리): "GoodsReceipt" | 테이블명(논리): 입고
-- 설명: 구매 발주된 품목을 협력업체로부터 납품 받은 정보를 의미한다.
-- ---------------------------------------------------------------------
CREATE TABLE "GoodsReceipt" ( -- [KS X 9101 표준] 입고 (표 42)
    "GoodsReceiptSequenceNo" BIGINT GENERATED BY DEFAULT AS IDENTITY, -- [KS X 9101 표준] 입고 일련번호(PK)
    "EnterpriseID" VARCHAR(50) NOT NULL, -- [KS X 9101 표준] 회사식별자
    "SiteID" VARCHAR(50) NOT NULL, -- [KS X 9101 표준] 사업장식별자
    "PlantID" VARCHAR(50) NOT NULL, -- [KS X 9101 표준] 공장식별자
    "CreatorID" VARCHAR(50), -- [KS X 9101 표준] 등록자식별자
    "CreationDateTime" TIMESTAMP, -- [KS X 9101 표준] 등록일시
    "ModifierID" VARCHAR(50), -- [KS X 9101 표준] 수정자식별자
    "ModificationDateTime" TIMESTAMP, -- [KS X 9101 표준] 수정일시
    "Note" VARCHAR(1000), -- [KS X 9101 표준] 비고
    "GoodsReceiptID" VARCHAR(50) NOT NULL, -- [KS X 9101 표준] 입고식별자
    "WarehouseID" VARCHAR(50), -- [KS X 9101 표준] 창고식별자
    "PersonnelID" VARCHAR(50), -- [KS X 9101 표준] 사원식별자
    "GoodsReceiptSequence" INTEGER NOT NULL, -- [KS X 9101 표준] 입고순번
    "GoodsReceiptType" VARCHAR(30), -- [KS X 9101 표준] 입고처리유형
    "GoodsReceiptReturnType" VARCHAR(30), -- [KS X 9101 표준] 입고반품유형
    "GoodsReceiptDate" DATE, -- [KS X 9101 표준] 입고처리일
    "ItemID" VARCHAR(50), -- [KS X 9101 표준] 품목식별자
    "ItemName" VARCHAR(200), -- [KS X 9101 표준] 품목명
    "InventoryTransactionDocumentNumber" VARCHAR(50), -- [KS X 9101 표준] 수불문서번호
    "InventoryTransactionDocumentSequence" INTEGER, -- [KS X 9101 표준] 수불문서순번
    "InventoryTransactionTypeCode" VARCHAR(30), -- [KS X 9101 표준] 수불유형코드
    "InvoiceNumber" VARCHAR(50), -- [KS X 9101 표준] 송장번호
    "InvoiceSequence" INTEGER, -- [KS X 9101 표준] 송장라인순번
    "InvoiceProcessingIndicator" BOOLEAN, -- [KS X 9101 표준] 송장처리여부
    "IncomingInspectionIndicator" BOOLEAN, -- [KS X 9101 표준] 수입검사여부
    "VendorID" VARCHAR(50), -- [KS X 9101 표준] 공급사식별자
    "PurchaseOrderUOMCode" VARCHAR(20), -- [KS X 9101 표준] 발주단위코드
    "ItemUnitQuantity" NUMERIC(18,6), -- [KS X 9101 표준] 기준단위수량
    "GoodsReceiptQuantity" NUMERIC(18,6), -- [KS X 9101 표준] 입고처리수량
    "IncomingInspectionAcceptedQuantity" NUMERIC(18,6), -- [KS X 9101 표준] 수입검사합격수량
    "IncomingInspectionRejectedQuantity" NUMERIC(18,6), -- [KS X 9101 표준] 수입검사불합격수량
    "PurchaseGroupCode" VARCHAR(30), -- [KS X 9101 표준] 구매그룹코드
    "ItemUOMCode" VARCHAR(20), -- [KS X 9101 표준] 기준단위코드
    CONSTRAINT "PK_GoodsReceipt" PRIMARY KEY ("GoodsReceiptSequenceNo"),
    CONSTRAINT "UK_GoodsReceipt" UNIQUE ("EnterpriseID", "GoodsReceiptID", "GoodsReceiptSequence")
);

COMMENT ON TABLE "GoodsReceipt" IS '[KS X 9101 표준] 입고 (구매 발주된 품목을 협력업체로부터 납품 받은 정보를 의미한다.)';
COMMENT ON COLUMN "GoodsReceipt"."GoodsReceiptSequenceNo" IS '[KS X 9101 표준] 입고 일련번호: — 테이블 행을 식별하는 일련번호(PK, 대리키) — 표준 외 물리 컬럼
— 자동 증가 값(IDENTITY)으로 부여하며 다른 테이블이 참조하지 않음(FK는 UK 참조)';
COMMENT ON COLUMN "GoodsReceipt"."EnterpriseID" IS '[KS X 9101 표준] 회사식별자: — 회사를 유일하게 구분할 수 있는 고유식별값
— 기업업무시스템 간의 연동을 수행하는 회사들 간에 자체적으로 정의한 고유식별값
— 참조 대상: 회사(Enterprise)';
COMMENT ON COLUMN "GoodsReceipt"."SiteID" IS '[KS X 9101 표준] 사업장식별자: — 회사 내에서 사업장을 구분할수 있는 고유식별값
— 참조 대상: 사업장(Site)';
COMMENT ON COLUMN "GoodsReceipt"."PlantID" IS '[KS X 9101 표준] 공장식별자: — 회사 내에서 공장을 구분할 수있는 고유식별값(만약, 공장 개념을 사용하지 않는다면 고정식별자로 설정하여 입력해야 함)
— 참조 대상: 공장(Plant)';
COMMENT ON COLUMN "GoodsReceipt"."CreatorID" IS '[KS X 9101 표준] 등록자식별자: — 정보를 처음으로 등록한 사람을 구분할 수 있는 고유식별값으로, 일반적으로 사원번호가사용됨
— 참조 대상: 사원(Personnel)';
COMMENT ON COLUMN "GoodsReceipt"."CreationDateTime" IS '[KS X 9101 표준] 등록일시: — 정보를 처음으로 등록한 날짜 (KS X ISO 8601을 따른다)';
COMMENT ON COLUMN "GoodsReceipt"."ModifierID" IS '[KS X 9101 표준] 수정자식별자: — 정보를 마지막으로 수정한 사람을 구분할 수 있는 고유식별값으로, 일반적으로 사원번호가 사용됨
— 참조 대상: 사원(Personnel)';
COMMENT ON COLUMN "GoodsReceipt"."ModificationDateTime" IS '[KS X 9101 표준] 수정일시: — 정보를 마지막으로 수정한 날짜 (KS X ISO 8601을 따른다.)';
COMMENT ON COLUMN "GoodsReceipt"."Note" IS '[KS X 9101 표준] 비고: — 비고사항';
COMMENT ON COLUMN "GoodsReceipt"."GoodsReceiptID" IS '[KS X 9101 표준] 입고식별자: — 입고를 식별하기 위한 고유값
— 입고 문서 단위로 부여하며, 한 입고 문서에 속한 모든 품목 행에 같은 값을 사용함';
COMMENT ON COLUMN "GoodsReceipt"."WarehouseID" IS '[KS X 9101 표준] 창고식별자: — 창고를 식별하기 위한 고유값
— 참조 대상: 창고(WarehouseLocation)';
COMMENT ON COLUMN "GoodsReceipt"."PersonnelID" IS '[KS X 9101 표준] 사원식별자: — 인사조직 내 사원을 식별하기 위한 고유값
— 입고 처리를 한 담당자의 식별정보
— 참조 대상: 사원(Personnel)';
COMMENT ON COLUMN "GoodsReceipt"."GoodsReceiptSequence" IS '[KS X 9101 표준] 입고순번: — 입고순번
— 입고 행은 입고식별자와 입고순번의 조합으로 구분함';
COMMENT ON COLUMN "GoodsReceipt"."GoodsReceiptType" IS '[KS X 9101 표준] 입고처리유형: — 입고처리유형
— 입고처리유형은 발주입고, 검사입고, 예외입고 등을 포함
— 참조 대상: 공통코드정보(CommonCodeMaster)의 코드';
COMMENT ON COLUMN "GoodsReceipt"."GoodsReceiptReturnType" IS '[KS X 9101 표준] 입고반품유형: — 입고반품유형은 구매발주된 품목의 입고 반품 처리 유형
— 입고반품유형은 공급업체 반품, 입고 취소, 반품 PO 기반 입고 등을 포함
— 참조 대상: 공통코드정보(CommonCodeMaster)의 코드';
COMMENT ON COLUMN "GoodsReceipt"."GoodsReceiptDate" IS '[KS X 9101 표준] 입고처리일: — 입고처리일';
COMMENT ON COLUMN "GoodsReceipt"."ItemID" IS '[KS X 9101 표준] 품목식별자: — 품목을 식별하기 위한 고유값
— 제품, 반제품, 상품, 원자재, 부자재, 저장품, 소모품 등회사 내 시스템으로 관리되는 모든 품목을 포함
— 참조 대상: 품목마스터(ItemMaster)';
COMMENT ON COLUMN "GoodsReceipt"."ItemName" IS '[KS X 9101 표준] 품목명: — 품목의 명칭
— 참조 대상: 품목마스터(ItemMaster.ItemName)';
COMMENT ON COLUMN "GoodsReceipt"."InventoryTransactionDocumentNumber" IS '[KS X 9101 표준] 수불문서번호: — 수불문서번호';
COMMENT ON COLUMN "GoodsReceipt"."InventoryTransactionDocumentSequence" IS '[KS X 9101 표준] 수불문서순번: — 수불문서순번';
COMMENT ON COLUMN "GoodsReceipt"."InventoryTransactionTypeCode" IS '[KS X 9101 표준] 수불유형코드: — 재고 변동(수불)의 성격과 원인을 구분하는 상세 코드로, 입출고유형(이동·조정은 수불유형)의 하위에 속함
— 수불유형코드가 정해지면 수불유형, 입출고유형, 재고증감유형이 정해지며, 함께 기재하는 경우 그 값과 일치해야 함
— 예: 구매입고, 구매입고 취소, 생산출고, 생산출고 반납, 창고간 이동, 실사 조정 등
— 참조 대상: 공통코드정보(CommonCodeMaster)의 코드';
COMMENT ON COLUMN "GoodsReceipt"."InvoiceNumber" IS '[KS X 9101 표준] 송장번호: — 구매송장번호, 구매송장 처리 후 업데이트되는 항목';
COMMENT ON COLUMN "GoodsReceipt"."InvoiceSequence" IS '[KS X 9101 표준] 송장라인순번: — 구매송장순번, 구매송장 처리 후 업데이트되는 항목';
COMMENT ON COLUMN "GoodsReceipt"."InvoiceProcessingIndicator" IS '[KS X 9101 표준] 송장처리여부: — 구매송장 처리여부, 구매송장 처리 후 업데이트되는항목';
COMMENT ON COLUMN "GoodsReceipt"."IncomingInspectionIndicator" IS '[KS X 9101 표준] 수입검사여부: — 수입검사여부
— 참조 대상: 품목마스터(ItemMaster.IncomingInspectionIndicator)';
COMMENT ON COLUMN "GoodsReceipt"."VendorID" IS '[KS X 9101 표준] 공급사식별자: — 품목을 구입해오는 거래처를 식별하기 위한 고유값
— 참조 대상: 공급사(VendorPartyMaster)';
COMMENT ON COLUMN "GoodsReceipt"."PurchaseOrderUOMCode" IS '[KS X 9101 표준] 발주단위코드: — 발주단위코드
— 예: EA, BOX, kg, ROL 등
— 참조 대상: 단위그룹(UOMGroup)의 단위코드';
COMMENT ON COLUMN "GoodsReceipt"."ItemUnitQuantity" IS '[KS X 9101 표준] 기준단위수량: — 기준수량(수량의 단위는 기준단위코드로 함)';
COMMENT ON COLUMN "GoodsReceipt"."GoodsReceiptQuantity" IS '[KS X 9101 표준] 입고처리수량: — 입고 처리된 수량';
COMMENT ON COLUMN "GoodsReceipt"."IncomingInspectionAcceptedQuantity" IS '[KS X 9101 표준] 수입검사합격수량: — 수입검사합격수량';
COMMENT ON COLUMN "GoodsReceipt"."IncomingInspectionRejectedQuantity" IS '[KS X 9101 표준] 수입검사불합격수량: — 수입검사불합격수량';
COMMENT ON COLUMN "GoodsReceipt"."PurchaseGroupCode" IS '[KS X 9101 표준] 구매그룹코드: — 구매그룹코드
— 구매 업무를 담당하는 구매그룹(구매조직 내 담당 단위)의 코드
— 구매조직이 세분화되지 않은 기업은 단일 코드로 운영할 수 있음
— 예: 원자재 구매, 부자재 구매, 외주 구매, 설비·자산 구매, MRO 구매, 수입 구매 등
— 참조 대상: 공통코드정보(CommonCodeMaster)의 코드';
COMMENT ON COLUMN "GoodsReceipt"."ItemUOMCode" IS '[KS X 9101 표준] 기준단위코드: — 기준단위코드(예: EA, DZ, HD 등)
— 참조 대상: 단위그룹(UOMGroup)의 단위코드';

-- ---------------------------------------------------------------------
-- [표준 구분: KS X 9101 표준] 표 43, 조항 7.4.5.3 | 업무영역: 자재관리
-- 테이블명(물리): "GoodsIssue" | 테이블명(논리): 자재불출
-- 설명: 자재불출 요청된 자재를 불출하는 것을 의미한다(일반적으로 재고 관리주체가 다를 경우 창고관리부서에서 사용).
-- ---------------------------------------------------------------------
CREATE TABLE "GoodsIssue" ( -- [KS X 9101 표준] 자재불출 (표 43)
    "GoodsIssueSequenceNo" BIGINT GENERATED BY DEFAULT AS IDENTITY, -- [KS X 9101 표준] 자재불출 일련번호(PK)
    "EnterpriseID" VARCHAR(50) NOT NULL, -- [KS X 9101 표준] 회사식별자
    "SiteID" VARCHAR(50) NOT NULL, -- [KS X 9101 표준] 사업장식별자
    "PlantID" VARCHAR(50) NOT NULL, -- [KS X 9101 표준] 공장식별자
    "CreatorID" VARCHAR(50), -- [KS X 9101 표준] 등록자식별자
    "CreationDateTime" TIMESTAMP, -- [KS X 9101 표준] 등록일시
    "ModifierID" VARCHAR(50), -- [KS X 9101 표준] 수정자식별자
    "ModificationDateTime" TIMESTAMP, -- [KS X 9101 표준] 수정일시
    "Note" VARCHAR(1000), -- [KS X 9101 표준] 비고
    "GoodsIssueID" VARCHAR(50) NOT NULL, -- [KS X 9101 표준] 자재불출식별자
    "InventoryTransactionDocumentNumber" VARCHAR(50), -- [KS X 9101 표준] 수불문서번호
    "InventoryTransactionDocumentSequence" INTEGER, -- [KS X 9101 표준] 수불문서순번
    "ItemID" VARCHAR(50), -- [KS X 9101 표준] 품목식별자
    "InventoryTransactionTypeCode" VARCHAR(30), -- [KS X 9101 표준] 수불유형코드
    "InventoryTransferType" VARCHAR(30), -- [KS X 9101 표준] 입출고유형
    "InventoryVariationType" VARCHAR(30), -- [KS X 9101 표준] 재고증감유형
    "InventoryTransactionType" VARCHAR(30), -- [KS X 9101 표준] 수불유형
    "LotID" VARCHAR(50), -- [KS X 9101 표준] 로트식별자
    "SerialUseIndicator" BOOLEAN, -- [KS X 9101 표준] 시리얼사용여부
    "VendorID" VARCHAR(50), -- [KS X 9101 표준] 공급사식별자
    "WarehouseID" VARCHAR(50), -- [KS X 9101 표준] 창고식별자
    "ItemUOMCode" VARCHAR(20), -- [KS X 9101 표준] 기준단위코드
    "ItemUnitQuantity" NUMERIC(18,6), -- [KS X 9101 표준] 기준단위수량
    "OrderUOMCode" VARCHAR(20), -- [KS X 9101 표준] 오더단위코드
    "OrderQuantity" NUMERIC(18,6), -- [KS X 9101 표준] 오더수량
    CONSTRAINT "PK_GoodsIssue" PRIMARY KEY ("GoodsIssueSequenceNo"),
    CONSTRAINT "UK_GoodsIssue" UNIQUE ("EnterpriseID", "GoodsIssueID")
);

COMMENT ON TABLE "GoodsIssue" IS '[KS X 9101 표준] 자재불출 (자재불출 요청된 자재를 불출하는 것을 의미한다(일반적으로 재고 관리주체가 다를 경우 창고관리부서에서 사용).)';
COMMENT ON COLUMN "GoodsIssue"."GoodsIssueSequenceNo" IS '[KS X 9101 표준] 자재불출 일련번호: — 테이블 행을 식별하는 일련번호(PK, 대리키) — 표준 외 물리 컬럼
— 자동 증가 값(IDENTITY)으로 부여하며 다른 테이블이 참조하지 않음(FK는 UK 참조)';
COMMENT ON COLUMN "GoodsIssue"."EnterpriseID" IS '[KS X 9101 표준] 회사식별자: — 회사를 유일하게 구분할 수 있는 고유식별값
