— 참조 대상: 회사(Enterprise)';
COMMENT ON COLUMN "GoodsIssue"."SiteID" IS '[KS X 9101 표준] 사업장식별자: — 회사 내에서 사업장을 구분할수 있는 고유식별값
— 참조 대상: 사업장(Site)';
COMMENT ON COLUMN "GoodsIssue"."PlantID" IS '[KS X 9101 표준] 공장식별자: — 회사 내에서 공장을 구분할 수있는 고유식별값(만약, 공장 개념을 사용하지 않는다면 고정식별자로 설정하여 입력해야 함)
— 참조 대상: 공장(Plant)';
COMMENT ON COLUMN "GoodsIssue"."CreatorID" IS '[KS X 9101 표준] 등록자식별자: — 정보를 처음으로 등록한 사람을 구분할 수 있는 고유식별값으로, 일반적으로 사원번호가사용됨
— 참조 대상: 사원(Personnel)';
COMMENT ON COLUMN "GoodsIssue"."CreationDateTime" IS '[KS X 9101 표준] 등록일시: — 정보를 처음으로 등록한 날짜 (KS X ISO 8601을 따른다)';
COMMENT ON COLUMN "GoodsIssue"."ModifierID" IS '[KS X 9101 표준] 수정자식별자: — 정보를 마지막으로 수정한 사람을 구분할 수 있는 고유식별값으로, 일반적으로 사원번호가 사용됨
— 참조 대상: 사원(Personnel)';
COMMENT ON COLUMN "GoodsIssue"."ModificationDateTime" IS '[KS X 9101 표준] 수정일시: — 정보를 마지막으로 수정한 날짜 (KS X ISO 8601을 따른다.)';
COMMENT ON COLUMN "GoodsIssue"."Note" IS '[KS X 9101 표준] 비고: — 비고사항';
COMMENT ON COLUMN "GoodsIssue"."GoodsIssueID" IS '[KS X 9101 표준] 자재불출식별자: — 자재불출을 식별하기 위한 고유값';
COMMENT ON COLUMN "GoodsIssue"."InventoryTransactionDocumentNumber" IS '[KS X 9101 표준] 수불문서번호: — 수불문서번호';
COMMENT ON COLUMN "GoodsIssue"."InventoryTransactionDocumentSequence" IS '[KS X 9101 표준] 수불문서순번: — 수불문서순번';
COMMENT ON COLUMN "GoodsIssue"."ItemID" IS '[KS X 9101 표준] 품목식별자: — 품목을 식별하기 위한 고유값
— 제품, 반제품, 상품, 원자재, 부자재, 저장품, 소모품 등회사 내 시스템으로 관리되는 모든 품목을 포함
— 참조 대상: 품목마스터(ItemMaster)';
COMMENT ON COLUMN "GoodsIssue"."InventoryTransactionTypeCode" IS '[KS X 9101 표준] 수불유형코드: — 재고 변동(수불)의 성격과 원인을 구분하는 상세 코드로, 입출고유형(이동·조정은 수불유형)의 하위에 속함
— 수불유형코드가 정해지면 수불유형, 입출고유형, 재고증감유형이 정해지며, 함께 기재하는 경우 그 값과 일치해야 함
— 예: 구매입고, 구매입고 취소, 생산출고, 생산출고 반납, 창고간 이동, 실사 조정 등
— 참조 대상: 공통코드정보(CommonCodeMaster)의 코드';
COMMENT ON COLUMN "GoodsIssue"."InventoryTransferType" IS '[KS X 9101 표준] 입출고유형: — 입고 또는 출고의 사유로, 수불유형(입고·출고)의 하위에 속함
— 예: 입고는 구매입고, 생산입고, 외주입고, 매출반품입고, 타계정입고 등, 출고는 판매출고, 생산출고, 외주출고, 매입반품출고, 타계정출고, 폐기출고 등
— 참조 대상: 공통코드정보(CommonCodeMaster)의 코드';
COMMENT ON COLUMN "GoodsIssue"."InventoryVariationType" IS '[KS X 9101 표준] 재고증감유형: — 해당 수불이 재고 수량을 증가시키는지 감소시키는지의 구분으로, 수불유형코드에 따라 정해짐(취소 거래는 원거래와 반대)
— 예: 증가, 감소
— 참조 대상: 공통코드정보(CommonCodeMaster)의 코드';
COMMENT ON COLUMN "GoodsIssue"."InventoryTransactionType" IS '[KS X 9101 표준] 수불유형: — 재고 변동의 종류
— 예: 입고, 출고, 이동, 조정
— 참조 대상: 공통코드정보(CommonCodeMaster)의 코드';
COMMENT ON COLUMN "GoodsIssue"."LotID" IS '[KS X 9101 표준] 로트식별자: — 자재불출에 포함된 로트의 고유식별값
— 참조 대상: 로트(Lot)';
COMMENT ON COLUMN "GoodsIssue"."SerialUseIndicator" IS '[KS X 9101 표준] 시리얼사용여부: — 시리얼사용여부';
COMMENT ON COLUMN "GoodsIssue"."VendorID" IS '[KS X 9101 표준] 공급사식별자: — 품목을 구입해오는 거래처를 식별하기 위한 고유값
— 참조 대상: 공급사(VendorPartyMaster)';
COMMENT ON COLUMN "GoodsIssue"."WarehouseID" IS '[KS X 9101 표준] 창고식별자: — 창고를 식별하기 위한 고유값
— 참조 대상: 창고(WarehouseLocation)';
COMMENT ON COLUMN "GoodsIssue"."ItemUOMCode" IS '[KS X 9101 표준] 기준단위코드: — 기준단위코드(예: EA, DZ, HD 등)
— 참조 대상: 단위그룹(UOMGroup)의 단위코드';
COMMENT ON COLUMN "GoodsIssue"."ItemUnitQuantity" IS '[KS X 9101 표준] 기준단위수량: — 기준단위수량(수량의 단위는 기준단위코드로 함)';
COMMENT ON COLUMN "GoodsIssue"."OrderUOMCode" IS '[KS X 9101 표준] 오더단위코드: — 오더단위코드(예: EA, DZ, HD 등)
— 참조 대상: 단위그룹(UOMGroup)의 단위코드';
COMMENT ON COLUMN "GoodsIssue"."OrderQuantity" IS '[KS X 9101 표준] 오더수량: — 오더수량(수량의 단위는 오더단위코드로 함)';

-- ---------------------------------------------------------------------
-- [표준 구분: KS X 9101 표준] 표 44, 조항 7.4.6.1 | 업무영역: 생산관리
-- 테이블명(물리): "ProductionPlanning" | 테이블명(논리): 생산계획
-- 설명: 특정 제품을 생산하기 위한 계획을 의미한다.
-- ---------------------------------------------------------------------
CREATE TABLE "ProductionPlanning" ( -- [KS X 9101 표준] 생산계획 (표 44)
    "ProductionPlanningSequenceNo" BIGINT GENERATED BY DEFAULT AS IDENTITY, -- [KS X 9101 표준] 생산계획 일련번호(PK)
    "EnterpriseID" VARCHAR(50) NOT NULL, -- [KS X 9101 표준] 회사식별자
    "SiteID" VARCHAR(50) NOT NULL, -- [KS X 9101 표준] 사업장식별자
    "PlantID" VARCHAR(50) NOT NULL, -- [KS X 9101 표준] 공장식별자
    "CreatorID" VARCHAR(50), -- [KS X 9101 표준] 등록자식별자
    "CreationDateTime" TIMESTAMP, -- [KS X 9101 표준] 등록일시
    "ModifierID" VARCHAR(50), -- [KS X 9101 표준] 수정자식별자
    "ModificationDateTime" TIMESTAMP, -- [KS X 9101 표준] 수정일시
    "Note" VARCHAR(1000), -- [KS X 9101 표준] 비고
    "ProductionPlanID" VARCHAR(50) NOT NULL, -- [KS X 9101 표준] 생산계획식별자
    "ItemID" VARCHAR(50), -- [KS X 9101 표준] 품목식별자
    "ProductionPlanQuantity" INTEGER, -- [KS X 9101 표준] 생산계획수량
    "ScheduleStartDateTime" TIMESTAMP, -- [KS X 9101 표준] 생산계획시작일시
    "ScheduleEndDateTime" TIMESTAMP, -- [KS X 9101 표준] 생산계획종료일시
    CONSTRAINT "PK_ProductionPlanning" PRIMARY KEY ("ProductionPlanningSequenceNo"),
    CONSTRAINT "UK_ProductionPlanning" UNIQUE ("EnterpriseID", "ProductionPlanID")
);

