-- ---------------------------------------------------------------------
-- [표준 구분: KS X 9101 표준] 표 45, 조항 7.4.6.2 | 업무영역: 생산관리
-- 테이블명(물리): "ProductionOrder" | 테이블명(논리): 생산지시
-- 설명: 특정 제품의 생산을 지시하는 정보를 의미한다.
-- ---------------------------------------------------------------------
CREATE TABLE "ProductionOrder" ( -- [KS X 9101 표준] 생산지시 (표 45)
    "ProductionOrderSequenceNo" BIGINT GENERATED BY DEFAULT AS IDENTITY, -- [KS X 9101 표준] 생산지시 일련번호(PK)
    "EnterpriseID" VARCHAR(50) NOT NULL, -- [KS X 9101 표준] 회사식별자
    "SiteID" VARCHAR(50) NOT NULL, -- [KS X 9101 표준] 사업장식별자
    "PlantID" VARCHAR(50) NOT NULL, -- [KS X 9101 표준] 공장식별자
    "CreatorID" VARCHAR(50), -- [KS X 9101 표준] 등록자식별자
    "CreationDateTime" TIMESTAMP, -- [KS X 9101 표준] 등록일시
    "ModifierID" VARCHAR(50), -- [KS X 9101 표준] 수정자식별자
    "ModificationDateTime" TIMESTAMP, -- [KS X 9101 표준] 수정일시
    "Note" VARCHAR(1000), -- [KS X 9101 표준] 비고
    "ProductionOrderID" VARCHAR(50) NOT NULL, -- [KS X 9101 표준] 생산지시식별자
    "ProductionOrderSequence" INTEGER NOT NULL, -- [KS X 9101 표준] 생산지시순번
    "ItemID" VARCHAR(50), -- [KS X 9101 표준] 품목식별자
    "LineID" VARCHAR(50), -- [KS X 9101 표준] 라인식별자
    "RoutingID" VARCHAR(50), -- [KS X 9101 표준] 공정경로식별자
    "BOMID" VARCHAR(50), -- [KS X 9101 표준] 자재명세서식별자
    "BOMRevisionNumber" INTEGER, -- [KS X 9101 표준] 자재명세서버전
    "ItemUOMCode" VARCHAR(20), -- [KS X 9101 표준] 기준단위코드
    "ProductionOrderQuantity" INTEGER, -- [KS X 9101 표준] 생산지시수량
    "ProductionDueDateTime" TIMESTAMP, -- [KS X 9101 표준] 생산완료기한일시
    "ScheduleStartDateTime" TIMESTAMP, -- [KS X 9101 표준] 생산계획시작일시
    "ScheduleEndDateTime" TIMESTAMP, -- [KS X 9101 표준] 생산계획종료일시
    "SalesDocumentNumber" VARCHAR(50), -- [KS X 9101 표준] 수주문서번호
    "SalesDocumentSequence" INTEGER, -- [KS X 9101 표준] 수주문서순번
    CONSTRAINT "PK_ProductionOrder" PRIMARY KEY ("ProductionOrderSequenceNo"),
    CONSTRAINT "UK_ProductionOrder" UNIQUE ("EnterpriseID", "ProductionOrderID", "ProductionOrderSequence")
);

COMMENT ON TABLE "ProductionOrder" IS '[KS X 9101 표준] 생산지시 (특정 제품의 생산을 지시하는 정보를 의미한다.)';
