— 기업업무시스템 간의 연동을 수행하는 회사들 간에 자체적으로 정의한 고유식별값
— 참조 대상: 회사(Enterprise)';
COMMENT ON COLUMN "ProductionOrder"."SiteID" IS '[KS X 9101 표준] 사업장식별자: — 회사 내에서 사업장을 구분할수 있는 고유식별값
— 참조 대상: 사업장(Site)';
COMMENT ON COLUMN "ProductionOrder"."PlantID" IS '[KS X 9101 표준] 공장식별자: — 회사 내에서 공장을 구분할 수있는 고유식별값(만약, 공장 개념을 사용하지 않는다면 고정식별자로 설정하여 입력해야 함)
— 참조 대상: 공장(Plant)';
COMMENT ON COLUMN "ProductionOrder"."CreatorID" IS '[KS X 9101 표준] 등록자식별자: — 정보를 처음으로 등록한 사람을 구분할 수 있는 고유식별값으로, 일반적으로 사원번호가사용됨
— 참조 대상: 사원(Personnel)';
COMMENT ON COLUMN "ProductionOrder"."CreationDateTime" IS '[KS X 9101 표준] 등록일시: — 정보를 처음으로 등록한 날짜 (KS X ISO 8601을 따른다)';
COMMENT ON COLUMN "ProductionOrder"."ModifierID" IS '[KS X 9101 표준] 수정자식별자: — 정보를 마지막으로 수정한 사람을 구분할 수 있는 고유식별값으로, 일반적으로 사원번호가 사용됨
— 참조 대상: 사원(Personnel)';
COMMENT ON COLUMN "ProductionOrder"."ModificationDateTime" IS '[KS X 9101 표준] 수정일시: — 정보를 마지막으로 수정한 날짜 (KS X ISO 8601을 따른다.)';
COMMENT ON COLUMN "ProductionOrder"."Note" IS '[KS X 9101 표준] 비고: — 비고사항';
COMMENT ON COLUMN "ProductionOrder"."ProductionOrderID" IS '[KS X 9101 표준] 생산지시식별자: — 생산지시를 식별하기 위한 고유값';
COMMENT ON COLUMN "ProductionOrder"."ProductionOrderSequence" IS '[KS X 9101 표준] 생산지시순번: — 생산지시식별자 내 순서
— 생산지시 명사의 식별자는 생산지시식별자, 생산지시순번 조합';
COMMENT ON COLUMN "ProductionOrder"."ItemID" IS '[KS X 9101 표준] 품목식별자: — 품목을 식별하기 위한 고유값
— 제품, 반제품, 상품, 원자재, 부자재, 저장품, 소모품 등 회사 내시스템으로 관리되는 모든 품목을 포함
— 참조 대상: 품목마스터(ItemMaster)';
COMMENT ON COLUMN "ProductionOrder"."LineID" IS '[KS X 9101 표준] 라인식별자: — 라인을 식별하기 위한 고유값
— 참조 대상: 라인(Line)';
COMMENT ON COLUMN "ProductionOrder"."RoutingID" IS '[KS X 9101 표준] 공정경로식별자: — 공정경로를 식별하기 위한 고유값
— 생산지시는 공정경로식별자가 가리키는 공정경로 전체를 따르며, 공정순번은 지정하지 않음
— 참조 대상: 공정경로(Routing)';
COMMENT ON COLUMN "ProductionOrder"."BOMID" IS '[KS X 9101 표준] 자재명세서식별자: — 자재명세서를 식별하기 위한 고유값
— 참조 대상: 자재명세서(BOM)';
COMMENT ON COLUMN "ProductionOrder"."BOMRevisionNumber" IS '[KS X 9101 표준] 자재명세서버전: — 자재명세서의 버전
— 자재명세서식별자(BOMID)와 함께 자재명세서(BOM)를 참조한다';
COMMENT ON COLUMN "ProductionOrder"."ItemUOMCode" IS '[KS X 9101 표준] 기준단위코드: — 기준단위코드(예: EA, DZ, HD 등)
— 참조 대상: 단위그룹(UOMGroup)의 단위코드';
COMMENT ON COLUMN "ProductionOrder"."ProductionOrderQuantity" IS '[KS X 9101 표준] 생산지시수량: — 생산지시에 따라 생산할 품목의 수량(수량의 단위는 기준단위코드로 함)';
COMMENT ON COLUMN "ProductionOrder"."ProductionDueDateTime" IS '[KS X 9101 표준] 생산완료기한일시: — 생산지시에 따라 계획한 작업의 생산종료일(KS X ISO 8601을 따른다)';
COMMENT ON COLUMN "ProductionOrder"."ScheduleStartDateTime" IS '[KS X 9101 표준] 생산계획시작일시: — 생산계획상의 예상 생산시작일(KS X ISO 8601을 따른다)';
COMMENT ON COLUMN "ProductionOrder"."ScheduleEndDateTime" IS '[KS X 9101 표준] 생산계획종료일시: — 생산계획상의 예상 생산종료일(KS X ISO 8601을 따른다)';
COMMENT ON COLUMN "ProductionOrder"."SalesDocumentNumber" IS '[KS X 9101 표준] 수주문서번호: — 수주문서번호
— 참조 대상: 수주오더(SalesOrder)
— 수주문서순번(SalesDocumentSequence)과 함께 사용한다';
COMMENT ON COLUMN "ProductionOrder"."SalesDocumentSequence" IS '[KS X 9101 표준] 수주문서순번: — 수주문서순번
— 수주문서번호(SalesDocumentNumber)와 함께 수주오더(SalesOrder)를 참조한다';

-- ---------------------------------------------------------------------
-- [표준 구분: KS X 9101 표준] 표 46, 조항 7.4.6.3 | 업무영역: 생산관리
-- 테이블명(물리): "OperationStart" | 테이블명(논리): 착공
-- 설명: 설비에 해당 공정의 생산을 지시한다.
-- ---------------------------------------------------------------------
CREATE TABLE "OperationStart" ( -- [KS X 9101 표준] 착공 (표 46)
    "OperationStartSequenceNo" BIGINT GENERATED BY DEFAULT AS IDENTITY, -- [KS X 9101 표준] 착공 일련번호(PK)
    "EnterpriseID" VARCHAR(50) NOT NULL, -- [KS X 9101 표준] 회사식별자
    "SiteID" VARCHAR(50) NOT NULL, -- [KS X 9101 표준] 사업장식별자
    "PlantID" VARCHAR(50) NOT NULL, -- [KS X 9101 표준] 공장식별자
    "CreatorID" VARCHAR(50), -- [KS X 9101 표준] 등록자식별자
    "CreationDateTime" TIMESTAMP, -- [KS X 9101 표준] 등록일시
    "ModifierID" VARCHAR(50), -- [KS X 9101 표준] 수정자식별자
    "ModificationDateTime" TIMESTAMP, -- [KS X 9101 표준] 수정일시
    "Note" VARCHAR(1000), -- [KS X 9101 표준] 비고
    "OperationStartID" VARCHAR(50) NOT NULL, -- [KS X 9101 표준] 착공식별자
    "LotID" VARCHAR(50), -- [KS X 9101 표준] 로트식별자
    "LotName" VARCHAR(200), -- [KS X 9101 표준] 로트명
    "LotDescription" VARCHAR(1000), -- [KS X 9101 표준] 로트설명
    "LotCreatedQuantity" NUMERIC(18,6), -- [KS X 9101 표준] 로트수량
    "OperationID" VARCHAR(50), -- [KS X 9101 표준] 공정식별자
    "EquipmentID" VARCHAR(50), -- [KS X 9101 표준] 설비식별자
    "OperationStartTime" TIMESTAMP, -- [KS X 9101 표준] 착공시간
    "PersonnelID" VARCHAR(50), -- [KS X 9101 표준] 사원식별자
    CONSTRAINT "PK_OperationStart" PRIMARY KEY ("OperationStartSequenceNo"),
    CONSTRAINT "UK_OperationStart" UNIQUE ("EnterpriseID", "OperationStartID")
);

COMMENT ON TABLE "OperationStart" IS '[KS X 9101 표준] 착공 (설비에 해당 공정의 생산을 지시한다.)';
COMMENT ON COLUMN "OperationStart"."OperationStartSequenceNo" IS '[KS X 9101 표준] 착공 일련번호: — 테이블 행을 식별하는 일련번호(PK, 대리키) — 표준 외 물리 컬럼
— 자동 증가 값(IDENTITY)으로 부여하며 다른 테이블이 참조하지 않음(FK는 UK 참조)';
COMMENT ON COLUMN "OperationStart"."EnterpriseID" IS '[KS X 9101 표준] 회사식별자: — 회사를 유일하게 구분할 수 있는 고유식별값
— 기업업무시스템 간의 연동을 수행하는 회사들 간에 자체적으로 정의한 고유식별값
— 참조 대상: 회사(Enterprise)';
COMMENT ON COLUMN "OperationStart"."SiteID" IS '[KS X 9101 표준] 사업장식별자: — 회사 내에서 사업장을 구분할수 있는 고유식별값
— 참조 대상: 사업장(Site)';
COMMENT ON COLUMN "OperationStart"."PlantID" IS '[KS X 9101 표준] 공장식별자: — 회사 내에서 공장을 구분할 수있는 고유식별값(만약, 공장 개념을 사용하지 않는다면 고정식별자로 설정하여 입력해야 함)
— 참조 대상: 공장(Plant)';
COMMENT ON COLUMN "OperationStart"."CreatorID" IS '[KS X 9101 표준] 등록자식별자: — 정보를 처음으로 등록한 사람을 구분할 수 있는 고유식별값으로, 일반적으로 사원번호가사용됨
— 참조 대상: 사원(Personnel)';
COMMENT ON COLUMN "OperationStart"."CreationDateTime" IS '[KS X 9101 표준] 등록일시: — 정보를 처음으로 등록한 날짜 (KS X ISO 8601을 따른다)';
COMMENT ON COLUMN "OperationStart"."ModifierID" IS '[KS X 9101 표준] 수정자식별자: — 정보를 마지막으로 수정한 사람을 구분할 수 있는 고유식별값으로, 일반적으로 사원번호가 사용됨
— 참조 대상: 사원(Personnel)';
COMMENT ON COLUMN "OperationStart"."ModificationDateTime" IS '[KS X 9101 표준] 수정일시: — 정보를 마지막으로 수정한 날짜 (KS X ISO 8601을 따른다.)';
COMMENT ON COLUMN "OperationStart"."Note" IS '[KS X 9101 표준] 비고: — 비고사항';
COMMENT ON COLUMN "OperationStart"."OperationStartID" IS '[KS X 9101 표준] 착공식별자: — 착공을 식별하기 위한 고유값
— 이벤트를 최초로 발생시킨 시스템이 GUID 형식으로 부여하며, BOD로 최초 송신한 경우 해당 BOD의 BODID를 식별자로 사용할 수 있음(7.1)';
COMMENT ON COLUMN "OperationStart"."LotID" IS '[KS X 9101 표준] 로트식별자: — 로트를 식별하기 위한 고유값
— 참조 대상: 로트(Lot)';
COMMENT ON COLUMN "OperationStart"."LotName" IS '[KS X 9101 표준] 로트명: — 로트의 명칭
— 참조 대상: 로트(Lot.LotName)';
COMMENT ON COLUMN "OperationStart"."LotDescription" IS '[KS X 9101 표준] 로트설명: — 로트 설명 정보
— 참조 대상: 로트(Lot.LotDescription)';
COMMENT ON COLUMN "OperationStart"."LotCreatedQuantity" IS '[KS X 9101 표준] 로트수량: — 처음 생성 시 로트 수량
— 참조 대상: 로트(Lot.LotCreatedQuantity)';
COMMENT ON COLUMN "OperationStart"."OperationID" IS '[KS X 9101 표준] 공정식별자: — 공정을 식별하기 위한 고유값
— 참조 대상: 공정(Operation)';
COMMENT ON COLUMN "OperationStart"."EquipmentID" IS '[KS X 9101 표준] 설비식별자: — 설비를 식별하기 위한 고유값
— 참조 대상: 설비(Equipment)';
COMMENT ON COLUMN "OperationStart"."OperationStartTime" IS '[KS X 9101 표준] 착공시간: — 로트를 생산하기 위한 공정 투입 시간(KS X ISO 8601을 따른다)';
COMMENT ON COLUMN "OperationStart"."PersonnelID" IS '[KS X 9101 표준] 사원식별자: — 인사조직 내 사원을 식별하기 위한 고유값
— 해당 공정에서 로트를 생산하는 작업자의 식별정보
— 참조 대상: 사원(Personnel)';

