CREATE TABLE "OperationEnd" ( -- [KS X 9101 표준] 완공 (표 47)
    "OperationEndSequenceNo" BIGINT GENERATED BY DEFAULT AS IDENTITY, -- [KS X 9101 표준] 완공 일련번호(PK)
