— 이벤트를 최초로 발생시킨 시스템이 GUID 형식으로 부여하며, BOD로 최초 송신한 경우 해당 BOD의 BODID를 식별자로 사용할 수 있음(7.1)';
COMMENT ON COLUMN "OperationEnd"."LotID" IS '[KS X 9101 표준] 로트식별자: — 로트를 식별하기 위한 고유값
— 참조 대상: 로트(Lot)';
COMMENT ON COLUMN "OperationEnd"."LotName" IS '[KS X 9101 표준] 로트명: — 로트의 명칭
— 참조 대상: 로트(Lot.LotName)';
COMMENT ON COLUMN "OperationEnd"."LotDescription" IS '[KS X 9101 표준] 로트설명: — 로트 설명 정보
— 참조 대상: 로트(Lot.LotDescription)';
COMMENT ON COLUMN "OperationEnd"."LotCreatedQuantity" IS '[KS X 9101 표준] 로트수량: — 처음 생성시 로트 수량
— 참조 대상: 로트(Lot.LotCreatedQuantity)';
COMMENT ON COLUMN "OperationEnd"."OperationID" IS '[KS X 9101 표준] 공정식별자: — 공정을 식별하기 위한 고유값
— 참조 대상: 공정(Operation)';
COMMENT ON COLUMN "OperationEnd"."EquipmentID" IS '[KS X 9101 표준] 설비식별자: — 설비를 식별하기 위한 고유값
— 참조 대상: 설비(Equipment)';
COMMENT ON COLUMN "OperationEnd"."OperationEndTime" IS '[KS X 9101 표준] 완공시간: — 로트를 생산한 공정 완료 시간(KS X ISO 8601을 따른다)';
COMMENT ON COLUMN "OperationEnd"."PersonnelID" IS '[KS X 9101 표준] 사원식별자: — 인사조직 내 사원을 식별하기 위한 고유값
— 해당 공정에서 로트 생산을 완료하는 작업자의 식별정보
— 참조 대상: 사원(Personnel)';
COMMENT ON COLUMN "OperationEnd"."ProducedQuantity" IS '[KS X 9101 표준] 생산수량: — 해당 공정에서 생산된 로트의 전체 수량';
COMMENT ON COLUMN "OperationEnd"."DefectQuantity" IS '[KS X 9101 표준] 불량수량: — 해당 공정에서 생산된 로트의 전체 수량 중 불량수량';
COMMENT ON COLUMN "OperationEnd"."ReworkCount" IS '[KS X 9101 표준] 재작업횟수: — 해당 공정의 재작업 횟수';

-- ---------------------------------------------------------------------
-- [표준 구분: KS X 9101 표준] 표 48, 조항 7.4.6.5 | 업무영역: 생산관리
-- 테이블명(물리): "TransferCommand" | 테이블명(논리): 이동지시
-- 설명: 현재 공정에서 다음 공정으로 작업할 Lot의 이동을 지시한다.
-- ---------------------------------------------------------------------
CREATE TABLE "TransferCommand" ( -- [KS X 9101 표준] 이동지시 (표 48)
    "TransferCommandSequenceNo" BIGINT GENERATED BY DEFAULT AS IDENTITY, -- [KS X 9101 표준] 이동지시 일련번호(PK)
    "EnterpriseID" VARCHAR(50) NOT NULL, -- [KS X 9101 표준] 회사식별자
    "SiteID" VARCHAR(50) NOT NULL, -- [KS X 9101 표준] 사업장식별자
    "PlantID" VARCHAR(50) NOT NULL, -- [KS X 9101 표준] 공장식별자
    "CreatorID" VARCHAR(50), -- [KS X 9101 표준] 등록자식별자
    "CreationDateTime" TIMESTAMP, -- [KS X 9101 표준] 등록일시
    "ModifierID" VARCHAR(50), -- [KS X 9101 표준] 수정자식별자
    "ModificationDateTime" TIMESTAMP, -- [KS X 9101 표준] 수정일시
    "Note" VARCHAR(1000), -- [KS X 9101 표준] 비고
    "TransferCommandID" VARCHAR(50) NOT NULL, -- [KS X 9101 표준] 이동지시식별자
    "LotID" VARCHAR(50), -- [KS X 9101 표준] 로트식별자
    "LotName" VARCHAR(200), -- [KS X 9101 표준] 로트명
    "LotDescription" VARCHAR(1000), -- [KS X 9101 표준] 로트설명
    "CarrierID" VARCHAR(50), -- [KS X 9101 표준] 캐리어식별자
    "SourceID" VARCHAR(50), -- [KS X 9101 표준] 출발지식별자
    "SourceType" VARCHAR(30), -- [KS X 9101 표준] 출발지유형
    "SourceName" VARCHAR(200), -- [KS X 9101 표준] 출발지명
    "DestinationID" VARCHAR(50), -- [KS X 9101 표준] 목적지식별자
    "DestinationType" VARCHAR(30), -- [KS X 9101 표준] 목적지유형
    "DestinationName" VARCHAR(200), -- [KS X 9101 표준] 목적지명
    CONSTRAINT "PK_TransferCommand" PRIMARY KEY ("TransferCommandSequenceNo"),
    CONSTRAINT "UK_TransferCommand" UNIQUE ("EnterpriseID", "TransferCommandID")
);

COMMENT ON TABLE "TransferCommand" IS '[KS X 9101 표준] 이동지시 (현재 공정에서 다음 공정으로 작업할 Lot의 이동을 지시한다.)';
COMMENT ON COLUMN "TransferCommand"."TransferCommandSequenceNo" IS '[KS X 9101 표준] 이동지시 일련번호: — 테이블 행을 식별하는 일련번호(PK, 대리키) — 표준 외 물리 컬럼
— 자동 증가 값(IDENTITY)으로 부여하며 다른 테이블이 참조하지 않음(FK는 UK 참조)';
COMMENT ON COLUMN "TransferCommand"."EnterpriseID" IS '[KS X 9101 표준] 회사식별자: — 회사를 유일하게 구분할 수 있는 고유식별값
— 기업업무시스템 간의 연동을 수행하는 회사들 간에 자체적으로 정의한 고유식별값
— 참조 대상: 회사(Enterprise)';
COMMENT ON COLUMN "TransferCommand"."SiteID" IS '[KS X 9101 표준] 사업장식별자: — 회사 내에서 사업장을 구분할수 있는 고유식별값
— 참조 대상: 사업장(Site)';
COMMENT ON COLUMN "TransferCommand"."PlantID" IS '[KS X 9101 표준] 공장식별자: — 회사 내에서 공장을 구분할 수있는 고유식별값(만약, 공장 개념을 사용하지 않는다면 고정식별자로 설정하여 입력해야 함)
— 참조 대상: 공장(Plant)';
COMMENT ON COLUMN "TransferCommand"."CreatorID" IS '[KS X 9101 표준] 등록자식별자: — 정보를 처음으로 등록한 사람을 구분할 수 있는 고유식별값으로, 일반적으로 사원번호가사용됨
— 참조 대상: 사원(Personnel)';
COMMENT ON COLUMN "TransferCommand"."CreationDateTime" IS '[KS X 9101 표준] 등록일시: — 정보를 처음으로 등록한 날짜 (KS X ISO 8601을 따른다)';
COMMENT ON COLUMN "TransferCommand"."ModifierID" IS '[KS X 9101 표준] 수정자식별자: — 정보를 마지막으로 수정한 사람을 구분할 수 있는 고유식별값으로, 일반적으로 사원번호가 사용됨
— 참조 대상: 사원(Personnel)';
COMMENT ON COLUMN "TransferCommand"."ModificationDateTime" IS '[KS X 9101 표준] 수정일시: — 정보를 마지막으로 수정한 날짜 (KS X ISO 8601을 따른다.)';
COMMENT ON COLUMN "TransferCommand"."Note" IS '[KS X 9101 표준] 비고: — 비고사항';
COMMENT ON COLUMN "TransferCommand"."TransferCommandID" IS '[KS X 9101 표준] 이동지시식별자: — 이동 유형에 따른 이동지시를 식별하기 위한 고유값';
COMMENT ON COLUMN "TransferCommand"."LotID" IS '[KS X 9101 표준] 로트식별자: — 로트를 식별하기 위한 고유값
— 참조 대상: 로트(Lot)';
COMMENT ON COLUMN "TransferCommand"."LotName" IS '[KS X 9101 표준] 로트명: — 로트의 명칭
— 참조 대상: 로트(Lot.LotName)';
COMMENT ON COLUMN "TransferCommand"."LotDescription" IS '[KS X 9101 표준] 로트설명: — 로트 설명 정보
— 참조 대상: 로트(Lot.LotDescription)';
COMMENT ON COLUMN "TransferCommand"."CarrierID" IS '[KS X 9101 표준] 캐리어식별자: — 캐리어를 식별하기 위한 고유값
— 참조 대상: 캐리어(Carrier)';
COMMENT ON COLUMN "TransferCommand"."SourceID" IS '[KS X 9101 표준] 출발지식별자: — 로트의 현재 위치 정보의 고유값
— OperationID(공정식별자), EquipmentID(설비식별자), StockerInventoryID(저장소재공정보식별자), 그 외 각 공장 특성에 따라 EVENT 처리를 위해 지정한 특정 LocationID
— 참조 대상: 공정(Operation), 설비(Equipment), 저장소재공정보(StockerInventory) 또는 캐리어(Carrier)
— 값이 가리키는 명사는 출발지유형(SourceType)으로 구분한다';
COMMENT ON COLUMN "TransferCommand"."SourceType" IS '[KS X 9101 표준] 출발지유형: — 로트의 현재 위치 정보를 나타내는 출발지 유형
— 출발지 유형은 설비 포트, 저장소, 캐리어 등을 포함
— 참조 대상: 공통코드정보(CommonCodeMaster)의 코드';
COMMENT ON COLUMN "TransferCommand"."SourceName" IS '[KS X 9101 표준] 출발지명: — 로트의 현재 위치의 명칭';
COMMENT ON COLUMN "TransferCommand"."DestinationID" IS '[KS X 9101 표준] 목적지식별자: — 로트가 이동하여 도착할 목적지 정보의 고유값
— OperationID(공정식별자), EquipmentID(설비식별자), StockerInventoryID(저장소재공정보식별자), 그 외 각 공장 특성에 따라 EVENT 처리를 위해 지정한 특정 LocationID
— 참조 대상: 공정(Operation), 설비(Equipment), 저장소재공정보(StockerInventory) 또는 캐리어(Carrier)
— 값이 가리키는 명사는 목적지유형(DestinationType)으로 구분한다';
COMMENT ON COLUMN "TransferCommand"."DestinationType" IS '[KS X 9101 표준] 목적지유형: — 로트가 이동하여 도착할 목적지 유형
— 목적지 유형은 설비 포트, 저장소, 캐리어 등을 포함
— 참조 대상: 공통코드정보(CommonCodeMaster)의 코드';
COMMENT ON COLUMN "TransferCommand"."DestinationName" IS '[KS X 9101 표준] 목적지명: — 로트가 이동하여 도착할 목적지의 명칭';

-- ---------------------------------------------------------------------
-- [표준 구분: KS X 9101 표준] 표 49, 조항 7.4.6.6 | 업무영역: 생산관리
-- 테이블명(물리): "TransferStart" | 테이블명(논리): 운행시작
-- 설명: 이동지시 명령을 받아 운행 시작 시 시작 정보를 보고한다.
-- ---------------------------------------------------------------------
CREATE TABLE "TransferStart" ( -- [KS X 9101 표준] 운행시작 (표 49)
    "TransferStartSequenceNo" BIGINT GENERATED BY DEFAULT AS IDENTITY, -- [KS X 9101 표준] 운행시작 일련번호(PK)
    "EnterpriseID" VARCHAR(50) NOT NULL, -- [KS X 9101 표준] 회사식별자
    "SiteID" VARCHAR(50) NOT NULL, -- [KS X 9101 표준] 사업장식별자
    "PlantID" VARCHAR(50) NOT NULL, -- [KS X 9101 표준] 공장식별자
    "CreatorID" VARCHAR(50), -- [KS X 9101 표준] 등록자식별자
    "CreationDateTime" TIMESTAMP, -- [KS X 9101 표준] 등록일시
    "ModifierID" VARCHAR(50), -- [KS X 9101 표준] 수정자식별자
    "ModificationDateTime" TIMESTAMP, -- [KS X 9101 표준] 수정일시
    "Note" VARCHAR(1000), -- [KS X 9101 표준] 비고
    "TransferStartID" VARCHAR(50) NOT NULL, -- [KS X 9101 표준] 운행시작식별자
    "TransferCommandID" VARCHAR(50), -- [KS X 9101 표준] 이동지시식별자
    "LotID" VARCHAR(50), -- [KS X 9101 표준] 로트식별자
    "LotName" VARCHAR(200), -- [KS X 9101 표준] 로트명
    "LotDescription" VARCHAR(1000), -- [KS X 9101 표준] 로트설명
    "CarrierID" VARCHAR(50), -- [KS X 9101 표준] 캐리어식별자
    "TransferStartDateTime" TIMESTAMP, -- [KS X 9101 표준] 운행시작일시
    "CurrentLocation" VARCHAR(1000), -- [KS X 9101 표준] 현재위치
    "DestinationID" VARCHAR(50), -- [KS X 9101 표준] 목적지식별자
    "DestinationType" VARCHAR(30), -- [KS X 9101 표준] 목적지유형
    "DestinationName" VARCHAR(200), -- [KS X 9101 표준] 목적지명
    "ErrorCode" VARCHAR(30), -- [KS X 9101 표준] 오류코드
    "ErrorMessage" VARCHAR(1000), -- [KS X 9101 표준] 오류메세지
    CONSTRAINT "PK_TransferStart" PRIMARY KEY ("TransferStartSequenceNo"),
    CONSTRAINT "UK_TransferStart" UNIQUE ("EnterpriseID", "TransferStartID")
);

COMMENT ON TABLE "TransferStart" IS '[KS X 9101 표준] 운행시작 (이동지시 명령을 받아 운행 시작 시 시작 정보를 보고한다.)';
COMMENT ON COLUMN "TransferStart"."TransferStartSequenceNo" IS '[KS X 9101 표준] 운행시작 일련번호: — 테이블 행을 식별하는 일련번호(PK, 대리키) — 표준 외 물리 컬럼
