COMMENT ON COLUMN "TransferStart"."CurrentLocation" IS '[KS X 9101 표준] 현재위치: — 현재 로트가 위치하는 정보';
COMMENT ON COLUMN "TransferStart"."DestinationID" IS '[KS X 9101 표준] 목적지식별자: — 로트가 이동하여 도착할 목적지 정보의 고유값
— OperationID(공정식별자), EquipmentID(설비식별자), StockerInventoryID(저장소재공정보식별자), 그 외 각 공장 특성에 따라 EVENT 처리를 위해 지정한 특정 LocationID
— 참조 대상: 공정(Operation), 설비(Equipment), 저장소재공정보(StockerInventory) 또는 캐리어(Carrier)
— 값이 가리키는 명사는 목적지유형(DestinationType)으로 구분한다';
COMMENT ON COLUMN "TransferStart"."DestinationType" IS '[KS X 9101 표준] 목적지유형: — 로트가 이동하여 도착할 목적지 유형
— 목적지 유형은 설비 포트, 저장소, 캐리어 등을 포함
— 참조 대상: 공통코드정보(CommonCodeMaster)의 코드';
COMMENT ON COLUMN "TransferStart"."DestinationName" IS '[KS X 9101 표준] 목적지명: — 로트가 이동하여 도착할 목적지의 명칭
— 참조 대상: 이동지시(TransferCommand.DestinationName)';
COMMENT ON COLUMN "TransferStart"."ErrorCode" IS '[KS X 9101 표준] 오류코드: — 오류 발생 시 해당 오류 코드 값
— 예: 목적지 포트 점유, 반송 경로 차단, 캐리어 식별자 불일치, 반송 시간 초과 등
— 공통코드그룹은 반송오류코드(TransferErrorCode)로 하고, 코드값은 접두어 ‘TR-’로 시작(예: TR-001)
— 참조 대상: 공통코드정보(CommonCodeMaster)의 코드';
COMMENT ON COLUMN "TransferStart"."ErrorMessage" IS '[KS X 9101 표준] 오류메세지: — 오류 발생 시 해당 메시지';

-- ---------------------------------------------------------------------
-- [표준 구분: KS X 9101 표준] 표 50, 조항 7.4.6.7 | 업무영역: 생산관리
-- 테이블명(물리): "TransferEnd" | 테이블명(논리): 운행완료
-- 설명: 이동지시 명령을 받아 운행 완료 시 완료 정보를 보고한다.
-- ---------------------------------------------------------------------
CREATE TABLE "TransferEnd" ( -- [KS X 9101 표준] 운행완료 (표 50)
    "TransferEndSequenceNo" BIGINT GENERATED BY DEFAULT AS IDENTITY, -- [KS X 9101 표준] 운행완료 일련번호(PK)
    "EnterpriseID" VARCHAR(50) NOT NULL, -- [KS X 9101 표준] 회사식별자
    "SiteID" VARCHAR(50) NOT NULL, -- [KS X 9101 표준] 사업장식별자
    "PlantID" VARCHAR(50) NOT NULL, -- [KS X 9101 표준] 공장식별자
    "CreatorID" VARCHAR(50), -- [KS X 9101 표준] 등록자식별자
    "CreationDateTime" TIMESTAMP, -- [KS X 9101 표준] 등록일시
    "ModifierID" VARCHAR(50), -- [KS X 9101 표준] 수정자식별자
    "ModificationDateTime" TIMESTAMP, -- [KS X 9101 표준] 수정일시
    "Note" VARCHAR(1000), -- [KS X 9101 표준] 비고
    "TransferEndID" VARCHAR(50) NOT NULL, -- [KS X 9101 표준] 운행완료식별자
    "TransferCommandID" VARCHAR(50), -- [KS X 9101 표준] 이동지시식별자
    "LotID" VARCHAR(50), -- [KS X 9101 표준] 로트식별자
    "LotName" VARCHAR(200), -- [KS X 9101 표준] 로트명
    "LotDescription" VARCHAR(1000), -- [KS X 9101 표준] 로트설명
    "CarrierID" VARCHAR(50), -- [KS X 9101 표준] 캐리어식별자
    "TransferEndDateTime" TIMESTAMP, -- [KS X 9101 표준] 운행완료일시
    "DestinationID" VARCHAR(50), -- [KS X 9101 표준] 목적지식별자
    "DestinationType" VARCHAR(30), -- [KS X 9101 표준] 목적지유형
    "DestinationName" VARCHAR(200), -- [KS X 9101 표준] 목적지명
    CONSTRAINT "PK_TransferEnd" PRIMARY KEY ("TransferEndSequenceNo"),
    CONSTRAINT "UK_TransferEnd" UNIQUE ("EnterpriseID", "TransferEndID")
);

COMMENT ON TABLE "TransferEnd" IS '[KS X 9101 표준] 운행완료 (이동지시 명령을 받아 운행 완료 시 완료 정보를 보고한다.)';
COMMENT ON COLUMN "TransferEnd"."TransferEndSequenceNo" IS '[KS X 9101 표준] 운행완료 일련번호: — 테이블 행을 식별하는 일련번호(PK, 대리키) — 표준 외 물리 컬럼
— 자동 증가 값(IDENTITY)으로 부여하며 다른 테이블이 참조하지 않음(FK는 UK 참조)';
COMMENT ON COLUMN "TransferEnd"."EnterpriseID" IS '[KS X 9101 표준] 회사식별자: — 회사를 유일하게 구분할 수 있는 고유식별값
— 기업업무시스템 간의 연동을 수행하는 회사들 간에 자체적으로 정의한 고유식별값
— 참조 대상: 회사(Enterprise)';
COMMENT ON COLUMN "TransferEnd"."SiteID" IS '[KS X 9101 표준] 사업장식별자: — 회사 내에서 사업장을 구분할수 있는 고유식별값
— 참조 대상: 사업장(Site)';
COMMENT ON COLUMN "TransferEnd"."PlantID" IS '[KS X 9101 표준] 공장식별자: — 회사 내에서 공장을 구분할 수있는 고유식별값(만약, 공장 개념을 사용하지 않는다면 고정식별자로 설정하여 입력해야 함)
— 참조 대상: 공장(Plant)';
COMMENT ON COLUMN "TransferEnd"."CreatorID" IS '[KS X 9101 표준] 등록자식별자: — 정보를 처음으로 등록한 사람을 구분할 수 있는 고유식별값으로, 일반적으로 사원번호가사용됨
— 참조 대상: 사원(Personnel)';
COMMENT ON COLUMN "TransferEnd"."CreationDateTime" IS '[KS X 9101 표준] 등록일시: — 정보를 처음으로 등록한 날짜 (KS X ISO 8601을 따른다)';
COMMENT ON COLUMN "TransferEnd"."ModifierID" IS '[KS X 9101 표준] 수정자식별자: — 정보를 마지막으로 수정한 사람을 구분할 수 있는 고유식별값으로, 일반적으로 사원번호가 사용됨
— 참조 대상: 사원(Personnel)';
COMMENT ON COLUMN "TransferEnd"."ModificationDateTime" IS '[KS X 9101 표준] 수정일시: — 정보를 마지막으로 수정한 날짜 (KS X ISO 8601을 따른다.)';
COMMENT ON COLUMN "TransferEnd"."Note" IS '[KS X 9101 표준] 비고: — 비고사항';
COMMENT ON COLUMN "TransferEnd"."TransferEndID" IS '[KS X 9101 표준] 운행완료식별자: — 운행완료를 식별하기 위한 고유값
— 이벤트를 최초로 발생시킨 시스템이 GUID 형식으로 부여하며, BOD로 최초 송신한 경우 해당 BOD의 BODID를 식별자로 사용할 수 있음(7.1)';
COMMENT ON COLUMN "TransferEnd"."TransferCommandID" IS '[KS X 9101 표준] 이동지시식별자: — 이동 유형에 따른 이동지시를 식별하기 위한 고유값
— 참조 대상: 이동지시(TransferCommand)';
COMMENT ON COLUMN "TransferEnd"."LotID" IS '[KS X 9101 표준] 로트식별자: — 로트를 식별하기 위한 고유값
— 참조 대상: 로트(Lot)';
COMMENT ON COLUMN "TransferEnd"."LotName" IS '[KS X 9101 표준] 로트명: — 로트 명칭
— 참조 대상: 로트(Lot.LotName)';
COMMENT ON COLUMN "TransferEnd"."LotDescription" IS '[KS X 9101 표준] 로트설명: — 로트 설명 정보
— 참조 대상: 로트(Lot.LotDescription)';
COMMENT ON COLUMN "TransferEnd"."CarrierID" IS '[KS X 9101 표준] 캐리어식별자: — 캐리어를 식별하기 위한 고유값
— 참조 대상: 캐리어(Carrier)';
COMMENT ON COLUMN "TransferEnd"."TransferEndDateTime" IS '[KS X 9101 표준] 운행완료일시: — 운행을 완료한 일시(KS X ISO 8601을 따른다)';
COMMENT ON COLUMN "TransferEnd"."DestinationID" IS '[KS X 9101 표준] 목적지식별자: — 로트가 이동하여 도착할 목적지 정보의 고유값
— OperationID(공정식별자), EquipmentID(설비식별자), StockerInventoryID(저장소재공정보식별자), 그 외 각 공장 특성에 따라 EVENT 처리를 위해 지정한 특정 LocationID
— 참조 대상: 공정(Operation), 설비(Equipment), 저장소재공정보(StockerInventory) 또는 캐리어(Carrier)
— 값이 가리키는 명사는 목적지유형(DestinationType)으로 구분한다';
COMMENT ON COLUMN "TransferEnd"."DestinationType" IS '[KS X 9101 표준] 목적지유형: — 로트가 이동하여 도착할 목적지 유형
— 목적지 유형은 설비 포트, 저장소, 캐리어 등을 포함
— 참조 대상: 공통코드정보(CommonCodeMaster)의 코드';
COMMENT ON COLUMN "TransferEnd"."DestinationName" IS '[KS X 9101 표준] 목적지명: — 로트가 이동하여 도착할 목적지의 명칭
— 참조 대상: 이동지시(TransferCommand.DestinationName)';

-- ---------------------------------------------------------------------
-- [표준 구분: KS X 9101 표준] 표 51, 조항 7.4.6.8 | 업무영역: 생산관리
-- 테이블명(물리): "InTransitLocation" | 테이블명(논리): 운송위치
-- 설명: 이동 중 현재 운송 위치 정보를 보고한다.
-- ---------------------------------------------------------------------
CREATE TABLE "InTransitLocation" ( -- [KS X 9101 표준] 운송위치 (표 51)
    "InTransitLocationSequenceNo" BIGINT GENERATED BY DEFAULT AS IDENTITY, -- [KS X 9101 표준] 운송위치 일련번호(PK)
