COMMENT ON COLUMN "InTransitLocation"."CreationDateTime" IS '[KS X 9101 표준] 등록일시: — 정보를 처음으로 등록한 날짜 (KS X ISO 8601을 따른다)';
COMMENT ON COLUMN "InTransitLocation"."ModifierID" IS '[KS X 9101 표준] 수정자식별자: — 정보를 마지막으로 수정한 사람을 구분할 수 있는 고유식별값으로, 일반적으로 사원번호가 사용됨
— 참조 대상: 사원(Personnel)';
COMMENT ON COLUMN "InTransitLocation"."ModificationDateTime" IS '[KS X 9101 표준] 수정일시: — 정보를 마지막으로 수정한 날짜 (KS X ISO 8601을 따른다.)';
COMMENT ON COLUMN "InTransitLocation"."Note" IS '[KS X 9101 표준] 비고: — 비고사항';
COMMENT ON COLUMN "InTransitLocation"."InTransitLocationID" IS '[KS X 9101 표준] 운송위치식별자: — 운송위치를 식별하기 위한 고유값
— 이벤트를 최초로 발생시킨 시스템이 GUID 형식으로 부여하며, BOD로 최초 송신한 경우 해당 BOD의 BODID를 식별자로 사용할 수 있음(7.1)';
