    "EquipmentStateSequenceNo" BIGINT GENERATED BY DEFAULT AS IDENTITY, -- [KS X 9101 표준] 설비상태 일련번호(PK)
    "EnterpriseID" VARCHAR(50) NOT NULL, -- [KS X 9101 표준] 회사식별자
