    "PlantID" VARCHAR(50) NOT NULL, -- [KS X 9101 표준] 공장식별자
    "CreatorID" VARCHAR(50), -- [KS X 9101 표준] 등록자식별자
    "CreationDateTime" TIMESTAMP, -- [KS X 9101 표준] 등록일시
    "ModifierID" VARCHAR(50), -- [KS X 9101 표준] 수정자식별자
    "ModificationDateTime" TIMESTAMP, -- [KS X 9101 표준] 수정일시
    "Note" VARCHAR(1000), -- [KS X 9101 표준] 비고
    "EquipmentStateID" VARCHAR(50) NOT NULL, -- [KS X 9101 표준] 설비상태식별자
    "EquipmentID" VARCHAR(50), -- [KS X 9101 표준] 설비식별자
    "EquipmentState" VARCHAR(30), -- [KS X 9101 표준] 설비상태
    "EquipmentControlMode" VARCHAR(30), -- [KS X 9101 표준] 설비제어모드
    "EquipmentOperationMode" VARCHAR(30), -- [KS X 9101 표준] 설비운영모드
    "ProcessedLotQuantity" NUMERIC(18,6), -- [KS X 9101 표준] 진행로트수량
    "LastProcessedLotID" VARCHAR(50), -- [KS X 9101 표준] 최종진행로트식별자
    "LastProcessedOperationID" VARCHAR(50), -- [KS X 9101 표준] 최종진행공정식별자
    "ErrorCode" VARCHAR(30), -- [KS X 9101 표준] 오류코드
    "ErrorMessage" VARCHAR(1000), -- [KS X 9101 표준] 오류메세지
    CONSTRAINT "PK_EquipmentState" PRIMARY KEY ("EquipmentStateSequenceNo"),
    CONSTRAINT "UK_EquipmentState" UNIQUE ("EnterpriseID", "EquipmentStateID")
);

COMMENT ON TABLE "EquipmentState" IS '[KS X 9101 표준] 설비상태 (설비의 상태가 변경될 시 상태 정보를 보고한다.)';
COMMENT ON COLUMN "EquipmentState"."EquipmentStateSequenceNo" IS '[KS X 9101 표준] 설비상태 일련번호: — 테이블 행을 식별하는 일련번호(PK, 대리키) — 표준 외 물리 컬럼
— 자동 증가 값(IDENTITY)으로 부여하며 다른 테이블이 참조하지 않음(FK는 UK 참조)';
COMMENT ON COLUMN "EquipmentState"."EnterpriseID" IS '[KS X 9101 표준] 회사식별자: — 회사를 유일하게 구분할 수 있는 고유식별값
— 기업업무시스템 간의 연동을 수행하는 회사들 간에 자체적으로 정의한 고유식별값
— 참조 대상: 회사(Enterprise)';
COMMENT ON COLUMN "EquipmentState"."SiteID" IS '[KS X 9101 표준] 사업장식별자: — 회사 내에서 사업장을 구분할수 있는 고유식별값
— 참조 대상: 사업장(Site)';
COMMENT ON COLUMN "EquipmentState"."PlantID" IS '[KS X 9101 표준] 공장식별자: — 회사 내에서 공장을 구분할 수있는 고유식별값(만약, 공장 개념을 사용하지 않는다면 고정식별자로 설정하여 입력해야 함)
— 참조 대상: 공장(Plant)';
COMMENT ON COLUMN "EquipmentState"."CreatorID" IS '[KS X 9101 표준] 등록자식별자: — 정보를 처음으로 등록한 사람을 구분할 수 있는 고유식별값으로, 일반적으로 사원번호가사용됨
— 참조 대상: 사원(Personnel)';
COMMENT ON COLUMN "EquipmentState"."CreationDateTime" IS '[KS X 9101 표준] 등록일시: — 정보를 처음으로 등록한 날짜 (KS X ISO 8601을 따른다)';
COMMENT ON COLUMN "EquipmentState"."ModifierID" IS '[KS X 9101 표준] 수정자식별자: — 정보를 마지막으로 수정한 사람을 구분할 수 있는 고유식별값으로, 일반적으로 사원번호가 사용됨
— 참조 대상: 사원(Personnel)';
COMMENT ON COLUMN "EquipmentState"."ModificationDateTime" IS '[KS X 9101 표준] 수정일시: — 정보를 마지막으로 수정한 날짜 (KS X ISO 8601을 따른다.)';
COMMENT ON COLUMN "EquipmentState"."Note" IS '[KS X 9101 표준] 비고: — 비고사항';
COMMENT ON COLUMN "EquipmentState"."EquipmentStateID" IS '[KS X 9101 표준] 설비상태식별자: — 설비상태를 식별하기 위한 고유값
— 이벤트를 최초로 발생시킨 시스템이 GUID 형식으로 부여하며, BOD로 최초 송신한 경우 해당 BOD의 BODID를 식별자로 사용할 수 있음(7.1)';
COMMENT ON COLUMN "EquipmentState"."EquipmentID" IS '[KS X 9101 표준] 설비식별자: — 설비를 식별하기 위한 고유값
— 참조 대상: 설비(Equipment)';
COMMENT ON COLUMN "EquipmentState"."EquipmentState" IS '[KS X 9101 표준] 설비상태: — 설비 상태 값(예: Run, Idle, Down)
— 참조 대상: 공통코드정보(CommonCodeMaster)의 코드';
COMMENT ON COLUMN "EquipmentState"."EquipmentControlMode" IS '[KS X 9101 표준] 설비제어모드: — 설비 제어모드 값(예: Online, Local, Offline)
— 참조 대상: 공통코드정보(CommonCodeMaster)의 코드';
COMMENT ON COLUMN "EquipmentState"."EquipmentOperationMode" IS '[KS X 9101 표준] 설비운영모드: — 설비 운영모드 값(예: Full-Auto, Semi-Auto, Manual)
— 참조 대상: 공통코드정보(CommonCodeMaster)의 코드';
COMMENT ON COLUMN "EquipmentState"."ProcessedLotQuantity" IS '[KS X 9101 표준] 진행로트수량: — 생산이 진행된 로트 수량';
COMMENT ON COLUMN "EquipmentState"."LastProcessedLotID" IS '[KS X 9101 표준] 최종진행로트식별자: — 마지막 진행된 로트를 식별하기 위한 고유값
— 참조 대상: 로트(Lot)';
COMMENT ON COLUMN "EquipmentState"."LastProcessedOperationID" IS '[KS X 9101 표준] 최종진행공정식별자: — 마지막 진행된 공정을 식별하기 위한 고유값
— 참조 대상: 공정(Operation)';
COMMENT ON COLUMN "EquipmentState"."ErrorCode" IS '[KS X 9101 표준] 오류코드: — 오류 발생 시 해당 오류 코드 값
— 예: 비상정지, 과부하, 온도 이상, 압력 이상, 통신 이상, 공구 마모·파손 등(설비 제작사 오류코드 체계 사용 가능)
— 공통코드그룹은 설비오류코드(EquipmentErrorCode)로 하고, 코드값은 접두어 ‘EQ-’로 시작(예: EQ-001)
— 참조 대상: 공통코드정보(CommonCodeMaster)의 코드';
COMMENT ON COLUMN "EquipmentState"."ErrorMessage" IS '[KS X 9101 표준] 오류메세지: — 알람 발생 시 오류 설명 정보';

-- ---------------------------------------------------------------------
-- [표준 구분: KS X 9101 표준] 표 53, 조항 7.4.6.10 | 업무영역: 생산관리
-- 테이블명(물리): "Alarm" | 테이블명(논리): 알람
-- 설명: 설비에서 발생하는 알람 정보를 의미한다.
-- ---------------------------------------------------------------------
CREATE TABLE "Alarm" ( -- [KS X 9101 표준] 알람 (표 53)
    "AlarmSequenceNo" BIGINT GENERATED BY DEFAULT AS IDENTITY, -- [KS X 9101 표준] 알람 일련번호(PK)
    "EnterpriseID" VARCHAR(50) NOT NULL, -- [KS X 9101 표준] 회사식별자
    "SiteID" VARCHAR(50) NOT NULL, -- [KS X 9101 표준] 사업장식별자
    "PlantID" VARCHAR(50) NOT NULL, -- [KS X 9101 표준] 공장식별자
    "CreatorID" VARCHAR(50), -- [KS X 9101 표준] 등록자식별자
    "CreationDateTime" TIMESTAMP, -- [KS X 9101 표준] 등록일시
    "ModifierID" VARCHAR(50), -- [KS X 9101 표준] 수정자식별자
    "ModificationDateTime" TIMESTAMP, -- [KS X 9101 표준] 수정일시
    "Note" VARCHAR(1000), -- [KS X 9101 표준] 비고
    "AlarmID" VARCHAR(50) NOT NULL, -- [KS X 9101 표준] 알람식별자
    "EquipmentID" VARCHAR(50), -- [KS X 9101 표준] 설비식별자
    "AlarmState" VARCHAR(30), -- [KS X 9101 표준] 알람상태
    "ErrorCode" VARCHAR(30), -- [KS X 9101 표준] 오류코드
    "ErrorMessage" VARCHAR(1000), -- [KS X 9101 표준] 오류메세지
    "EventDateTime" TIMESTAMP, -- [KS X 9101 표준] 이벤트발생일시
    "CurrentLocation" VARCHAR(1000), -- [KS X 9101 표준] 현재위치
    CONSTRAINT "PK_Alarm" PRIMARY KEY ("AlarmSequenceNo"),
    CONSTRAINT "UK_Alarm" UNIQUE ("EnterpriseID", "AlarmID")
);

COMMENT ON TABLE "Alarm" IS '[KS X 9101 표준] 알람 (설비에서 발생하는 알람 정보를 의미한다.)';
COMMENT ON COLUMN "Alarm"."AlarmSequenceNo" IS '[KS X 9101 표준] 알람 일련번호: — 테이블 행을 식별하는 일련번호(PK, 대리키) — 표준 외 물리 컬럼
— 자동 증가 값(IDENTITY)으로 부여하며 다른 테이블이 참조하지 않음(FK는 UK 참조)';
COMMENT ON COLUMN "Alarm"."EnterpriseID" IS '[KS X 9101 표준] 회사식별자: — 회사를 유일하게 구분할 수 있는 고유식별값
— 기업업무시스템 간의 연동을 수행하는 회사들 간에 자체적으로 정의한 고유식별값
— 참조 대상: 회사(Enterprise)';
COMMENT ON COLUMN "Alarm"."SiteID" IS '[KS X 9101 표준] 사업장식별자: — 회사 내에서 사업장을 구분할수 있는 고유식별값
— 참조 대상: 사업장(Site)';
COMMENT ON COLUMN "Alarm"."PlantID" IS '[KS X 9101 표준] 공장식별자: — 회사 내에서 공장을 구분할 수있는 고유식별값(만약, 공장 개념을 사용하지 않는다면 고정식별자로 설정하여 입력해야 함)
— 참조 대상: 공장(Plant)';
COMMENT ON COLUMN "Alarm"."CreatorID" IS '[KS X 9101 표준] 등록자식별자: — 정보를 처음으로 등록한 사람을 구분할 수 있는 고유식별값으로, 일반적으로 사원번호가사용됨
— 참조 대상: 사원(Personnel)';
COMMENT ON COLUMN "Alarm"."CreationDateTime" IS '[KS X 9101 표준] 등록일시: — 정보를 처음으로 등록한 날짜 (KS X ISO 8601을 따른다)';
COMMENT ON COLUMN "Alarm"."ModifierID" IS '[KS X 9101 표준] 수정자식별자: — 정보를 마지막으로 수정한 사람을 구분할 수 있는 고유식별값으로, 일반적으로 사원번호가 사용됨
— 참조 대상: 사원(Personnel)';
COMMENT ON COLUMN "Alarm"."ModificationDateTime" IS '[KS X 9101 표준] 수정일시: — 정보를 마지막으로 수정한 날짜 (KS X ISO 8601을 따른다.)';
COMMENT ON COLUMN "Alarm"."Note" IS '[KS X 9101 표준] 비고: — 비고사항';
COMMENT ON COLUMN "Alarm"."AlarmID" IS '[KS X 9101 표준] 알람식별자: — 알람을 식별하기 위한 고유값
— 이벤트를 최초로 발생시킨 시스템이 GUID 형식으로 부여하며, BOD로 최초 송신한 경우 해당 BOD의 BODID를 식별자로 사용할 수 있음(7.1)';
COMMENT ON COLUMN "Alarm"."EquipmentID" IS '[KS X 9101 표준] 설비식별자: — 설비를 식별하기 위한 고유값
— 참조 대상: 설비(Equipment)';
COMMENT ON COLUMN "Alarm"."AlarmState" IS '[KS X 9101 표준] 알람상태: — 알람상태(예: Alarm, No Alarm, Maintenance, Normal)
— 참조 대상: 공통코드정보(CommonCodeMaster)의 코드';
COMMENT ON COLUMN "Alarm"."ErrorCode" IS '[KS X 9101 표준] 오류코드: — 오류 발생 시 해당 오류 코드 값
— 예: 비상정지, 과부하, 온도 이상, 압력 이상, 통신 이상, 공구 마모·파손 등(설비 제작사 오류코드 체계 사용 가능)
— 공통코드그룹은 설비오류코드(EquipmentErrorCode)로 하고, 코드값은 접두어 ‘EQ-’로 시작(예: EQ-001)
— 참조 대상: 공통코드정보(CommonCodeMaster)의 코드';
COMMENT ON COLUMN "Alarm"."ErrorMessage" IS '[KS X 9101 표준] 오류메세지: — 알람 발생 시 오류 설명 정보';
COMMENT ON COLUMN "Alarm"."EventDateTime" IS '[KS X 9101 표준] 이벤트발생일시: — 알람 발생 일시(KS X ISO 8601을 따른다)';
COMMENT ON COLUMN "Alarm"."CurrentLocation" IS '[KS X 9101 표준] 현재위치: — 현재 설비의 위치정보(예: EquipmentID(설비식별자), StockerInventoryID(저장소재공정보식별자), CarrierID(캐리어식별자))';

-- ---------------------------------------------------------------------
-- [표준 구분: KS X 9101 표준] 표 54, 조항 7.4.6.11 | 업무영역: 생산관리
-- 테이블명(물리): "SupplierInspectionPlan" | 테이블명(논리): 협력업체품질검사계획
-- 설명: 수주산업에서 프로젝트성으로 추진하고 있는 협력업체 발주품에 대해 발주처 및 협력업체 품질부서에서 품질검사를 하기 위한 일정 계획을 의미한다.
-- ---------------------------------------------------------------------
CREATE TABLE "SupplierInspectionPlan" ( -- [KS X 9101 표준] 협력업체품질검사계획 (표 54)
    "SupplierInspectionPlanSequenceNo" BIGINT GENERATED BY DEFAULT AS IDENTITY, -- [KS X 9101 표준] 협력업체품질검사계획 일련번호(PK)
    "EnterpriseID" VARCHAR(50) NOT NULL, -- [KS X 9101 표준] 회사식별자
    "SiteID" VARCHAR(50) NOT NULL, -- [KS X 9101 표준] 사업장식별자
    "PlantID" VARCHAR(50) NOT NULL, -- [KS X 9101 표준] 공장식별자
    "CreatorID" VARCHAR(50), -- [KS X 9101 표준] 등록자식별자
    "CreationDateTime" TIMESTAMP, -- [KS X 9101 표준] 등록일시
    "ModifierID" VARCHAR(50), -- [KS X 9101 표준] 수정자식별자
    "ModificationDateTime" TIMESTAMP, -- [KS X 9101 표준] 수정일시
    "Note" VARCHAR(1000), -- [KS X 9101 표준] 비고
    "VendorID" VARCHAR(50), -- [KS X 9101 표준] 공급사식별자
    "ProjectID" VARCHAR(50), -- [KS X 9101 표준] 프로젝트식별자
    "ItemID" VARCHAR(50), -- [KS X 9101 표준] 품목식별자
    "ItemName" VARCHAR(200), -- [KS X 9101 표준] 품목명
    "ItemUOMCode" VARCHAR(20), -- [KS X 9101 표준] 기준단위코드
    "PurchaseDocumentNumber" VARCHAR(50), -- [KS X 9101 표준] 구매문서번호
    "PurchaseDocumentSequence" INTEGER, -- [KS X 9101 표준] 구매문서순번
    "PurchaseOrderQuantity" NUMERIC(18,6), -- [KS X 9101 표준] 구매발주수량
    "LotID" VARCHAR(50), -- [KS X 9101 표준] 로트식별자
    "BatchID" VARCHAR(50), -- [KS X 9101 표준] 배치식별자
    "ExpectedDeliveryDate" DATE, -- [KS X 9101 표준] 납기예정일
    "InspectionPlanID" VARCHAR(50) NOT NULL, -- [KS X 9101 표준] 검사계획식별자
    "InspectionID" VARCHAR(50) NOT NULL, -- [KS X 9101 표준] 검사식별자
    "InspectionName" VARCHAR(200), -- [KS X 9101 표준] 검사명
    "Inspector" VARCHAR(255), -- [KS X 9101 표준] 검사자
    "InspectionLocation" VARCHAR(1000), -- [KS X 9101 표준] 검사위치
    "ExpectedInspectionDate" DATE, -- [KS X 9101 표준] 검사예정일
    "ExpectedInspectionTimePeriod" INTEGER, -- [KS X 9101 표준] 검사예정기간
    "InspectionMethod" VARCHAR(30), -- [KS X 9101 표준] 검사방법
    "InspectionPlanQuantity" NUMERIC(18,6), -- [KS X 9101 표준] 검사계획수량
    "InspectionCheckSheet" VARCHAR(1000), -- [KS X 9101 표준] 검사체크시트
    CONSTRAINT "PK_SupplierInspectionPlan" PRIMARY KEY ("SupplierInspectionPlanSequenceNo"),
    CONSTRAINT "UK_SupplierInspectionPlan" UNIQUE ("EnterpriseID", "InspectionPlanID", "InspectionID")
);

COMMENT ON TABLE "SupplierInspectionPlan" IS '[KS X 9101 표준] 협력업체품질검사계획 (수주산업에서 프로젝트성으로 추진하고 있는 협력업체 발주품에 대해 발주처 및 협력업체 품질부서에서 품질검사를 하기 위한 일정 계획을 의미한다.)';
COMMENT ON COLUMN "SupplierInspectionPlan"."SupplierInspectionPlanSequenceNo" IS '[KS X 9101 표준] 협력업체품질검사계획 일련번호: — 테이블 행을 식별하는 일련번호(PK, 대리키) — 표준 외 물리 컬럼
— 자동 증가 값(IDENTITY)으로 부여하며 다른 테이블이 참조하지 않음(FK는 UK 참조)';
COMMENT ON COLUMN "SupplierInspectionPlan"."EnterpriseID" IS '[KS X 9101 표준] 회사식별자: — 회사를 유일하게 구분할 수 있는 고유식별값
— 기업업무시스템 간의 연동을 수행하는 회사들 간에 자체적으로 정의한 고유식별값
— 참조 대상: 회사(Enterprise)';
COMMENT ON COLUMN "SupplierInspectionPlan"."SiteID" IS '[KS X 9101 표준] 사업장식별자: — 회사 내에서 사업장을 구분할수 있는 고유식별값
— 참조 대상: 사업장(Site)';
COMMENT ON COLUMN "SupplierInspectionPlan"."PlantID" IS '[KS X 9101 표준] 공장식별자: — 회사 내에서 공장을 구분할 수있는 고유식별값(만약, 공장 개념을 사용하지 않는다면 고정식별자로 설정하여 입력해야 함)
— 참조 대상: 공장(Plant)';
COMMENT ON COLUMN "SupplierInspectionPlan"."CreatorID" IS '[KS X 9101 표준] 등록자식별자: — 정보를 처음으로 등록한 사람을 구분할 수 있는 고유식별값으로, 일반적으로 사원번호가사용됨
— 참조 대상: 사원(Personnel)';
COMMENT ON COLUMN "SupplierInspectionPlan"."CreationDateTime" IS '[KS X 9101 표준] 등록일시: — 정보를 처음으로 등록한 날짜 (KS X ISO 8601을 따른다)';
COMMENT ON COLUMN "SupplierInspectionPlan"."ModifierID" IS '[KS X 9101 표준] 수정자식별자: — 정보를 마지막으로 수정한 사람을 구분할 수 있는 고유식별값으로, 일반적으로 사원번호가 사용됨
— 참조 대상: 사원(Personnel)';
COMMENT ON COLUMN "SupplierInspectionPlan"."ModificationDateTime" IS '[KS X 9101 표준] 수정일시: — 정보를 마지막으로 수정한 날짜 (KS X ISO 8601을 따른다.)';
COMMENT ON COLUMN "SupplierInspectionPlan"."Note" IS '[KS X 9101 표준] 비고: — 비고사항';
COMMENT ON COLUMN "SupplierInspectionPlan"."VendorID" IS '[KS X 9101 표준] 공급사식별자: — 품목을 구입해오는 거래처를 식별하기 위한 고유값
— 참조 대상: 공급사(VendorPartyMaster)';
COMMENT ON COLUMN "SupplierInspectionPlan"."ProjectID" IS '[KS X 9101 표준] 프로젝트식별자: — 프로젝트를 식별하기 위한 고유값
— 참조 대상: 프로젝트마스터(ProjectMaster)';
COMMENT ON COLUMN "SupplierInspectionPlan"."ItemID" IS '[KS X 9101 표준] 품목식별자: — 품목을 식별하기 위한 고유값
— 제품, 반제품, 상품, 원자재, 부자재, 저장품, 소모품 등 회사내 시스템으로 관리되는 모든 품목을 포함
— 참조 대상: 품목마스터(ItemMaster)';
COMMENT ON COLUMN "SupplierInspectionPlan"."ItemName" IS '[KS X 9101 표준] 품목명: — 품목의 명칭
— 참조 대상: 품목마스터(ItemMaster.ItemName)';
COMMENT ON COLUMN "SupplierInspectionPlan"."ItemUOMCode" IS '[KS X 9101 표준] 기준단위코드: — 기준단위코드(예: EA, DZ, HD 등)
— 참조 대상: 단위그룹(UOMGroup)의 단위코드';
COMMENT ON COLUMN "SupplierInspectionPlan"."PurchaseDocumentNumber" IS '[KS X 9101 표준] 구매문서번호: — 구매문서번호
— 구매문서순번(PurchaseDocumentSequence)과 함께 사용한다
— 참조 대상: 구매발주(PurchaseOrder)';
COMMENT ON COLUMN "SupplierInspectionPlan"."PurchaseDocumentSequence" IS '[KS X 9101 표준] 구매문서순번: — 구매문서순번
— 구매문서번호(PurchaseDocumentNumber)와 함께 구매발주(PurchaseOrder)를 참조한다';
COMMENT ON COLUMN "SupplierInspectionPlan"."PurchaseOrderQuantity" IS '[KS X 9101 표준] 구매발주수량: — 구매발주수량(수량의 단위는 기준단위코드로 함)
— 참조 대상: 구매발주(PurchaseOrder.PurchaseOrderQuantity)';
COMMENT ON COLUMN "SupplierInspectionPlan"."LotID" IS '[KS X 9101 표준] 로트식별자: — 품질검사계획에 포함된 로트의 고유식별값
— 참조 대상: 로트(Lot)';
COMMENT ON COLUMN "SupplierInspectionPlan"."BatchID" IS '[KS X 9101 표준] 배치식별자: — 품질검사계획에 포함된 배치의 고유식별값
— 참조 대상: 배치(Batch)';
COMMENT ON COLUMN "SupplierInspectionPlan"."ExpectedDeliveryDate" IS '[KS X 9101 표준] 납기예정일: — 자재의 납기 예정일자(KS X ISO 8601을 따른다)
— 참조 대상: 구매발주(PurchaseOrder.ExpectedDeliveryDate)';
COMMENT ON COLUMN "SupplierInspectionPlan"."InspectionPlanID" IS '[KS X 9101 표준] 검사계획식별자: — 검사계획을 식별하기 위한 고유값';
COMMENT ON COLUMN "SupplierInspectionPlan"."InspectionID" IS '[KS X 9101 표준] 검사식별자: — 검사를 식별하기 위한 고유값
— 검사식별자(InspectionID)는 협력업체품질계획수립 시 신규 생성하며, 검사계획과 검사항목은 1:N의 관계
— 검사계획식별자(InspectionPlanID) 와 검사식별자(InspectionID) 두 속성의 조합이 식별자';
COMMENT ON COLUMN "SupplierInspectionPlan"."InspectionName" IS '[KS X 9101 표준] 검사명: — 검사의 명칭';
COMMENT ON COLUMN "SupplierInspectionPlan"."Inspector" IS '[KS X 9101 표준] 검사자: — 검사계획에 따라 배정된 검사원';
COMMENT ON COLUMN "SupplierInspectionPlan"."InspectionLocation" IS '[KS X 9101 표준] 검사위치: — 검사를 진행하는 위치(장소)';
COMMENT ON COLUMN "SupplierInspectionPlan"."ExpectedInspectionDate" IS '[KS X 9101 표준] 검사예정일: — 검사가 진행될 예정일자(KS X ISO 8601을 따른다)';
COMMENT ON COLUMN "SupplierInspectionPlan"."ExpectedInspectionTimePeriod" IS '[KS X 9101 표준] 검사예정기간: — 검사시작일과 검사종료일 사이의 예정일 수';
COMMENT ON COLUMN "SupplierInspectionPlan"."InspectionMethod" IS '[KS X 9101 표준] 검사방법: — 검사의 방법(예: 육안검사, 비파괴검사, 치수검사 등)
— 참조 대상: 공통코드정보(CommonCodeMaster)의 코드';
COMMENT ON COLUMN "SupplierInspectionPlan"."InspectionPlanQuantity" IS '[KS X 9101 표준] 검사계획수량: — 검사 대상이 되는 검사계획수량';
COMMENT ON COLUMN "SupplierInspectionPlan"."InspectionCheckSheet" IS '[KS X 9101 표준] 검사체크시트: — 발주처에서 정한 품질 수준을 점검하기 위한 프로젝트, 검사방법, 점검내용 등 온라인 문서의 URI(Uniform Resource Identifier)';

-- ---------------------------------------------------------------------
-- [표준 구분: KS X 9101 표준] 표 55, 조항 7.4.6.12 | 업무영역: 생산관리
-- 테이블명(물리): "SupplierInspectionApplication" | 테이블명(논리): 협력업체품질검사신청
-- 설명: 품질검사계획에 따라 협력업체에 품질검사를 신청하는 것을 의미한다.
-- ---------------------------------------------------------------------
CREATE TABLE "SupplierInspectionApplication" ( -- [KS X 9101 표준] 협력업체품질검사신청 (표 55)
    "SupplierInspectionApplicationSequenceNo" BIGINT GENERATED BY DEFAULT AS IDENTITY, -- [KS X 9101 표준] 협력업체품질검사신청 일련번호(PK)
    "EnterpriseID" VARCHAR(50) NOT NULL, -- [KS X 9101 표준] 회사식별자
    "SiteID" VARCHAR(50) NOT NULL, -- [KS X 9101 표준] 사업장식별자
    "PlantID" VARCHAR(50) NOT NULL, -- [KS X 9101 표준] 공장식별자
    "CreatorID" VARCHAR(50), -- [KS X 9101 표준] 등록자식별자
    "CreationDateTime" TIMESTAMP, -- [KS X 9101 표준] 등록일시
    "ModifierID" VARCHAR(50), -- [KS X 9101 표준] 수정자식별자
    "ModificationDateTime" TIMESTAMP, -- [KS X 9101 표준] 수정일시
    "Note" VARCHAR(1000), -- [KS X 9101 표준] 비고
    "VendorID" VARCHAR(50), -- [KS X 9101 표준] 공급사식별자
    "ProjectID" VARCHAR(50), -- [KS X 9101 표준] 프로젝트식별자
    "ItemID" VARCHAR(50), -- [KS X 9101 표준] 품목식별자
    "ItemName" VARCHAR(200), -- [KS X 9101 표준] 품목명
    "ItemUOMCode" VARCHAR(20), -- [KS X 9101 표준] 기준단위코드
    "PurchaseDocumentNumber" VARCHAR(50), -- [KS X 9101 표준] 구매문서번호
    "PurchaseDocumentSequence" INTEGER, -- [KS X 9101 표준] 구매문서순번
    "LotID" VARCHAR(50), -- [KS X 9101 표준] 로트식별자
    "BatchID" VARCHAR(50), -- [KS X 9101 표준] 배치식별자
    "InspectionPlanID" VARCHAR(50), -- [KS X 9101 표준] 검사계획식별자
    "InspectionID" VARCHAR(50), -- [KS X 9101 표준] 검사식별자
    "InspectionApplicationID" VARCHAR(50) NOT NULL, -- [KS X 9101 표준] 검사신청식별자
    "ApplicationPersonnelID" VARCHAR(50), -- [KS X 9101 표준] 검사신청자
    "InspectionName" VARCHAR(200), -- [KS X 9101 표준] 검사명
    "InspectionLocation" VARCHAR(1000), -- [KS X 9101 표준] 검사위치
    "InspectionMethod" VARCHAR(30), -- [KS X 9101 표준] 검사방법
    "ExpectedInspectionDate" DATE, -- [KS X 9101 표준] 검사예정일
    "InspectionDate" DATE, -- [KS X 9101 표준] 검사일
    "InspectionTimePeriod" INTEGER, -- [KS X 9101 표준] 검사기간
    "InspectionQuantity" NUMERIC(18,6), -- [KS X 9101 표준] 검사수량
    "SelfCheckInspectionResultSheet" VARCHAR(1000), -- [KS X 9101 표준] 자체점검결과시트
    "InspectionStatusCode" VARCHAR(30), -- [KS X 9101 표준] 검사상태코드
    "ReasonForApplication" VARCHAR(255), -- [KS X 9101 표준] 검사신청사유
    "InspectionCancelReason" VARCHAR(1000), -- [KS X 9101 표준] 검사취소사유
    CONSTRAINT "PK_SupplierInspectionApplication" PRIMARY KEY ("SupplierInspectionApplicationSequenceNo"),
    CONSTRAINT "UK_SupplierInspectionApplication" UNIQUE ("EnterpriseID", "InspectionApplicationID")
);

COMMENT ON TABLE "SupplierInspectionApplication" IS '[KS X 9101 표준] 협력업체품질검사신청 (품질검사계획에 따라 협력업체에 품질검사를 신청하는 것을 의미한다.)';
COMMENT ON COLUMN "SupplierInspectionApplication"."SupplierInspectionApplicationSequenceNo" IS '[KS X 9101 표준] 협력업체품질검사신청 일련번호: — 테이블 행을 식별하는 일련번호(PK, 대리키) — 표준 외 물리 컬럼
