COMMENT ON COLUMN "SupplierInspectionApplication"."Note" IS '[KS X 9101 표준] 비고: — 비고사항';
COMMENT ON COLUMN "SupplierInspectionApplication"."VendorID" IS '[KS X 9101 표준] 공급사식별자: — 품목을 구입해오는 거래처를 식별하기 위한 고유값
