— 참조 대상: 사원(Personnel)';
COMMENT ON COLUMN "SupplierInspectionApplication"."InspectionName" IS '[KS X 9101 표준] 검사명: — 검사의 명칭
— 참조 대상: 협력업체품질검사계획(SupplierInspectionPlan.InspectionName)';
COMMENT ON COLUMN "SupplierInspectionApplication"."InspectionLocation" IS '[KS X 9101 표준] 검사위치: — 검사를 진행하는 위치(장소)
— 참조 대상: 협력업체품질검사계획(SupplierInspectionPlan.InspectionLocation)';
COMMENT ON COLUMN "SupplierInspectionApplication"."InspectionMethod" IS '[KS X 9101 표준] 검사방법: — 검사의 방법(예: 육안검사, 비파괴검사, 치수검사 등)
— 참조 대상: 공통코드정보(CommonCodeMaster)의 코드';
COMMENT ON COLUMN "SupplierInspectionApplication"."ExpectedInspectionDate" IS '[KS X 9101 표준] 검사예정일: — 검사가 진행될 예정일자(KS X ISO 8601을 따른다)
— 참조 대상: 협력업체품질검사계획(SupplierInspectionPlan.ExpectedInspectionDate)';
COMMENT ON COLUMN "SupplierInspectionApplication"."InspectionDate" IS '[KS X 9101 표준] 검사일: — 검사를 진행한 실제 검사일자(KS X ISO 8601을 따른다)';
COMMENT ON COLUMN "SupplierInspectionApplication"."InspectionTimePeriod" IS '[KS X 9101 표준] 검사기간: — 검사시작일과 검사종료일 사이의 일 수';
COMMENT ON COLUMN "SupplierInspectionApplication"."InspectionQuantity" IS '[KS X 9101 표준] 검사수량: — 검사의 대상이 되는 자재의 수량';
COMMENT ON COLUMN "SupplierInspectionApplication"."SelfCheckInspectionResultSheet" IS '[KS X 9101 표준] 자체점검결과시트: — 공급사에서 자체적으로 진행한 체크검사 결과 시트로서온라인 문서의 URI(Uniform Resource Identifier)';
COMMENT ON COLUMN "SupplierInspectionApplication"."InspectionStatusCode" IS '[KS X 9101 표준] 검사상태코드: — 검사 진행 상태
— 예: 신청대기, 신청, 접수, 검사중, 완료, 취소 등
— 합격, 불합격 등 검사 판정은 검사결과(InspectionResult)로 구분함
— 참조 대상: 공통코드정보(CommonCodeMaster)의 코드';
COMMENT ON COLUMN "SupplierInspectionApplication"."ReasonForApplication" IS '[KS X 9101 표준] 검사신청사유: — 검사를 신청한 사유';
COMMENT ON COLUMN "SupplierInspectionApplication"."InspectionCancelReason" IS '[KS X 9101 표준] 검사취소사유: — 검사 절차상, 취소되거나 확정이 불가한 사유';

-- ---------------------------------------------------------------------
-- [표준 구분: KS X 9101 표준] 표 56, 조항 7.4.6.13 | 업무영역: 생산관리
-- 테이블명(물리): "SupplierInspectionResult" | 테이블명(논리): 협력업체품질검사결과
-- 설명: 검사결과를 품질관리 부서에 전달하는 것을 의미한다.
-- ---------------------------------------------------------------------
CREATE TABLE "SupplierInspectionResult" ( -- [KS X 9101 표준] 협력업체품질검사결과 (표 56)
    "SupplierInspectionResultSequenceNo" BIGINT GENERATED BY DEFAULT AS IDENTITY, -- [KS X 9101 표준] 협력업체품질검사결과 일련번호(PK)
    "EnterpriseID" VARCHAR(50) NOT NULL, -- [KS X 9101 표준] 회사식별자
    "SiteID" VARCHAR(50) NOT NULL, -- [KS X 9101 표준] 사업장식별자
    "PlantID" VARCHAR(50) NOT NULL, -- [KS X 9101 표준] 공장식별자
    "CreatorID" VARCHAR(50), -- [KS X 9101 표준] 등록자식별자
    "CreationDateTime" TIMESTAMP, -- [KS X 9101 표준] 등록일시
    "ModifierID" VARCHAR(50), -- [KS X 9101 표준] 수정자식별자
    "ModificationDateTime" TIMESTAMP, -- [KS X 9101 표준] 수정일시
    "Note" VARCHAR(1000), -- [KS X 9101 표준] 비고
    "VendorID" VARCHAR(50), -- [KS X 9101 표준] 공급사식별자
    "ProjectID" VARCHAR(50), -- [KS X 9101 표준] 프로젝트식별자
    "ItemID" VARCHAR(50), -- [KS X 9101 표준] 품목식별자
    "ItemName" VARCHAR(200), -- [KS X 9101 표준] 품목명
    "LotID" VARCHAR(50), -- [KS X 9101 표준] 로트식별자
    "BatchID" VARCHAR(50), -- [KS X 9101 표준] 배치식별자
    "InspectionPlanID" VARCHAR(50), -- [KS X 9101 표준] 검사계획식별자
    "InspectionID" VARCHAR(50), -- [KS X 9101 표준] 검사식별자
    "InspectionApplicationID" VARCHAR(50), -- [KS X 9101 표준] 검사신청식별자
    "InspectionResultID" VARCHAR(50) NOT NULL, -- [KS X 9101 표준] 검사결과식별자
    "Inspector" VARCHAR(255), -- [KS X 9101 표준] 검사자
    "InspectionParticipant" VARCHAR(1000), -- [KS X 9101 표준] 검사입회자
    "InspectionLocation" VARCHAR(1000), -- [KS X 9101 표준] 검사위치
    "InspectionDate" DATE, -- [KS X 9101 표준] 검사일
    "InspectionQuantity" NUMERIC(18,6), -- [KS X 9101 표준] 검사수량
    "InspectionResult" VARCHAR(30), -- [KS X 9101 표준] 검사결과
    "InspectionResultSheet" VARCHAR(1000), -- [KS X 9101 표준] 검사결과시트
    "InspectionStatusCode" VARCHAR(30), -- [KS X 9101 표준] 검사상태코드
    CONSTRAINT "PK_SupplierInspectionResult" PRIMARY KEY ("SupplierInspectionResultSequenceNo"),
    CONSTRAINT "UK_SupplierInspectionResult" UNIQUE ("EnterpriseID", "InspectionResultID")
);

COMMENT ON TABLE "SupplierInspectionResult" IS '[KS X 9101 표준] 협력업체품질검사결과 (검사결과를 품질관리 부서에 전달하는 것을 의미한다.)';
COMMENT ON COLUMN "SupplierInspectionResult"."SupplierInspectionResultSequenceNo" IS '[KS X 9101 표준] 협력업체품질검사결과 일련번호: — 테이블 행을 식별하는 일련번호(PK, 대리키) — 표준 외 물리 컬럼
— 자동 증가 값(IDENTITY)으로 부여하며 다른 테이블이 참조하지 않음(FK는 UK 참조)';
COMMENT ON COLUMN "SupplierInspectionResult"."EnterpriseID" IS '[KS X 9101 표준] 회사식별자: — 회사를 유일하게 구분할 수 있는 고유식별값
— 기업업무시스템 간의 연동을 수행하는 회사들 간에 자체적으로 정의한 고유식별값
— 참조 대상: 회사(Enterprise)';
COMMENT ON COLUMN "SupplierInspectionResult"."SiteID" IS '[KS X 9101 표준] 사업장식별자: — 회사 내에서 사업장을 구분할수 있는 고유식별값
— 참조 대상: 사업장(Site)';
COMMENT ON COLUMN "SupplierInspectionResult"."PlantID" IS '[KS X 9101 표준] 공장식별자: — 회사 내에서 공장을 구분할 수있는 고유식별값(만약, 공장 개념을 사용하지 않는다면 고정식별자로 설정하여 입력해야 함)
— 참조 대상: 공장(Plant)';
COMMENT ON COLUMN "SupplierInspectionResult"."CreatorID" IS '[KS X 9101 표준] 등록자식별자: — 정보를 처음으로 등록한 사람을 구분할 수 있는 고유식별값으로, 일반적으로 사원번호가사용됨
— 참조 대상: 사원(Personnel)';
COMMENT ON COLUMN "SupplierInspectionResult"."CreationDateTime" IS '[KS X 9101 표준] 등록일시: — 정보를 처음으로 등록한 날짜 (KS X ISO 8601을 따른다)';
COMMENT ON COLUMN "SupplierInspectionResult"."ModifierID" IS '[KS X 9101 표준] 수정자식별자: — 정보를 마지막으로 수정한 사람을 구분할 수 있는 고유식별값으로, 일반적으로 사원번호가 사용됨
— 참조 대상: 사원(Personnel)';
COMMENT ON COLUMN "SupplierInspectionResult"."ModificationDateTime" IS '[KS X 9101 표준] 수정일시: — 정보를 마지막으로 수정한 날짜 (KS X ISO 8601을 따른다.)';
COMMENT ON COLUMN "SupplierInspectionResult"."Note" IS '[KS X 9101 표준] 비고: — 비고사항';
COMMENT ON COLUMN "SupplierInspectionResult"."VendorID" IS '[KS X 9101 표준] 공급사식별자: — 품목을 구입해오는 거래처를 식별하기 위한 고유값
— 참조 대상: 공급사(VendorPartyMaster)';
COMMENT ON COLUMN "SupplierInspectionResult"."ProjectID" IS '[KS X 9101 표준] 프로젝트식별자: — 프로젝트를 식별하기 위한 고유값
— 참조 대상: 프로젝트마스터(ProjectMaster)';
COMMENT ON COLUMN "SupplierInspectionResult"."ItemID" IS '[KS X 9101 표준] 품목식별자: — 품목을 식별하기 위한 고유값
— 제품, 반제품, 상품, 원자재, 부자재, 저장품, 소모품 등 회사내 시스템으로 관리되는 모든 품목을 포함
— 참조 대상: 품목마스터(ItemMaster)';
COMMENT ON COLUMN "SupplierInspectionResult"."ItemName" IS '[KS X 9101 표준] 품목명: — 품목의 명칭
— 참조 대상: 품목마스터(ItemMaster.ItemName)';
COMMENT ON COLUMN "SupplierInspectionResult"."LotID" IS '[KS X 9101 표준] 로트식별자: — 품질검사결과에 포함된 로트의 고유식별값
— 참조 대상: 로트(Lot)';
COMMENT ON COLUMN "SupplierInspectionResult"."BatchID" IS '[KS X 9101 표준] 배치식별자: — 품질검사결과에 포함된 배치의 고유식별값
— 참조 대상: 배치(Batch)';
COMMENT ON COLUMN "SupplierInspectionResult"."InspectionPlanID" IS '[KS X 9101 표준] 검사계획식별자: — 검사계획을 식별하기 위한 고유값
— 참조 대상: 협력업체품질검사계획(SupplierInspectionPlan)';
COMMENT ON COLUMN "SupplierInspectionResult"."InspectionID" IS '[KS X 9101 표준] 검사식별자: — 검사를 식별하기 위한 고유값
— 참조 대상: 협력업체품질검사계획(SupplierInspectionPlan)의 검사 항목
— 검사계획식별자(InspectionPlanID)와 함께 사용한다';
COMMENT ON COLUMN "SupplierInspectionResult"."InspectionApplicationID" IS '[KS X 9101 표준] 검사신청식별자: — 검사신청을 식별하기 위한 고유값
— 참조 대상: 협력업체품질검사신청(SupplierInspectionApplication)';
COMMENT ON COLUMN "SupplierInspectionResult"."InspectionResultID" IS '[KS X 9101 표준] 검사결과식별자: — 검사결과를 식별하기 위한 고유값';
COMMENT ON COLUMN "SupplierInspectionResult"."Inspector" IS '[KS X 9101 표준] 검사자: — 검사를 진행한 담당자';
COMMENT ON COLUMN "SupplierInspectionResult"."InspectionParticipant" IS '[KS X 9101 표준] 검사입회자: — 검사 시 입회한 사업장 품질 담당자';
COMMENT ON COLUMN "SupplierInspectionResult"."InspectionLocation" IS '[KS X 9101 표준] 검사위치: — 검사를 진행하는 위치(장소)
— 참조 대상: 협력업체품질검사신청(SupplierInspectionApplication.InspectionLocation)';
COMMENT ON COLUMN "SupplierInspectionResult"."InspectionDate" IS '[KS X 9101 표준] 검사일: — 검사를 진행한 실제 검사일자(KS X ISO 8601을 따른다)';
COMMENT ON COLUMN "SupplierInspectionResult"."InspectionQuantity" IS '[KS X 9101 표준] 검사수량: — 검사의 대상이 되는 자재의 수량
— 참조 대상: 협력업체품질검사신청(SupplierInspectionApplication.InspectionQuantity)';
COMMENT ON COLUMN "SupplierInspectionResult"."InspectionResult" IS '[KS X 9101 표준] 검사결과: — 검사를 진행한 결과
— 검사 결과(예: 합격, 불합격, 조건부 합격)
— 참조 대상: 공통코드정보(CommonCodeMaster)의 코드';
COMMENT ON COLUMN "SupplierInspectionResult"."InspectionResultSheet" IS '[KS X 9101 표준] 검사결과시트: — 발주처의 검사체크시트를 기준으로 검사한 결과시트로서 온라인 문서의 URI(Uniform Resource Identifier)';
COMMENT ON COLUMN "SupplierInspectionResult"."InspectionStatusCode" IS '[KS X 9101 표준] 검사상태코드: — 검사 진행 상태
— 예: 신청대기, 신청, 접수, 검사중, 완료, 취소 등
— 합격, 불합격 등 검사 판정은 검사결과(InspectionResult)로 구분함
— 참조 대상: 공통코드정보(CommonCodeMaster)의 코드';

-- ---------------------------------------------------------------------
-- [표준 구분: KS X 9101 표준] 표 57, 조항 7.4.6.14 | 업무영역: 생산관리
-- 테이블명(물리): "CorrectiveActionRequest" | 테이블명(논리): 시정조치요청
-- 설명: 공급사에 시정조치를 요청하는 것을 의미한다.
-- ---------------------------------------------------------------------
CREATE TABLE "CorrectiveActionRequest" ( -- [KS X 9101 표준] 시정조치요청 (표 57)
    "CorrectiveActionRequestSequenceNo" BIGINT GENERATED BY DEFAULT AS IDENTITY, -- [KS X 9101 표준] 시정조치요청 일련번호(PK)
    "EnterpriseID" VARCHAR(50) NOT NULL, -- [KS X 9101 표준] 회사식별자
    "SiteID" VARCHAR(50) NOT NULL, -- [KS X 9101 표준] 사업장식별자
    "PlantID" VARCHAR(50) NOT NULL, -- [KS X 9101 표준] 공장식별자
    "CreatorID" VARCHAR(50), -- [KS X 9101 표준] 등록자식별자
    "CreationDateTime" TIMESTAMP, -- [KS X 9101 표준] 등록일시
    "ModifierID" VARCHAR(50), -- [KS X 9101 표준] 수정자식별자
    "ModificationDateTime" TIMESTAMP, -- [KS X 9101 표준] 수정일시
    "Note" VARCHAR(1000), -- [KS X 9101 표준] 비고
    "VendorID" VARCHAR(50), -- [KS X 9101 표준] 공급사식별자
    "ItemID" VARCHAR(50), -- [KS X 9101 표준] 품목식별자
    "ItemName" VARCHAR(200), -- [KS X 9101 표준] 품목명
    "LotID" VARCHAR(50), -- [KS X 9101 표준] 로트식별자
    "BatchID" VARCHAR(50), -- [KS X 9101 표준] 배치식별자
    "InspectionApplicationID" VARCHAR(50), -- [KS X 9101 표준] 검사신청식별자
    "CorrectiveActionRequestID" VARCHAR(50) NOT NULL, -- [KS X 9101 표준] 시정조치요청식별자
    "CorrectiveActionRequestIssuerID" VARCHAR(50), -- [KS X 9101 표준] 시정조치요청발행자식별자
    "CorrectiveActionRequestRecipientID" VARCHAR(50), -- [KS X 9101 표준] 시정조치요청접수자식별자
    "CorrectiveActionRequestLocation" VARCHAR(1000), -- [KS X 9101 표준] 시정조치요청위치
    "CorrectiveActionRequestDocumentReference" VARCHAR(255), -- [KS X 9101 표준] 시정조치요청첨부자료
    CONSTRAINT "PK_CorrectiveActionRequest" PRIMARY KEY ("CorrectiveActionRequestSequenceNo"),
    CONSTRAINT "UK_CorrectiveActionRequest" UNIQUE ("EnterpriseID", "CorrectiveActionRequestID")
);

COMMENT ON TABLE "CorrectiveActionRequest" IS '[KS X 9101 표준] 시정조치요청 (공급사에 시정조치를 요청하는 것을 의미한다.)';
COMMENT ON COLUMN "CorrectiveActionRequest"."CorrectiveActionRequestSequenceNo" IS '[KS X 9101 표준] 시정조치요청 일련번호: — 테이블 행을 식별하는 일련번호(PK, 대리키) — 표준 외 물리 컬럼
— 자동 증가 값(IDENTITY)으로 부여하며 다른 테이블이 참조하지 않음(FK는 UK 참조)';
COMMENT ON COLUMN "CorrectiveActionRequest"."EnterpriseID" IS '[KS X 9101 표준] 회사식별자: — 회사를 유일하게 구분할 수 있는 고유식별값
— 기업업무시스템 간의 연동을 수행하는 회사들 간에 자체적으로 정의한 고유식별값
— 참조 대상: 회사(Enterprise)';
COMMENT ON COLUMN "CorrectiveActionRequest"."SiteID" IS '[KS X 9101 표준] 사업장식별자: — 회사 내에서 사업장을 구분할수 있는 고유식별값
— 참조 대상: 사업장(Site)';
COMMENT ON COLUMN "CorrectiveActionRequest"."PlantID" IS '[KS X 9101 표준] 공장식별자: — 회사 내에서 공장을 구분할 수있는 고유식별값(만약, 공장 개념을 사용하지 않는다면 고정식별자로 설정하여 입력해야 함)
— 참조 대상: 공장(Plant)';
COMMENT ON COLUMN "CorrectiveActionRequest"."CreatorID" IS '[KS X 9101 표준] 등록자식별자: — 정보를 처음으로 등록한 사람을 구분할 수 있는 고유식별값으로, 일반적으로 사원번호가사용됨
— 참조 대상: 사원(Personnel)';
COMMENT ON COLUMN "CorrectiveActionRequest"."CreationDateTime" IS '[KS X 9101 표준] 등록일시: — 정보를 처음으로 등록한 날짜 (KS X ISO 8601을 따른다)';
COMMENT ON COLUMN "CorrectiveActionRequest"."ModifierID" IS '[KS X 9101 표준] 수정자식별자: — 정보를 마지막으로 수정한 사람을 구분할 수 있는 고유식별값으로, 일반적으로 사원번호가 사용됨
