COMMENT ON COLUMN "CorrectiveActionRequest"."VendorID" IS '[KS X 9101 표준] 공급사식별자: — 품목을 구입해오는 거래처를 식별하기 위한 고유값
— 참조 대상: 공급사(VendorPartyMaster)';
COMMENT ON COLUMN "CorrectiveActionRequest"."ItemID" IS '[KS X 9101 표준] 품목식별자: — 품목을 식별하기 위한 고유값
— 제품, 반제품, 상품, 원자재, 부자재, 저장품, 소모품 등회사 내 시스템으로 관리되는 모든 품목을 포함
— 참조 대상: 품목마스터(ItemMaster)';
COMMENT ON COLUMN "CorrectiveActionRequest"."ItemName" IS '[KS X 9101 표준] 품목명: — 품목의 명칭
— 참조 대상: 품목마스터(ItemMaster.ItemName)';
COMMENT ON COLUMN "CorrectiveActionRequest"."LotID" IS '[KS X 9101 표준] 로트식별자: — 시정조치요청에 포함된 로트의 고유식별값
— 참조 대상: 로트(Lot)';
COMMENT ON COLUMN "CorrectiveActionRequest"."BatchID" IS '[KS X 9101 표준] 배치식별자: — 시정조치요청에 포함된 배치의 고유식별값
— 참조 대상: 배치(Batch)';
COMMENT ON COLUMN "CorrectiveActionRequest"."InspectionApplicationID" IS '[KS X 9101 표준] 검사신청식별자: — 검사신청을 식별하기 위한 고유값
— 참조 대상: 협력업체품질검사신청(SupplierInspectionApplication)';
COMMENT ON COLUMN "CorrectiveActionRequest"."CorrectiveActionRequestID" IS '[KS X 9101 표준] 시정조치요청식별자: — 시정조치요청을 식별하기 위한 고유값';
COMMENT ON COLUMN "CorrectiveActionRequest"."CorrectiveActionRequestIssuerID" IS '[KS X 9101 표준] 시정조치요청발행자식별자: — 시정조치요청 발행자를 식별하기 위한 고유값
— 참조 대상: 사원(Personnel)';
COMMENT ON COLUMN "CorrectiveActionRequest"."CorrectiveActionRequestRecipientID" IS '[KS X 9101 표준] 시정조치요청접수자식별자: — 시정조치요청 접수자를 식별하기 위한 고유값
— 공급사 측 접수 담당자의 식별값으로, 시정조치요청 시에는 값을 생략하고 공급사가 회신(AcknowledgeCorrectiveActionRequest)할 때 입력한다';
COMMENT ON COLUMN "CorrectiveActionRequest"."CorrectiveActionRequestLocation" IS '[KS X 9101 표준] 시정조치요청위치: — 시정조치 항목의 위치(예: 1번방 상단)';
COMMENT ON COLUMN "CorrectiveActionRequest"."CorrectiveActionRequestDocumentReference" IS '[KS X 9101 표준] 시정조치요청첨부자료: — 시정조치요청을 설명하기 위한 사진, 문서 등에 대한 온라인 URI(Uniform Resource Identifier)';

-- ---------------------------------------------------------------------
-- [표준 구분: KS X 9101 표준] 표 58, 조항 7.4.6.15 | 업무영역: 생산관리
-- 테이블명(물리): "CorrectiveActionPlan" | 테이블명(논리): 시정조치계획
-- 설명: 공급사에서 시정조치 사항을 기술하고, 시정조치 계획을 수립하여 고객사에게 전달하는 것을 의미한다.
-- ---------------------------------------------------------------------
CREATE TABLE "CorrectiveActionPlan" ( -- [KS X 9101 표준] 시정조치계획 (표 58)
    "CorrectiveActionPlanSequenceNo" BIGINT GENERATED BY DEFAULT AS IDENTITY, -- [KS X 9101 표준] 시정조치계획 일련번호(PK)
    "EnterpriseID" VARCHAR(50) NOT NULL, -- [KS X 9101 표준] 회사식별자
    "SiteID" VARCHAR(50) NOT NULL, -- [KS X 9101 표준] 사업장식별자
    "PlantID" VARCHAR(50) NOT NULL, -- [KS X 9101 표준] 공장식별자
    "CreatorID" VARCHAR(50), -- [KS X 9101 표준] 등록자식별자
    "CreationDateTime" TIMESTAMP, -- [KS X 9101 표준] 등록일시
    "ModifierID" VARCHAR(50), -- [KS X 9101 표준] 수정자식별자
    "ModificationDateTime" TIMESTAMP, -- [KS X 9101 표준] 수정일시
    "Note" VARCHAR(1000), -- [KS X 9101 표준] 비고
    "VendorID" VARCHAR(50), -- [KS X 9101 표준] 공급사식별자
    "ItemID" VARCHAR(50), -- [KS X 9101 표준] 품목식별자
    "ItemName" VARCHAR(200), -- [KS X 9101 표준] 품목명
    "LotID" VARCHAR(50), -- [KS X 9101 표준] 로트식별자
    "BatchID" VARCHAR(50), -- [KS X 9101 표준] 배치식별자
    "CorrectiveActionRequestID" VARCHAR(50), -- [KS X 9101 표준] 시정조치요청식별자
    "CorrectiveActionPlanID" VARCHAR(50) NOT NULL, -- [KS X 9101 표준] 시정조치계획식별자
    "PersonInChargeID" VARCHAR(50), -- [KS X 9101 표준] 시정조치담당자식별자
    "PersonInChargeEmail" VARCHAR(255), -- [KS X 9101 표준] 시정조치담당자이메일명
    "PersonInChargeDialNumber" VARCHAR(30), -- [KS X 9101 표준] 시정조치담당자전화번호
    "ExpectedCorrectiveActionDate" DATE, -- [KS X 9101 표준] 시정조치예정일
    "CorrectiveActionRequestDocumentReference" VARCHAR(255), -- [KS X 9101 표준] 시정조치요청첨부자료
    "CorrectiveActionApprovalIndicator" BOOLEAN, -- [KS X 9101 표준] 시정조치접수여부
    "CorrectiveActionStatusCode" VARCHAR(30), -- [KS X 9101 표준] 시정조치상태코드
    "ReasonForRejection" VARCHAR(255), -- [KS X 9101 표준] 반려사유
    CONSTRAINT "PK_CorrectiveActionPlan" PRIMARY KEY ("CorrectiveActionPlanSequenceNo"),
    CONSTRAINT "UK_CorrectiveActionPlan" UNIQUE ("EnterpriseID", "CorrectiveActionPlanID")
);

COMMENT ON TABLE "CorrectiveActionPlan" IS '[KS X 9101 표준] 시정조치계획 (공급사에서 시정조치 사항을 기술하고, 시정조치 계획을 수립하여 고객사에게 전달하는 것을 의미한다.)';
COMMENT ON COLUMN "CorrectiveActionPlan"."CorrectiveActionPlanSequenceNo" IS '[KS X 9101 표준] 시정조치계획 일련번호: — 테이블 행을 식별하는 일련번호(PK, 대리키) — 표준 외 물리 컬럼
— 자동 증가 값(IDENTITY)으로 부여하며 다른 테이블이 참조하지 않음(FK는 UK 참조)';
COMMENT ON COLUMN "CorrectiveActionPlan"."EnterpriseID" IS '[KS X 9101 표준] 회사식별자: — 회사를 유일하게 구분할 수 있는 고유식별값
— 기업업무시스템 간의 연동을 수행하는 회사들 간에 자체적으로 정의한 고유식별값
— 참조 대상: 회사(Enterprise)';
COMMENT ON COLUMN "CorrectiveActionPlan"."SiteID" IS '[KS X 9101 표준] 사업장식별자: — 회사 내에서 사업장을 구분할수 있는 고유식별값
— 참조 대상: 사업장(Site)';
COMMENT ON COLUMN "CorrectiveActionPlan"."PlantID" IS '[KS X 9101 표준] 공장식별자: — 회사 내에서 공장을 구분할 수있는 고유식별값(만약, 공장 개념을 사용하지 않는다면 고정식별자로 설정하여 입력해야 함)
— 참조 대상: 공장(Plant)';
COMMENT ON COLUMN "CorrectiveActionPlan"."CreatorID" IS '[KS X 9101 표준] 등록자식별자: — 정보를 처음으로 등록한 사람을 구분할 수 있는 고유식별값으로, 일반적으로 사원번호가사용됨
— 참조 대상: 사원(Personnel)';
COMMENT ON COLUMN "CorrectiveActionPlan"."CreationDateTime" IS '[KS X 9101 표준] 등록일시: — 정보를 처음으로 등록한 날짜 (KS X ISO 8601을 따른다)';
COMMENT ON COLUMN "CorrectiveActionPlan"."ModifierID" IS '[KS X 9101 표준] 수정자식별자: — 정보를 마지막으로 수정한 사람을 구분할 수 있는 고유식별값으로, 일반적으로 사원번호가 사용됨
— 참조 대상: 사원(Personnel)';
COMMENT ON COLUMN "CorrectiveActionPlan"."ModificationDateTime" IS '[KS X 9101 표준] 수정일시: — 정보를 마지막으로 수정한 날짜 (KS X ISO 8601을 따른다.)';
COMMENT ON COLUMN "CorrectiveActionPlan"."Note" IS '[KS X 9101 표준] 비고: — 비고사항';
COMMENT ON COLUMN "CorrectiveActionPlan"."VendorID" IS '[KS X 9101 표준] 공급사식별자: — 품목을 구입해오는 거래처를 식별하기 위한 고유값
— 참조 대상: 공급사(VendorPartyMaster)';
COMMENT ON COLUMN "CorrectiveActionPlan"."ItemID" IS '[KS X 9101 표준] 품목식별자: — 품목을 식별하기 위한 고유값
— 제품, 반제품, 상품, 원자재, 부자재, 저장품, 소모품등 회사 내 시스템으로 관리되는 모든 품목을 포함
— 참조 대상: 품목마스터(ItemMaster)';
COMMENT ON COLUMN "CorrectiveActionPlan"."ItemName" IS '[KS X 9101 표준] 품목명: — 품목의 명칭
— 참조 대상: 품목마스터(ItemMaster.ItemName)';
COMMENT ON COLUMN "CorrectiveActionPlan"."LotID" IS '[KS X 9101 표준] 로트식별자: — 시정조치계획에 포함된 로트의 고유식별값
— 참조 대상: 로트(Lot)';
COMMENT ON COLUMN "CorrectiveActionPlan"."BatchID" IS '[KS X 9101 표준] 배치식별자: — 시정조치계획에 포함된 배치의 고유식별값
— 참조 대상: 배치(Batch)';
COMMENT ON COLUMN "CorrectiveActionPlan"."CorrectiveActionRequestID" IS '[KS X 9101 표준] 시정조치요청식별자: — 시정조치요청을 식별하기 위한 고유값
— 참조 대상: 시정조치요청(CorrectiveActionRequest)';
COMMENT ON COLUMN "CorrectiveActionPlan"."CorrectiveActionPlanID" IS '[KS X 9101 표준] 시정조치계획식별자: — 시정조치계획을 식별하기 위한 고유값';
COMMENT ON COLUMN "CorrectiveActionPlan"."PersonInChargeID" IS '[KS X 9101 표준] 시정조치담당자식별자: — 시정조치요청을 처리할 담당자를 식별하기 위한 고유값
— 참조 대상: 사원(Personnel)';
COMMENT ON COLUMN "CorrectiveActionPlan"."PersonInChargeEmail" IS '[KS X 9101 표준] 시정조치담당자이메일명: — 시정조치담당자의 이메일';
COMMENT ON COLUMN "CorrectiveActionPlan"."PersonInChargeDialNumber" IS '[KS X 9101 표준] 시정조치담당자전화번호: — 시정조치담당자의 전화번호';
COMMENT ON COLUMN "CorrectiveActionPlan"."ExpectedCorrectiveActionDate" IS '[KS X 9101 표준] 시정조치예정일: — 시정조치 처리 예정일시(KS X ISO 8601을 따른다)';
COMMENT ON COLUMN "CorrectiveActionPlan"."CorrectiveActionRequestDocumentReference" IS '[KS X 9101 표준] 시정조치요청첨부자료: — 시정조치요청을 설명하기 위한 사진, 문서 등에 대한 온라인 URI(Uniform Resource Identifier)';
COMMENT ON COLUMN "CorrectiveActionPlan"."CorrectiveActionApprovalIndicator" IS '[KS X 9101 표준] 시정조치접수여부: — 시정조치 접수 여부';
COMMENT ON COLUMN "CorrectiveActionPlan"."CorrectiveActionStatusCode" IS '[KS X 9101 표준] 시정조치상태코드: — 시정조치 진행 상태(예: 발행, 접수, 진행, 반려, 완료, 종결 등)
— 참조 대상: 공통코드정보(CommonCodeMaster)의 코드';
COMMENT ON COLUMN "CorrectiveActionPlan"."ReasonForRejection" IS '[KS X 9101 표준] 반려사유: — 시정조치 반려 사유';

-- ---------------------------------------------------------------------
-- [표준 구분: KS X 9101 표준] 표 59, 조항 7.4.6.16 | 업무영역: 생산관리
