    "CorrectiveActionResultID" VARCHAR(50) NOT NULL, -- [KS X 9101 표준] 시정조치결과식별자
    "PersonInChargeID" VARCHAR(50), -- [KS X 9101 표준] 시정조치담당자식별자
    "PersonInChargeEmail" VARCHAR(255), -- [KS X 9101 표준] 시정조치담당자이메일명
    "PersonInChargeDialNumber" VARCHAR(30), -- [KS X 9101 표준] 시정조치담당자전화번호
