COMMENT ON COLUMN "CorrectiveActionResult"."CorrectiveActionResultID" IS '[KS X 9101 표준] 시정조치결과식별자: — 시정조치결과를 식별하기 위한 고유값';
COMMENT ON COLUMN "CorrectiveActionResult"."PersonInChargeID" IS '[KS X 9101 표준] 시정조치담당자식별자: — 시정조치요청을 처리할 담당자를 식별하기 위한 고유값
