COMMENT ON COLUMN "CorrectiveActionResult"."PersonInChargeEmail" IS '[KS X 9101 표준] 시정조치담당자이메일명: — 시정조치담당자의 이메일';
COMMENT ON COLUMN "CorrectiveActionResult"."PersonInChargeDialNumber" IS '[KS X 9101 표준] 시정조치담당자전화번호: — 시정조치담당자의 전화번호';
COMMENT ON COLUMN "CorrectiveActionResult"."CorrectiveActionConfirmorID" IS '[KS X 9101 표준] 시정조치확인자식별자: — 시정조치결과를 확인한 담당자를 식별하기 위한 고유값
— 참조 대상: 사원(Personnel)';
COMMENT ON COLUMN "CorrectiveActionResult"."CorrectiveActionConfirmorEmail" IS '[KS X 9101 표준] 시정조치확인자이메일명: — 시정조치확인자의 이메일';
COMMENT ON COLUMN "CorrectiveActionResult"."CorrectiveActionConfirmorDialNumber" IS '[KS X 9101 표준] 시정조치확인자전화번호: — 시정조치확인자의 전화번호';
COMMENT ON COLUMN "CorrectiveActionResult"."CorrectiveActionDateTime" IS '[KS X 9101 표준] 시정조치일시: — 시정조치 처리 완료일시(KS X ISO 8601을 따른다)';
COMMENT ON COLUMN "CorrectiveActionResult"."CorrectiveActionResultDescription" IS '[KS X 9101 표준] 시정조치결과내용: — 시정조치 처리 완료 결과 내용';
COMMENT ON COLUMN "CorrectiveActionResult"."CorrectiveActionStatusCode" IS '[KS X 9101 표준] 시정조치상태코드: — 시정조치 진행 상태(예: 발행, 접수, 진행, 반려, 완료, 종결 등)
— 참조 대상: 공통코드정보(CommonCodeMaster)의 코드';
COMMENT ON COLUMN "CorrectiveActionResult"."ReasonForRejection" IS '[KS X 9101 표준] 반려사유: — 시정조치 반려 사유';

-- ---------------------------------------------------------------------
-- [표준 구분: KS X 9101 표준] 표 60, 조항 7.4.6.17 | 업무영역: 생산관리
-- 테이블명(물리): "ProductPacking" | 테이블명(논리): 제품포장
-- 설명: 제품 출하를 위해 완성된 제품을 포장하기 위한 정보를 의미한다.
-- ---------------------------------------------------------------------
CREATE TABLE "ProductPacking" ( -- [KS X 9101 표준] 제품포장 (표 60)
    "ProductPackingSequenceNo" BIGINT GENERATED BY DEFAULT AS IDENTITY, -- [KS X 9101 표준] 제품포장 일련번호(PK)
    "EnterpriseID" VARCHAR(50) NOT NULL, -- [KS X 9101 표준] 회사식별자
    "SiteID" VARCHAR(50) NOT NULL, -- [KS X 9101 표준] 사업장식별자
    "PlantID" VARCHAR(50) NOT NULL, -- [KS X 9101 표준] 공장식별자
    "CreatorID" VARCHAR(50), -- [KS X 9101 표준] 등록자식별자
    "CreationDateTime" TIMESTAMP, -- [KS X 9101 표준] 등록일시
    "ModifierID" VARCHAR(50), -- [KS X 9101 표준] 수정자식별자
    "ModificationDateTime" TIMESTAMP, -- [KS X 9101 표준] 수정일시
    "Note" VARCHAR(1000), -- [KS X 9101 표준] 비고
    "PackingType" VARCHAR(30), -- [KS X 9101 표준] 포장유형
    "WarehouseID" VARCHAR(50), -- [KS X 9101 표준] 창고식별자
    "SerialNumber" VARCHAR(50), -- [KS X 9101 표준] 일련번호
    "BoxNumber" VARCHAR(50) NOT NULL, -- [KS X 9101 표준] 포장박스번호
    "PalletNumber" VARCHAR(50), -- [KS X 9101 표준] 포장파렛트번호
    "ItemID" VARCHAR(50), -- [KS X 9101 표준] 품목식별자
    "PackingSequence" INTEGER NOT NULL, -- [KS X 9101 표준] 포장순번
    "LotID" VARCHAR(50), -- [KS X 9101 표준] 로트식별자
    CONSTRAINT "PK_ProductPacking" PRIMARY KEY ("ProductPackingSequenceNo"),
    CONSTRAINT "UK_ProductPacking" UNIQUE ("EnterpriseID", "BoxNumber", "PackingSequence")
);

COMMENT ON TABLE "ProductPacking" IS '[KS X 9101 표준] 제품포장 (제품 출하를 위해 완성된 제품을 포장하기 위한 정보를 의미한다.)';
