— 참조 대상: 사업장(Site)';
COMMENT ON COLUMN "ProductPacking"."PlantID" IS '[KS X 9101 표준] 공장식별자: — 회사 내에서 공장을 구분할 수있는 고유식별값(만약, 공장 개념을 사용하지 않는다면 고정식별자로 설정하여 입력해야 함)
— 참조 대상: 공장(Plant)';
COMMENT ON COLUMN "ProductPacking"."CreatorID" IS '[KS X 9101 표준] 등록자식별자: — 정보를 처음으로 등록한 사람을 구분할 수 있는 고유식별값으로, 일반적으로 사원번호가사용됨
— 참조 대상: 사원(Personnel)';
COMMENT ON COLUMN "ProductPacking"."CreationDateTime" IS '[KS X 9101 표준] 등록일시: — 정보를 처음으로 등록한 날짜 (KS X ISO 8601을 따른다)';
COMMENT ON COLUMN "ProductPacking"."ModifierID" IS '[KS X 9101 표준] 수정자식별자: — 정보를 마지막으로 수정한 사람을 구분할 수 있는 고유식별값으로, 일반적으로 사원번호가 사용됨
— 참조 대상: 사원(Personnel)';
COMMENT ON COLUMN "ProductPacking"."ModificationDateTime" IS '[KS X 9101 표준] 수정일시: — 정보를 마지막으로 수정한 날짜 (KS X ISO 8601을 따른다.)';
COMMENT ON COLUMN "ProductPacking"."Note" IS '[KS X 9101 표준] 비고: — 비고사항';
COMMENT ON COLUMN "ProductPacking"."PackingType" IS '[KS X 9101 표준] 포장유형: — 포장유형
— 포장유형(예: 박스, 파렛트, 벌크 등)
— 참조 대상: 공통코드정보(CommonCodeMaster)의 코드';
COMMENT ON COLUMN "ProductPacking"."WarehouseID" IS '[KS X 9101 표준] 창고식별자: — 창고를 식별하기 위한 고유값
— 참조 대상: 창고(WarehouseLocation)';
COMMENT ON COLUMN "ProductPacking"."SerialNumber" IS '[KS X 9101 표준] 일련번호: — 일련번호';
COMMENT ON COLUMN "ProductPacking"."BoxNumber" IS '[KS X 9101 표준] 포장박스번호: — 포장박스번호';
COMMENT ON COLUMN "ProductPacking"."PalletNumber" IS '[KS X 9101 표준] 포장파렛트번호: — 포장된 파렛트번호';
COMMENT ON COLUMN "ProductPacking"."ItemID" IS '[KS X 9101 표준] 품목식별자: — 품목을 식별하기 위한 고유값
— 제품, 반제품, 상품, 원자재, 부자재, 저장품, 소모품 등회사 내 시스템으로 관리되는 모든 품목을 포함
— 참조 대상: 품목마스터(ItemMaster)';
COMMENT ON COLUMN "ProductPacking"."PackingSequence" IS '[KS X 9101 표준] 포장순번: — 포장된 순번
— 제품포장 행은 포장박스번호와 포장순번의 조합으로 구분하며, 조합에 포함되는 속성은 값을 생략할 수 없음(7.1)';
COMMENT ON COLUMN "ProductPacking"."LotID" IS '[KS X 9101 표준] 로트식별자: — 제품포장에 포함된 로트의 고유식별값
— 참조 대상: 로트(Lot)';

-- ---------------------------------------------------------------------
-- [표준 구분: KS X 9101 표준] 표 61, 조항 7.4.6.18 | 업무영역: 생산관리
-- 테이블명(물리): "EquipmentParameter" | 테이블명(논리): 설비파라미터
-- 설명: 설비에서 수집되는 Parameter 값의 집합을 의미한다.
-- ---------------------------------------------------------------------
CREATE TABLE "EquipmentParameter" ( -- [KS X 9101 표준] 설비파라미터 (표 61)
    "EquipmentParameterSequenceNo" BIGINT GENERATED BY DEFAULT AS IDENTITY, -- [KS X 9101 표준] 설비파라미터 일련번호(PK)
    "EnterpriseID" VARCHAR(50) NOT NULL, -- [KS X 9101 표준] 회사식별자
    "SiteID" VARCHAR(50) NOT NULL, -- [KS X 9101 표준] 사업장식별자
    "PlantID" VARCHAR(50) NOT NULL, -- [KS X 9101 표준] 공장식별자
    "CreatorID" VARCHAR(50), -- [KS X 9101 표준] 등록자식별자
    "CreationDateTime" TIMESTAMP, -- [KS X 9101 표준] 등록일시
    "ModifierID" VARCHAR(50), -- [KS X 9101 표준] 수정자식별자
    "ModificationDateTime" TIMESTAMP, -- [KS X 9101 표준] 수정일시
    "Note" VARCHAR(1000), -- [KS X 9101 표준] 비고
    "ParameterID" VARCHAR(50) NOT NULL, -- [KS X 9101 표준] 파라미터식별자
    "ParameterName" VARCHAR(200), -- [KS X 9101 표준] 파라미터명
    "ParameterType" VARCHAR(30), -- [KS X 9101 표준] 파라미터유형
    "ParameterGrade" VARCHAR(30), -- [KS X 9101 표준] 파라미터등급
    "ParameterUOMCode" VARCHAR(20), -- [KS X 9101 표준] 파라미터단위코드
    "EquipmentID" VARCHAR(50), -- [KS X 9101 표준] 설비식별자
    "LSL" NUMERIC(18,6), -- [KS X 9101 표준] 규격하한
    "USL" NUMERIC(18,6), -- [KS X 9101 표준] 규격상한
    "PeriodicDataCollectionIndicator" BOOLEAN, -- [KS X 9101 표준] 주기적수집여부
    "DataCollectionPeriod" INTERVAL, -- [KS X 9101 표준] 수집주기
    CONSTRAINT "PK_EquipmentParameter" PRIMARY KEY ("EquipmentParameterSequenceNo"),
    CONSTRAINT "UK_EquipmentParameter" UNIQUE ("EnterpriseID", "ParameterID")
);

