— 참조 대상: 사원(Personnel)';
COMMENT ON COLUMN "EquipmentParameter"."CreationDateTime" IS '[KS X 9101 표준] 등록일시: — 정보를 처음으로 등록한 날짜 (KS X ISO 8601을 따른다)';
COMMENT ON COLUMN "EquipmentParameter"."ModifierID" IS '[KS X 9101 표준] 수정자식별자: — 정보를 마지막으로 수정한 사람을 구분할 수 있는 고유식별값으로, 일반적으로 사원번호가 사용됨
— 참조 대상: 사원(Personnel)';
COMMENT ON COLUMN "EquipmentParameter"."ModificationDateTime" IS '[KS X 9101 표준] 수정일시: — 정보를 마지막으로 수정한 날짜 (KS X ISO 8601을 따른다.)';
COMMENT ON COLUMN "EquipmentParameter"."Note" IS '[KS X 9101 표준] 비고: — 비고사항';
COMMENT ON COLUMN "EquipmentParameter"."ParameterID" IS '[KS X 9101 표준] 파라미터식별자: — 설비에서 수집하는 파라미터 식별을 위한 고유값';
COMMENT ON COLUMN "EquipmentParameter"."ParameterName" IS '[KS X 9101 표준] 파라미터명: — 설비에서 수집하는 파라미터의 명칭';
COMMENT ON COLUMN "EquipmentParameter"."ParameterType" IS '[KS X 9101 표준] 파라미터유형: — 설비에서 수집하는 파라미터의 유형
— 파라미터 유형(예: 온도, 압력, 전류, 진동 등)
— 참조 대상: 공통코드정보(CommonCodeMaster)의 코드';
COMMENT ON COLUMN "EquipmentParameter"."ParameterGrade" IS '[KS X 9101 표준] 파라미터등급: — 파라미터의 중요도와 위험성에 따라 분류된 등급
— 파라미터 등급(예: Critical(핵심), Major(주요), Minor(일반))
— 참조 대상: 공통코드정보(CommonCodeMaster)의 코드';
COMMENT ON COLUMN "EquipmentParameter"."ParameterUOMCode" IS '[KS X 9101 표준] 파라미터단위코드: — 설비에서 수집하는 파라미터 데이터의 단위(예: Cel, mV, RH, PCT 등)
— 참조 대상: 단위그룹(UOMGroup)의 단위코드';
COMMENT ON COLUMN "EquipmentParameter"."EquipmentID" IS '[KS X 9101 표준] 설비식별자: — 설비를 식별하기 위한 고유값
— 참조 대상: 설비(Equipment)';
COMMENT ON COLUMN "EquipmentParameter"."LSL" IS '[KS X 9101 표준] 규격하한: — 설비에서 수집하는 파라미터의 허용하한치';
COMMENT ON COLUMN "EquipmentParameter"."USL" IS '[KS X 9101 표준] 규격상한: — 설비에서 수집하는 파라미터의 허용상한치';
COMMENT ON COLUMN "EquipmentParameter"."PeriodicDataCollectionIndicator" IS '[KS X 9101 표준] 주기적수집여부: — 파라미터의 주기적 수집 여부';
COMMENT ON COLUMN "EquipmentParameter"."DataCollectionPeriod" IS '[KS X 9101 표준] 수집주기: — 파라미터 데이터의 수집주기(KS X ISO 8601을 따른다)
— 주기적 수집여부의 값이 ‘주기적’일 때만 값을 가짐';

-- ---------------------------------------------------------------------
-- [표준 구분: KS X 9101 표준] 표 62, 조항 7.4.6.19 | 업무영역: 생산관리
-- 테이블명(물리): "TraceParameter" | 테이블명(논리): 설비파라미터이력
-- 설명: 설비에서 수집되는 Parameter 값의 적재 및 검증 이력을 의미한다.
-- ---------------------------------------------------------------------
CREATE TABLE "TraceParameter" ( -- [KS X 9101 표준] 설비파라미터이력 (표 62)
    "TraceParameterSequenceNo" BIGINT GENERATED BY DEFAULT AS IDENTITY, -- [KS X 9101 표준] 설비파라미터이력 일련번호(PK)
    "EnterpriseID" VARCHAR(50) NOT NULL, -- [KS X 9101 표준] 회사식별자
    "SiteID" VARCHAR(50) NOT NULL, -- [KS X 9101 표준] 사업장식별자
    "PlantID" VARCHAR(50) NOT NULL, -- [KS X 9101 표준] 공장식별자
    "CreatorID" VARCHAR(50), -- [KS X 9101 표준] 등록자식별자
    "CreationDateTime" TIMESTAMP, -- [KS X 9101 표준] 등록일시
    "ModifierID" VARCHAR(50), -- [KS X 9101 표준] 수정자식별자
    "ModificationDateTime" TIMESTAMP, -- [KS X 9101 표준] 수정일시
    "Note" VARCHAR(1000), -- [KS X 9101 표준] 비고
    "TraceParameterID" VARCHAR(50) NOT NULL, -- [KS X 9101 표준] 설비파라미터이력식별자
    "EquipmentID" VARCHAR(50), -- [KS X 9101 표준] 설비식별자
    "ParameterID" VARCHAR(50), -- [KS X 9101 표준] 파라미터식별자
    "EventDateTime" TIMESTAMP, -- [KS X 9101 표준] 이벤트발생일시
    "ParameterUOMCode" VARCHAR(20), -- [KS X 9101 표준] 파라미터단위코드
    "ParameterValue" NUMERIC(18,6), -- [KS X 9101 표준] 파라미터값
    "ValidationResultCode" VARCHAR(30), -- [KS X 9101 표준] 검증결과코드
    CONSTRAINT "PK_TraceParameter" PRIMARY KEY ("TraceParameterSequenceNo"),
    CONSTRAINT "UK_TraceParameter" UNIQUE ("EnterpriseID", "TraceParameterID")
);

COMMENT ON TABLE "TraceParameter" IS '[KS X 9101 표준] 설비파라미터이력 (설비에서 수집되는 Parameter 값의 적재 및 검증 이력을 의미한다.)';
COMMENT ON COLUMN "TraceParameter"."TraceParameterSequenceNo" IS '[KS X 9101 표준] 설비파라미터이력 일련번호: — 테이블 행을 식별하는 일련번호(PK, 대리키) — 표준 외 물리 컬럼
— 자동 증가 값(IDENTITY)으로 부여하며 다른 테이블이 참조하지 않음(FK는 UK 참조)';
COMMENT ON COLUMN "TraceParameter"."EnterpriseID" IS '[KS X 9101 표준] 회사식별자: — 회사를 유일하게 구분할 수 있는 고유식별값
— 기업업무시스템 간의 연동을 수행하는 회사들 간에 자체적으로 정의한 고유식별값
— 참조 대상: 회사(Enterprise)';
COMMENT ON COLUMN "TraceParameter"."SiteID" IS '[KS X 9101 표준] 사업장식별자: — 회사 내에서 사업장을 구분할수 있는 고유식별값
— 참조 대상: 사업장(Site)';
COMMENT ON COLUMN "TraceParameter"."PlantID" IS '[KS X 9101 표준] 공장식별자: — 회사 내에서 공장을 구분할 수있는 고유식별값(만약, 공장 개념을 사용하지 않는다면 고정식별자로 설정하여 입력해야 함)
— 참조 대상: 공장(Plant)';
COMMENT ON COLUMN "TraceParameter"."CreatorID" IS '[KS X 9101 표준] 등록자식별자: — 정보를 처음으로 등록한 사람을 구분할 수 있는 고유식별값으로, 일반적으로 사원번호가사용됨
— 참조 대상: 사원(Personnel)';
COMMENT ON COLUMN "TraceParameter"."CreationDateTime" IS '[KS X 9101 표준] 등록일시: — 정보를 처음으로 등록한 날짜 (KS X ISO 8601을 따른다)';
COMMENT ON COLUMN "TraceParameter"."ModifierID" IS '[KS X 9101 표준] 수정자식별자: — 정보를 마지막으로 수정한 사람을 구분할 수 있는 고유식별값으로, 일반적으로 사원번호가 사용됨
— 참조 대상: 사원(Personnel)';
COMMENT ON COLUMN "TraceParameter"."ModificationDateTime" IS '[KS X 9101 표준] 수정일시: — 정보를 마지막으로 수정한 날짜 (KS X ISO 8601을 따른다.)';
COMMENT ON COLUMN "TraceParameter"."Note" IS '[KS X 9101 표준] 비고: — 비고사항';
COMMENT ON COLUMN "TraceParameter"."TraceParameterID" IS '[KS X 9101 표준] 설비파라미터이력식별자: — 설비파라미터이력을 식별하기 위한 고유값
— 이벤트를 최초로 발생시킨 시스템이 GUID 형식으로 부여하며, BOD로 최초 송신한 경우 해당 BOD의 BODID를 식별자로 사용할 수 있음(7.1)';
COMMENT ON COLUMN "TraceParameter"."EquipmentID" IS '[KS X 9101 표준] 설비식별자: — 설비를 식별하기 위한 고유값
— 참조 대상: 설비(Equipment)';
COMMENT ON COLUMN "TraceParameter"."ParameterID" IS '[KS X 9101 표준] 파라미터식별자: — 설비에서 수집하는 파라미터 식별을 위한 고유값
— 참조 대상: 설비파라미터(EquipmentParameter)
— 설비식별자(EquipmentID)와 함께 사용한다';
COMMENT ON COLUMN "TraceParameter"."EventDateTime" IS '[KS X 9101 표준] 이벤트발생일시: — 설비에서 파라미터 수집된 일시(KS X ISO 8601을 따른다)';
COMMENT ON COLUMN "TraceParameter"."ParameterUOMCode" IS '[KS X 9101 표준] 파라미터단위코드: — 설비에서 수집하는 파라미터 데이터의 단위(예: Cel, mV, RH, PCT 등)
— 참조 대상: 단위그룹(UOMGroup)의 단위코드';
COMMENT ON COLUMN "TraceParameter"."ParameterValue" IS '[KS X 9101 표준] 파라미터값: — 이벤트가 발생하여 수집된 파라미터 데이터의 값(파라미터값의 단위는 파라미터단위코드로 함)';
COMMENT ON COLUMN "TraceParameter"."ValidationResultCode" IS '[KS X 9101 표준] 검증결과코드: — 수집된 파라미터 데이터가 정상범위 안에 들어가는지, 아니면 허용상한치를 초과하거나 허용하한치에 미달하는지를 의미
— 검증 결과(예: Normal(정상), OverUSL(상한 초과), UnderLSL(하한 미달))
— 참조 대상: 공통코드정보(CommonCodeMaster)의 코드';

-- ---------------------------------------------------------------------
-- [표준 구분: KS X 9101 표준] 표 63, 조항 7.4.6.20 | 업무영역: 생산관리
-- 테이블명(물리): "ProductionPerformance" | 테이블명(논리): 생산실적
-- 설명: 생산지시에 의해 실행된 생산의 실적 결과 정보를 의미한다.
-- ---------------------------------------------------------------------
CREATE TABLE "ProductionPerformance" ( -- [KS X 9101 표준] 생산실적 (표 63)
    "ProductionPerformanceSequenceNo" BIGINT GENERATED BY DEFAULT AS IDENTITY, -- [KS X 9101 표준] 생산실적 일련번호(PK)
    "EnterpriseID" VARCHAR(50) NOT NULL, -- [KS X 9101 표준] 회사식별자
    "SiteID" VARCHAR(50) NOT NULL, -- [KS X 9101 표준] 사업장식별자
    "PlantID" VARCHAR(50) NOT NULL, -- [KS X 9101 표준] 공장식별자
    "CreatorID" VARCHAR(50), -- [KS X 9101 표준] 등록자식별자
    "CreationDateTime" TIMESTAMP, -- [KS X 9101 표준] 등록일시
    "ModifierID" VARCHAR(50), -- [KS X 9101 표준] 수정자식별자
    "ModificationDateTime" TIMESTAMP, -- [KS X 9101 표준] 수정일시
    "Note" VARCHAR(1000), -- [KS X 9101 표준] 비고
    "ProductionPerformanceID" VARCHAR(50) NOT NULL, -- [KS X 9101 표준] 생산실적식별자
    "ProductionPerformanceSequence" INTEGER NOT NULL, -- [KS X 9101 표준] 생산실적순번
    "ProductionOrderID" VARCHAR(50), -- [KS X 9101 표준] 생산지시식별자
    "ProductionOrderSequence" INTEGER, -- [KS X 9101 표준] 생산지시순번
    "ItemID" VARCHAR(50), -- [KS X 9101 표준] 품목식별자
    "ItemUOMCode" VARCHAR(20), -- [KS X 9101 표준] 기준단위코드
    "ProducedQuantity" NUMERIC(18,6), -- [KS X 9101 표준] 생산수량
    "DefectQuantity" NUMERIC(18,6), -- [KS X 9101 표준] 불량수량
    "ReworkQuantity" INTEGER, -- [KS X 9101 표준] 재작업수량
    "OperationID" VARCHAR(50), -- [KS X 9101 표준] 공정식별자
    "RoutingID" VARCHAR(50), -- [KS X 9101 표준] 공정경로식별자
    "OperationSequence" INTEGER, -- [KS X 9101 표준] 공정순번
    "PersonnelID" VARCHAR(50), -- [KS X 9101 표준] 사원식별자
    "ProductionPerformanceDate" DATE, -- [KS X 9101 표준] 생산실적일자
    "ExecutionStartDateTime" TIMESTAMP, -- [KS X 9101 표준] 생산시작일시
    "ExecutionEndDateTime" TIMESTAMP, -- [KS X 9101 표준] 생산종료일시
    "CancelIndicator" BOOLEAN, -- [KS X 9101 표준] 취소여부
    "CancelDateTime" TIMESTAMP, -- [KS X 9101 표준] 취소일시
    "LotID" VARCHAR(50), -- [KS X 9101 표준] 로트식별자
    "BatchID" VARCHAR(50), -- [KS X 9101 표준] 배치식별자
    CONSTRAINT "PK_ProductionPerformance" PRIMARY KEY ("ProductionPerformanceSequenceNo"),
    CONSTRAINT "UK_ProductionPerformance" UNIQUE ("EnterpriseID", "ProductionPerformanceID", "ProductionPerformanceSequence")
);

COMMENT ON TABLE "ProductionPerformance" IS '[KS X 9101 표준] 생산실적 (생산지시에 의해 실행된 생산의 실적 결과 정보를 의미한다.)';
COMMENT ON COLUMN "ProductionPerformance"."ProductionPerformanceSequenceNo" IS '[KS X 9101 표준] 생산실적 일련번호: — 테이블 행을 식별하는 일련번호(PK, 대리키) — 표준 외 물리 컬럼
— 자동 증가 값(IDENTITY)으로 부여하며 다른 테이블이 참조하지 않음(FK는 UK 참조)';
COMMENT ON COLUMN "ProductionPerformance"."EnterpriseID" IS '[KS X 9101 표준] 회사식별자: — 회사를 유일하게 구분할 수 있는 고유식별값
— 기업업무시스템 간의 연동을 수행하는 회사들 간에 자체적으로 정의한 고유식별값
— 참조 대상: 회사(Enterprise)';
COMMENT ON COLUMN "ProductionPerformance"."SiteID" IS '[KS X 9101 표준] 사업장식별자: — 회사 내에서 사업장을 구분할수 있는 고유식별값
— 참조 대상: 사업장(Site)';
COMMENT ON COLUMN "ProductionPerformance"."PlantID" IS '[KS X 9101 표준] 공장식별자: — 회사 내에서 공장을 구분할 수있는 고유식별값(만약, 공장 개념을 사용하지 않는다면 고정식별자로 설정하여 입력해야 함)
— 참조 대상: 공장(Plant)';
COMMENT ON COLUMN "ProductionPerformance"."CreatorID" IS '[KS X 9101 표준] 등록자식별자: — 정보를 처음으로 등록한 사람을 구분할 수 있는 고유식별값으로, 일반적으로 사원번호가사용됨
— 참조 대상: 사원(Personnel)';
COMMENT ON COLUMN "ProductionPerformance"."CreationDateTime" IS '[KS X 9101 표준] 등록일시: — 정보를 처음으로 등록한 날짜 (KS X ISO 8601을 따른다)';
COMMENT ON COLUMN "ProductionPerformance"."ModifierID" IS '[KS X 9101 표준] 수정자식별자: — 정보를 마지막으로 수정한 사람을 구분할 수 있는 고유식별값으로, 일반적으로 사원번호가 사용됨
— 참조 대상: 사원(Personnel)';
COMMENT ON COLUMN "ProductionPerformance"."ModificationDateTime" IS '[KS X 9101 표준] 수정일시: — 정보를 마지막으로 수정한 날짜 (KS X ISO 8601을 따른다.)';
COMMENT ON COLUMN "ProductionPerformance"."Note" IS '[KS X 9101 표준] 비고: — 비고사항';
COMMENT ON COLUMN "ProductionPerformance"."ProductionPerformanceID" IS '[KS X 9101 표준] 생산실적식별자: — 생산실적을 식별하기 위한 고유값
— 생산실적 단위로 부여하며, 한 생산실적에 속한 모든 실적 행에 같은 값을 사용함';
COMMENT ON COLUMN "ProductionPerformance"."ProductionPerformanceSequence" IS '[KS X 9101 표준] 생산실적순번: — 생산실적이 발생한 순서
— 생산실적 행은 생산실적식별자와 생산실적순번의 조합으로 구분하며, 생산실적투입품목·생산실적투입인력·설비활용실적·생산품질실적은 이 조합으로 생산실적을 참조함';
COMMENT ON COLUMN "ProductionPerformance"."ProductionOrderID" IS '[KS X 9101 표준] 생산지시식별자: — 생산지시를 식별하기 위한 고유값 (생산실적을 생성한 생산지시의 ID를 입력)
— 참조 대상: 생산지시(ProductionOrder)';
COMMENT ON COLUMN "ProductionPerformance"."ProductionOrderSequence" IS '[KS X 9101 표준] 생산지시순번: — 생산지시식별자 내 순서 (생산실적을 생성한 생산지시의 순번을 입력)
— 생산지시식별자(ProductionOrderID)와 함께 생산지시(ProductionOrder)를 참조한다';
COMMENT ON COLUMN "ProductionPerformance"."ItemID" IS '[KS X 9101 표준] 품목식별자: — 품목을 식별하기 위한 고유값
— 제품, 반제품, 상품, 원자재, 부자재, 저장품, 소모품 등 회사내 시스템으로 관리되는 모든 품목을 포함
— 참조 대상: 품목마스터(ItemMaster)';
COMMENT ON COLUMN "ProductionPerformance"."ItemUOMCode" IS '[KS X 9101 표준] 기준단위코드: — 기준단위코드(예: EA, DZ, HD 등)
— 참조 대상: 단위그룹(UOMGroup)의 단위코드';
COMMENT ON COLUMN "ProductionPerformance"."ProducedQuantity" IS '[KS X 9101 표준] 생산수량: — 생산된 품목의 전체 수량(수량의 단위는 기준단위코드로 함)';
COMMENT ON COLUMN "ProductionPerformance"."DefectQuantity" IS '[KS X 9101 표준] 불량수량: — 생산된 품목의 전체 수량 중 불량수량(수량의 단위는 기준단위코드로 함)';
COMMENT ON COLUMN "ProductionPerformance"."ReworkQuantity" IS '[KS X 9101 표준] 재작업수량: — 불량수량 중 재작업을 수행한 수량';
COMMENT ON COLUMN "ProductionPerformance"."OperationID" IS '[KS X 9101 표준] 공정식별자: — 공정을 식별하기 위한 고유값
— 참조 대상: 공정(Operation)';
COMMENT ON COLUMN "ProductionPerformance"."RoutingID" IS '[KS X 9101 표준] 공정경로식별자: — 공정경로를 식별하기 위한 고유값
— 참조 대상: 공정경로(Routing)';
COMMENT ON COLUMN "ProductionPerformance"."OperationSequence" IS '[KS X 9101 표준] 공정순번: — 공정경로를 구성하는 공정의 순서
— 공정경로식별자(RoutingID)와 함께 공정경로(Routing)를 참조한다';
COMMENT ON COLUMN "ProductionPerformance"."PersonnelID" IS '[KS X 9101 표준] 사원식별자: — 인사조직 내 사원을 식별하기 위한 고유값
— 생산실적을 취합 관리하는 담당자의 식별정보
— 참조 대상: 사원(Personnel)';
COMMENT ON COLUMN "ProductionPerformance"."ProductionPerformanceDate" IS '[KS X 9101 표준] 생산실적일자: — 생산실적이 발생한 일자';
COMMENT ON COLUMN "ProductionPerformance"."ExecutionStartDateTime" IS '[KS X 9101 표준] 생산시작일시: — 생산지시에 따라 작업이 시작된 실제 생산시작일(KS X ISO 8601을 따른다)';
COMMENT ON COLUMN "ProductionPerformance"."ExecutionEndDateTime" IS '[KS X 9101 표준] 생산종료일시: — 생산지시에 따라 작업이 끝난 실제 생산종료일(KS X ISO 8601을 따른다)';
COMMENT ON COLUMN "ProductionPerformance"."CancelIndicator" IS '[KS X 9101 표준] 취소여부: — 생산실적 무효화 여부';
COMMENT ON COLUMN "ProductionPerformance"."CancelDateTime" IS '[KS X 9101 표준] 취소일시: — 생산실적을 무효화할 경우 무효화한 일자(KS X ISO 8601을 따른다)';
COMMENT ON COLUMN "ProductionPerformance"."LotID" IS '[KS X 9101 표준] 로트식별자: — 생산실적에 포함된 로트의 고유식별값
— 참조 대상: 로트(Lot)';
COMMENT ON COLUMN "ProductionPerformance"."BatchID" IS '[KS X 9101 표준] 배치식별자: — 생산실적에 포함된 배치의 고유식별값
— 참조 대상: 배치(Batch)';

-- ---------------------------------------------------------------------
-- [표준 구분: KS X 9101 표준] 표 64, 조항 7.4.6.21 | 업무영역: 생산관리
-- 테이블명(물리): "ProductionPerformanceItem" | 테이블명(논리): 생산실적투입품목
-- 설명: 생산 과정에서 투입되는 모든 품목(원자재, 부자재, 반제품, 완제품 등) 관련 정보를 의미한다.
-- ---------------------------------------------------------------------
CREATE TABLE "ProductionPerformanceItem" ( -- [KS X 9101 표준] 생산실적투입품목 (표 64)
    "ProductionPerformanceItemSequenceNo" BIGINT GENERATED BY DEFAULT AS IDENTITY, -- [KS X 9101 표준] 생산실적투입품목 일련번호(PK)
    "EnterpriseID" VARCHAR(50) NOT NULL, -- [KS X 9101 표준] 회사식별자
    "SiteID" VARCHAR(50) NOT NULL, -- [KS X 9101 표준] 사업장식별자
    "PlantID" VARCHAR(50) NOT NULL, -- [KS X 9101 표준] 공장식별자
    "CreatorID" VARCHAR(50), -- [KS X 9101 표준] 등록자식별자
    "CreationDateTime" TIMESTAMP, -- [KS X 9101 표준] 등록일시
    "ModifierID" VARCHAR(50), -- [KS X 9101 표준] 수정자식별자
    "ModificationDateTime" TIMESTAMP, -- [KS X 9101 표준] 수정일시
    "Note" VARCHAR(1000), -- [KS X 9101 표준] 비고
    "ProductionPerformanceID" VARCHAR(50) NOT NULL, -- [KS X 9101 표준] 생산실적식별자
    "ProductionPerformanceSequence" INTEGER NOT NULL, -- [KS X 9101 표준] 생산실적순번
    "ProductionOrderID" VARCHAR(50), -- [KS X 9101 표준] 생산지시식별자
    "ProductionOrderSequence" INTEGER, -- [KS X 9101 표준] 생산지시순번
    "ItemID" VARCHAR(50) NOT NULL, -- [KS X 9101 표준] 품목식별자
    "ItemUOMCode" VARCHAR(20), -- [KS X 9101 표준] 기준단위코드
    "LineID" VARCHAR(50), -- [KS X 9101 표준] 라인식별자
    "OperationID" VARCHAR(50), -- [KS X 9101 표준] 공정식별자
    "LotID" VARCHAR(50), -- [KS X 9101 표준] 로트식별자
    "ReplacementChildItemID" VARCHAR(50), -- [KS X 9101 표준] 대체자재식별자
    "WarehouseID" VARCHAR(50), -- [KS X 9101 표준] 창고식별자
    "WarehouseSection" VARCHAR(255), -- [KS X 9101 표준] 창고섹션
    "RequiredQuantity" INTEGER, -- [KS X 9101 표준] 소요수량
    "IssuedQuantity" INTEGER, -- [KS X 9101 표준] 출고수량
    "IssuedIndicator" BOOLEAN, -- [KS X 9101 표준] 출고완료여부
    CONSTRAINT "PK_ProductionPerformanceItem" PRIMARY KEY ("ProductionPerformanceItemSequenceNo"),
    CONSTRAINT "UK_ProductionPerformanceItem" UNIQUE ("EnterpriseID", "ProductionPerformanceID", "ProductionPerformanceSequence", "ItemID")
);

COMMENT ON TABLE "ProductionPerformanceItem" IS '[KS X 9101 표준] 생산실적투입품목 (생산 과정에서 투입되는 모든 품목(원자재, 부자재, 반제품, 완제품 등) 관련 정보를 의미한다.)';
COMMENT ON COLUMN "ProductionPerformanceItem"."ProductionPerformanceItemSequenceNo" IS '[KS X 9101 표준] 생산실적투입품목 일련번호: — 테이블 행을 식별하는 일련번호(PK, 대리키) — 표준 외 물리 컬럼
— 자동 증가 값(IDENTITY)으로 부여하며 다른 테이블이 참조하지 않음(FK는 UK 참조)';
COMMENT ON COLUMN "ProductionPerformanceItem"."EnterpriseID" IS '[KS X 9101 표준] 회사식별자: — 회사를 유일하게 구분할 수 있는 고유식별값
— 기업업무시스템 간의 연동을 수행하는 회사들 간에 자체적으로 정의한 고유식별값
— 참조 대상: 회사(Enterprise)';
COMMENT ON COLUMN "ProductionPerformanceItem"."SiteID" IS '[KS X 9101 표준] 사업장식별자: — 회사 내에서 사업장을 구분할수 있는 고유식별값
— 참조 대상: 사업장(Site)';
COMMENT ON COLUMN "ProductionPerformanceItem"."PlantID" IS '[KS X 9101 표준] 공장식별자: — 회사 내에서 공장을 구분할 수있는 고유식별값(만약, 공장 개념을 사용하지 않는다면 고정식별자로 설정하여 입력해야 함)
— 참조 대상: 공장(Plant)';
COMMENT ON COLUMN "ProductionPerformanceItem"."CreatorID" IS '[KS X 9101 표준] 등록자식별자: — 정보를 처음으로 등록한 사람을 구분할 수 있는 고유식별값으로, 일반적으로 사원번호가사용됨
— 참조 대상: 사원(Personnel)';
COMMENT ON COLUMN "ProductionPerformanceItem"."CreationDateTime" IS '[KS X 9101 표준] 등록일시: — 정보를 처음으로 등록한 날짜 (KS X ISO 8601을 따른다)';
COMMENT ON COLUMN "ProductionPerformanceItem"."ModifierID" IS '[KS X 9101 표준] 수정자식별자: — 정보를 마지막으로 수정한 사람을 구분할 수 있는 고유식별값으로, 일반적으로 사원번호가 사용됨
— 참조 대상: 사원(Personnel)';
COMMENT ON COLUMN "ProductionPerformanceItem"."ModificationDateTime" IS '[KS X 9101 표준] 수정일시: — 정보를 마지막으로 수정한 날짜 (KS X ISO 8601을 따른다.)';
COMMENT ON COLUMN "ProductionPerformanceItem"."Note" IS '[KS X 9101 표준] 비고: — 비고사항';
COMMENT ON COLUMN "ProductionPerformanceItem"."ProductionPerformanceID" IS '[KS X 9101 표준] 생산실적식별자: — 생산실적을 식별하기 위한 고유값
— 참조 대상: 생산실적(ProductionPerformance)';
COMMENT ON COLUMN "ProductionPerformanceItem"."ProductionPerformanceSequence" IS '[KS X 9101 표준] 생산실적순번: — 생산실적이 발생한 순서
— 생산실적식별자(ProductionPerformanceID)와 함께 생산실적(ProductionPerformance)을 참조한다';
COMMENT ON COLUMN "ProductionPerformanceItem"."ProductionOrderID" IS '[KS X 9101 표준] 생산지시식별자: — 생산지시를 식별하기 위한 고유값 (생산실적을 생성한 생산지시의 ID를 입력)
— 참조 대상: 생산지시(ProductionOrder)';
COMMENT ON COLUMN "ProductionPerformanceItem"."ProductionOrderSequence" IS '[KS X 9101 표준] 생산지시순번: — 생산지시식별자 내 순서 (생산실적을 생성한 생산지시의 순번을 입력)
— 생산지시식별자(ProductionOrderID)와 함께 생산지시(ProductionOrder)를 참조한다';
COMMENT ON COLUMN "ProductionPerformanceItem"."ItemID" IS '[KS X 9101 표준] 품목식별자: — 품목을 식별하기 위한 고유값
— 제품, 반제품, 상품, 원자재, 부자재, 저장품, 소모품 등 회사내 시스템으로 관리되는 모든 품목을 포함
— 참조 대상: 품목마스터(ItemMaster)
— 생산실적투입품목 행은 생산실적식별자, 생산실적순번, 품목식별자의 조합으로 구분하며, 조합에 포함되는 속성은 값을 생략할 수 없음(7.1)';
COMMENT ON COLUMN "ProductionPerformanceItem"."ItemUOMCode" IS '[KS X 9101 표준] 기준단위코드: — 기준단위코드(예: EA, DZ, HD 등)
— 참조 대상: 단위그룹(UOMGroup)의 단위코드';
COMMENT ON COLUMN "ProductionPerformanceItem"."LineID" IS '[KS X 9101 표준] 라인식별자: — 라인을 식별하기 위한 고유값
— 참조 대상: 라인(Line)';
COMMENT ON COLUMN "ProductionPerformanceItem"."OperationID" IS '[KS X 9101 표준] 공정식별자: — 공정을 식별하기 위한 고유값
— 참조 대상: 공정(Operation)';
COMMENT ON COLUMN "ProductionPerformanceItem"."LotID" IS '[KS X 9101 표준] 로트식별자: — 생산실적에 포함된 로트의 고유식별값
— 참조 대상: 로트(Lot)';
COMMENT ON COLUMN "ProductionPerformanceItem"."ReplacementChildItemID" IS '[KS X 9101 표준] 대체자재식별자: — 품목의 품절 등의 사유로 생산에 투입될 수 없을 때 대체할 수 있는 품목
— 참조 대상: 품목마스터(ItemMaster)';
COMMENT ON COLUMN "ProductionPerformanceItem"."WarehouseID" IS '[KS X 9101 표준] 창고식별자: — 창고를 식별하기 위한 고유값
— 참조 대상: 창고(WarehouseLocation)';
COMMENT ON COLUMN "ProductionPerformanceItem"."WarehouseSection" IS '[KS X 9101 표준] 창고섹션: — 창고 내 저장 섹션(창고 하위 개념)
— 창고식별자(WarehouseID)와 함께 창고(WarehouseLocation)의 창고라인을 참조한다';
COMMENT ON COLUMN "ProductionPerformanceItem"."RequiredQuantity" IS '[KS X 9101 표준] 소요수량: — 투입된 품목의 소요수량(수량의 단위는 기준단위코드로함)
— 소요수량은 생산지시에 의해 설정된 계획수량 개념을의미함';
COMMENT ON COLUMN "ProductionPerformanceItem"."IssuedQuantity" IS '[KS X 9101 표준] 출고수량: — 출고수량(수량의 단위는 기준단위코드로 함)';
COMMENT ON COLUMN "ProductionPerformanceItem"."IssuedIndicator" IS '[KS X 9101 표준] 출고완료여부: — 투입된 품목의 실제 수량이 모두 투입되었는지 여부';

-- ---------------------------------------------------------------------
-- [표준 구분: KS X 9101 표준] 표 65, 조항 7.4.6.22 | 업무영역: 생산관리
-- 테이블명(물리): "ProductionPerformancePersonnel" | 테이블명(논리): 생산실적투입인력
-- 설명: 생산 과정에서 투입된 인력정보를 의미한다. 생산실적투입인력 명사는 표 65와같은 정보 속성을 포함하고 있다.
-- ---------------------------------------------------------------------
CREATE TABLE "ProductionPerformancePersonnel" ( -- [KS X 9101 표준] 생산실적투입인력 (표 65)
    "ProductionPerformancePersonnelSequenceNo" BIGINT GENERATED BY DEFAULT AS IDENTITY, -- [KS X 9101 표준] 생산실적투입인력 일련번호(PK)
    "EnterpriseID" VARCHAR(50) NOT NULL, -- [KS X 9101 표준] 회사식별자
    "SiteID" VARCHAR(50) NOT NULL, -- [KS X 9101 표준] 사업장식별자
    "PlantID" VARCHAR(50) NOT NULL, -- [KS X 9101 표준] 공장식별자
    "CreatorID" VARCHAR(50), -- [KS X 9101 표준] 등록자식별자
    "CreationDateTime" TIMESTAMP, -- [KS X 9101 표준] 등록일시
    "ModifierID" VARCHAR(50), -- [KS X 9101 표준] 수정자식별자
    "ModificationDateTime" TIMESTAMP, -- [KS X 9101 표준] 수정일시
    "Note" VARCHAR(1000), -- [KS X 9101 표준] 비고
    "ProductionPerformanceID" VARCHAR(50) NOT NULL, -- [KS X 9101 표준] 생산실적식별자
    "ProductionPerformanceSequence" INTEGER NOT NULL, -- [KS X 9101 표준] 생산실적순번
    "ProductionOrderID" VARCHAR(50), -- [KS X 9101 표준] 생산지시식별자
    "ProductionOrderSequence" INTEGER, -- [KS X 9101 표준] 생산지시순번
    "OperationID" VARCHAR(50), -- [KS X 9101 표준] 공정식별자
    "PersonnelID" VARCHAR(50) NOT NULL, -- [KS X 9101 표준] 사원식별자
    "ExecutionStartDateTime" TIMESTAMP, -- [KS X 9101 표준] 생산시작일시
    "ExecutionEndDateTime" TIMESTAMP, -- [KS X 9101 표준] 생산종료일시
    "TaskGroupCode" VARCHAR(30), -- [KS X 9101 표준] 근무조코드
    "ActualLaborDateTime" TIMESTAMP, -- [KS X 9101 표준] 투입일시
    "ActualLaborTime" NUMERIC(18,6), -- [KS X 9101 표준] 투입시간
    "ActualLaborTimeUOMCode" VARCHAR(20), -- [KS X 9101 표준] 투입시간단위코드
    CONSTRAINT "PK_ProductionPerformancePersonnel" PRIMARY KEY ("ProductionPerformancePersonnelSequenceNo"),
    CONSTRAINT "UK_ProductionPerformancePersonnel" UNIQUE ("EnterpriseID", "ProductionPerformanceID", "ProductionPerformanceSequence", "PersonnelID")
);

COMMENT ON TABLE "ProductionPerformancePersonnel" IS '[KS X 9101 표준] 생산실적투입인력 (생산 과정에서 투입된 인력정보를 의미한다. 생산실적투입인력 명사는 표 65와같은 정보 속성을 포함하고 있다.)';
COMMENT ON COLUMN "ProductionPerformancePersonnel"."ProductionPerformancePersonnelSequenceNo" IS '[KS X 9101 표준] 생산실적투입인력 일련번호: — 테이블 행을 식별하는 일련번호(PK, 대리키) — 표준 외 물리 컬럼
— 자동 증가 값(IDENTITY)으로 부여하며 다른 테이블이 참조하지 않음(FK는 UK 참조)';
COMMENT ON COLUMN "ProductionPerformancePersonnel"."EnterpriseID" IS '[KS X 9101 표준] 회사식별자: — 회사를 유일하게 구분할 수 있는 고유식별값
