    "Note" VARCHAR(1000), -- [KS X 9101 표준] 비고
    "ProductionPerformanceID" VARCHAR(50) NOT NULL, -- [KS X 9101 표준] 생산실적식별자
    "ProductionPerformanceSequence" INTEGER NOT NULL, -- [KS X 9101 표준] 생산실적순번
    "ProductionOrderID" VARCHAR(50), -- [KS X 9101 표준] 생산지시식별자
    "ProductionOrderSequence" INTEGER, -- [KS X 9101 표준] 생산지시순번
    "ItemID" VARCHAR(50), -- [KS X 9101 표준] 품목식별자
    "ItemUOMCode" VARCHAR(20), -- [KS X 9101 표준] 기준단위코드
    "OperationID" VARCHAR(50), -- [KS X 9101 표준] 공정식별자
    "RoutingID" VARCHAR(50), -- [KS X 9101 표준] 공정경로식별자
    "OperationSequence" INTEGER, -- [KS X 9101 표준] 공정순번
    "ExecutionStartDateTime" TIMESTAMP, -- [KS X 9101 표준] 생산시작일시
    "ExecutionEndDateTime" TIMESTAMP, -- [KS X 9101 표준] 생산종료일시
    "LotID" VARCHAR(50), -- [KS X 9101 표준] 로트식별자
    "BatchID" VARCHAR(50), -- [KS X 9101 표준] 배치식별자
    "DefectTypeQuantity" INTEGER, -- [KS X 9101 표준] 불량유형별수량
    "DefectTypeCode" VARCHAR(30) NOT NULL, -- [KS X 9101 표준] 불량유형코드
    "DefectTypeDetailCode" VARCHAR(30) NOT NULL, -- [KS X 9101 표준] 불량유형상세코드
    CONSTRAINT "PK_ProductionPerformanceQuality" PRIMARY KEY ("ProductionPerformanceQualitySequenceNo"),
    CONSTRAINT "UK_ProductionPerformanceQuality" UNIQUE ("EnterpriseID", "ProductionPerformanceID", "ProductionPerformanceSequence", "DefectTypeCode", "DefectTypeDetailCode")
);

COMMENT ON TABLE "ProductionPerformanceQuality" IS '[KS X 9101 표준] 생산품질실적 (생산 과정에서 발생한 품질정보를 의미한다.)';
COMMENT ON COLUMN "ProductionPerformanceQuality"."ProductionPerformanceQualitySequenceNo" IS '[KS X 9101 표준] 생산품질실적 일련번호: — 테이블 행을 식별하는 일련번호(PK, 대리키) — 표준 외 물리 컬럼
— 자동 증가 값(IDENTITY)으로 부여하며 다른 테이블이 참조하지 않음(FK는 UK 참조)';
COMMENT ON COLUMN "ProductionPerformanceQuality"."EnterpriseID" IS '[KS X 9101 표준] 회사식별자: — 회사를 유일하게 구분할 수 있는 고유식별값
