COMMENT ON COLUMN "ProductionPerformanceQuality"."SiteID" IS '[KS X 9101 표준] 사업장식별자: — 회사 내에서 사업장을 구분할수 있는 고유식별값
— 참조 대상: 사업장(Site)';
COMMENT ON COLUMN "ProductionPerformanceQuality"."PlantID" IS '[KS X 9101 표준] 공장식별자: — 회사 내에서 공장을 구분할 수있는 고유식별값(만약, 공장 개념을 사용하지 않는다면 고정식별자로 설정하여 입력해야 함)
— 참조 대상: 공장(Plant)';
COMMENT ON COLUMN "ProductionPerformanceQuality"."CreatorID" IS '[KS X 9101 표준] 등록자식별자: — 정보를 처음으로 등록한 사람을 구분할 수 있는 고유식별값으로, 일반적으로 사원번호가사용됨
— 참조 대상: 사원(Personnel)';
COMMENT ON COLUMN "ProductionPerformanceQuality"."CreationDateTime" IS '[KS X 9101 표준] 등록일시: — 정보를 처음으로 등록한 날짜 (KS X ISO 8601을 따른다)';
COMMENT ON COLUMN "ProductionPerformanceQuality"."ModifierID" IS '[KS X 9101 표준] 수정자식별자: — 정보를 마지막으로 수정한 사람을 구분할 수 있는 고유식별값으로, 일반적으로 사원번호가 사용됨
— 참조 대상: 사원(Personnel)';
COMMENT ON COLUMN "ProductionPerformanceQuality"."ModificationDateTime" IS '[KS X 9101 표준] 수정일시: — 정보를 마지막으로 수정한 날짜 (KS X ISO 8601을 따른다.)';
COMMENT ON COLUMN "ProductionPerformanceQuality"."Note" IS '[KS X 9101 표준] 비고: — 비고사항';
COMMENT ON COLUMN "ProductionPerformanceQuality"."ProductionPerformanceID" IS '[KS X 9101 표준] 생산실적식별자: — 생산실적을 식별하기 위한 고유값
— 참조 대상: 생산실적(ProductionPerformance)';
COMMENT ON COLUMN "ProductionPerformanceQuality"."ProductionPerformanceSequence" IS '[KS X 9101 표준] 생산실적순번: — 생산실적이 발생한 순서
— 생산실적식별자(ProductionPerformanceID)와 함께 생산실적(ProductionPerformance)을 참조한다';
COMMENT ON COLUMN "ProductionPerformanceQuality"."ProductionOrderID" IS '[KS X 9101 표준] 생산지시식별자: — 생산지시를 식별하기 위한 고유값
— (생산실적을 생성한 생산지시식별자를 입력)
— 참조 대상: 생산지시(ProductionOrder)';
COMMENT ON COLUMN "ProductionPerformanceQuality"."ProductionOrderSequence" IS '[KS X 9101 표준] 생산지시순번: — 생산지시식별자 내 순서
— (생산실적을 생성한 생산지시의 순번을 입력)
— 생산지시식별자(ProductionOrderID)와 함께 생산지시(ProductionOrder)를 참조한다';
COMMENT ON COLUMN "ProductionPerformanceQuality"."ItemID" IS '[KS X 9101 표준] 품목식별자: — 품목을 식별하기 위한 고유값
— 제품, 반제품, 상품, 원자재, 부자재, 저장품, 소모품 등 회사내 시스템으로 관리되는 모든 품목을 포함
— 참조 대상: 품목마스터(ItemMaster)';
COMMENT ON COLUMN "ProductionPerformanceQuality"."ItemUOMCode" IS '[KS X 9101 표준] 기준단위코드: — 기준단위코드(예: EA, DZ, HD 등)
— 참조 대상: 단위그룹(UOMGroup)의 단위코드';
COMMENT ON COLUMN "ProductionPerformanceQuality"."OperationID" IS '[KS X 9101 표준] 공정식별자: — 공정을 식별하기 위한 고유값
— 참조 대상: 공정(Operation)';
COMMENT ON COLUMN "ProductionPerformanceQuality"."RoutingID" IS '[KS X 9101 표준] 공정경로식별자: — 공정경로를 식별하기 위한 고유값
— 참조 대상: 공정경로(Routing)';
COMMENT ON COLUMN "ProductionPerformanceQuality"."OperationSequence" IS '[KS X 9101 표준] 공정순번: — 공정 경로를 구성하는 공정의 순서
— 공정경로식별자(RoutingID)와 함께 공정경로(Routing)를 참조한다';
COMMENT ON COLUMN "ProductionPerformanceQuality"."ExecutionStartDateTime" IS '[KS X 9101 표준] 생산시작일시: — 생산지시에 따라 작업이 시작된 실제 생산시작일(KS X ISO 8601을 따른다)';
COMMENT ON COLUMN "ProductionPerformanceQuality"."ExecutionEndDateTime" IS '[KS X 9101 표준] 생산종료일시: — 생산지시에 따라 작업이 끝난 실제 생산종료일(KS X ISO 8601을 따른다)';
COMMENT ON COLUMN "ProductionPerformanceQuality"."LotID" IS '[KS X 9101 표준] 로트식별자: — 생산실적에 포함된 로트의 고유식별값
— 참조 대상: 로트(Lot)';
COMMENT ON COLUMN "ProductionPerformanceQuality"."BatchID" IS '[KS X 9101 표준] 배치식별자: — 생산실적에 포함된 배치의 고유식별값
— 참조 대상: 배치(Batch)';
COMMENT ON COLUMN "ProductionPerformanceQuality"."DefectTypeQuantity" IS '[KS X 9101 표준] 불량유형별수량: — 불량유형별 수량(수량의 단위는 기준단위 코드로 함)';
COMMENT ON COLUMN "ProductionPerformanceQuality"."DefectTypeCode" IS '[KS X 9101 표준] 불량유형코드: — 불량의 유형을 나타내는 코드값
— 공통코드에 등록하여 관리하며 회사 기준 분류체계에 의해정해짐
— 예: 외관불량, 치수불량, 기능불량, 재질불량, 조립불량, 포장불량 등
— 참조 대상: 공통코드정보(CommonCodeMaster)의 코드';
COMMENT ON COLUMN "ProductionPerformanceQuality"."DefectTypeDetailCode" IS '[KS X 9101 표준] 불량유형상세코드: — 불량의 상세한 유형을 나타내는 코드값
— 불량내역코드는 공통코드에 등록하여 관리하며 회사 기준 분류체계에 의해 정해짐(불량유형 하위에 속함)
— 예: 불량유형 외관불량 하위의 스크래치, 찍힘, 얼룩·오염, 버, 크랙 등
— 참조 대상: 공통코드정보(CommonCodeMaster)의 코드
— 생산품질실적 행은 생산실적식별자, 생산실적순번, 불량유형코드, 불량유형상세코드의 조합으로 구분하며, 조합에 포함되는 속성은 값을 생략할 수 없음(7.1)';

-- ---------------------------------------------------------------------
-- [표준 구분: KS X 9101 표준] 표 68, 조항 7.4.7.1 | 업무영역: 재고관리
-- 테이블명(물리): "Inventory" | 테이블명(논리): 재고
-- 설명: 저장위치에 있는 품목의 실제 보유(On-hand) 수량을 의미한다.
-- ---------------------------------------------------------------------
CREATE TABLE "Inventory" ( -- [KS X 9101 표준] 재고 (표 68)
    "InventorySequenceNo" BIGINT GENERATED BY DEFAULT AS IDENTITY, -- [KS X 9101 표준] 재고 일련번호(PK)
    "EnterpriseID" VARCHAR(50) NOT NULL, -- [KS X 9101 표준] 회사식별자
    "SiteID" VARCHAR(50) NOT NULL, -- [KS X 9101 표준] 사업장식별자
    "PlantID" VARCHAR(50) NOT NULL, -- [KS X 9101 표준] 공장식별자
    "CreatorID" VARCHAR(50), -- [KS X 9101 표준] 등록자식별자
    "CreationDateTime" TIMESTAMP, -- [KS X 9101 표준] 등록일시
    "ModifierID" VARCHAR(50), -- [KS X 9101 표준] 수정자식별자
    "ModificationDateTime" TIMESTAMP, -- [KS X 9101 표준] 수정일시
    "Note" VARCHAR(1000), -- [KS X 9101 표준] 비고
    "WarehouseID" VARCHAR(50) NOT NULL, -- [KS X 9101 표준] 창고식별자
    "ItemID" VARCHAR(50) NOT NULL, -- [KS X 9101 표준] 품목식별자
    "InventoryQuantity" NUMERIC(18,6), -- [KS X 9101 표준] 현재고수량
    "ItemUOMCode" VARCHAR(20), -- [KS X 9101 표준] 기준단위코드
    CONSTRAINT "PK_Inventory" PRIMARY KEY ("InventorySequenceNo"),
    CONSTRAINT "UK_Inventory" UNIQUE ("EnterpriseID", "WarehouseID", "ItemID")
);

COMMENT ON TABLE "Inventory" IS '[KS X 9101 표준] 재고 (저장위치에 있는 품목의 실제 보유(On-hand) 수량을 의미한다.)';
COMMENT ON COLUMN "Inventory"."InventorySequenceNo" IS '[KS X 9101 표준] 재고 일련번호: — 테이블 행을 식별하는 일련번호(PK, 대리키) — 표준 외 물리 컬럼
— 자동 증가 값(IDENTITY)으로 부여하며 다른 테이블이 참조하지 않음(FK는 UK 참조)';
COMMENT ON COLUMN "Inventory"."EnterpriseID" IS '[KS X 9101 표준] 회사식별자: — 회사를 유일하게 구분할 수 있는 고유식별값
— 기업업무시스템 간의 연동을 수행하는 회사들 간에 자체적으로 정의한 고유식별값
— 참조 대상: 회사(Enterprise)';
COMMENT ON COLUMN "Inventory"."SiteID" IS '[KS X 9101 표준] 사업장식별자: — 회사 내에서 사업장을 구분할수 있는 고유식별값
— 참조 대상: 사업장(Site)';
COMMENT ON COLUMN "Inventory"."PlantID" IS '[KS X 9101 표준] 공장식별자: — 회사 내에서 공장을 구분할 수있는 고유식별값(만약, 공장 개념을 사용하지 않는다면 고정식별자로 설정하여 입력해야 함)
— 참조 대상: 공장(Plant)';
COMMENT ON COLUMN "Inventory"."CreatorID" IS '[KS X 9101 표준] 등록자식별자: — 정보를 처음으로 등록한 사람을 구분할 수 있는 고유식별값으로, 일반적으로 사원번호가사용됨
— 참조 대상: 사원(Personnel)';
COMMENT ON COLUMN "Inventory"."CreationDateTime" IS '[KS X 9101 표준] 등록일시: — 정보를 처음으로 등록한 날짜 (KS X ISO 8601을 따른다)';
COMMENT ON COLUMN "Inventory"."ModifierID" IS '[KS X 9101 표준] 수정자식별자: — 정보를 마지막으로 수정한 사람을 구분할 수 있는 고유식별값으로, 일반적으로 사원번호가 사용됨
— 참조 대상: 사원(Personnel)';
COMMENT ON COLUMN "Inventory"."ModificationDateTime" IS '[KS X 9101 표준] 수정일시: — 정보를 마지막으로 수정한 날짜 (KS X ISO 8601을 따른다.)';
COMMENT ON COLUMN "Inventory"."Note" IS '[KS X 9101 표준] 비고: — 비고사항';
COMMENT ON COLUMN "Inventory"."WarehouseID" IS '[KS X 9101 표준] 창고식별자: — 창고를 식별하기 위한 고유값
— 참조 대상: 창고(WarehouseLocation)';
COMMENT ON COLUMN "Inventory"."ItemID" IS '[KS X 9101 표준] 품목식별자: — 품목을 식별하기 위한 고유값
— 제품, 반제품, 상품, 원자재, 부자재, 저장품, 소모품 등 회사 내시스템으로 관리되는 모든 품목을 포함
— 참조 대상: 품목마스터(ItemMaster)
— 재고 행은 창고식별자와 품목식별자의 조합으로 구분하며, 조합에 포함되는 속성은 값을 생략할 수 없음(7.1)';
COMMENT ON COLUMN "Inventory"."InventoryQuantity" IS '[KS X 9101 표준] 현재고수량: — 전산시스템 상에 조회되는 현재 재고수량(수량의 단위는 기준단위코드로 함)';
COMMENT ON COLUMN "Inventory"."ItemUOMCode" IS '[KS X 9101 표준] 기준단위코드: — 기준단위코드(예: EA, DZ, HD 등)
— 참조 대상: 단위그룹(UOMGroup)의 단위코드';

-- ---------------------------------------------------------------------
-- [표준 구분: KS X 9101 표준] 표 69, 조항 7.4.7.2 | 업무영역: 재고관리
-- 테이블명(물리): "AvailableInventory" | 테이블명(논리): 가용재고
-- 설명: 현 재고와 특정 시점까지의 예상 입출고를 감안하여 사용 가능한 재고를 의미한다.
-- ---------------------------------------------------------------------
CREATE TABLE "AvailableInventory" ( -- [KS X 9101 표준] 가용재고 (표 69)
    "AvailableInventorySequenceNo" BIGINT GENERATED BY DEFAULT AS IDENTITY, -- [KS X 9101 표준] 가용재고 일련번호(PK)
    "EnterpriseID" VARCHAR(50) NOT NULL, -- [KS X 9101 표준] 회사식별자
    "SiteID" VARCHAR(50) NOT NULL, -- [KS X 9101 표준] 사업장식별자
    "PlantID" VARCHAR(50) NOT NULL, -- [KS X 9101 표준] 공장식별자
    "CreatorID" VARCHAR(50), -- [KS X 9101 표준] 등록자식별자
    "CreationDateTime" TIMESTAMP, -- [KS X 9101 표준] 등록일시
    "ModifierID" VARCHAR(50), -- [KS X 9101 표준] 수정자식별자
    "ModificationDateTime" TIMESTAMP, -- [KS X 9101 표준] 수정일시
    "Note" VARCHAR(1000), -- [KS X 9101 표준] 비고
    "AvailableInventoryID" VARCHAR(50) NOT NULL, -- [KS X 9101 표준] 가용재고식별자
    "ItemID" VARCHAR(50), -- [KS X 9101 표준] 품목식별자
    "ItemName" VARCHAR(200), -- [KS X 9101 표준] 품목명
    "AvailableInventoryQuantity" NUMERIC(18,6), -- [KS X 9101 표준] 가용재고량
    "ItemUOMCode" VARCHAR(20), -- [KS X 9101 표준] 기준단위코드
    "DemandPriority" NUMERIC(18,6), -- [KS X 9101 표준] 요청우선순위
    "PriorDemandQuantity" NUMERIC(18,6), -- [KS X 9101 표준] 요청우선수량
    "ExpectedDeliveryDate" DATE, -- [KS X 9101 표준] 납기예정일
    CONSTRAINT "PK_AvailableInventory" PRIMARY KEY ("AvailableInventorySequenceNo"),
    CONSTRAINT "UK_AvailableInventory" UNIQUE ("EnterpriseID", "AvailableInventoryID")
);

COMMENT ON TABLE "AvailableInventory" IS '[KS X 9101 표준] 가용재고 (현 재고와 특정 시점까지의 예상 입출고를 감안하여 사용 가능한 재고를 의미한다.)';
