-- ---------------------------------------------------------------------
-- [표준 구분: KS X 9101 표준] 표 71, 조항 7.4.7.4 | 업무영역: 재고관리
-- 테이블명(물리): "InventoryCount" | 테이블명(논리): 재고실사
-- 설명: 보관된 재고에 대해 실수량을 파악하기 위한 정보를 의미한다.
-- ---------------------------------------------------------------------
CREATE TABLE "InventoryCount" ( -- [KS X 9101 표준] 재고실사 (표 71)
    "InventoryCountSequenceNo" BIGINT GENERATED BY DEFAULT AS IDENTITY, -- [KS X 9101 표준] 재고실사 일련번호(PK)
    "EnterpriseID" VARCHAR(50) NOT NULL, -- [KS X 9101 표준] 회사식별자
    "SiteID" VARCHAR(50) NOT NULL, -- [KS X 9101 표준] 사업장식별자
    "PlantID" VARCHAR(50) NOT NULL, -- [KS X 9101 표준] 공장식별자
    "CreatorID" VARCHAR(50), -- [KS X 9101 표준] 등록자식별자
    "CreationDateTime" TIMESTAMP, -- [KS X 9101 표준] 등록일시
    "ModifierID" VARCHAR(50), -- [KS X 9101 표준] 수정자식별자
    "ModificationDateTime" TIMESTAMP, -- [KS X 9101 표준] 수정일시
    "Note" VARCHAR(1000), -- [KS X 9101 표준] 비고
    "InventoryCountDocumentNumber" VARCHAR(50) NOT NULL, -- [KS X 9101 표준] 재고실사문서번호
    "InventoryCountDateTime" TIMESTAMP, -- [KS X 9101 표준] 재고실사일시
    "WarehouseID" VARCHAR(50) NOT NULL, -- [KS X 9101 표준] 창고식별자
    "ItemID" VARCHAR(50) NOT NULL, -- [KS X 9101 표준] 품목식별자
    "InventoryQuantity" NUMERIC(18,6), -- [KS X 9101 표준] 현재고수량
    "InventoryCountQuantity" NUMERIC(18,6), -- [KS X 9101 표준] 실사수량
    "ItemUOMCode" VARCHAR(20), -- [KS X 9101 표준] 기준단위코드
    CONSTRAINT "PK_InventoryCount" PRIMARY KEY ("InventoryCountSequenceNo"),
    CONSTRAINT "UK_InventoryCount" UNIQUE ("EnterpriseID", "InventoryCountDocumentNumber", "WarehouseID", "ItemID")
);

