    "ProductIncomingSequenceNo" BIGINT GENERATED BY DEFAULT AS IDENTITY, -- [KS X 9101 표준] 제품입고 일련번호(PK)
    "EnterpriseID" VARCHAR(50) NOT NULL, -- [KS X 9101 표준] 회사식별자
    "SiteID" VARCHAR(50) NOT NULL, -- [KS X 9101 표준] 사업장식별자
    "PlantID" VARCHAR(50) NOT NULL, -- [KS X 9101 표준] 공장식별자
    "CreatorID" VARCHAR(50), -- [KS X 9101 표준] 등록자식별자
    "CreationDateTime" TIMESTAMP, -- [KS X 9101 표준] 등록일시
    "ModifierID" VARCHAR(50), -- [KS X 9101 표준] 수정자식별자
    "ModificationDateTime" TIMESTAMP, -- [KS X 9101 표준] 수정일시
    "Note" VARCHAR(1000), -- [KS X 9101 표준] 비고
    "ProductIncomingID" VARCHAR(50) NOT NULL, -- [KS X 9101 표준] 제품입고식별자
    "ProductIncomingSequence" INTEGER NOT NULL, -- [KS X 9101 표준] 제품입고순번
    "InventoryTransactionDocumentNumber" VARCHAR(50), -- [KS X 9101 표준] 수불문서번호
    "InventoryTransactionDocumentSequence" INTEGER, -- [KS X 9101 표준] 수불문서순번
    "InventoryTransactionDate" DATE, -- [KS X 9101 표준] 수불일
    "ItemID" VARCHAR(50), -- [KS X 9101 표준] 품목식별자
    "CustomerID" VARCHAR(50), -- [KS X 9101 표준] 고객사식별자
    "WarehouseID" VARCHAR(50), -- [KS X 9101 표준] 창고식별자
    "InventoryTransactionTypeCode" VARCHAR(30), -- [KS X 9101 표준] 수불유형코드
    "SerialUseIndicator" BOOLEAN, -- [KS X 9101 표준] 시리얼사용여부
    "InventoryTransferType" VARCHAR(30), -- [KS X 9101 표준] 입출고유형
    "InventoryVariationType" VARCHAR(30), -- [KS X 9101 표준] 재고증감유형
    "InventoryTransactionType" VARCHAR(30), -- [KS X 9101 표준] 수불유형
    "LotControlIndicator" BOOLEAN, -- [KS X 9101 표준] 로트사용여부
    "LotID" VARCHAR(50), -- [KS X 9101 표준] 로트식별자
    "ItemUOMCode" VARCHAR(20), -- [KS X 9101 표준] 기준단위코드
    "ItemUnitQuantity" NUMERIC(18,6), -- [KS X 9101 표준] 기준단위수량
    "OrderUOMCode" VARCHAR(20), -- [KS X 9101 표준] 오더단위코드
    "OrderQuantity" NUMERIC(18,6), -- [KS X 9101 표준] 오더수량
    CONSTRAINT "PK_ProductIncoming" PRIMARY KEY ("ProductIncomingSequenceNo"),
    CONSTRAINT "UK_ProductIncoming" UNIQUE ("EnterpriseID", "ProductIncomingID", "ProductIncomingSequence")
);

COMMENT ON TABLE "ProductIncoming" IS '[KS X 9101 표준] 제품입고 (생산된 제품을 창고에 저장하는 것을 의미한다.)';
COMMENT ON COLUMN "ProductIncoming"."ProductIncomingSequenceNo" IS '[KS X 9101 표준] 제품입고 일련번호: — 테이블 행을 식별하는 일련번호(PK, 대리키) — 표준 외 물리 컬럼
— 자동 증가 값(IDENTITY)으로 부여하며 다른 테이블이 참조하지 않음(FK는 UK 참조)';
COMMENT ON COLUMN "ProductIncoming"."EnterpriseID" IS '[KS X 9101 표준] 회사식별자: — 회사를 유일하게 구분할 수 있는 고유식별값
— 기업업무시스템 간의 연동을 수행하는 회사들 간에 자체적으로 정의한 고유식별값
— 참조 대상: 회사(Enterprise)';
COMMENT ON COLUMN "ProductIncoming"."SiteID" IS '[KS X 9101 표준] 사업장식별자: — 회사 내에서 사업장을 구분할수 있는 고유식별값
— 참조 대상: 사업장(Site)';
COMMENT ON COLUMN "ProductIncoming"."PlantID" IS '[KS X 9101 표준] 공장식별자: — 회사 내에서 공장을 구분할 수있는 고유식별값(만약, 공장 개념을 사용하지 않는다면 고정식별자로 설정하여 입력해야 함)
— 참조 대상: 공장(Plant)';
COMMENT ON COLUMN "ProductIncoming"."CreatorID" IS '[KS X 9101 표준] 등록자식별자: — 정보를 처음으로 등록한 사람을 구분할 수 있는 고유식별값으로, 일반적으로 사원번호가사용됨
— 참조 대상: 사원(Personnel)';
COMMENT ON COLUMN "ProductIncoming"."CreationDateTime" IS '[KS X 9101 표준] 등록일시: — 정보를 처음으로 등록한 날짜 (KS X ISO 8601을 따른다)';
COMMENT ON COLUMN "ProductIncoming"."ModifierID" IS '[KS X 9101 표준] 수정자식별자: — 정보를 마지막으로 수정한 사람을 구분할 수 있는 고유식별값으로, 일반적으로 사원번호가 사용됨
— 참조 대상: 사원(Personnel)';
COMMENT ON COLUMN "ProductIncoming"."ModificationDateTime" IS '[KS X 9101 표준] 수정일시: — 정보를 마지막으로 수정한 날짜 (KS X ISO 8601을 따른다.)';
COMMENT ON COLUMN "ProductIncoming"."Note" IS '[KS X 9101 표준] 비고: — 비고사항';
COMMENT ON COLUMN "ProductIncoming"."ProductIncomingID" IS '[KS X 9101 표준] 제품입고식별자: — 제품입고를 식별하기 위한 고유값
— 제품입고 문서 단위로 부여하며, 한 제품입고 문서에 속한 모든 품목 행에 같은 값을 사용함';
COMMENT ON COLUMN "ProductIncoming"."ProductIncomingSequence" IS '[KS X 9101 표준] 제품입고순번: — 제품입고식별자 내 행의 순서
— 제품입고 행은 제품입고식별자와 제품입고순번의 조합으로 구분함';
COMMENT ON COLUMN "ProductIncoming"."InventoryTransactionDocumentNumber" IS '[KS X 9101 표준] 수불문서번호: — 수불문서번호';
COMMENT ON COLUMN "ProductIncoming"."InventoryTransactionDocumentSequence" IS '[KS X 9101 표준] 수불문서순번: — 수불문서순번';
COMMENT ON COLUMN "ProductIncoming"."InventoryTransactionDate" IS '[KS X 9101 표준] 수불일: — 수불일(KS X ISO 8601을 따른다)';
COMMENT ON COLUMN "ProductIncoming"."ItemID" IS '[KS X 9101 표준] 품목식별자: — 품목을 식별하기 위한 고유값
— 제품, 반제품, 상품, 원자재, 부자재, 저장품, 소모품 등회사 내 시스템으로 관리되는 모든 품목을 포함
— 참조 대상: 품목마스터(ItemMaster)';
COMMENT ON COLUMN "ProductIncoming"."CustomerID" IS '[KS X 9101 표준] 고객사식별자: — 품목을 구매해가는 거래처를 식별하기 위한 고유값
— 참조 대상: 고객사(CustomerPartyMaster)';
COMMENT ON COLUMN "ProductIncoming"."WarehouseID" IS '[KS X 9101 표준] 창고식별자: — 창고를 식별하기 위한 고유값
— 참조 대상: 창고(WarehouseLocation)';
COMMENT ON COLUMN "ProductIncoming"."InventoryTransactionTypeCode" IS '[KS X 9101 표준] 수불유형코드: — 재고 변동(수불)의 성격과 원인을 구분하는 상세 코드로, 입출고유형(이동·조정은 수불유형)의 하위에 속함
— 수불유형코드가 정해지면 수불유형, 입출고유형, 재고증감유형이 정해지며, 함께 기재하는 경우 그 값과 일치해야 함
— 예: 구매입고, 구매입고 취소, 생산출고, 생산출고 반납, 창고간 이동, 실사 조정 등
— 참조 대상: 공통코드정보(CommonCodeMaster)의 코드';
COMMENT ON COLUMN "ProductIncoming"."SerialUseIndicator" IS '[KS X 9101 표준] 시리얼사용여부: — 시리얼사용여부';
COMMENT ON COLUMN "ProductIncoming"."InventoryTransferType" IS '[KS X 9101 표준] 입출고유형: — 입고 또는 출고의 사유로, 수불유형(입고·출고)의 하위에 속함
— 예: 입고는 구매입고, 생산입고, 외주입고, 매출반품입고, 타계정입고 등, 출고는 판매출고, 생산출고, 외주출고, 매입반품출고, 타계정출고, 폐기출고 등
— 참조 대상: 공통코드정보(CommonCodeMaster)의 코드';
COMMENT ON COLUMN "ProductIncoming"."InventoryVariationType" IS '[KS X 9101 표준] 재고증감유형: — 해당 수불이 재고 수량을 증가시키는지 감소시키는지의 구분으로, 수불유형코드에 따라 정해짐(취소 거래는 원거래와 반대)
— 예: 증가, 감소
— 참조 대상: 공통코드정보(CommonCodeMaster)의 코드';
COMMENT ON COLUMN "ProductIncoming"."InventoryTransactionType" IS '[KS X 9101 표준] 수불유형: — 재고 변동의 종류
— 예: 입고, 출고, 이동, 조정
— 참조 대상: 공통코드정보(CommonCodeMaster)의 코드';
COMMENT ON COLUMN "ProductIncoming"."LotControlIndicator" IS '[KS X 9101 표준] 로트사용여부: — 품목의 로트 단위로 관리여부
— 참조 대상: 품목마스터(ItemMaster.LotControlIndicator)';
COMMENT ON COLUMN "ProductIncoming"."LotID" IS '[KS X 9101 표준] 로트식별자: — 제품입고에 포함된 로트의 고유식별값
— 참조 대상: 로트(Lot)';
COMMENT ON COLUMN "ProductIncoming"."ItemUOMCode" IS '[KS X 9101 표준] 기준단위코드: — 기준단위코드(예: EA, DZ, HD 등)
— 참조 대상: 단위그룹(UOMGroup)의 단위코드';
COMMENT ON COLUMN "ProductIncoming"."ItemUnitQuantity" IS '[KS X 9101 표준] 기준단위수량: — 기준단위수량(수량의 단위는 기준단위코드로 함)';
COMMENT ON COLUMN "ProductIncoming"."OrderUOMCode" IS '[KS X 9101 표준] 오더단위코드: — 오더단위코드(예: EA, DZ, HD 등)
— 참조 대상: 단위그룹(UOMGroup)의 단위코드';
COMMENT ON COLUMN "ProductIncoming"."OrderQuantity" IS '[KS X 9101 표준] 오더수량: — 오더수량(수량의 단위는 오더단위코드로 함)';

-- ---------------------------------------------------------------------
-- [표준 구분: KS X 9101 표준] 표 73, 조항 7.4.8.2 | 업무영역: 창고관리
-- 테이블명(물리): "ProductReleaseRequestHeader" | 테이블명(논리): 출하의뢰헤더
-- 설명: 출하의뢰(ProductReleaseRequest) 명사의 헤더 구조체(struct) 출하의뢰 문서 1건의 공통 정보(납품문서번호, 납품구분유형, 납품지시일, 고객사) 출하의뢰마다 1회 나타남
-- ---------------------------------------------------------------------
CREATE TABLE "ProductReleaseRequestHeader" ( -- [KS X 9101 표준] 출하의뢰헤더 (표 73)
    "ProductReleaseRequestHeaderSequenceNo" BIGINT GENERATED BY DEFAULT AS IDENTITY, -- [KS X 9101 표준] 출하의뢰헤더 일련번호(PK)
    "EnterpriseID" VARCHAR(50) NOT NULL, -- [KS X 9101 표준] 회사식별자
    "SiteID" VARCHAR(50) NOT NULL, -- [KS X 9101 표준] 사업장식별자
    "PlantID" VARCHAR(50) NOT NULL, -- [KS X 9101 표준] 공장식별자
    "CreatorID" VARCHAR(50), -- [KS X 9101 표준] 등록자식별자
    "CreationDateTime" TIMESTAMP, -- [KS X 9101 표준] 등록일시
    "ModifierID" VARCHAR(50), -- [KS X 9101 표준] 수정자식별자
    "ModificationDateTime" TIMESTAMP, -- [KS X 9101 표준] 수정일시
    "Note" VARCHAR(1000), -- [KS X 9101 표준] 비고
    "ProductReleaseRequestID" VARCHAR(50) NOT NULL, -- [KS X 9101 표준] 출하요청식별자
    "ProductReleaseRequestDocumentNumber" VARCHAR(50), -- [KS X 9101 표준] 납품문서번호
    "ProductReleaseRequestType" VARCHAR(30), -- [KS X 9101 표준] 납품구분유형
    "ProductReleaseRequestDate" DATE, -- [KS X 9101 표준] 납품지시일
    "CustomerID" VARCHAR(50), -- [KS X 9101 표준] 고객사식별자
    CONSTRAINT "PK_ProductReleaseRequestHeader" PRIMARY KEY ("ProductReleaseRequestHeaderSequenceNo"),
    CONSTRAINT "UK_ProductReleaseRequestHeader" UNIQUE ("EnterpriseID", "ProductReleaseRequestID")
);

COMMENT ON TABLE "ProductReleaseRequestHeader" IS '[KS X 9101 표준] 출하의뢰헤더 (출하의뢰(ProductReleaseRequest) 명사의 헤더 구조체(struct) 출하의뢰 문서 1건의 공통 정보(납품문서번호, 납품구분유형, 납품지시일, 고객사) 출하의뢰마다 1회 나타남)';
COMMENT ON COLUMN "ProductReleaseRequestHeader"."ProductReleaseRequestHeaderSequenceNo" IS '[KS X 9101 표준] 출하의뢰헤더 일련번호: — 테이블 행을 식별하는 일련번호(PK, 대리키) — 표준 외 물리 컬럼
— 자동 증가 값(IDENTITY)으로 부여하며 다른 테이블이 참조하지 않음(FK는 UK 참조)';
COMMENT ON COLUMN "ProductReleaseRequestHeader"."EnterpriseID" IS '[KS X 9101 표준] 회사식별자: — 회사를 유일하게 구분할 수 있는 고유식별값
— 기업업무시스템 간의 연동을 수행하는 회사들 간에 자체적으로 정의한 고유식별값
— 참조 대상: 회사(Enterprise)';
COMMENT ON COLUMN "ProductReleaseRequestHeader"."SiteID" IS '[KS X 9101 표준] 사업장식별자: — 회사 내에서 사업장을 구분할수 있는 고유식별값
— 참조 대상: 사업장(Site)';
COMMENT ON COLUMN "ProductReleaseRequestHeader"."PlantID" IS '[KS X 9101 표준] 공장식별자: — 회사 내에서 공장을 구분할 수있는 고유식별값(만약, 공장 개념을 사용하지 않는다면 고정식별자로 설정하여 입력해야 함)
— 참조 대상: 공장(Plant)';
COMMENT ON COLUMN "ProductReleaseRequestHeader"."CreatorID" IS '[KS X 9101 표준] 등록자식별자: — 정보를 처음으로 등록한 사람을 구분할 수 있는 고유식별값으로, 일반적으로 사원번호가사용됨
— 참조 대상: 사원(Personnel)';
COMMENT ON COLUMN "ProductReleaseRequestHeader"."CreationDateTime" IS '[KS X 9101 표준] 등록일시: — 정보를 처음으로 등록한 날짜 (KS X ISO 8601을 따른다)';
COMMENT ON COLUMN "ProductReleaseRequestHeader"."ModifierID" IS '[KS X 9101 표준] 수정자식별자: — 정보를 마지막으로 수정한 사람을 구분할 수 있는 고유식별값으로, 일반적으로 사원번호가 사용됨
— 참조 대상: 사원(Personnel)';
COMMENT ON COLUMN "ProductReleaseRequestHeader"."ModificationDateTime" IS '[KS X 9101 표준] 수정일시: — 정보를 마지막으로 수정한 날짜 (KS X ISO 8601을 따른다.)';
COMMENT ON COLUMN "ProductReleaseRequestHeader"."Note" IS '[KS X 9101 표준] 비고: — 비고사항';
COMMENT ON COLUMN "ProductReleaseRequestHeader"."ProductReleaseRequestID" IS '[KS X 9101 표준] 출하요청식별자: — 출하요청을 식별하기 위한 고유값
— 출하의뢰 문서 단위로 부여하며, 출하의뢰헤더에 1회 기재함';
COMMENT ON COLUMN "ProductReleaseRequestHeader"."ProductReleaseRequestDocumentNumber" IS '[KS X 9101 표준] 납품문서번호: — 납품문서번호';
COMMENT ON COLUMN "ProductReleaseRequestHeader"."ProductReleaseRequestType" IS '[KS X 9101 표준] 납품구분유형: — 납품구분유형
— 납품구분유형은 일반 납품, 긴급 납품, 무상납품, 시방/시운전 납품, 타계정 출하 등을 포함
— 참조 대상: 공통코드정보(CommonCodeMaster)의 코드';
COMMENT ON COLUMN "ProductReleaseRequestHeader"."ProductReleaseRequestDate" IS '[KS X 9101 표준] 납품지시일: — 납품지시일(KS X ISO 8601을 따른다)';
COMMENT ON COLUMN "ProductReleaseRequestHeader"."CustomerID" IS '[KS X 9101 표준] 고객사식별자: — 품목을 구매해가는 거래처를 식별하기 위한 고유값
— 참조 대상: 고객사(CustomerPartyMaster)';

-- ---------------------------------------------------------------------
-- [표준 구분: KS X 9101 표준] 표 73, 조항 7.4.8.2 | 업무영역: 창고관리
-- 테이블명(물리): "ProductReleaseRequestLine" | 테이블명(논리): 출하의뢰라인
-- 설명: 출하의뢰(ProductReleaseRequest) 명사의 라인 구조체(struct[1..N]) 출하의뢰 문서를 구성하는 품목 행 정보 출하의뢰헤더 아래에 1회 이상 반복하여 나타남(1..N)
-- ---------------------------------------------------------------------
CREATE TABLE "ProductReleaseRequestLine" ( -- [KS X 9101 표준] 출하의뢰라인 (표 73)
    "ProductReleaseRequestLineSequenceNo" BIGINT GENERATED BY DEFAULT AS IDENTITY, -- [KS X 9101 표준] 출하의뢰라인 일련번호(PK)
    "EnterpriseID" VARCHAR(50) NOT NULL, -- [KS X 9101 표준] 회사식별자
    "SiteID" VARCHAR(50) NOT NULL, -- [KS X 9101 표준] 사업장식별자
    "PlantID" VARCHAR(50) NOT NULL, -- [KS X 9101 표준] 공장식별자
    "CreatorID" VARCHAR(50), -- [KS X 9101 표준] 등록자식별자
    "CreationDateTime" TIMESTAMP, -- [KS X 9101 표준] 등록일시
    "ModifierID" VARCHAR(50), -- [KS X 9101 표준] 수정자식별자
    "ModificationDateTime" TIMESTAMP, -- [KS X 9101 표준] 수정일시
    "Note" VARCHAR(1000), -- [KS X 9101 표준] 비고
    "ProductReleaseRequestID" VARCHAR(50) NOT NULL, -- [KS X 9101 표준] 출하요청식별자
    "ProductReleaseRequestSequence" INTEGER NOT NULL, -- [KS X 9101 표준] 납품순번
    "LineID" VARCHAR(50), -- [KS X 9101 표준] 라인식별자
    "ItemID" VARCHAR(50), -- [KS X 9101 표준] 품목식별자
    "ItemName" VARCHAR(200), -- [KS X 9101 표준] 품목명
    "ProductReleaseRequestQuantity" NUMERIC(18,6), -- [KS X 9101 표준] 납품수량
    "ProductReleaseQuantity" NUMERIC(18,6), -- [KS X 9101 표준] 출고수량
    "SalesQuantity" NUMERIC(18,6), -- [KS X 9101 표준] 매출수량
    "ItemUOMCode" VARCHAR(20), -- [KS X 9101 표준] 기준단위코드
    "SellingUOMCode" VARCHAR(20), -- [KS X 9101 표준] 판매단위코드
    "ItemUnitQuantity" NUMERIC(18,6), -- [KS X 9101 표준] 기준단위수량
    "ProductReleaseUnitQuantity" NUMERIC(18,6), -- [KS X 9101 표준] 기준출고수량
    "SalesUnitQuantity" NUMERIC(18,6), -- [KS X 9101 표준] 기준매출수량
    "WarehouseID" VARCHAR(50), -- [KS X 9101 표준] 창고식별자
    "RequestedDeliveryDate" DATE, -- [KS X 9101 표준] 요청납기일
    "SalesDocumentNumber" VARCHAR(50), -- [KS X 9101 표준] 수주문서번호
    "SalesDocumentSequence" INTEGER, -- [KS X 9101 표준] 수주문서순번
    "ProductReleaseDate" DATE, -- [KS X 9101 표준] 출고일
    "DeliveryDate" DATE, -- [KS X 9101 표준] 납품일
    CONSTRAINT "PK_ProductReleaseRequestLine" PRIMARY KEY ("ProductReleaseRequestLineSequenceNo"),
    CONSTRAINT "UK_ProductReleaseRequestLine" UNIQUE ("EnterpriseID", "ProductReleaseRequestID", "ProductReleaseRequestSequence")
);

COMMENT ON TABLE "ProductReleaseRequestLine" IS '[KS X 9101 표준] 출하의뢰라인 (출하의뢰(ProductReleaseRequest) 명사의 라인 구조체(struct[1..N]) 출하의뢰 문서를 구성하는 품목 행 정보 출하의뢰헤더 아래에 1회 이상 반복하여 나타남(1..N))';
COMMENT ON COLUMN "ProductReleaseRequestLine"."ProductReleaseRequestLineSequenceNo" IS '[KS X 9101 표준] 출하의뢰라인 일련번호: — 테이블 행을 식별하는 일련번호(PK, 대리키) — 표준 외 물리 컬럼
— 자동 증가 값(IDENTITY)으로 부여하며 다른 테이블이 참조하지 않음(FK는 UK 참조)';
COMMENT ON COLUMN "ProductReleaseRequestLine"."EnterpriseID" IS '[KS X 9101 표준] 회사식별자: — 회사를 유일하게 구분할 수 있는 고유식별값
— 기업업무시스템 간의 연동을 수행하는 회사들 간에 자체적으로 정의한 고유식별값
— 참조 대상: 회사(Enterprise)';
COMMENT ON COLUMN "ProductReleaseRequestLine"."SiteID" IS '[KS X 9101 표준] 사업장식별자: — 회사 내에서 사업장을 구분할수 있는 고유식별값
— 참조 대상: 사업장(Site)';
COMMENT ON COLUMN "ProductReleaseRequestLine"."PlantID" IS '[KS X 9101 표준] 공장식별자: — 회사 내에서 공장을 구분할 수있는 고유식별값(만약, 공장 개념을 사용하지 않는다면 고정식별자로 설정하여 입력해야 함)
— 참조 대상: 공장(Plant)';
COMMENT ON COLUMN "ProductReleaseRequestLine"."CreatorID" IS '[KS X 9101 표준] 등록자식별자: — 정보를 처음으로 등록한 사람을 구분할 수 있는 고유식별값으로, 일반적으로 사원번호가사용됨
— 참조 대상: 사원(Personnel)';
COMMENT ON COLUMN "ProductReleaseRequestLine"."CreationDateTime" IS '[KS X 9101 표준] 등록일시: — 정보를 처음으로 등록한 날짜 (KS X ISO 8601을 따른다)';
COMMENT ON COLUMN "ProductReleaseRequestLine"."ModifierID" IS '[KS X 9101 표준] 수정자식별자: — 정보를 마지막으로 수정한 사람을 구분할 수 있는 고유식별값으로, 일반적으로 사원번호가 사용됨
— 참조 대상: 사원(Personnel)';
COMMENT ON COLUMN "ProductReleaseRequestLine"."ModificationDateTime" IS '[KS X 9101 표준] 수정일시: — 정보를 마지막으로 수정한 날짜 (KS X ISO 8601을 따른다.)';
COMMENT ON COLUMN "ProductReleaseRequestLine"."Note" IS '[KS X 9101 표준] 비고: — 비고사항';
COMMENT ON COLUMN "ProductReleaseRequestLine"."ProductReleaseRequestID" IS '[KS X 9101 표준] 출하요청식별자: — 출하요청을 식별하기 위한 고유값
— 참조 대상: 출하의뢰헤더(ProductReleaseRequestHeader)';
COMMENT ON COLUMN "ProductReleaseRequestLine"."ProductReleaseRequestSequence" IS '[KS X 9101 표준] 납품순번: — 납품순번
— 출하의뢰라인의 행 순번으로, 출하의뢰라인은 출하요청식별자와 납품순번의 조합으로 구분함';
COMMENT ON COLUMN "ProductReleaseRequestLine"."LineID" IS '[KS X 9101 표준] 라인식별자: — 라인을 식별하기 위한 고유값
— 참조 대상: 라인(Line)';
COMMENT ON COLUMN "ProductReleaseRequestLine"."ItemID" IS '[KS X 9101 표준] 품목식별자: — 품목을 식별하기 위한 고유값
— 제품, 반제품, 상품, 원자재, 부자재, 저장품, 소모품 등회사 내 시스템으로 관리되는 모든 품목을 포함
— 참조 대상: 품목마스터(ItemMaster)';
COMMENT ON COLUMN "ProductReleaseRequestLine"."ItemName" IS '[KS X 9101 표준] 품목명: — 품목의 명칭
— 참조 대상: 품목마스터(ItemMaster.ItemName)';
COMMENT ON COLUMN "ProductReleaseRequestLine"."ProductReleaseRequestQuantity" IS '[KS X 9101 표준] 납품수량: — 납품수량(수량의 단위는 판매단위코드로 함)';
COMMENT ON COLUMN "ProductReleaseRequestLine"."ProductReleaseQuantity" IS '[KS X 9101 표준] 출고수량: — 출고수량(수량의 단위는 판매단위코드로 함)';
COMMENT ON COLUMN "ProductReleaseRequestLine"."SalesQuantity" IS '[KS X 9101 표준] 매출수량: — 매출수량(수량의 단위는 판매단위코드로 함)';
COMMENT ON COLUMN "ProductReleaseRequestLine"."ItemUOMCode" IS '[KS X 9101 표준] 기준단위코드: — 기준단위코드(예: EA, DZ, HD 등)
— 참조 대상: 단위그룹(UOMGroup)의 단위코드';
COMMENT ON COLUMN "ProductReleaseRequestLine"."SellingUOMCode" IS '[KS X 9101 표준] 판매단위코드: — 판매단위코드(예: EA, DZ, HD 등)
— 참조 대상: 단위그룹(UOMGroup)의 단위코드';
COMMENT ON COLUMN "ProductReleaseRequestLine"."ItemUnitQuantity" IS '[KS X 9101 표준] 기준단위수량: — 기준수량(수량의 단위는 기준단위코드로 함)';
COMMENT ON COLUMN "ProductReleaseRequestLine"."ProductReleaseUnitQuantity" IS '[KS X 9101 표준] 기준출고수량: — 기준출고수량(수량의 단위는 기준단위코드로 함)';
COMMENT ON COLUMN "ProductReleaseRequestLine"."SalesUnitQuantity" IS '[KS X 9101 표준] 기준매출수량: — 기준매출수량(수량의 단위는 기준단위코드로 함)';
COMMENT ON COLUMN "ProductReleaseRequestLine"."WarehouseID" IS '[KS X 9101 표준] 창고식별자: — 창고를 식별하기 위한 고유값
— 참조 대상: 창고(WarehouseLocation)';
COMMENT ON COLUMN "ProductReleaseRequestLine"."RequestedDeliveryDate" IS '[KS X 9101 표준] 요청납기일: — 요청납기일(KS X ISO 8601을 따른다)';
COMMENT ON COLUMN "ProductReleaseRequestLine"."SalesDocumentNumber" IS '[KS X 9101 표준] 수주문서번호: — 수주문서번호
— 참조 대상: 수주오더(SalesOrder)
— 수주문서순번(SalesDocumentSequence)과 함께 사용한다';
COMMENT ON COLUMN "ProductReleaseRequestLine"."SalesDocumentSequence" IS '[KS X 9101 표준] 수주문서순번: — 수주문서순번
— 수주문서번호(SalesDocumentNumber)와 함께 수주오더(SalesOrder)를 참조한다';
COMMENT ON COLUMN "ProductReleaseRequestLine"."ProductReleaseDate" IS '[KS X 9101 표준] 출고일: — 출고일(KS X ISO 8601을 따른다)';
COMMENT ON COLUMN "ProductReleaseRequestLine"."DeliveryDate" IS '[KS X 9101 표준] 납품일: — 납품일(KS X ISO 8601을 따른다)';

-- ---------------------------------------------------------------------
-- [표준 구분: KS X 9101 표준] 표 74, 조항 7.4.8.3 | 업무영역: 창고관리
-- 테이블명(물리): "ProductRelease" | 테이블명(논리): 제품출고
-- 설명: 수주된 품목을 고객에게 보내는 것을 의미한다.
-- ---------------------------------------------------------------------
CREATE TABLE "ProductRelease" ( -- [KS X 9101 표준] 제품출고 (표 74)
    "ProductReleaseSequenceNo" BIGINT GENERATED BY DEFAULT AS IDENTITY, -- [KS X 9101 표준] 제품출고 일련번호(PK)
    "EnterpriseID" VARCHAR(50) NOT NULL, -- [KS X 9101 표준] 회사식별자
    "SiteID" VARCHAR(50) NOT NULL, -- [KS X 9101 표준] 사업장식별자
    "PlantID" VARCHAR(50) NOT NULL, -- [KS X 9101 표준] 공장식별자
    "CreatorID" VARCHAR(50), -- [KS X 9101 표준] 등록자식별자
    "CreationDateTime" TIMESTAMP, -- [KS X 9101 표준] 등록일시
    "ModifierID" VARCHAR(50), -- [KS X 9101 표준] 수정자식별자
    "ModificationDateTime" TIMESTAMP, -- [KS X 9101 표준] 수정일시
    "Note" VARCHAR(1000), -- [KS X 9101 표준] 비고
    "ProductReleaseID" VARCHAR(50) NOT NULL, -- [KS X 9101 표준] 출고식별자
    "ProductReleaseSequence" INTEGER NOT NULL, -- [KS X 9101 표준] 출고순번
    "ProductReleaseRequestID" VARCHAR(50), -- [KS X 9101 표준] 출하요청식별자
    "SalesDocumentNumber" VARCHAR(50), -- [KS X 9101 표준] 수주문서번호
    "SalesDocumentSequence" INTEGER, -- [KS X 9101 표준] 수주문서순번
    "InventoryTransactionDate" DATE, -- [KS X 9101 표준] 수불일
    "LineID" VARCHAR(50), -- [KS X 9101 표준] 라인식별자
    "ItemID" VARCHAR(50), -- [KS X 9101 표준] 품목식별자
    "ItemName" VARCHAR(200), -- [KS X 9101 표준] 품목명
    "OrderUOMCode" VARCHAR(20), -- [KS X 9101 표준] 오더단위코드
    "OrderQuantity" NUMERIC(18,6), -- [KS X 9101 표준] 오더수량
    "SellingUOMCode" VARCHAR(20), -- [KS X 9101 표준] 판매단위코드
    "SalesQuantity" NUMERIC(18,6), -- [KS X 9101 표준] 매출수량
    "ReturnIndicator" BOOLEAN, -- [KS X 9101 표준] 반품여부
    "ItemUOMCode" VARCHAR(20), -- [KS X 9101 표준] 기준단위코드
    "ItemUnitQuantity" NUMERIC(18,6), -- [KS X 9101 표준] 기준단위수량
    "SalesUnitQuantity" NUMERIC(18,6), -- [KS X 9101 표준] 기준매출수량
    "ReturnUnitQuantity" NUMERIC(18,6), -- [KS X 9101 표준] 기준반품수량
    "CustomerID" VARCHAR(50), -- [KS X 9101 표준] 고객사식별자
    "LotID" VARCHAR(50), -- [KS X 9101 표준] 로트식별자
    "SerialUseIndicator" BOOLEAN, -- [KS X 9101 표준] 시리얼사용여부
    "WarehouseID" VARCHAR(50), -- [KS X 9101 표준] 창고식별자
    CONSTRAINT "PK_ProductRelease" PRIMARY KEY ("ProductReleaseSequenceNo"),
    CONSTRAINT "UK_ProductRelease" UNIQUE ("EnterpriseID", "ProductReleaseID", "ProductReleaseSequence")
);

COMMENT ON TABLE "ProductRelease" IS '[KS X 9101 표준] 제품출고 (수주된 품목을 고객에게 보내는 것을 의미한다.)';
COMMENT ON COLUMN "ProductRelease"."ProductReleaseSequenceNo" IS '[KS X 9101 표준] 제품출고 일련번호: — 테이블 행을 식별하는 일련번호(PK, 대리키) — 표준 외 물리 컬럼
— 자동 증가 값(IDENTITY)으로 부여하며 다른 테이블이 참조하지 않음(FK는 UK 참조)';
COMMENT ON COLUMN "ProductRelease"."EnterpriseID" IS '[KS X 9101 표준] 회사식별자: — 회사를 유일하게 구분할 수 있는 고유식별값
— 기업업무시스템 간의 연동을 수행하는 회사들 간에 자체적으로 정의한 고유식별값
— 참조 대상: 회사(Enterprise)';
COMMENT ON COLUMN "ProductRelease"."SiteID" IS '[KS X 9101 표준] 사업장식별자: — 회사 내에서 사업장을 구분할수 있는 고유식별값
— 참조 대상: 사업장(Site)';
COMMENT ON COLUMN "ProductRelease"."PlantID" IS '[KS X 9101 표준] 공장식별자: — 회사 내에서 공장을 구분할 수있는 고유식별값(만약, 공장 개념을 사용하지 않는다면 고정식별자로 설정하여 입력해야 함)
— 참조 대상: 공장(Plant)';
COMMENT ON COLUMN "ProductRelease"."CreatorID" IS '[KS X 9101 표준] 등록자식별자: — 정보를 처음으로 등록한 사람을 구분할 수 있는 고유식별값으로, 일반적으로 사원번호가사용됨
— 참조 대상: 사원(Personnel)';
COMMENT ON COLUMN "ProductRelease"."CreationDateTime" IS '[KS X 9101 표준] 등록일시: — 정보를 처음으로 등록한 날짜 (KS X ISO 8601을 따른다)';
COMMENT ON COLUMN "ProductRelease"."ModifierID" IS '[KS X 9101 표준] 수정자식별자: — 정보를 마지막으로 수정한 사람을 구분할 수 있는 고유식별값으로, 일반적으로 사원번호가 사용됨
— 참조 대상: 사원(Personnel)';
COMMENT ON COLUMN "ProductRelease"."ModificationDateTime" IS '[KS X 9101 표준] 수정일시: — 정보를 마지막으로 수정한 날짜 (KS X ISO 8601을 따른다.)';
COMMENT ON COLUMN "ProductRelease"."Note" IS '[KS X 9101 표준] 비고: — 비고사항';
COMMENT ON COLUMN "ProductRelease"."ProductReleaseID" IS '[KS X 9101 표준] 출고식별자: — 출고를 식별하기 위한 고유값
— 제품출고 문서 단위로 부여하며, 한 제품출고 문서에 속한 모든 품목 행에 같은 값을 사용함';
COMMENT ON COLUMN "ProductRelease"."ProductReleaseSequence" IS '[KS X 9101 표준] 출고순번: — 출고순번
— 제품출고 행은 출고식별자와 출고순번의 조합으로 구분함';
COMMENT ON COLUMN "ProductRelease"."ProductReleaseRequestID" IS '[KS X 9101 표준] 출하요청식별자: — 출하요청을 식별하기 위한 고유값
— 출하요청식별자가 가리키는 출하의뢰헤더(출하의뢰 문서 전체)를 참조하며, 출하의뢰라인과는 품목식별자·수주문서순번으로 대응함
— 참조 대상: 출하의뢰(ProductReleaseRequest)';
COMMENT ON COLUMN "ProductRelease"."SalesDocumentNumber" IS '[KS X 9101 표준] 수주문서번호: — 수주문서번호
— 수주문서순번(SalesDocumentSequence)과 함께 사용한다
— 참조 대상: 수주오더(SalesOrder)
— 수주문서순번(SalesDocumentSequence)과 함께 사용한다';
COMMENT ON COLUMN "ProductRelease"."SalesDocumentSequence" IS '[KS X 9101 표준] 수주문서순번: — 수주문서순번
— 수주문서번호(SalesDocumentNumber)와 함께 수주오더(SalesOrder)를 참조한다';
COMMENT ON COLUMN "ProductRelease"."InventoryTransactionDate" IS '[KS X 9101 표준] 수불일: — 수불일(KS X ISO 8601을 따른다)';
COMMENT ON COLUMN "ProductRelease"."LineID" IS '[KS X 9101 표준] 라인식별자: — 라인을 식별하기 위한 고유값
— 참조 대상: 라인(Line)';
COMMENT ON COLUMN "ProductRelease"."ItemID" IS '[KS X 9101 표준] 품목식별자: — 품목을 식별하기 위한 고유값
— 제품, 반제품, 상품, 원자재, 부자재, 저장품, 소모품 등회사 내 시스템으로 관리되는 모든 품목을 포함
— 참조 대상: 품목마스터(ItemMaster)';
COMMENT ON COLUMN "ProductRelease"."ItemName" IS '[KS X 9101 표준] 품목명: — 품목의 명칭
— 참조 대상: 품목마스터(ItemMaster.ItemName)';
COMMENT ON COLUMN "ProductRelease"."OrderUOMCode" IS '[KS X 9101 표준] 오더단위코드: — 오더단위코드(예: EA, DZ, HD 등)
— 참조 대상: 단위그룹(UOMGroup)의 단위코드';
COMMENT ON COLUMN "ProductRelease"."OrderQuantity" IS '[KS X 9101 표준] 오더수량: — 오더수량(수량의 단위는 오더단위코드로 함)';
COMMENT ON COLUMN "ProductRelease"."SellingUOMCode" IS '[KS X 9101 표준] 판매단위코드: — 판매단위코드(예: EA, DZ, HD 등)
— 참조 대상: 단위그룹(UOMGroup)의 단위코드';
COMMENT ON COLUMN "ProductRelease"."SalesQuantity" IS '[KS X 9101 표준] 매출수량: — 매출수량(수량의 단위는 판매단위코드로 함)';
COMMENT ON COLUMN "ProductRelease"."ReturnIndicator" IS '[KS X 9101 표준] 반품여부: — 반품여부';
COMMENT ON COLUMN "ProductRelease"."ItemUOMCode" IS '[KS X 9101 표준] 기준단위코드: — 기준단위코드(예: EA, DZ, HD 등)
— 참조 대상: 단위그룹(UOMGroup)의 단위코드';
COMMENT ON COLUMN "ProductRelease"."ItemUnitQuantity" IS '[KS X 9101 표준] 기준단위수량: — 기준단위수량(수량의 단위는 기준단위코드로 함)';
COMMENT ON COLUMN "ProductRelease"."SalesUnitQuantity" IS '[KS X 9101 표준] 기준매출수량: — 기준매출수량(수량의 단위는 기준단위코드로 함)';
COMMENT ON COLUMN "ProductRelease"."ReturnUnitQuantity" IS '[KS X 9101 표준] 기준반품수량: — 기준반품수량(수량의 단위는 기준단위코드로 함)';
COMMENT ON COLUMN "ProductRelease"."CustomerID" IS '[KS X 9101 표준] 고객사식별자: — 품목을 구매해가는 거래처를 식별하기 위한 고유값
— 참조 대상: 고객사(CustomerPartyMaster)';
COMMENT ON COLUMN "ProductRelease"."LotID" IS '[KS X 9101 표준] 로트식별자: — 제품출고에 포함된 로트의 고유식별값
— 참조 대상: 로트(Lot)';
COMMENT ON COLUMN "ProductRelease"."SerialUseIndicator" IS '[KS X 9101 표준] 시리얼사용여부: — 시리얼사용여부';
COMMENT ON COLUMN "ProductRelease"."WarehouseID" IS '[KS X 9101 표준] 창고식별자: — 창고를 식별하기 위한 고유값
— 참조 대상: 창고(WarehouseLocation)';

-- ---------------------------------------------------------------------
-- [표준 구분: KS X 9101 표준] 표 75, 조항 7.4.8.4 | 업무영역: 창고관리
-- 테이블명(물리): "DeliveryHeader" | 테이블명(논리): 배송헤더
-- 설명: 배송(Delivery) 명사의 헤더 구조체(struct) 특정 수량의 물품을 공급업체에서 단일 고객 목적지로 운송하는 데 사용되는 배송 1건의 공통 정보 배송마다 1회 나타남
-- ---------------------------------------------------------------------
CREATE TABLE "DeliveryHeader" ( -- [KS X 9101 표준] 배송헤더 (표 75)
    "DeliveryHeaderSequenceNo" BIGINT GENERATED BY DEFAULT AS IDENTITY, -- [KS X 9101 표준] 배송헤더 일련번호(PK)
    "EnterpriseID" VARCHAR(50) NOT NULL, -- [KS X 9101 표준] 회사식별자
    "SiteID" VARCHAR(50) NOT NULL, -- [KS X 9101 표준] 사업장식별자
    "PlantID" VARCHAR(50) NOT NULL, -- [KS X 9101 표준] 공장식별자
    "CreatorID" VARCHAR(50), -- [KS X 9101 표준] 등록자식별자
    "CreationDateTime" TIMESTAMP, -- [KS X 9101 표준] 등록일시
    "ModifierID" VARCHAR(50), -- [KS X 9101 표준] 수정자식별자
    "ModificationDateTime" TIMESTAMP, -- [KS X 9101 표준] 수정일시
    "Note" VARCHAR(1000), -- [KS X 9101 표준] 비고
    "DeliveryID" VARCHAR(50) NOT NULL, -- [KS X 9101 표준] 배송식별자
    "DeliveryDateTime" TIMESTAMP, -- [KS X 9101 표준] 배송일시
    "CustomerID" VARCHAR(50), -- [KS X 9101 표준] 고객사식별자
    "PackingList" VARCHAR(1000), -- [KS X 9101 표준] 포장내용
    "PackingType" VARCHAR(30), -- [KS X 9101 표준] 포장유형
    "TransportationMethodCode" VARCHAR(30), -- [KS X 9101 표준] 운송방법
    "DepartmentInChargeID" VARCHAR(50), -- [KS X 9101 표준] 배송처리담당부서식별자
    "DepartmentInChargeName" VARCHAR(200), -- [KS X 9101 표준] 배송처리담당부서명
    "PersonInChargeID" VARCHAR(50), -- [KS X 9101 표준] 배송처리담당자식별자
    "PersonInChargeName" VARCHAR(200), -- [KS X 9101 표준] 배송처리담당자명
    "PersonInChargeDialNumber" VARCHAR(30), -- [KS X 9101 표준] 배송처리담당자전화번호
    "TransportationCompany" VARCHAR(255), -- [KS X 9101 표준] 운송사
    "PersonInChargeNameOfTransportation" VARCHAR(255), -- [KS X 9101 표준] 운송담당자명
    "PersonInChargeDialNumberOfTransportation" VARCHAR(255), -- [KS X 9101 표준] 운송담당자전화번호
    "Recipient" VARCHAR(255), -- [KS X 9101 표준] 수취인
    "RecipientDialNumber" VARCHAR(30), -- [KS X 9101 표준] 수취인전화번호
    "RecipientEmail" VARCHAR(255), -- [KS X 9101 표준] 수취인이메일
    "ShippingPoint" VARCHAR(255), -- [KS X 9101 표준] 선적지
    "ShipToAddress" VARCHAR(1000), -- [KS X 9101 표준] 배송지
    "PreferredReceiptDate" DATE, -- [KS X 9101 표준] 인수희망일
    "DeliveryNote" VARCHAR(1000), -- [KS X 9101 표준] 배송메모
    "DeliveryConfirmationDocument" VARCHAR(255), -- [KS X 9101 표준] 납품확인서
    CONSTRAINT "PK_DeliveryHeader" PRIMARY KEY ("DeliveryHeaderSequenceNo"),
    CONSTRAINT "UK_DeliveryHeader" UNIQUE ("EnterpriseID", "DeliveryID")
);

COMMENT ON TABLE "DeliveryHeader" IS '[KS X 9101 표준] 배송헤더 (배송(Delivery) 명사의 헤더 구조체(struct) 특정 수량의 물품을 공급업체에서 단일 고객 목적지로 운송하는 데 사용되는 배송 1건의 공통 정보 배송마다 1회 나타남)';
COMMENT ON COLUMN "DeliveryHeader"."DeliveryHeaderSequenceNo" IS '[KS X 9101 표준] 배송헤더 일련번호: — 테이블 행을 식별하는 일련번호(PK, 대리키) — 표준 외 물리 컬럼
— 자동 증가 값(IDENTITY)으로 부여하며 다른 테이블이 참조하지 않음(FK는 UK 참조)';
COMMENT ON COLUMN "DeliveryHeader"."EnterpriseID" IS '[KS X 9101 표준] 회사식별자: — 회사를 유일하게 구분할 수 있는 고유식별값
— 기업업무시스템 간의 연동을 수행하는 회사들 간에 자체적으로 정의한 고유식별값
— 참조 대상: 회사(Enterprise)';
COMMENT ON COLUMN "DeliveryHeader"."SiteID" IS '[KS X 9101 표준] 사업장식별자: — 회사 내에서 사업장을 구분할수 있는 고유식별값
— 참조 대상: 사업장(Site)';
COMMENT ON COLUMN "DeliveryHeader"."PlantID" IS '[KS X 9101 표준] 공장식별자: — 회사 내에서 공장을 구분할 수있는 고유식별값(만약, 공장 개념을 사용하지 않는다면 고정식별자로 설정하여 입력해야 함)
— 참조 대상: 공장(Plant)';
COMMENT ON COLUMN "DeliveryHeader"."CreatorID" IS '[KS X 9101 표준] 등록자식별자: — 정보를 처음으로 등록한 사람을 구분할 수 있는 고유식별값으로, 일반적으로 사원번호가사용됨
— 참조 대상: 사원(Personnel)';
COMMENT ON COLUMN "DeliveryHeader"."CreationDateTime" IS '[KS X 9101 표준] 등록일시: — 정보를 처음으로 등록한 날짜 (KS X ISO 8601을 따른다)';
COMMENT ON COLUMN "DeliveryHeader"."ModifierID" IS '[KS X 9101 표준] 수정자식별자: — 정보를 마지막으로 수정한 사람을 구분할 수 있는 고유식별값으로, 일반적으로 사원번호가 사용됨
— 참조 대상: 사원(Personnel)';
COMMENT ON COLUMN "DeliveryHeader"."ModificationDateTime" IS '[KS X 9101 표준] 수정일시: — 정보를 마지막으로 수정한 날짜 (KS X ISO 8601을 따른다.)';
COMMENT ON COLUMN "DeliveryHeader"."Note" IS '[KS X 9101 표준] 비고: — 비고사항';
COMMENT ON COLUMN "DeliveryHeader"."DeliveryID" IS '[KS X 9101 표준] 배송식별자: — 배송을 식별하기 위한 고유값
— 배송 단위로 부여하며, 배송헤더에 1회 기재함';
COMMENT ON COLUMN "DeliveryHeader"."DeliveryDateTime" IS '[KS X 9101 표준] 배송일시: — 배송일시(KS X ISO 8601을 따른다)';
COMMENT ON COLUMN "DeliveryHeader"."CustomerID" IS '[KS X 9101 표준] 고객사식별자: — 품목을 구매해가는 거래처를 식별하기 위한 고유값
— 참조 대상: 고객사(CustomerPartyMaster)';
COMMENT ON COLUMN "DeliveryHeader"."PackingList" IS '[KS X 9101 표준] 포장내용: — 선적할 화물의 포장 단위별로 내용물, 수량, 무게 등을 명시한 서류에 대한 정보';
COMMENT ON COLUMN "DeliveryHeader"."PackingType" IS '[KS X 9101 표준] 포장유형: — 포장 유형
— 예: 박스, 팔레트, 벌크 등
— 참조 대상: 공통코드정보(CommonCodeMaster)의 코드';
COMMENT ON COLUMN "DeliveryHeader"."TransportationMethodCode" IS '[KS X 9101 표준] 운송방법: — 항공, 해상, 도로, 철도 등 운송 수단
— 참조 대상: 공통코드정보(CommonCodeMaster)의 코드';
COMMENT ON COLUMN "DeliveryHeader"."DepartmentInChargeID" IS '[KS X 9101 표준] 배송처리담당부서식별자: — 배송을 처리하는 담당부서를 식별하기 위한 고유값
— 참조 대상: 부서(Department)';
COMMENT ON COLUMN "DeliveryHeader"."DepartmentInChargeName" IS '[KS X 9101 표준] 배송처리담당부서명: — 배송을 처리하는 담당부서 명칭
— 참조 대상: 부서(Department.DepartmentName)';
COMMENT ON COLUMN "DeliveryHeader"."PersonInChargeID" IS '[KS X 9101 표준] 배송처리담당자식별자: — 배송을 처리하는 담당자를 식별하기 위한 고유값
— 참조 대상: 사원(Personnel)';
COMMENT ON COLUMN "DeliveryHeader"."PersonInChargeName" IS '[KS X 9101 표준] 배송처리담당자명: — 배송을 처리하는 담당자 이름
— 참조 대상: 사원(Personnel.PersonnelName)';
COMMENT ON COLUMN "DeliveryHeader"."PersonInChargeDialNumber" IS '[KS X 9101 표준] 배송처리담당자전화번호: — 배송을 처리하는 담당자 전화번호
— 참조 대상: 사원(Personnel.PersonInChargeDialNumber)';
COMMENT ON COLUMN "DeliveryHeader"."TransportationCompany" IS '[KS X 9101 표준] 운송사: — 제품의 운송을 담당하는 회사';
COMMENT ON COLUMN "DeliveryHeader"."PersonInChargeNameOfTransportation" IS '[KS X 9101 표준] 운송담당자명: — 운송사 배송 담당자의 이름';
COMMENT ON COLUMN "DeliveryHeader"."PersonInChargeDialNumberOfTransportation" IS '[KS X 9101 표준] 운송담당자전화번호: — 운송사 배송 담당자의 전화번호';
COMMENT ON COLUMN "DeliveryHeader"."Recipient" IS '[KS X 9101 표준] 수취인: — 배송된 제품을 받는 담당자 또는 담당 부서';
COMMENT ON COLUMN "DeliveryHeader"."RecipientDialNumber" IS '[KS X 9101 표준] 수취인전화번호: — 배송된 제품을 받는 담당자 전화번호';
COMMENT ON COLUMN "DeliveryHeader"."RecipientEmail" IS '[KS X 9101 표준] 수취인이메일: — 배송된 제품을 받는 담당자 이메일 주소';
COMMENT ON COLUMN "DeliveryHeader"."ShippingPoint" IS '[KS X 9101 표준] 선적지: — 제품이 배송되는 출발지 주소';
COMMENT ON COLUMN "DeliveryHeader"."ShipToAddress" IS '[KS X 9101 표준] 배송지: — 제품이 도착할 목적지 주소';
COMMENT ON COLUMN "DeliveryHeader"."PreferredReceiptDate" IS '[KS X 9101 표준] 인수희망일: — 고객이 물품을 받기를 원하는 날짜(KS X ISO 8601을 따른다)';
COMMENT ON COLUMN "DeliveryHeader"."DeliveryNote" IS '[KS X 9101 표준] 배송메모: — 수취인 요청사항 등을 운송사에 전달하는 메시지';
COMMENT ON COLUMN "DeliveryHeader"."DeliveryConfirmationDocument" IS '[KS X 9101 표준] 납품확인서: — 납품 확인 문서에 대한 온라인 URI(Uniform Resource Identifier)';

-- ---------------------------------------------------------------------
-- [표준 구분: KS X 9101 표준] 표 75, 조항 7.4.8.4 | 업무영역: 창고관리
-- 테이블명(물리): "DeliveryLine" | 테이블명(논리): 배송라인
-- 설명: 배송(Delivery) 명사의 라인 구조체(struct[1..N]) 납품되는 품목 행 정보 배송헤더 아래에 1회 이상 반복하여 나타남(1..N)
-- ---------------------------------------------------------------------
CREATE TABLE "DeliveryLine" ( -- [KS X 9101 표준] 배송라인 (표 75)
    "DeliveryLineSequenceNo" BIGINT GENERATED BY DEFAULT AS IDENTITY, -- [KS X 9101 표준] 배송라인 일련번호(PK)
    "EnterpriseID" VARCHAR(50) NOT NULL, -- [KS X 9101 표준] 회사식별자
    "SiteID" VARCHAR(50) NOT NULL, -- [KS X 9101 표준] 사업장식별자
    "PlantID" VARCHAR(50) NOT NULL, -- [KS X 9101 표준] 공장식별자
    "CreatorID" VARCHAR(50), -- [KS X 9101 표준] 등록자식별자
    "CreationDateTime" TIMESTAMP, -- [KS X 9101 표준] 등록일시
    "ModifierID" VARCHAR(50), -- [KS X 9101 표준] 수정자식별자
    "ModificationDateTime" TIMESTAMP, -- [KS X 9101 표준] 수정일시
    "Note" VARCHAR(1000), -- [KS X 9101 표준] 비고
    "DeliveryID" VARCHAR(50) NOT NULL, -- [KS X 9101 표준] 배송식별자
    "DeliveryLineSequence" INTEGER NOT NULL, -- [KS X 9101 표준] 배송라인순번
    "ProductReleaseID" VARCHAR(50), -- [KS X 9101 표준] 출고식별자
    "ProductReleaseSequence" INTEGER, -- [KS X 9101 표준] 출고순번
    "SalesDocumentNumber" VARCHAR(50), -- [KS X 9101 표준] 수주문서번호
    "SalesDocumentSequence" INTEGER, -- [KS X 9101 표준] 수주문서순번
    "ItemID" VARCHAR(50), -- [KS X 9101 표준] 품목식별자
    "ItemName" VARCHAR(200), -- [KS X 9101 표준] 품목명
    "InvoiceNumber" VARCHAR(50), -- [KS X 9101 표준] 거래명세서번호
    "LotID" VARCHAR(50), -- [KS X 9101 표준] 로트식별자
    "ItemUOMCode" VARCHAR(20), -- [KS X 9101 표준] 기준단위코드
    "ItemUnitQuantity" NUMERIC(18,6), -- [KS X 9101 표준] 기준단위수량
    "OrderUOMCode" VARCHAR(20), -- [KS X 9101 표준] 오더단위코드
    "OrderQuantity" NUMERIC(18,6), -- [KS X 9101 표준] 오더수량
    "ProductDeliveryUOMCode" VARCHAR(20), -- [KS X 9101 표준] 납품단위코드
    "ProductDeliveryQuantity" NUMERIC(18,6), -- [KS X 9101 표준] 납품수량
    "RequestedDeliveryDate" DATE, -- [KS X 9101 표준] 요청납품일
    CONSTRAINT "PK_DeliveryLine" PRIMARY KEY ("DeliveryLineSequenceNo"),
    CONSTRAINT "UK_DeliveryLine" UNIQUE ("EnterpriseID", "DeliveryID", "DeliveryLineSequence")
);

COMMENT ON TABLE "DeliveryLine" IS '[KS X 9101 표준] 배송라인 (배송(Delivery) 명사의 라인 구조체(struct[1..N]) 납품되는 품목 행 정보 배송헤더 아래에 1회 이상 반복하여 나타남(1..N))';
COMMENT ON COLUMN "DeliveryLine"."DeliveryLineSequenceNo" IS '[KS X 9101 표준] 배송라인 일련번호: — 테이블 행을 식별하는 일련번호(PK, 대리키) — 표준 외 물리 컬럼
— 자동 증가 값(IDENTITY)으로 부여하며 다른 테이블이 참조하지 않음(FK는 UK 참조)';
