COMMENT ON COLUMN "DeliveryLine"."CreationDateTime" IS '[KS X 9101 표준] 등록일시: — 정보를 처음으로 등록한 날짜 (KS X ISO 8601을 따른다)';
COMMENT ON COLUMN "DeliveryLine"."ModifierID" IS '[KS X 9101 표준] 수정자식별자: — 정보를 마지막으로 수정한 사람을 구분할 수 있는 고유식별값으로, 일반적으로 사원번호가 사용됨
— 참조 대상: 사원(Personnel)';
COMMENT ON COLUMN "DeliveryLine"."ModificationDateTime" IS '[KS X 9101 표준] 수정일시: — 정보를 마지막으로 수정한 날짜 (KS X ISO 8601을 따른다.)';
COMMENT ON COLUMN "DeliveryLine"."Note" IS '[KS X 9101 표준] 비고: — 비고사항';
COMMENT ON COLUMN "DeliveryLine"."DeliveryID" IS '[KS X 9101 표준] 배송식별자: — 배송을 식별하기 위한 고유값
— 참조 대상: 배송헤더(DeliveryHeader)';
COMMENT ON COLUMN "DeliveryLine"."DeliveryLineSequence" IS '[KS X 9101 표준] 배송라인순번: — 배송 내 품목 행의 순서
— 배송라인은 배송식별자와 배송라인순번의 조합으로 구분함';
COMMENT ON COLUMN "DeliveryLine"."ProductReleaseID" IS '[KS X 9101 표준] 출고식별자: — 배송하는 제품출고의 고유값
