— 참조 대상: 제품출고(ProductRelease)';
COMMENT ON COLUMN "DeliveryLine"."ProductReleaseSequence" IS '[KS X 9101 표준] 출고순번: — 배송하는 제품출고의 행 순번
— 출고식별자(ProductReleaseID)와 함께 제품출고(ProductRelease)를 참조한다';
COMMENT ON COLUMN "DeliveryLine"."SalesDocumentNumber" IS '[KS X 9101 표준] 수주문서번호: — 수주문서번호
