— 참조 대상: 수주오더(SalesOrder)';
COMMENT ON COLUMN "DeliveryLine"."SalesDocumentSequence" IS '[KS X 9101 표준] 수주문서순번: — 수주문서순번
— 수주문서번호(SalesDocumentNumber)와 함께 수주오더(SalesOrder)를 참조한다';
COMMENT ON COLUMN "DeliveryLine"."ItemID" IS '[KS X 9101 표준] 품목식별자: — 품목을 식별하기 위한 고유값
— 고객에게 납품되는 제품을 의미
— 참조 대상: 품목마스터(ItemMaster)';
COMMENT ON COLUMN "DeliveryLine"."ItemName" IS '[KS X 9101 표준] 품목명: — 품목의 명칭
— 참조 대상: 품목마스터(ItemMaster.ItemName)';
COMMENT ON COLUMN "DeliveryLine"."InvoiceNumber" IS '[KS X 9101 표준] 거래명세서번호: — 거래명세서 문서에 부여되는 고유한 식별 번호';
COMMENT ON COLUMN "DeliveryLine"."LotID" IS '[KS X 9101 표준] 로트식별자: — 배송에 포함된 로트의 고유식별값
— 참조 대상: 로트(Lot)';
COMMENT ON COLUMN "DeliveryLine"."ItemUOMCode" IS '[KS X 9101 표준] 기준단위코드: — 기준단위코드(예: EA, DZ, HD 등)
— 참조 대상: 단위그룹(UOMGroup)의 단위코드';
COMMENT ON COLUMN "DeliveryLine"."ItemUnitQuantity" IS '[KS X 9101 표준] 기준단위수량: — 기준단위수량(수량의 단위는 기준단위코드로 함)';
COMMENT ON COLUMN "DeliveryLine"."OrderUOMCode" IS '[KS X 9101 표준] 오더단위코드: — 오더단위코드(예: EA, DZ, HD 등)
— 참조 대상: 단위그룹(UOMGroup)의 단위코드';
COMMENT ON COLUMN "DeliveryLine"."OrderQuantity" IS '[KS X 9101 표준] 오더수량: — 오더수량(수량의 단위는 오더단위코드로 함)';
COMMENT ON COLUMN "DeliveryLine"."ProductDeliveryUOMCode" IS '[KS X 9101 표준] 납품단위코드: — 납품단위코드(예: EA, DZ, HD 등)
— 참조 대상: 단위그룹(UOMGroup)의 단위코드';
COMMENT ON COLUMN "DeliveryLine"."ProductDeliveryQuantity" IS '[KS X 9101 표준] 납품수량: — 납품수량(수량의 단위는 납품단위코드로 함)';
COMMENT ON COLUMN "DeliveryLine"."RequestedDeliveryDate" IS '[KS X 9101 표준] 요청납품일: — 요청납품일(KS X ISO 8601을 따른다)
— 참조 대상: 수주오더(SalesOrder.RequestedDeliveryDate)';

-- ---------------------------------------------------------------------
-- [표준 구분: KS X 9101 표준] 표 76, 조항 7.4.9.1 | 업무영역: 서비스관리
-- 테이블명(물리): "Return" | 테이블명(논리): 반품
-- 설명: 반품(구매반품, 제품반품)에 대한 정보를 의미한다.
-- ---------------------------------------------------------------------
CREATE TABLE "Return" ( -- [KS X 9101 표준] 반품 (표 76)
    "ReturnSequenceNo" BIGINT GENERATED BY DEFAULT AS IDENTITY, -- [KS X 9101 표준] 반품 일련번호(PK)
    "EnterpriseID" VARCHAR(50) NOT NULL, -- [KS X 9101 표준] 회사식별자
    "SiteID" VARCHAR(50) NOT NULL, -- [KS X 9101 표준] 사업장식별자
    "PlantID" VARCHAR(50) NOT NULL, -- [KS X 9101 표준] 공장식별자
    "CreatorID" VARCHAR(50), -- [KS X 9101 표준] 등록자식별자
    "CreationDateTime" TIMESTAMP, -- [KS X 9101 표준] 등록일시
    "ModifierID" VARCHAR(50), -- [KS X 9101 표준] 수정자식별자
    "ModificationDateTime" TIMESTAMP, -- [KS X 9101 표준] 수정일시
    "Note" VARCHAR(1000), -- [KS X 9101 표준] 비고
    "ReturnID" VARCHAR(50) NOT NULL, -- [KS X 9101 표준] 반품식별자
    "ItemID" VARCHAR(50), -- [KS X 9101 표준] 품목식별자
    "LotID" VARCHAR(50), -- [KS X 9101 표준] 로트식별자
    "BatchID" VARCHAR(50), -- [KS X 9101 표준] 배치식별자
    "WarehouseID" VARCHAR(50), -- [KS X 9101 표준] 창고식별자
    "ReturnSequence" INTEGER NOT NULL, -- [KS X 9101 표준] 반품순서
    "ReturnNumber" VARCHAR(50), -- [KS X 9101 표준] 반품번호
    "ProductReturnDocumentNumber" VARCHAR(50), -- [KS X 9101 표준] 반품문서번호
    "ReturnDateTime" TIMESTAMP, -- [KS X 9101 표준] 반품일시
    "CustomerID" VARCHAR(50), -- [KS X 9101 표준] 고객사식별자
    "VendorID" VARCHAR(50), -- [KS X 9101 표준] 공급사식별자
    "ReturnQuantity" NUMERIC(18,6), -- [KS X 9101 표준] 반품수량
    "ReturnType" VARCHAR(30), -- [KS X 9101 표준] 반품유형
    CONSTRAINT "PK_Return" PRIMARY KEY ("ReturnSequenceNo"),
    CONSTRAINT "UK_Return" UNIQUE ("EnterpriseID", "ReturnID", "ReturnSequence")
);

COMMENT ON TABLE "Return" IS '[KS X 9101 표준] 반품 (반품(구매반품, 제품반품)에 대한 정보를 의미한다.)';
COMMENT ON COLUMN "Return"."ReturnSequenceNo" IS '[KS X 9101 표준] 반품 일련번호: — 테이블 행을 식별하는 일련번호(PK, 대리키) — 표준 외 물리 컬럼
— 자동 증가 값(IDENTITY)으로 부여하며 다른 테이블이 참조하지 않음(FK는 UK 참조)';
COMMENT ON COLUMN "Return"."EnterpriseID" IS '[KS X 9101 표준] 회사식별자: — 회사를 유일하게 구분할 수 있는 고유식별값
— 기업업무시스템 간의 연동을 수행하는 회사들 간에 자체적으로 정의한 고유식별값
— 참조 대상: 회사(Enterprise)';
COMMENT ON COLUMN "Return"."SiteID" IS '[KS X 9101 표준] 사업장식별자: — 회사 내에서 사업장을 구분할수 있는 고유식별값
— 참조 대상: 사업장(Site)';
COMMENT ON COLUMN "Return"."PlantID" IS '[KS X 9101 표준] 공장식별자: — 회사 내에서 공장을 구분할 수있는 고유식별값(만약, 공장 개념을 사용하지 않는다면 고정식별자로 설정하여 입력해야 함)
— 참조 대상: 공장(Plant)';
COMMENT ON COLUMN "Return"."CreatorID" IS '[KS X 9101 표준] 등록자식별자: — 정보를 처음으로 등록한 사람을 구분할 수 있는 고유식별값으로, 일반적으로 사원번호가사용됨
— 참조 대상: 사원(Personnel)';
COMMENT ON COLUMN "Return"."CreationDateTime" IS '[KS X 9101 표준] 등록일시: — 정보를 처음으로 등록한 날짜 (KS X ISO 8601을 따른다)';
COMMENT ON COLUMN "Return"."ModifierID" IS '[KS X 9101 표준] 수정자식별자: — 정보를 마지막으로 수정한 사람을 구분할 수 있는 고유식별값으로, 일반적으로 사원번호가 사용됨
— 참조 대상: 사원(Personnel)';
COMMENT ON COLUMN "Return"."ModificationDateTime" IS '[KS X 9101 표준] 수정일시: — 정보를 마지막으로 수정한 날짜 (KS X ISO 8601을 따른다.)';
COMMENT ON COLUMN "Return"."Note" IS '[KS X 9101 표준] 비고: — 비고사항';
COMMENT ON COLUMN "Return"."ReturnID" IS '[KS X 9101 표준] 반품식별자: — 반품처리를 식별하기 위한 고유값
— 반품 문서 단위로 부여하며, 한 반품 문서에 속한 모든 품목 행에 같은 값을 사용함';
COMMENT ON COLUMN "Return"."ItemID" IS '[KS X 9101 표준] 품목식별자: — 품목을 식별하기 위한 고유값
— 제품, 반제품, 상품, 원자재, 부자재, 저장품, 소모품 등회사내 시스템으로 관리되는 모든 품목을 포함
— 참조 대상: 품목마스터(ItemMaster)';
COMMENT ON COLUMN "Return"."LotID" IS '[KS X 9101 표준] 로트식별자: — 반품에 포함된 로트의 고유식별값
— 참조 대상: 로트(Lot)';
COMMENT ON COLUMN "Return"."BatchID" IS '[KS X 9101 표준] 배치식별자: — 반품에 포함된 배치의 고유식별값
— 참조 대상: 배치(Batch)';
COMMENT ON COLUMN "Return"."WarehouseID" IS '[KS X 9101 표준] 창고식별자: — 창고를 식별하기 위한 고유값
— 참조 대상: 창고(WarehouseLocation)';
COMMENT ON COLUMN "Return"."ReturnSequence" IS '[KS X 9101 표준] 반품순서: — 반품 순서
— 반품 행은 반품식별자와 반품순서의 조합으로 구분함';
COMMENT ON COLUMN "Return"."ReturnNumber" IS '[KS X 9101 표준] 반품번호: — 반품 번호';
COMMENT ON COLUMN "Return"."ProductReturnDocumentNumber" IS '[KS X 9101 표준] 반품문서번호: — 제품반품 문서번호';
COMMENT ON COLUMN "Return"."ReturnDateTime" IS '[KS X 9101 표준] 반품일시: — 반품일시(KS X ISO 8601을 따른다)';
COMMENT ON COLUMN "Return"."CustomerID" IS '[KS X 9101 표준] 고객사식별자: — 품목을 구매해가는 거래처를 식별하기 위한 고유값
— 참조 대상: 고객사(CustomerPartyMaster)';
COMMENT ON COLUMN "Return"."VendorID" IS '[KS X 9101 표준] 공급사식별자: — 품목을 구입해오는 거래처를 식별하기 위한 고유값
— 참조 대상: 공급사(VendorPartyMaster)';
COMMENT ON COLUMN "Return"."ReturnQuantity" IS '[KS X 9101 표준] 반품수량: — 반품 수량';
COMMENT ON COLUMN "Return"."ReturnType" IS '[KS X 9101 표준] 반품유형: — 반품 유형(구매, 제품 반품 등)
— 반품 유형의 세부적 분류는 불량, 수량오류, 오배송, 계약위반 등을 포함
— 참조 대상: 공통코드정보(CommonCodeMaster)의 코드';

-- ---------------------------------------------------------------------
-- [표준 구분: KS X 9101 표준] 표 77, 조항 7.4.9.2 | 업무영역: 서비스관리
-- 테이블명(물리): "ProductTraceParameterOnCustomer" | 테이블명(논리): 고객제품데이터
-- 설명: 고객에게 판매 완료 후 부가적인 서비스 제공 및 가치창출을 위해 고객 제품에서 수집되는 데이터를 의미한다.
-- ---------------------------------------------------------------------
CREATE TABLE "ProductTraceParameterOnCustomer" ( -- [KS X 9101 표준] 고객제품데이터 (표 77)
    "ProductTraceParameterOnCustomerSequenceNo" BIGINT GENERATED BY DEFAULT AS IDENTITY, -- [KS X 9101 표준] 고객제품데이터 일련번호(PK)
    "EnterpriseID" VARCHAR(50) NOT NULL, -- [KS X 9101 표준] 회사식별자
    "SiteID" VARCHAR(50) NOT NULL, -- [KS X 9101 표준] 사업장식별자
    "PlantID" VARCHAR(50) NOT NULL, -- [KS X 9101 표준] 공장식별자
    "CreatorID" VARCHAR(50), -- [KS X 9101 표준] 등록자식별자
    "CreationDateTime" TIMESTAMP, -- [KS X 9101 표준] 등록일시
    "ModifierID" VARCHAR(50), -- [KS X 9101 표준] 수정자식별자
    "ModificationDateTime" TIMESTAMP, -- [KS X 9101 표준] 수정일시
    "Note" VARCHAR(1000), -- [KS X 9101 표준] 비고
    "ProductTraceParameterOnCustomerID" VARCHAR(50) NOT NULL, -- [KS X 9101 표준] 고객제품데이터식별자
    "ItemID" VARCHAR(50), -- [KS X 9101 표준] 품목식별자
    "SerialNumber" VARCHAR(50), -- [KS X 9101 표준] 제조번호
    "Location" VARCHAR(1000), -- [KS X 9101 표준] 위치
    "ItemType" VARCHAR(30), -- [KS X 9101 표준] 품목유형
    "ParameterName" VARCHAR(200), -- [KS X 9101 표준] 파라미터명
    "ParameterValue" NUMERIC(18,6), -- [KS X 9101 표준] 파라미터값
    "CollectionDateTime" TIMESTAMP, -- [KS X 9101 표준] 수집일시
    CONSTRAINT "PK_ProductTraceParameterOnCustomer" PRIMARY KEY ("ProductTraceParameterOnCustomerSequenceNo"),
    CONSTRAINT "UK_ProductTraceParameterOnCustomer" UNIQUE ("EnterpriseID", "ProductTraceParameterOnCustomerID")
);

COMMENT ON TABLE "ProductTraceParameterOnCustomer" IS '[KS X 9101 표준] 고객제품데이터 (고객에게 판매 완료 후 부가적인 서비스 제공 및 가치창출을 위해 고객 제품에서 수집되는 데이터를 의미한다.)';
