COMMENT ON COLUMN "ProductTraceParameterOnCustomer"."ParameterValue" IS '[KS X 9101 표준] 파라미터값: — 수집된 파라미터 데이터의 값';
COMMENT ON COLUMN "ProductTraceParameterOnCustomer"."CollectionDateTime" IS '[KS X 9101 표준] 수집일시: — 데이터를 수집한 일시(KS X ISO 8601을 따른다)';

-- ---------------------------------------------------------------------
-- [표준 구분: KS X 9101 표준] 표 78, 조항 7.4.9.3 | 업무영역: 서비스관리
-- 테이블명(물리): "AfterSalesServiceRequest" | 테이블명(논리): 사후서비스신청
-- 설명: 고객에게 판매된 제품의 고장으로 제조자 혹은 대리점 등에 고장 접수 시 필요한 데이터를 의미한다.
-- ---------------------------------------------------------------------
CREATE TABLE "AfterSalesServiceRequest" ( -- [KS X 9101 표준] 사후서비스신청 (표 78)
    "AfterSalesServiceRequestSequenceNo" BIGINT GENERATED BY DEFAULT AS IDENTITY, -- [KS X 9101 표준] 사후서비스신청 일련번호(PK)
    "EnterpriseID" VARCHAR(50) NOT NULL, -- [KS X 9101 표준] 회사식별자
    "SiteID" VARCHAR(50) NOT NULL, -- [KS X 9101 표준] 사업장식별자
    "PlantID" VARCHAR(50) NOT NULL, -- [KS X 9101 표준] 공장식별자
    "CreatorID" VARCHAR(50), -- [KS X 9101 표준] 등록자식별자
    "CreationDateTime" TIMESTAMP, -- [KS X 9101 표준] 등록일시
    "ModifierID" VARCHAR(50), -- [KS X 9101 표준] 수정자식별자
    "ModificationDateTime" TIMESTAMP, -- [KS X 9101 표준] 수정일시
    "Note" VARCHAR(1000), -- [KS X 9101 표준] 비고
    "ItemID" VARCHAR(50), -- [KS X 9101 표준] 품목식별자
    "ItemName" VARCHAR(200), -- [KS X 9101 표준] 품목명
    "RequestNumber" VARCHAR(50) NOT NULL, -- [KS X 9101 표준] 신청번호
    "TransferSequence" INTEGER, -- [KS X 9101 표준] 이관순번
    "BasicAcceptProcessCode" VARCHAR(30), -- [KS X 9101 표준] 접수내용단순처리코드
    "PromisedVisitDateTime" TIMESTAMP, -- [KS X 9101 표준] 약속방문일시
    "TransferRegistrationCode" VARCHAR(30), -- [KS X 9101 표준] 이관등록코드
    "SerialNumber" VARCHAR(50), -- [KS X 9101 표준] 제조번호
    CONSTRAINT "PK_AfterSalesServiceRequest" PRIMARY KEY ("AfterSalesServiceRequestSequenceNo"),
    CONSTRAINT "UK_AfterSalesServiceRequest" UNIQUE ("EnterpriseID", "RequestNumber")
);

