COMMENT ON COLUMN "AfterSalesServiceRequest"."TransferRegistrationCode" IS '[KS X 9101 표준] 이관등록코드: — 사후서비스 접수 후 실제 사후서비스를 이관 받아 수행할 주체를 식별하기 위한 코드(예: 기사, 본사, 대리점 등)
