-- [표준 구분: KS X 9101 표준] 표 79, 조항 7.4.9.4 | 업무영역: 서비스관리
-- 테이블명(물리): "AfterSalesServiceRequestResult" | 테이블명(논리): 사후서비스결과
-- 설명: 고객의 사후서비스 접수 이후 제조사 혹은 대리점의 처리결과를 교환하기 위해 필요한 데이터를 의미한다.
-- ---------------------------------------------------------------------
CREATE TABLE "AfterSalesServiceRequestResult" ( -- [KS X 9101 표준] 사후서비스결과 (표 79)
    "AfterSalesServiceRequestResultSequenceNo" BIGINT GENERATED BY DEFAULT AS IDENTITY, -- [KS X 9101 표준] 사후서비스결과 일련번호(PK)
    "EnterpriseID" VARCHAR(50) NOT NULL, -- [KS X 9101 표준] 회사식별자
    "SiteID" VARCHAR(50) NOT NULL, -- [KS X 9101 표준] 사업장식별자
    "PlantID" VARCHAR(50) NOT NULL, -- [KS X 9101 표준] 공장식별자
    "CreatorID" VARCHAR(50), -- [KS X 9101 표준] 등록자식별자
    "CreationDateTime" TIMESTAMP, -- [KS X 9101 표준] 등록일시
    "ModifierID" VARCHAR(50), -- [KS X 9101 표준] 수정자식별자
    "ModificationDateTime" TIMESTAMP, -- [KS X 9101 표준] 수정일시
    "Note" VARCHAR(1000), -- [KS X 9101 표준] 비고
    "ItemID" VARCHAR(50), -- [KS X 9101 표준] 품목식별자
    "ItemName" VARCHAR(200), -- [KS X 9101 표준] 품목명
    "RequestNumber" VARCHAR(50) NOT NULL, -- [KS X 9101 표준] 신청번호
    "TransferSequence" INTEGER NOT NULL, -- [KS X 9101 표준] 이관순번
    "RegisterSequence" INTEGER NOT NULL, -- [KS X 9101 표준] 등록순번
    "RepairSequence" INTEGER NOT NULL, -- [KS X 9101 표준] 수리순번
    "SerialNumber" VARCHAR(50), -- [KS X 9101 표준] 제조번호
    "FaultLargeClass" VARCHAR(30), -- [KS X 9101 표준] 하자현상대분류
    "FaultSmallClass" VARCHAR(30), -- [KS X 9101 표준] 하자현상소분류
    "ErrorCode" VARCHAR(30), -- [KS X 9101 표준] 오류코드
    "InstallationDate" DATE, -- [KS X 9101 표준] 설치일
    "ProcessingDate" DATE, -- [KS X 9101 표준] 처리일
    "EndIndicator" BOOLEAN, -- [KS X 9101 표준] 종료여부
    "WorkType" VARCHAR(30), -- [KS X 9101 표준] 작업유형
    "ChildItemID" VARCHAR(50), -- [KS X 9101 표준] 자품목식별자
    "ChildItemName" VARCHAR(200), -- [KS X 9101 표준] 자품목명
    "ItemSpecification" VARCHAR(1000), -- [KS X 9101 표준] 품목사양
    "RepairType" VARCHAR(30), -- [KS X 9101 표준] 수리유형
    CONSTRAINT "PK_AfterSalesServiceRequestResult" PRIMARY KEY ("AfterSalesServiceRequestResultSequenceNo"),
    CONSTRAINT "UK_AfterSalesServiceRequestResult" UNIQUE ("EnterpriseID", "RequestNumber", "TransferSequence", "RegisterSequence", "RepairSequence")
);

