— 참조 대상: 사원(Personnel)';
COMMENT ON COLUMN "AfterSalesServiceRequestResult"."CreationDateTime" IS '[KS X 9101 표준] 등록일시: — 정보를 처음으로 등록한 날짜 (KS X ISO 8601을 따른다)';
COMMENT ON COLUMN "AfterSalesServiceRequestResult"."ModifierID" IS '[KS X 9101 표준] 수정자식별자: — 정보를 마지막으로 수정한 사람을 구분할 수 있는 고유식별값으로, 일반적으로 사원번호가 사용됨
— 참조 대상: 사원(Personnel)';
COMMENT ON COLUMN "AfterSalesServiceRequestResult"."ModificationDateTime" IS '[KS X 9101 표준] 수정일시: — 정보를 마지막으로 수정한 날짜 (KS X ISO 8601을 따른다.)';
COMMENT ON COLUMN "AfterSalesServiceRequestResult"."Note" IS '[KS X 9101 표준] 비고: — 비고사항';
COMMENT ON COLUMN "AfterSalesServiceRequestResult"."ItemID" IS '[KS X 9101 표준] 품목식별자: — 사후서비스 처리 제품을 식별하기 위한 고유값
— 참조 대상: 품목마스터(ItemMaster)';
COMMENT ON COLUMN "AfterSalesServiceRequestResult"."ItemName" IS '[KS X 9101 표준] 품목명: — 사후서비스 처리 제품의 명칭
— 참조 대상: 품목마스터(ItemMaster.ItemName)';
COMMENT ON COLUMN "AfterSalesServiceRequestResult"."RequestNumber" IS '[KS X 9101 표준] 신청번호: — 사후서비스접수 번호
— 참조 대상: 사후서비스신청(AfterSalesServiceRequest)';
COMMENT ON COLUMN "AfterSalesServiceRequestResult"."TransferSequence" IS '[KS X 9101 표준] 이관순번: — 대리점 혹은 관련 부서 등에 이관한 순번';
COMMENT ON COLUMN "AfterSalesServiceRequestResult"."RegisterSequence" IS '[KS X 9101 표준] 등록순번: — 사후서비스가 접수 등록된 순번';
COMMENT ON COLUMN "AfterSalesServiceRequestResult"."RepairSequence" IS '[KS X 9101 표준] 수리순번: — 사후서비스가 이루어진 순번
— 사후서비스결과 행은 신청번호, 이관순번, 등록순번, 수리순번의 조합으로 구분하며, 조합에 포함되는 속성은 값을 생략할 수 없음(7.1)';
COMMENT ON COLUMN "AfterSalesServiceRequestResult"."SerialNumber" IS '[KS X 9101 표준] 제조번호: — 데이터 발생 장치를 포함하는 제품의 고유 제조번호
— 참조 대상: 고객 설치 제품(제조번호 단위)
— 이 표준에 정의되지 않은 명사로, 7.1의 확장 명사 규정을 따른다';
COMMENT ON COLUMN "AfterSalesServiceRequestResult"."FaultLargeClass" IS '[KS X 9101 표준] 하자현상대분류: — 제품고장이 속한 현상대분류
— 하자현상대분류는 공통코드에 등록하여 관리하며 회사기준 분류체계에 의해 정해짐
— 예: 전원, 동작, 소음·진동, 누수·누유, 표시·제어, 외관 등
— 참조 대상: 공통코드정보(CommonCodeMaster)의 코드';
COMMENT ON COLUMN "AfterSalesServiceRequestResult"."FaultSmallClass" IS '[KS X 9101 표준] 하자현상소분류: — 제품고장이 속한 현상소분류
— 하자현상소분류는 공통코드에 등록하여 관리하며 회사기준 분류체계에 의해 정해짐
— 예: 하자현상대분류 전원 하위의 전원 안 켜짐, 전원 차단 반복 등
— 참조 대상: 공통코드정보(CommonCodeMaster)의 코드';
COMMENT ON COLUMN "AfterSalesServiceRequestResult"."ErrorCode" IS '[KS X 9101 표준] 오류코드: — 오류 발생 시 해당 오류 코드 값
— 예: 전원 불량, 동작 불량, 소음·진동, 누수·누유, 표시부 오류 등
— 공통코드그룹은 서비스오류코드(ServiceErrorCode)로 하고, 코드값은 접두어 ‘AS-’로 시작(예: AS-001)
— 참조 대상: 공통코드정보(CommonCodeMaster)의 코드';
COMMENT ON COLUMN "AfterSalesServiceRequestResult"."InstallationDate" IS '[KS X 9101 표준] 설치일: — 설치형 제품의 경우 고객에 제품이 설치된 일자';
COMMENT ON COLUMN "AfterSalesServiceRequestResult"."ProcessingDate" IS '[KS X 9101 표준] 처리일: — 사후서비스가 처리된 일자';
COMMENT ON COLUMN "AfterSalesServiceRequestResult"."EndIndicator" IS '[KS X 9101 표준] 종료여부: — 사후서비스처리가 완전히 종료되었는지 여부를 확인하기 위한 여부';
COMMENT ON COLUMN "AfterSalesServiceRequestResult"."WorkType" IS '[KS X 9101 표준] 작업유형: — 교환, 수리, 점검 등 사후서비스 처리 내용
— 참조 대상: 공통코드정보(CommonCodeMaster)의 코드';
COMMENT ON COLUMN "AfterSalesServiceRequestResult"."ChildItemID" IS '[KS X 9101 표준] 자품목식별자: — 사후서비스가 이루어진 대상 자품목(부품)코드
— 참조 대상: 품목마스터(ItemMaster)';
COMMENT ON COLUMN "AfterSalesServiceRequestResult"."ChildItemName" IS '[KS X 9101 표준] 자품목명: — 사후서비스가 이루어진 대상 자품목(부품)명';
COMMENT ON COLUMN "AfterSalesServiceRequestResult"."ItemSpecification" IS '[KS X 9101 표준] 품목사양: — 품목의 사양 또는 규격
— 참조 대상: 품목마스터(ItemMaster.ItemSpecification)';
COMMENT ON COLUMN "AfterSalesServiceRequestResult"."RepairType" IS '[KS X 9101 표준] 수리유형: — 사후서비스 부품별로 어떤 현상으로 교체하였는지 관리하기 위한 유형
— 수리유형은 공통코드에 등록하여 관리하며 회사 기준분류 체계에 의해 정해짐
— 예: 마모, 파손, 소손, 부식, 오염, 기능 불량, 예방 교체 등
— 참조 대상: 공통코드정보(CommonCodeMaster)의 코드';

-- =====================================================================================
-- [PART 2] MPSI 금형/사출 14단계(Step 0~13) 실무 특화 확장 테이블 (총 20개 테이블)
-- KS X 9101-1 표준에 정의되지 않은 사출 금형 개발 및 양산 실무 워크플로우를 완벽 지원하기 위해
-- KS X 9101 명명 규칙(대소문자 보존, SequenceNo, IDREF, BaseAttributes 확장)을 준용하여 확장
-- =====================================================================================

-- 1. Table: "MpsiProjectStage" (공정 14단계 상태 머신)
CREATE TABLE IF NOT EXISTS "MpsiProjectStage" (
    "StageSequenceNo"                BIGINT GENERATED BY DEFAULT AS IDENTITY, -- [MPSI 실무 확장] 단계 일련번호(PK)
    "ProjectID"                      VARCHAR(50)          NOT NULL, -- [KS X 9101 표준 준용] 프로젝트식별자
    "StepNumber"                     INTEGER              NOT NULL, -- [MPSI 실무 확장] 공정 단계 번호 (0~13)
    "StepName"                       VARCHAR(100)         NOT NULL, -- [MPSI 실무 확장] 공정 단계명
    "StepStatus"                     VARCHAR(30)          DEFAULT '대기', -- [MPSI 실무 확장] 단계 진행상태 (대기/진행중/완료/지연)
    "ResponsibleOrgType"             VARCHAR(30)          NOT NULL, -- [MPSI 실무 확장] 주관 조직 (MPSI, MOLD_VENDOR, MASS_VENDOR)
    "PlannedStartDate"               DATE, -- [MPSI 실무 확장] 계획 시작일자
    "PlannedEndDate"                 DATE, -- [MPSI 실무 확장] 계획 완료일자
    "ActualStartDate"                DATE, -- [MPSI 실무 확장] 실제 착수일자
    "ActualEndDate"                  DATE, -- [MPSI 실무 확장] 실제 완료일자
    "CompletionRate"                 NUMERIC(5,2)         DEFAULT 0.00, -- [MPSI 실무 확장] 단계 달성률 (%)
    "ApprovalStatus"                 VARCHAR(30)          DEFAULT '미승인', -- [MPSI 실무 확장] 단계 승인여부 (미승인/승인완료/반려)
    "ApproverID"                     VARCHAR(50), -- [KS X 9101 표준 준용] 승인자 사원식별자
    "ApprovalDateTime"               TIMESTAMP, -- [KS X 9101 표준 준용] 승인일시
    "CreatorID"                      VARCHAR(50), -- [KS X 9101 표준 준용] 등록자식별자
    "CreationDateTime"               TIMESTAMP            DEFAULT CURRENT_TIMESTAMP, -- [KS X 9101 표준 준용] 등록일시
    "ModifierID"                     VARCHAR(50), -- [KS X 9101 표준 준용] 수정자식별자
    "ModificationDateTime"           TIMESTAMP            DEFAULT CURRENT_TIMESTAMP, -- [KS X 9101 표준 준용] 수정일시
    "Note"                           VARCHAR(1000), -- [KS X 9101 표준 준용] 비고
    CONSTRAINT "PK_MpsiProjectStage" PRIMARY KEY ("StageSequenceNo"),
    CONSTRAINT "UK_MpsiProjectStage" UNIQUE ("ProjectID", "StepNumber")
);

COMMENT ON TABLE "MpsiProjectStage" IS '[MPSI 실무 확장] 14단계(Step 0~13) 공정 라이프사이클 상태 머신 테이블';
COMMENT ON COLUMN "MpsiProjectStage"."StageSequenceNo" IS '[MPSI 실무 확장] 단계 일련번호(PK)';
COMMENT ON COLUMN "MpsiProjectStage"."ProjectID" IS '[KS X 9101 표준 준용] 대상 프로젝트 식별자 (ProjectMaster 참조)';
COMMENT ON COLUMN "MpsiProjectStage"."StepNumber" IS '[MPSI 실무 확장] 공정 단계 순번 (0:원청견적, 1~10:금형개발, 11~13:사출양산)';
COMMENT ON COLUMN "MpsiProjectStage"."StepName" IS '[MPSI 실무 확장] 공정 단계 공식 명칭';
COMMENT ON COLUMN "MpsiProjectStage"."StepStatus" IS '[MPSI 실무 확장] 단계 진행 상태';

-- 2. Table: "MpsiMoldQuotation" (금형 개발 견적 및 계약 관리 - 공정 1단계)
CREATE TABLE IF NOT EXISTS "MpsiMoldQuotation" (
    "QuotationSequenceNo"            BIGINT GENERATED BY DEFAULT AS IDENTITY, -- [MPSI 실무 확장] 견적 일련번호(PK)
    "QuotationID"                    VARCHAR(50)          NOT NULL, -- [MPSI 실무 확장] 견적서 식별자
    "ProjectID"                      VARCHAR(50)          NOT NULL, -- [KS X 9101 표준 준용] 프로젝트식별자
    "EstimateNumber"                 VARCHAR(50)          NOT NULL, -- [MPSI 실무 확장] 견적 관리번호 (예: Q26001-01)
    "MoldVendorID"                   VARCHAR(50)          NOT NULL, -- [KS X 9101 표준 준용] 금형제작사식별자 (VendorPartyMaster 참조)
    "MaterialCost"                   NUMERIC(15,2)        DEFAULT 0, -- [MPSI 실무 확장] 재료비 (원)
    "MachiningCost"                  NUMERIC(15,2)        DEFAULT 0, -- [MPSI 실무 확장] 가공비 (원)
    "DesignCost"                     NUMERIC(15,2)        DEFAULT 0, -- [MPSI 실무 확장] 설계비 (원)
    "ManagementCost"                 NUMERIC(15,2)        DEFAULT 0, -- [MPSI 실무 확장] 일반관리비 (원)
    "TotalQuotationAmount"           NUMERIC(15,2)        NOT NULL, -- [MPSI 실무 확장] 금형 견적 총액 (원)
    "FinalNegotiatedAmount"          NUMERIC(15,2), -- [MPSI 실무 확장] 최종 네고 합의금액 (원)
    "TargetMoldDays"                 INTEGER, -- [MPSI 실무 확장] 목표 제작 소요일수 (일)
    "QuotationStatus"                VARCHAR(30)          DEFAULT '견적제출', -- [MPSI 실무 확장] 견적 상태 (견적제출/네고중/수주확정/미성사)
    "SubmissionDate"                 DATE                 NOT NULL, -- [MPSI 실무 확장] 견적 제출일자
    "ConfirmedDate"                  DATE, -- [MPSI 실무 확장] 수주 확정일자
    "CreatorID"                      VARCHAR(50), -- [KS X 9101 표준 준용] 등록자식별자
    "CreationDateTime"               TIMESTAMP            DEFAULT CURRENT_TIMESTAMP, -- [KS X 9101 표준 준용] 등록일시
    "ModifierID"                     VARCHAR(50), -- [KS X 9101 표준 준용] 수정자식별자
    "ModificationDateTime"           TIMESTAMP            DEFAULT CURRENT_TIMESTAMP, -- [KS X 9101 표준 준용] 수정일시
    "Note"                           VARCHAR(1000), -- [KS X 9101 표준 준용] 비고
    CONSTRAINT "PK_MpsiMoldQuotation" PRIMARY KEY ("QuotationSequenceNo"),
    CONSTRAINT "UK_MpsiMoldQuotation" UNIQUE ("QuotationID")
);

COMMENT ON TABLE "MpsiMoldQuotation" IS '[MPSI 실무 확장] 금형 외주 견적서 및 수주 계약 관리 테이블 (공정 1단계)';

-- 3. Table: "MpsiMoldDesign" (제품 검토 및 금형 3D 설계 - 공정 2~3단계)
CREATE TABLE IF NOT EXISTS "MpsiMoldDesign" (
    "DesignSequenceNo"               BIGINT GENERATED BY DEFAULT AS IDENTITY, -- [MPSI 실무 확장] 설계 일련번호(PK)
    "DesignID"                       VARCHAR(50)          NOT NULL, -- [MPSI 실무 확장] 설계 식별자
    "ProjectID"                      VARCHAR(50)          NOT NULL, -- [KS X 9101 표준 준용] 프로젝트식별자
    "CadRevision"                    VARCHAR(20)          NOT NULL, -- [MPSI 실무 확장] CAD 버전
    "Product3DModelFile"             VARCHAR(255), -- [MPSI 실무 확장] 제품 3D 모델 파일명 (STEP)
    "Mold3DModelFile"                VARCHAR(255), -- [MPSI 실무 확장] 금형 3D 조립도 파일명
    "DfmReportFile"                  VARCHAR(255), -- [MPSI 실무 확장] DFM 제조성 검토서 파일명
    "CaeAnalysisFile"                VARCHAR(255), -- [MPSI 실무 확장] Moldflow 유동해석 성적서
    "DesignReviewStatus"             VARCHAR(30)          DEFAULT '검토진행중', -- [MPSI 실무 확장] 설계 검토 상태
    "DesignApprovalStatus"           VARCHAR(30)          DEFAULT '미승인', -- [MPSI 실무 확장] 출도 승인 여부
    "ApprovedDateTime"               TIMESTAMP, -- [MPSI 실무 확장] 출도 승인 일시
    "CreatorID"                      VARCHAR(50), -- [KS X 9101 표준 준용] 등록자식별자
    "CreationDateTime"               TIMESTAMP            DEFAULT CURRENT_TIMESTAMP, -- [KS X 9101 표준 준용] 등록일시
    CONSTRAINT "PK_MpsiMoldDesign" PRIMARY KEY ("DesignSequenceNo"),
    CONSTRAINT "UK_MpsiMoldDesign" UNIQUE ("DesignID")
);

COMMENT ON TABLE "MpsiMoldDesign" IS '[MPSI 실무 확장] 제품 3D 모델 검토 및 금형 출도 설계 관리 테이블 (공정 2~3단계)';

-- 4. Table: "MpsiMoldManufacture" (금형 7대 가공 공정 관리 - 공정 4~6단계)
CREATE TABLE IF NOT EXISTS "MpsiMoldManufacture" (
    "ManufactureSequenceNo"          BIGINT GENERATED BY DEFAULT AS IDENTITY, -- [MPSI 실무 확장] 제작 일련번호(PK)
    "ManufactureID"                  VARCHAR(50)          NOT NULL, -- [MPSI 실무 확장] 제작 식별자
    "ProjectID"                      VARCHAR(50)          NOT NULL, -- [KS X 9101 표준 준용] 프로젝트식별자
    "MoldPoNo"                       VARCHAR(50)          NOT NULL, -- [MPSI 실무 확장] MPSI 금형 발주번호 (PO)
    "OrderAmount"                    NUMERIC(15,2)        NOT NULL, -- [MPSI 실무 확장] 발주금액 (원)
    "OrderDate"                      DATE                 NOT NULL, -- [MPSI 실무 확장] 발주일자
    "TargetT1Date"                   DATE                 NOT NULL, -- [MPSI 실무 확장] 목표 T1 시사출일
    "MoldDeliveryDate"               DATE, -- [MPSI 실무 확장] 금형 출고 납기일
    "OverallProgressRate"            NUMERIC(5,2)         DEFAULT 0.00, -- [MPSI 실무 확장] 전체 가공 공정률 (%)
    "GunDrillProgress"               NUMERIC(5,2)         DEFAULT 0.00, -- [MPSI 실무 확장] 1. 건드릴 공정률
    "MillingProgress"                NUMERIC(5,2)         DEFAULT 0.00, -- [MPSI 실무 확장] 2. 밀링 공정률
    "HeatTreatmentProgress"          NUMERIC(5,2)         DEFAULT 0.00, -- [MPSI 실무 확장] 3. 열처리 공정률
    "CncMachiningProgress"           NUMERIC(5,2)         DEFAULT 0.00, -- [MPSI 실무 확장] 4. CNC 가공 공정률
    "EdmProgress"                    NUMERIC(5,2)         DEFAULT 0.00, -- [MPSI 실무 확장] 5. 방전가공 공정률
    "PolishingProgress"              NUMERIC(5,2)         DEFAULT 0.00, -- [MPSI 실무 확장] 6. 래핑/사상 공정률
    "AssemblyProgress"               NUMERIC(5,2)         DEFAULT 0.00, -- [MPSI 실무 확장] 7. 조립/습합 공정률
    "ManufactureStatus"              VARCHAR(30)          DEFAULT '가공중', -- [MPSI 실무 확장] 제작 상태
    "CreatorID"                      VARCHAR(50), -- [KS X 9101 표준 준용] 등록자식별자
    "CreationDateTime"               TIMESTAMP            DEFAULT CURRENT_TIMESTAMP, -- [KS X 9101 표준 준용] 등록일시
    "ModifierID"                     VARCHAR(50), -- [KS X 9101 표준 준용] 수정자식별자
    "ModificationDateTime"           TIMESTAMP            DEFAULT CURRENT_TIMESTAMP, -- [KS X 9101 표준 준용] 수정일시
    CONSTRAINT "PK_MpsiMoldManufacture" PRIMARY KEY ("ManufactureSequenceNo"),
    CONSTRAINT "UK_MpsiMoldManufacture" UNIQUE ("ManufactureID")
);

COMMENT ON TABLE "MpsiMoldManufacture" IS '[MPSI 실무 확장] 금형 7대 가공 공정 및 제작 진척 관리 테이블 (공정 4~6단계)';

-- 5. Table: "MpsiMoldTrial" (T1~T4 시사출 및 금형 육성 관리 - 공정 7~10단계)
CREATE TABLE IF NOT EXISTS "MpsiMoldTrial" (
    "TrialSequenceNo"                BIGINT GENERATED BY DEFAULT AS IDENTITY, -- [MPSI 실무 확장] 시사출 일련번호(PK)
    "TrialID"                        VARCHAR(50)          NOT NULL, -- [MPSI 실무 확장] 시사출 고유 식별자
    "ProjectID"                      VARCHAR(50)          NOT NULL, -- [KS X 9101 표준 준용] 프로젝트식별자
    "TrialDegree"                    VARCHAR(20)          NOT NULL, -- [MPSI 실무 확장] 시사출 차수 (T1, T2, T3, T4)
    "TrialDate"                      DATE                 NOT NULL, -- [MPSI 실무 확장] 시사출 실시일자
    "TrialLocation"                  VARCHAR(100), -- [MPSI 실무 확장] 시사출 장소 (외주처 또는 MPSI)
    "MachineTonnage"                 VARCHAR(50), -- [MPSI 실무 확장] 시사출기 톤수 (예: 450T)
    "ClampingForceTon"               NUMERIC(10,2), -- [MPSI 실무 확장] 형체력
    "CycleTimeSeconds"               NUMERIC(8,2), -- [MPSI 실무 확장] 사이클 타임 (초)
    "TrialStatus"                    VARCHAR(30)          DEFAULT '육성 진행중', -- [MPSI 실무 확장] 결과 상태 (Pass, Fail, 육성 진행중)
    "MpsiDecision"                   VARCHAR(30)          DEFAULT '검토중', -- [MPSI 실무 확장] MPSI 승인 판정
    "TrialReportFile"                VARCHAR(255), -- [MPSI 실무 확장] 시사출 성적서 첨부 파일
    "DimensionReportFile"            VARCHAR(255), -- [MPSI 실무 확장] CMM 치수 성적서 첨부 파일
    "CreatorID"                      VARCHAR(50), -- [KS X 9101 표준 준용] 등록자식별자
    "CreationDateTime"               TIMESTAMP            DEFAULT CURRENT_TIMESTAMP, -- [KS X 9101 표준 준용] 등록일시
    CONSTRAINT "PK_MpsiMoldTrial" PRIMARY KEY ("TrialSequenceNo"),
    CONSTRAINT "UK_MpsiMoldTrial" UNIQUE ("TrialID")
);

COMMENT ON TABLE "MpsiMoldTrial" IS '[MPSI 실무 확장] T1~T4 시사출 조건표 및 금형 육성 관리 테이블 (공정 7~10단계)';

-- 6. Table: "MpsiInspectionReport" (시사출 치수 검사 성적서)
CREATE TABLE IF NOT EXISTS "MpsiInspectionReport" (
    "InspectionSequenceNo"           BIGINT GENERATED BY DEFAULT AS IDENTITY, -- [MPSI 실무 확장] 검사 일련번호(PK)
    "InspectionID"                   VARCHAR(50)          NOT NULL, -- [MPSI 실무 확장] 검사 식별자
    "TrialID"                        VARCHAR(50)          NOT NULL, -- [MPSI 실무 확장] 시사출 식별자
    "ProjectID"                      VARCHAR(50)          NOT NULL, -- [KS X 9101 표준 준용] 프로젝트식별자
    "InspectionType"                 VARCHAR(50)          NOT NULL, -- [MPSI 실무 확장] 검사 유형 (3차원 측정, 외관, 중량)
    "TotalInspectionPoints"          INTEGER              DEFAULT 0, -- [MPSI 실무 확장] 총 측정 포인트 수
    "PassedPoints"                   INTEGER              DEFAULT 0, -- [MPSI 실무 확장] 합격 포인트 수
    "FailedPoints"                   INTEGER              DEFAULT 0, -- [MPSI 실무 확장] 불합격 포인트 수
    "InspectionResult"               VARCHAR(20)          NOT NULL, -- [MPSI 실무 확장] 판정 결과 (OK, NG)
    "InspectorName"                  VARCHAR(50)          NOT NULL, -- [MPSI 실무 확장] 검사원 명칭
    "InspectionDate"                 DATE                 NOT NULL, -- [MPSI 실무 확장] 검사 일자
    "ReportFileName"                 VARCHAR(255), -- [MPSI 실무 확장] 성적서 파일
    CONSTRAINT "PK_MpsiInspectionReport" PRIMARY KEY ("InspectionSequenceNo"),
    CONSTRAINT "UK_MpsiInspectionReport" UNIQUE ("InspectionID")
);

COMMENT ON TABLE "MpsiInspectionReport" IS '[MPSI 실무 확장] 시사출 CMM 3차원 치수 및 품질 검사 성적서 테이블';

-- 7. Table: "MpsiMoldApproval" (금형제작 승인원 및 최종 명판 - 공정 10단계)
CREATE TABLE IF NOT EXISTS "MpsiMoldApproval" (
    "ApprovalSequenceNo"             BIGINT GENERATED BY DEFAULT AS IDENTITY, -- [MPSI 실무 확장] 승인 일련번호(PK)
    "ApprovalID"                     VARCHAR(50)          NOT NULL, -- [MPSI 실무 확장] 승인 식별자
    "ProjectID"                      VARCHAR(50)          NOT NULL, -- [KS X 9101 표준 준용] 프로젝트식별자
    "ApprovalCertificateNo"          VARCHAR(50)          NOT NULL, -- [MPSI 실무 확장] 금형제작 승인서 번호
    "FinalSamplePictureFile"         VARCHAR(255), -- [MPSI 실무 확장] 최종 초물 샘플 사진
    "MoldAssemblyPictureFile"        VARCHAR(255), -- [MPSI 실무 확장] 금형 조립 실물 사진
    "MoldNameplateFile"              VARCHAR(255), -- [MPSI 실무 확장] 금형 고유 명판 사진
    "ApprovedBy"                     VARCHAR(50)          NOT NULL, -- [MPSI 실무 확장] 최종 승인권자 (품질이사)
    "ApprovalDate"                   DATE                 NOT NULL, -- [MPSI 실무 확장] 승인 일자
    "IsApproved"                     BOOLEAN              DEFAULT FALSE, -- [MPSI 실무 확장] 승인 확정 여부
    CONSTRAINT "PK_MpsiMoldApproval" PRIMARY KEY ("ApprovalSequenceNo"),
    CONSTRAINT "UK_MpsiMoldApproval" UNIQUE ("ApprovalID")
);

COMMENT ON TABLE "MpsiMoldApproval" IS '[MPSI 실무 확장] 금형제작 완료 승인원 및 명판 등록 관리 테이블 (공정 10단계)';

-- 8. Table: "MpsiMoldTransfer" (금형 양산처 이관 및 인수인계 - 공정 10단계 완료)
CREATE TABLE IF NOT EXISTS "MpsiMoldTransfer" (
    "TransferSequenceNo"             BIGINT GENERATED BY DEFAULT AS IDENTITY, -- [MPSI 실무 확장] 이관 일련번호(PK)
    "TransferID"                     VARCHAR(50)          NOT NULL, -- [MPSI 실무 확장] 이관 식별자
    "ProjectID"                      VARCHAR(50)          NOT NULL, -- [KS X 9101 표준 준용] 프로젝트식별자
    "DispatchVendorID"               VARCHAR(50)          NOT NULL, -- [KS X 9101 표준 준용] 인출 제작처 (우성정공 등)
    "ReceiveVendorID"                VARCHAR(50)          NOT NULL, -- [KS X 9101 표준 준용] 인수 양산처 (뉴몰드 등)
    "TransferPlanDate"               DATE                 NOT NULL, -- [MPSI 실무 확장] 이관 계획일
    "TransferActualDate"             DATE, -- [MPSI 실무 확장] 실제 이관 완료일
    "HandoverCertificateFile"        VARCHAR(255), -- [MPSI 실무 확장] 금형 인수인계 확인서 파일
    "TransferStatus"                 VARCHAR(30)          DEFAULT '이관대기', -- [MPSI 실무 확장] 이관 상태
    "ConfirmedBy"                    VARCHAR(50), -- [MPSI 실무 확장] 인수 확인자
    CONSTRAINT "PK_MpsiMoldTransfer" PRIMARY KEY ("TransferSequenceNo"),
    CONSTRAINT "UK_MpsiMoldTransfer" UNIQUE ("TransferID")
);

COMMENT ON TABLE "MpsiMoldTransfer" IS '[MPSI 실무 확장] 금형제작처 ➔ 사출양산처 간 금형 실물 인수인계 관리 테이블';

-- 9. Table: "MpsiMassProductionValidation" (12H 연속사출 및 Cpk 공정능력 검증 - 공정 11단계)
CREATE TABLE IF NOT EXISTS "MpsiMassProductionValidation" (
    "ValidationSequenceNo"           BIGINT GENERATED BY DEFAULT AS IDENTITY, -- [MPSI 실무 확장] 검증 일련번호(PK)
    "ValidationID"                   VARCHAR(50)          NOT NULL, -- [MPSI 실무 확장] 검증 식별자
    "ProjectID"                      VARCHAR(50)          NOT NULL, -- [KS X 9101 표준 준용] 프로젝트식별자
    "MassVendorID"                   VARCHAR(50)          NOT NULL, -- [KS X 9101 표준 준용] 사출양산처 (뉴몰드 등)
    "ContinuousHours"                INTEGER              DEFAULT 12, -- [MPSI 실무 확장] 연속 사출 가동시간 (시간)
    "TotalShotCount"                 INTEGER              NOT NULL, -- [MPSI 실무 확장] 연속사출 총 타수 (Shot)
    "TotalProducedQuantity"          INTEGER              NOT NULL, -- [MPSI 실무 확장] 양품 생산수량 (EA)
    "DefectQuantity"                 INTEGER              DEFAULT 0, -- [MPSI 실무 확장] 불량 수량 (EA)
    "DefectRate"                     NUMERIC(5,2)         DEFAULT 0.00, -- [MPSI 실무 확장] 불량률 (%)
    "MeasuredCpk"                    NUMERIC(5,3)         NOT NULL, -- [MPSI 실무 확장] 측정 공정능력지수 Cpk (기준 >= 1.33)
    "CpkPassed"                      BOOLEAN              DEFAULT FALSE, -- [MPSI 실무 확장] Cpk 적합 여부
    "ValidationStatus"               VARCHAR(30)          DEFAULT '검증진행중', -- [MPSI 실무 확장] 검증 상태
    "ValidationReportFile"           VARCHAR(255), -- [MPSI 실무 확장] 시양산 검증 성적서
    "CreatorID"                      VARCHAR(50), -- [KS X 9101 표준 준용] 등록자식별자
    "CreationDateTime"               TIMESTAMP            DEFAULT CURRENT_TIMESTAMP, -- [KS X 9101 표준 준용] 등록일시
    CONSTRAINT "PK_MpsiMassProductionValidation" PRIMARY KEY ("ValidationSequenceNo"),
    CONSTRAINT "UK_MpsiMassProductionValidation" UNIQUE ("ValidationID")
);

COMMENT ON TABLE "MpsiMassProductionValidation" IS '[MPSI 실무 확장] 12시간 연속 사출 및 Cpk 공정능력 심사 관리 테이블 (공정 11단계)';

-- 10. Table: "MpsiPpapDocument" (PPAP 18대 품질서류 및 부품제출보증서 PSW - 공정 12단계)
CREATE TABLE IF NOT EXISTS "MpsiPpapDocument" (
    "PpapSequenceNo"                 BIGINT GENERATED BY DEFAULT AS IDENTITY, -- [MPSI 실무 확장] PPAP 일련번호(PK)
    "PpapID"                         VARCHAR(50)          NOT NULL, -- [MPSI 실무 확장] PPAP 식별자
    "ProjectID"                      VARCHAR(50)          NOT NULL, -- [KS X 9101 표준 준용] 프로젝트식별자
    "SubmissionRound"                INTEGER              DEFAULT 1, -- [MPSI 실무 확장] 제출 회차 (1회차, 2회차...)
    "DocumentPackageFile"            VARCHAR(255)         NOT NULL, -- [MPSI 실무 확장] 18대 품질서류 통합 압축 패키지
    "PswApprovalStatus"              VARCHAR(30)          DEFAULT '심사진행중', -- [MPSI 실무 확장] PSW 승인 상태 (심사진행중/양산승인/반려)
    "PartPoNo"                       VARCHAR(50), -- [MPSI 실무 확장] 최종 양산 구매 PO 번호
    "PartPoDate"                     DATE, -- [MPSI 실무 확장] 발주일자
    "ApprovalOfficer"                VARCHAR(50), -- [MPSI 실무 확장] MPSI 승인책임자
    "ApprovalDateTime"               TIMESTAMP, -- [MPSI 실무 확장] 승인일시
    "CreatorID"                      VARCHAR(50), -- [KS X 9101 표준 준용] 등록자식별자
    "CreationDateTime"               TIMESTAMP            DEFAULT CURRENT_TIMESTAMP, -- [KS X 9101 표준 준용] 등록일시
    CONSTRAINT "PK_MpsiPpapDocument" PRIMARY KEY ("PpapSequenceNo"),
    CONSTRAINT "UK_MpsiPpapDocument" UNIQUE ("PpapID")
);

COMMENT ON TABLE "MpsiPpapDocument" IS '[MPSI 실무 확장] 양산 승인 PPAP 18대 서류 및 부품제출보증서(PSW) 관리 테이블 (공정 12단계)';

-- 11. Table: "MpsiMassSettlement" (사출양산 정산 및 납품 마감 - 공정 13단계)
CREATE TABLE IF NOT EXISTS "MpsiMassSettlement" (
    "SettlementSequenceNo"           BIGINT GENERATED BY DEFAULT AS IDENTITY, -- [MPSI 실무 확장] 정산 일련번호(PK)
    "SettlementID"                   VARCHAR(50)          NOT NULL, -- [MPSI 실무 확장] 정산 식별자
    "ProjectID"                      VARCHAR(50)          NOT NULL, -- [KS X 9101 표준 준용] 프로젝트식별자
    "MassVendorID"                   VARCHAR(50)          NOT NULL, -- [KS X 9101 표준 준용] 사출양산처 식별자
    "SettlementMonth"                VARCHAR(7)           NOT NULL, -- [MPSI 실무 확장] 마감 정산월 (예: 2026-10)
    "DeliveredQuantity"              INTEGER              NOT NULL, -- [MPSI 실무 확장] 당월 총 납품수량 (EA)
    "UnitPrice"                      NUMERIC(12,2)        NOT NULL, -- [MPSI 실무 확장] EA당 단가 (원)
    "TotalSettlementAmount"          NUMERIC(15,2)        NOT NULL, -- [MPSI 실무 확장] 총 정산금액 (원)
    "SettlementStatus"               VARCHAR(30)          DEFAULT '마감대기', -- [MPSI 실무 확장] 정산 상태 (마감대기/정산확정/지급완료)
    "CreationDateTime"               TIMESTAMP            DEFAULT CURRENT_TIMESTAMP, -- [KS X 9101 표준 준용] 등록일시
    CONSTRAINT "PK_MpsiMassSettlement" PRIMARY KEY ("SettlementSequenceNo"),
    CONSTRAINT "UK_MpsiMassSettlement" UNIQUE ("SettlementID")
);

COMMENT ON TABLE "MpsiMassSettlement" IS '[MPSI 실무 확장] 양산 부품 납품 실적 및 월별 대금 정산 마감 테이블 (공정 13단계)';

-- 12. Table: "MpsiArcTalkMessage" (프로젝트별 1:1 기술 협의 아크톡)
CREATE TABLE IF NOT EXISTS "MpsiArcTalkMessage" (
    "MessageSequenceNo"              BIGINT GENERATED BY DEFAULT AS IDENTITY, -- [MPSI 실무 확장] 메시지 일련번호(PK)
    "MessageID"                      VARCHAR(50)          NOT NULL, -- [MPSI 실무 확장] 메시지 식별자
    "ProjectID"                      VARCHAR(50)          NOT NULL, -- [KS X 9101 표준 준용] 프로젝트식별자
    "SenderID"                       VARCHAR(50)          NOT NULL, -- [MPSI 실무 확장] 발신자 식별자
    "SenderName"                     VARCHAR(50)          NOT NULL, -- [MPSI 실무 확장] 발신자 성명
    "SenderCompany"                  VARCHAR(100)         NOT NULL, -- [MPSI 실무 확장] 발신자 소속사
    "Content"                        TEXT                 NOT NULL, -- [MPSI 실무 확장] 메시지 본문
    "AttachmentFileName"             VARCHAR(255), -- [MPSI 실무 확장] 첨부 파일명
    "CreationDateTime"               TIMESTAMP            DEFAULT CURRENT_TIMESTAMP, -- [KS X 9101 표준 준용] 발신일시
    CONSTRAINT "PK_MpsiArcTalkMessage" PRIMARY KEY ("MessageSequenceNo"),
    CONSTRAINT "UK_MpsiArcTalkMessage" UNIQUE ("MessageID")
);

COMMENT ON TABLE "MpsiArcTalkMessage" IS '[MPSI 실무 확장] MPSI ↔ 외주협력사 간 프로젝트별 1:1 기술 및 일정 협의 메시지 테이블';

-- 13. Table: "MpsiPmRevisionMaster" (금형 PM 예방보전 및 설계변경 마스터)
CREATE TABLE IF NOT EXISTS "MpsiPmRevisionMaster" (
    "PmSequenceNo"                   BIGINT GENERATED BY DEFAULT AS IDENTITY, -- [MPSI 실무 확장] PM 일련번호(PK)
    "PmMasterID"                     VARCHAR(50)          NOT NULL, -- [MPSI 실무 확장] PM 마스터 식별자
    "ProjectID"                      VARCHAR(50)          NOT NULL, -- [KS X 9101 표준 준용] 프로젝트식별자
    "CumulativeShotCount"            INTEGER              DEFAULT 0, -- [MPSI 실무 확장] 금형 누적 타수 (Shot)
    "PmTargetShotInterval"           INTEGER              DEFAULT 50000, -- [MPSI 실무 확장] 정기 PM 주기 타수 (예: 매 5만타)
    "NextPmScheduledDate"            DATE, -- [MPSI 실무 확장] 차기 PM 예정일자
    "ActiveRevisionCode"             VARCHAR(20)          DEFAULT 'N001', -- [MPSI 실무 확장] 현재 유효 설계변경 차수 (N001, E001...)
    "CreationDateTime"               TIMESTAMP            DEFAULT CURRENT_TIMESTAMP, -- [KS X 9101 표준 준용] 등록일시
    CONSTRAINT "PK_MpsiPmRevisionMaster" PRIMARY KEY ("PmSequenceNo"),
    CONSTRAINT "UK_MpsiPmRevisionMaster" UNIQUE ("PmMasterID")
);

COMMENT ON TABLE "MpsiPmRevisionMaster" IS '[MPSI 실무 확장] 금형 누적 타수 추적 및 정기 예방보전(PM)/설변 마스터 테이블';

-- 14. Table: "MpsiPmRound" (금형 정기점검 회차별 실적)
CREATE TABLE IF NOT EXISTS "MpsiPmRound" (
    "PmRoundSequenceNo"              BIGINT GENERATED BY DEFAULT AS IDENTITY, -- [MPSI 실무 확장] 회차 일련번호(PK)
    "RoundID"                        VARCHAR(50)          NOT NULL, -- [MPSI 실무 확장] 점검회차 식별자
    "PmMasterID"                     VARCHAR(50)          NOT NULL, -- [MPSI 실무 확장] PM 마스터 식별자
    "RoundNumber"                    INTEGER              NOT NULL, -- [MPSI 실무 확장] 점검 회차 (1차, 2차...)
    "InspectionDate"                 DATE                 NOT NULL, -- [MPSI 실무 확장] 점검 실시일자
    "InspectorName"                  VARCHAR(50)          NOT NULL, -- [MPSI 실무 확장] 점검자 성명
    "PmChecklistFile"                VARCHAR(255), -- [MPSI 실무 확장] 정기 PM 체크시트 결과 파일
    "PmStatus"                       VARCHAR(30)          DEFAULT '점검완료', -- [MPSI 실무 확장] 상태
    CONSTRAINT "PK_MpsiPmRound" PRIMARY KEY ("PmRoundSequenceNo"),
    CONSTRAINT "UK_MpsiPmRound" UNIQUE ("RoundID")
);

COMMENT ON TABLE "MpsiPmRound" IS '[MPSI 실무 확장] 금형 1~30차 정기 PM 예방보전 점검 실적 테이블';

-- 15. Table: "MpsiRevisionHistory" (E001 등 설계변경 이력 관리)
CREATE TABLE IF NOT EXISTS "MpsiRevisionHistory" (
    "RevisionSequenceNo"             BIGINT GENERATED BY DEFAULT AS IDENTITY, -- [MPSI 실무 확장] 설변 일련번호(PK)
    "RevisionID"                     VARCHAR(50)          NOT NULL, -- [MPSI 실무 확장] 설변 식별자
    "ProjectID"                      VARCHAR(50)          NOT NULL, -- [KS X 9101 표준 준용] 프로젝트식별자
    "RevisionCode"                   VARCHAR(20)          NOT NULL, -- [MPSI 실무 확장] 설변 차수 (E001, E002 등)
    "ChangeReason"                   VARCHAR(255)         NOT NULL, -- [MPSI 실무 확장] 설계변경 사유 (리브 두께 보강 등)
    "ChangeAmount"                   NUMERIC(15,2)        DEFAULT 0, -- [MPSI 실무 확장] 설변 견적비용
    "ApprovalStatus"                 VARCHAR(30)          DEFAULT '승인완료', -- [MPSI 실무 확장] 승인 상태
    "AppliedDate"                    DATE                 NOT NULL, -- [MPSI 실무 확장] 설변 적용일자
    "EcoDocumentFile"                VARCHAR(255), -- [MPSI 실무 확장] 설계변경 승인서 파일 (ECO)
    CONSTRAINT "PK_MpsiRevisionHistory" PRIMARY KEY ("RevisionSequenceNo"),
    CONSTRAINT "UK_MpsiRevisionHistory" UNIQUE ("RevisionID")
);

COMMENT ON TABLE "MpsiRevisionHistory" IS '[MPSI 실무 확장] 원청 요청 설계변경(ECO) 발생에 따른 차수별 이력 및 추가비용 관리 테이블';

-- 16. Table: "MpsiNotification" (SCM 전역 알림 센터)
CREATE TABLE IF NOT EXISTS "MpsiNotification" (
    "NotificationSequenceNo"         BIGINT GENERATED BY DEFAULT AS IDENTITY, -- [MPSI 실무 확장] 알림 일련번호(PK)
    "NotificationID"                 VARCHAR(50)          NOT NULL, -- [MPSI 실무 확장] 알림 식별자
    "TargetRole"                     VARCHAR(30)          NOT NULL, -- [MPSI 실무 확장] 수신 역할 (MPSI, VENDOR_MOLD, VENDOR_MASS)
    "TargetVendorName"               VARCHAR(100), -- [MPSI 실무 확장] 수신 대상 업체명
    "Title"                          VARCHAR(200)         NOT NULL, -- [MPSI 실무 확장] 알림 제목
    "Message"                        TEXT                 NOT NULL, -- [MPSI 실무 확장] 알림 본문
    "LinkUrl"                        VARCHAR(255), -- [MPSI 실무 확장] 클릭 시 이동할 URL 경로
    "IsConfirmed"                    BOOLEAN              DEFAULT FALSE, -- [MPSI 실무 확장] 확인 여부
    "CreationDateTime"               TIMESTAMP            DEFAULT CURRENT_TIMESTAMP, -- [KS X 9101 표준 준용] 발생일시
    CONSTRAINT "PK_MpsiNotification" PRIMARY KEY ("NotificationSequenceNo"),
    CONSTRAINT "UK_MpsiNotification" UNIQUE ("NotificationID")
);

COMMENT ON TABLE "MpsiNotification" IS '[MPSI 실무 확장] MPSI 본사 ↔ 외주협력사 간 업무 상태 변동 알림 테이블';

-- 17. Table: "MpsiDeliveryTracking" (SCM 완제품 배송 관제)
CREATE TABLE IF NOT EXISTS "MpsiDeliveryTracking" (
    "TrackingSequenceNo"             BIGINT GENERATED BY DEFAULT AS IDENTITY, -- [MPSI 실무 확장] 배송 일련번호(PK)
    "TrackingID"                     VARCHAR(50)          NOT NULL, -- [MPSI 실무 확장] 배송 식별자
    "ProjectID"                      VARCHAR(50)          NOT NULL, -- [KS X 9101 표준 준용] 프로젝트식별자
    "InvoiceNumber"                  VARCHAR(50)          NOT NULL, -- [MPSI 실무 확장] 송장번호
    "CarrierName"                    VARCHAR(100)         NOT NULL, -- [MPSI 실무 확장] 운송사명
    "DispatchDate"                   DATE                 NOT NULL, -- [MPSI 실무 확장] 출하 일자
    "DeliveryStatus"                 VARCHAR(30)          DEFAULT '배송중', -- [MPSI 실무 확장] 배송 상태
    CONSTRAINT "PK_MpsiDeliveryTracking" PRIMARY KEY ("TrackingSequenceNo"),
    CONSTRAINT "UK_MpsiDeliveryTracking" UNIQUE ("TrackingID")
);

COMMENT ON TABLE "MpsiDeliveryTracking" IS '[MPSI 실무 확장] 사출 완제품 출하부터 고객사 도착까지의 물류 배송 관제 테이블';

-- 18. Table: "MpsiDeliveryStep" (배송 단계별 세부 이력)
CREATE TABLE IF NOT EXISTS "MpsiDeliveryStep" (
    "StepSequenceNo"                 BIGINT GENERATED BY DEFAULT AS IDENTITY, -- [MPSI 실무 확장] 단계 일련번호(PK)
    "StepID"                         VARCHAR(50)          NOT NULL, -- [MPSI 실무 확장] 단계 식별자
    "TrackingID"                     VARCHAR(50)          NOT NULL, -- [MPSI 실무 확장] 배송 식별자
    "StepTitle"                      VARCHAR(100)         NOT NULL, -- [MPSI 실무 확장] 단계명 (상차완료, 운송중, 하차)
    "LocationName"                   VARCHAR(100)         NOT NULL, -- [MPSI 실무 확장] 위치
    "OccurredDateTime"               TIMESTAMP            NOT NULL, -- [MPSI 실무 확장] 발생일시
    CONSTRAINT "PK_MpsiDeliveryStep" PRIMARY KEY ("StepSequenceNo"),
    CONSTRAINT "UK_MpsiDeliveryStep" UNIQUE ("StepID")
);

COMMENT ON TABLE "MpsiDeliveryStep" IS '[MPSI 실무 확장] 완제품 배송 단계별 경유지 및 도착 이력 테이블';

-- 19. Table: "MpsiProjectStepAttachment" (공정 단계별 실무 첨부파일)
CREATE TABLE IF NOT EXISTS "MpsiProjectStepAttachment" (
    "AttachmentSequenceNo"           BIGINT GENERATED BY DEFAULT AS IDENTITY, -- [MPSI 실무 확장] 첨부 일련번호(PK)
    "AttachmentID"                   VARCHAR(50)          NOT NULL, -- [MPSI 실무 확장] 첨부 식별자
    "ProjectID"                      VARCHAR(50)          NOT NULL, -- [KS X 9101 표준 준용] 프로젝트식별자
    "StepNumber"                     INTEGER              NOT NULL, -- [MPSI 실무 확장] 공정 단계 (0~13)
    "FileName"                       VARCHAR(200)         NOT NULL, -- [MPSI 실무 확장] 파일명
    "FileSize"                       VARCHAR(30), -- [MPSI 실무 확장] 파일 크기
    "FileUrl"                        TEXT                 NOT NULL, -- [MPSI 실무 확장] 파일 URL/경로
    "UploaderName"                   VARCHAR(50)          NOT NULL, -- [MPSI 실무 확장] 업로더 성명
    "UploadDateTime"                 TIMESTAMP            DEFAULT CURRENT_TIMESTAMP, -- [KS X 9101 표준 준용] 업로드일시
    CONSTRAINT "PK_MpsiProjectStepAttachment" PRIMARY KEY ("AttachmentSequenceNo"),
    CONSTRAINT "UK_MpsiProjectStepAttachment" UNIQUE ("AttachmentID")
);

COMMENT ON TABLE "MpsiProjectStepAttachment" IS '[MPSI 실무 확장] 14단계 공정별 현장 첨부파일(도면, 성적서, 사진 등) 저장 테이블';

-- 20. Table: "MpsiProjectStepMemo" (공정 단계별 실무 메모)
CREATE TABLE IF NOT EXISTS "MpsiProjectStepMemo" (
    "MemoSequenceNo"                 BIGINT GENERATED BY DEFAULT AS IDENTITY, -- [MPSI 실무 확장] 메모 일련번호(PK)
    "MemoID"                         VARCHAR(50)          NOT NULL, -- [MPSI 실무 확장] 메모 식별자
    "ProjectID"                      VARCHAR(50)          NOT NULL, -- [KS X 9101 표준 준용] 프로젝트식별자
    "StepNumber"                     INTEGER              NOT NULL, -- [MPSI 실무 확장] 공정 단계 (0~13)
    "AuthorName"                     VARCHAR(50)          NOT NULL, -- [MPSI 실무 확장] 작성자 성명
    "AuthorCompany"                  VARCHAR(100)         NOT NULL, -- [MPSI 실무 확장] 작성자 소속사
    "Content"                        TEXT                 NOT NULL, -- [MPSI 실무 확장] 메모 본문
    "CreationDateTime"               TIMESTAMP            DEFAULT CURRENT_TIMESTAMP, -- [KS X 9101 표준 준용] 작성일시
    CONSTRAINT "PK_MpsiProjectStepMemo" PRIMARY KEY ("MemoSequenceNo"),
    CONSTRAINT "UK_MpsiProjectStepMemo" UNIQUE ("MemoID")
);

COMMENT ON TABLE "MpsiProjectStepMemo" IS '[MPSI 실무 확장] 14단계 공정별 협업 실무 메모 및 특이사항 기록 테이블';

-- =====================================================================================
-- [PART 3] MPSI 분산 노드 간 API 동기화 메타 테이블 (총 3개 테이블)
-- MPSI 본사, 우성정공, 뉴몰드 3개사 분산 독립 DB 간 비동기 연계를 위한 트랜잭셔널 아웃박스/인박스
-- =====================================================================================

-- 1. Table: "MpsiSyncOutbox" (타 노드로 전송할 비동기 이벤트 큐)
CREATE TABLE IF NOT EXISTS "MpsiSyncOutbox" (
    "OutboxSequenceNo"               BIGINT GENERATED BY DEFAULT AS IDENTITY, -- [MPSI 분산 연계] 아웃박스 일련번호(PK)
    "OutboxID"                       VARCHAR(50)          NOT NULL, -- [MPSI 분산 연계] 아웃박스 식별자 (예: OUT-20261022-0001)
    "EventType"                      VARCHAR(100)         NOT NULL, -- [MPSI 분산 연계] 연계 이벤트 유형 (예: MOLD_ORDER_DISPATCHED)
    "SourceNodeID"                   VARCHAR(50)          NOT NULL, -- [MPSI 분산 연계] 발신 노드 (MPSI_HQ, WOOSUNG_MOLD 등)
    "TargetNodeID"                   VARCHAR(50)          NOT NULL, -- [MPSI 분산 연계] 수신 대상 노드
    "EntityName"                     VARCHAR(100)         NOT NULL, -- [MPSI 분산 연계] 연계 대상 엔티티 테이블명
    "EntityID"                       VARCHAR(100)         NOT NULL, -- [MPSI 분산 연계] 연계 대상 엔티티 PK
    "PayloadJson"                    TEXT                 NOT NULL, -- [MPSI 분산 연계] 전송 비즈니스 데이터 전체 JSON 페이로드
    "IdempotencyKey"                 VARCHAR(100)         NOT NULL, -- [MPSI 분산 연계] 중복 방지용 UUID 멱등성 키
    "Status"                         VARCHAR(20)          DEFAULT 'PENDING', -- [MPSI 분산 연계] 발송 상태 (PENDING, PROCESSING, SUCCESS, FAILED)
    "RetryCount"                     INTEGER              DEFAULT 0, -- [MPSI 분산 연계] 발송 재시도 횟수
    "LastError"                      TEXT, -- [MPSI 분산 연계] 최근 발송 오류 메시지
    "CreationDateTime"               TIMESTAMP            DEFAULT CURRENT_TIMESTAMP, -- [KS X 9101 표준 준용] 등록일시
    "SentDateTime"                   TIMESTAMP, -- [MPSI 분산 연계] 발송 완료 일시
    CONSTRAINT "PK_MpsiSyncOutbox" PRIMARY KEY ("OutboxSequenceNo"),
    CONSTRAINT "UK_MpsiSyncOutbox_ID" UNIQUE ("OutboxID"),
    CONSTRAINT "UK_MpsiSyncOutbox_IdempotencyKey" UNIQUE ("IdempotencyKey")
);

COMMENT ON TABLE "MpsiSyncOutbox" IS '[MPSI 분산 연계] 분산 노드 간 데이터 연계를 위한 트랜잭셔널 아웃박스 이벤트 큐 테이블';
COMMENT ON COLUMN "MpsiSyncOutbox"."OutboxSequenceNo" IS '[MPSI 분산 연계] 아웃박스 일련번호(PK)';
COMMENT ON COLUMN "MpsiSyncOutbox"."OutboxID" IS '[MPSI 분산 연계] 아웃박스 이벤트 고유 식별자 (예: OUT-20261022-0001)';
COMMENT ON COLUMN "MpsiSyncOutbox"."EventType" IS '[MPSI 분산 연계] 연계 이벤트 유형 (MOLD_ORDER_DISPATCHED, MOLD_PROGRESS_UPDATED 등)';
COMMENT ON COLUMN "MpsiSyncOutbox"."SourceNodeID" IS '[MPSI 분산 연계] 발신 노드 식별자';
COMMENT ON COLUMN "MpsiSyncOutbox"."TargetNodeID" IS '[MPSI 분산 연계] 수신 대상 노드 식별자';
COMMENT ON COLUMN "MpsiSyncOutbox"."EntityName" IS '[MPSI 분산 연계] 연계 대상 엔티티 테이블명';
COMMENT ON COLUMN "MpsiSyncOutbox"."EntityID" IS '[MPSI 분산 연계] 연계 대상 엔티티 식별자';
COMMENT ON COLUMN "MpsiSyncOutbox"."PayloadJson" IS '[MPSI 분산 연계] 비즈니스 데이터 전체 JSON 페이로드';
COMMENT ON COLUMN "MpsiSyncOutbox"."IdempotencyKey" IS '[MPSI 분산 연계] 중복 발송/처리 방지용 UUID 멱등성 키';
COMMENT ON COLUMN "MpsiSyncOutbox"."Status" IS '[MPSI 분산 연계] 발송 처리 상태 (PENDING, PROCESSING, SUCCESS, FAILED)';

-- 2. Table: "MpsiSyncInbox" (타 노드로부터 수신한 이벤트 이력 - 멱등성 보장)
CREATE TABLE IF NOT EXISTS "MpsiSyncInbox" (
    "InboxSequenceNo"                BIGINT GENERATED BY DEFAULT AS IDENTITY, -- [MPSI 분산 연계] 인박스 일련번호(PK)
    "InboxID"                        VARCHAR(50)          NOT NULL, -- [MPSI 분산 연계] 인박스 식별자 (예: IN-20261022-0001)
    "SourceNodeID"                   VARCHAR(50)          NOT NULL, -- [MPSI 분산 연계] 발신 노드 식별자
    "EventType"                      VARCHAR(100)         NOT NULL, -- [MPSI 분산 연계] 연계 이벤트 유형
    "IdempotencyKey"                 VARCHAR(100)         NOT NULL, -- [MPSI 분산 연계] 중복 수신 방지용 멱등성 키
    "PayloadJson"                    TEXT                 NOT NULL, -- [MPSI 분산 연계] 수신된 비즈니스 데이터 JSON
    "Status"                         VARCHAR(20)          DEFAULT 'PROCESSED', -- [MPSI 분산 연계] 수신 처리 상태
    "ReceivedDateTime"               TIMESTAMP            DEFAULT CURRENT_TIMESTAMP, -- [MPSI 분산 연계] 수신일시
    CONSTRAINT "PK_MpsiSyncInbox" PRIMARY KEY ("InboxSequenceNo"),
    CONSTRAINT "UK_MpsiSyncInbox_ID" UNIQUE ("InboxID"),
    CONSTRAINT "UK_MpsiSyncInbox_IdempotencyKey" UNIQUE ("IdempotencyKey")
);

COMMENT ON TABLE "MpsiSyncInbox" IS '[MPSI 분산 연계] 타 노드로부터 수신된 이벤트 이력 및 중복 수신 방지(멱등성 보장) 테이블';

-- 3. Table: "MpsiSyncNodeRegistry" (분산 연계 노드 등록 정보 및 보안 키)
CREATE TABLE IF NOT EXISTS "MpsiSyncNodeRegistry" (
    "NodeSequenceNo"                 BIGINT GENERATED BY DEFAULT AS IDENTITY, -- [MPSI 분산 연계] 노드 일련번호(PK)
    "NodeID"                         VARCHAR(50)          NOT NULL, -- [MPSI 분산 연계] 노드 고유 식별자 (MPSI_HQ, WOOSUNG_MOLD, NEWMOLD_MASS)
    "NodeName"                       VARCHAR(100)         NOT NULL, -- [MPSI 분산 연계] 노드 기관/업체 공식 명칭
    "NodeType"                       VARCHAR(30)          NOT NULL, -- [MPSI 분산 연계] 노드 유형 (HQ, VENDOR_MOLD, VENDOR_MASS)
    "EndpointUrl"                    VARCHAR(255)         NOT NULL, -- [MPSI 분산 연계] 수신 REST API 엔드포인트 URL
    "ApiKey"                         VARCHAR(255)         NOT NULL, -- [MPSI 분산 연계] 노드 간 보안 인증 API 키
    "IsActive"                       BOOLEAN              DEFAULT TRUE, -- [MPSI 분산 연계] 노드 활성 상태
    "LastHeartbeatDateTime"          TIMESTAMP, -- [MPSI 분산 연계] 최근 통신 헬스체크 일시
    "CreationDateTime"               TIMESTAMP            DEFAULT CURRENT_TIMESTAMP, -- [KS X 9101 표준 준용] 등록일시
    CONSTRAINT "PK_MpsiSyncNodeRegistry" PRIMARY KEY ("NodeSequenceNo"),
    CONSTRAINT "UK_MpsiSyncNodeRegistry_ID" UNIQUE ("NodeID")
);

COMMENT ON TABLE "MpsiSyncNodeRegistry" IS '[MPSI 분산 연계] 분산 설치 노드 등록 및 접속 엔드포인트/보안키 메타 테이블';

-- -------------------------------------------------------------------------------------
-- 인덱스 및 시드 데이터
-- -------------------------------------------------------------------------------------
CREATE INDEX IF NOT EXISTS "IDX_MpsiSyncOutbox_Status" ON "MpsiSyncOutbox" ("Status", "CreationDateTime");
CREATE INDEX IF NOT EXISTS "IDX_MpsiSyncInbox_Source" ON "MpsiSyncInbox" ("SourceNodeID", "ReceivedDateTime");
CREATE INDEX IF NOT EXISTS "IDX_MpsiProjectStage_Project" ON "MpsiProjectStage" ("ProjectID");
CREATE INDEX IF NOT EXISTS "IDX_MpsiMoldTrial_Project" ON "MpsiMoldTrial" ("ProjectID");
CREATE INDEX IF NOT EXISTS "IDX_MpsiPpapDocument_Project" ON "MpsiPpapDocument" ("ProjectID");
CREATE INDEX IF NOT EXISTS "IDX_MpsiNotification_TargetRole" ON "MpsiNotification" ("TargetRole", "IsConfirmed");

-- 분산 클러스터 3개사 초기 노드 레지스트리 시드 데이터
INSERT INTO "MpsiSyncNodeRegistry" ("NodeID", "NodeName", "NodeType", "EndpointUrl", "ApiKey")
VALUES 
    ('MPSI_HQ', 'MPSI 본사', 'HQ', 'https://mpsi-hub.a2lab.co.kr/api/v1/sync/inbound', 'node_key_mpsi_hq_2026'),
    ('WOOSUNG_MOLD', '우성정공(주)', 'VENDOR_MOLD', 'https://woosung.mpsi-net.kr/api/v1/sync/inbound', 'node_key_woosung_2026'),
    ('NEWMOLD_MASS', '(주)뉴몰드', 'VENDOR_MASS', 'https://newmold.mpsi-net.kr/api/v1/sync/inbound', 'node_key_newmold_2026')
ON CONFLICT ("NodeID") DO UPDATE 
SET "NodeName" = EXCLUDED."NodeName", "EndpointUrl" = EXCLUDED."EndpointUrl";

-- 완료
